	function Library:MakeDraggable(Frame, Cutoff)
		self.Interface:BindDrag(Frame, Cutoff or 40)
		if self.Cursor then self.Cursor:WatchWidget(Frame) end
	end

	function Library:AddToolTip(InfoStr, HoverInstance)
		local X, Y = Library:GetTextBounds(InfoStr, Library.Font, 14)
		local Tooltip = Library:Create("Frame", {
			BackgroundColor3 = Library.MainColor,
			BorderColor3 = Library.OutlineColor,

			Size = UDim2.fromOffset(X + 5, Y + 4),
			ZIndex = 100,
			Parent = Library.ScreenGui,

			Visible = false,
		})

		Library:StyleSurface(Tooltip, 4)
		local Label = Library:CreateLabel({
			Position = UDim2.fromOffset(3, 1),
			Size = UDim2.fromOffset(X, Y),
			TextSize = 14,
			Text = InfoStr,
			TextColor3 = Library.FontColor,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = Tooltip.ZIndex + 1,

			Parent = Tooltip,
		})

		Library:AddToRegistry(Tooltip, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "OutlineColor",
		})

		Library:AddToRegistry(Label, {
			TextColor3 = "FontColor",
		})

		Tooltips[#Tooltips + 1] = Tooltip

		local IsHovering = false

		HoverInstance.MouseEnter:Connect(function()
			if Library:MouseIsOverOpenedFrame() then
				return
			end

			IsHovering = true

			Tooltip.Position = UDim2.fromOffset(Mouse.X + 15, Mouse.Y + 12)
			Tooltip.Visible = true

			while IsHovering do
				RunService.Heartbeat:Wait()
				Tooltip.Position = UDim2.fromOffset(Mouse.X + 15, Mouse.Y + 12)
			end
		end)

		HoverInstance.MouseLeave:Connect(function()
			IsHovering = false
			Tooltip.Visible = false
		end)
	end

	function Library:OnHighlight(HighlightInstance, Instance, Properties, PropertiesDefault)
		HighlightInstance.MouseEnter:Connect(function()
			local Reg = Library.RegistryMap[Instance]

			for Property, ColorIdx in next, Properties do
				Instance[Property] = Library[ColorIdx] or ColorIdx

				if Reg and Reg.Properties[Property] then
					Reg.Properties[Property] = ColorIdx
				end
			end
		end)

		HighlightInstance.MouseLeave:Connect(function()
			local Reg = Library.RegistryMap[Instance]

			for Property, ColorIdx in next, PropertiesDefault do
				Instance[Property] = Library[ColorIdx] or ColorIdx

				if Reg and Reg.Properties[Property] then
					Reg.Properties[Property] = ColorIdx
				end
			end
		end)
	end

	function Library:MouseIsOverOpenedFrame()
		for Frame, _ in next, Library.OpenedFrames do
			local AbsPos, AbsSize = Frame.AbsolutePosition, Frame.AbsoluteSize

			if
				Mouse.X >= AbsPos.X
				and Mouse.X <= AbsPos.X + AbsSize.X
				and Mouse.Y >= AbsPos.Y
				and Mouse.Y <= AbsPos.Y + AbsSize.Y
			then
				return true
			end
		end
	end

	function Library:IsMouseOverFrame(Frame)
		local AbsPos, AbsSize = Frame.AbsolutePosition, Frame.AbsoluteSize

		if
			Mouse.X >= AbsPos.X
			and Mouse.X <= AbsPos.X + AbsSize.X
			and Mouse.Y >= AbsPos.Y
			and Mouse.Y <= AbsPos.Y + AbsSize.Y
		then
			return true
		end
	end

	function Library:UpdateDependencyBoxes()
		for _, Depbox in next, Library.DependencyBoxes do
			Depbox:Update()
		end
	end

	function Library:MapValue(Value, MinA, MaxA, MinB, MaxB)
		return (1 - ((Value - MinA) / (MaxA - MinA))) * MinB + ((Value - MinA) / (MaxA - MinA)) * MaxB
	end

	function Library:GetTextBounds(Text, Font, Size, Resolution)
		local Bounds = TextService:GetTextSize(Text, Size * (Library.Appearance and Library.Appearance.fontScale or 1), Library.FontEnum or Enum.Font.Gotham, Resolution or Vector2.new(1920, 1080))
		return Bounds.X, Bounds.Y
	end

	function Library:GetDarkerColor(Color)
		local H, S, V = Color3.toHSV(Color)
		return Color3.fromHSV(H, S, V / 1.5)
	end
	Library.AccentColorDark = Library:GetDarkerColor(Library.AccentColor)

	function Library:AddToRegistry(Instance, Properties, IsHud)
		local Idx = #Library.Registry + 1
		local Data = {
			Instance = Instance,
			Properties = Properties,
			Idx = Idx,
		}

		table.insert(Library.Registry, Data)
		Library.RegistryMap[Instance] = Data

		if IsHud then
			table.insert(Library.HudRegistry, Data)
		end
	end

	function Library:RemoveFromRegistry(Instance)
		local Data = Library.RegistryMap[Instance]

		if Data then
			for Idx = #Library.Registry, 1, -1 do
				if Library.Registry[Idx] == Data then
					table.remove(Library.Registry, Idx)
				end
			end

			for Idx = #Library.HudRegistry, 1, -1 do
				if Library.HudRegistry[Idx] == Data then
					table.remove(Library.HudRegistry, Idx)
				end
			end

			Library.RegistryMap[Instance] = nil
		end
	end

	function Library:UpdateColorsUsingRegistry()
		-- TODO: Could have an 'active' list of objects
		-- where the active list only contains Visible objects.

		-- IMPL: Could setup .Changed events on the AddToRegistry function
		-- that listens for the 'Visible' propert being changed.
		-- Visible: true => Add to active list, and call UpdateColors function
		-- Visible: false => Remove from active list.

		-- The above would be especially efficient for a rainbow menu color or live color-changing.

		for Idx, Object in next, Library.Registry do
			for Property, ColorIdx in next, Object.Properties do
				-- Live theme colors supersede a pending tween to an older palette.
				local motion = Library.Motion and Library.Motion[Object.Instance]
				if motion and motion.goals[Property] ~= nil then
					local remaining = table.clone(motion.goals)
					remaining[Property] = nil
					motion.connection:Disconnect(); motion.tween:Cancel(); Library.Motion[Object.Instance] = nil
					if next(remaining) then Library:Animate(Object.Instance, remaining) end
				end
				if type(ColorIdx) == "string" then
					Object.Instance[Property] = Library[ColorIdx]
				elseif type(ColorIdx) == "function" then
					Object.Instance[Property] = ColorIdx()
				end
			end
		end
	end

	Library.UIScale = 1
	Library.HudTransparency = 0.18
	-- The visualizer replaces this position holder when its feature initializes.
	Library.AnimationVisualizerFrame = { Position = UDim2.fromOffset(0, 0) }

	function Library:NotifyWithSound(text, duration)
		return self:Notify(text, duration)
	end

	function Library:GiveSignal(Signal)
		-- Only used for signals not attached to library instances, as those should be cleaned up on object destruction by Roblox
		table.insert(Library.Signals, Signal)
	end

	function Library:Unload()
		Library.Interface.epoch = Library.Interface.epoch + 1
		Library.Interface:Close()
		Library.Interface:CloseInputs()
		Library.Interface:EndResize(true)
		Library.Interface:EndDrag(true)
		-- Unload all of the signals
		for Idx = #Library.Signals, 1, -1 do
			local Connection = table.remove(Library.Signals, Idx)
			Connection:Disconnect()
		end

		-- Call our unload callback, maybe to undo some hooks etc
		if Library.OnUnload then
			Library.OnUnload()
		end

		ScreenGui:Destroy()
	end

	function Library:OnUnload(Callback)
		Library.OnUnload = Callback
	end

	Library:GiveSignal(ScreenGui.DescendantRemoving:Connect(function(Instance)
		if Library.RegistryMap[Instance] then
			Library:RemoveFromRegistry(Instance)
		end
	end))

	-- Eager HUD creation below registers drag handlers before CreateWindow is called.
	require("GUI/Interface")(Library)

	local BaseAddons = {}

	-- Retarget from the current visual state; never accumulate idle frame callbacks.
	Library.Motion = {}
	function Library:Animate(Object, Goals, Duration)
		local previous = self.Motion[Object]
		if previous then
			local combined = table.clone(previous.goals)
			for key, value in pairs(Goals) do combined[key] = value end
			Goals = combined
			previous.connection:Disconnect(); previous.tween:Cancel(); self.Motion[Object] = nil
		end
		local changed = false
		for key, value in pairs(Goals) do if Object[key] ~= value then changed = true; break end end
		if not changed then return end
		local tween = TweenService:Create(Object, TweenInfo.new(Duration or 0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), Goals)
		local state = { tween = tween, goals = Goals }
		self.Motion[Object] = state
		state.connection = tween.Completed:Connect(function()
			state.connection:Disconnect()
			if self.Motion[Object] == state then self.Motion[Object] = nil end
		end)
		tween:Play()
	end
	Library:GiveSignal({ Disconnect = function()
		for object, state in pairs(Library.Motion) do
			state.connection:Disconnect(); state.tween:Cancel(); Library.Motion[object] = nil
		end
	end })

	local ControlHeight = 22
	local GroupInset = 8
	local GroupHeaderHeight = 28

	-- Keep the existing border property/registry contract; render it as a rounded stroke.
	function Library:StyleSurface(Object, Radius, Transparency)
		Object.BorderSizePixel = 0
		local Corner = Object:FindFirstChild("AeroCorner") or Library:Create("UICorner", { Name = "AeroCorner", Parent = Object })
		Corner.CornerRadius = UDim.new(0, Radius or 4)
		local Stroke = Object:FindFirstChild("AeroOutline")
		if not Stroke then
			Stroke = Library:Create("UIStroke", { Name = "AeroOutline", ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				Thickness = 1, Color = Object.BorderColor3, Parent = Object })
			Object:GetPropertyChangedSignal("BorderColor3"):Connect(function() Stroke.Color = Object.BorderColor3 end)
		end
		Stroke.Transparency = Transparency or 0
		return Stroke
	end

	local function roundInner(Object, Radius)
		Object.BorderSizePixel = 0
		Library:Create("UICorner", { CornerRadius = UDim.new(0, Radius or 4), Parent = Object })
	end

	-- Hover must not erase the active state while typing or using an open list.
	function Library:BindControlBorder(Outer, Box)
		local hovering, active = false, false
		local function update()
			local color = (hovering or active) and "AccentColor" or "OutlineColor"
			Outer.BorderColor3 = Library[color]
			local registry = Library.RegistryMap[Outer]
			if registry then registry.Properties.BorderColor3 = color end
		end
		Outer.MouseEnter:Connect(function() hovering = true; update() end)
		Outer.MouseLeave:Connect(function() hovering = false; update() end)
		local function setActive(value)
			active = value == true
			update()
		end
		if Box then
			Box.Focused:Connect(function() setActive(true) end)
			Box.FocusLost:Connect(function() setActive(false) end)
		end
		update()
		return setActive
	end

