				local area = Library:GetInterfaceViewport()
				local width, height = PickerFrameOuter.Size.X.Offset * Library.UIScale, PickerFrameOuter.Size.Y.Offset * Library.UIScale
				local p, size = DisplayFrame.AbsolutePosition, DisplayFrame.AbsoluteSize
				local y = p.Y + size.Y + 8
				if y + height > area.Y - 8 then y = p.Y - height - 8 end
				PickerFrameOuter.Position = UDim2.fromOffset(math.clamp(p.X + size.X - width, 8, math.max(8, area.X - width - 8)),
					math.clamp(y, 8, math.max(8, area.Y - height - 8)))
			end
			DisplayFrame:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
