			end)

			PickerFrameOuter.BackgroundColor3 = Library.MainColor
			PickerFrameOuter.BorderColor3 = Library.OutlineColor
			Library:AddToRegistry(PickerFrameOuter, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
