	function Library:CreateWindow(...)
		local Arguments = { ... }
		local Config = { AnchorPoint = Vector2.zero }

		if type(...) == "table" then
			Config = ...
		else
			Config.Title = Arguments[1]
			Config.AutoShow = Arguments[2] or false
		end

		if type(Config.Title) ~= "string" then
			Config.Title = "No title"
		end
		if type(Config.TabPadding) ~= "number" then
			Config.TabPadding = 16
		end
		if type(Config.MenuFadeTime) ~= "number" then
			Config.MenuFadeTime = 0.2
		end

		if typeof(Config.Position) ~= "UDim2" then
			Config.Position = UDim2.fromOffset(175, 50)
		end
		if typeof(Config.Size) ~= "UDim2" then
			Config.Size = UDim2.fromOffset(500, 600)
		end

		if Config.Center then
			Config.AnchorPoint = Vector2.new(0.5, 0.5)
			Config.Position = UDim2.fromScale(0.5, 0.5)
		end

		local Window = {
			Tabboxes = {},
			Tabs = {},
		}

		local Outer = Library:Create("Frame", {
			AnchorPoint = Config.AnchorPoint,
			BackgroundColor3 = Library.BackgroundColor,
			BorderSizePixel = 0,
			Position = Config.Position,
			Size = Config.Size,
			Visible = false,
			ZIndex = 1,
			Parent = ScreenGui,
		})

		Library:AddToRegistry(Outer, { BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" })
		if Library.Appearance then Library.Appearance:RegisterSurface(Outer, "BackgroundColor") end
		Outer.BorderColor3 = Library.OutlineColor
		Library:StyleSurface(Outer, 5, 0.55)
		Library:MakeDraggable(Outer, 38)

		local Inner = Library:Create("Frame", {
			BackgroundColor3 = Library.BackgroundColor,
			BackgroundTransparency = 1,
			BorderColor3 = Library.OutlineColor,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(0, 0),
			Size = UDim2.fromScale(1, 1),
			ZIndex = 1,
			Parent = Outer,
		})

		Library:AddToRegistry(Inner, {
			BackgroundColor3 = "BackgroundColor",
			BorderColor3 = "OutlineColor",
		})

		roundInner(Inner, 5)
		local WindowLabel = Library:CreateLabel({
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -212, 0, 34),
			TextSize = 15,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Text = Config.Title or "",
			TextColor3 = Library.AccentColor,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 1,
			Parent = Inner,
		})

		Library:AddToRegistry(WindowLabel, {
			TextColor3 = "AccentColor",
		})

		local TopbarDivider = Library:Create("Frame", { Name = "TopbarDivider", BackgroundColor3 = Library.OutlineColor,
			BackgroundTransparency = 0.45, BorderSizePixel = 0, Position = UDim2.fromOffset(10, 39),
			Size = UDim2.new(1, -20, 0, 1), ZIndex = 2, Parent = Inner })
		Library:AddToRegistry(TopbarDivider, { BackgroundColor3 = "OutlineColor" })

		local MainSectionOuter = Library:Create("Frame", {
			BackgroundColor3 = Library.BackgroundColor,
			BackgroundTransparency = 1,
			BorderColor3 = Library.OutlineColor,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(10, 44),
			Size = UDim2.new(1, -20, 1, -52),
			ZIndex = 1,
			Parent = Inner,
		})

		Library:AddToRegistry(MainSectionOuter, {
			BackgroundColor3 = "BackgroundColor",
			BorderColor3 = "OutlineColor",
		})

		local MainSectionInner = Library:Create("Frame", {
			BackgroundColor3 = Library.BackgroundColor,
			BackgroundTransparency = 1,
			BorderColor3 = Color3.new(0, 0, 0),
			BorderSizePixel = 0,
			Position = UDim2.new(0, 0, 0, 0),
