			ZIndex = 1,
			Parent = MainSectionOuter,
		})

		Library:AddToRegistry(MainSectionInner, {
			BackgroundColor3 = "BackgroundColor",
		})

		local TabArea = Library:Create("ScrollingFrame", {
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			CanvasSize = UDim2.fromOffset(0, 0),
			AutomaticCanvasSize = Enum.AutomaticSize.X,
			ScrollingDirection = Enum.ScrollingDirection.X,
			ScrollBarThickness = 0,
			Position = UDim2.fromOffset(8, 0),
			Size = UDim2.new(1, -16, 0, 28),
			ZIndex = 1,
			Parent = MainSectionInner,
		})

		local TabListLayout = Library:Create("UIListLayout", {
			Padding = UDim.new(0, Config.TabPadding),
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = TabArea,
		})

		-- Sibling overlay stays outside UIListLayout and clips at the horizontal tab viewport.
		local IndicatorViewport = Library:Create("Frame", { Name = "TabIndicatorViewport", BackgroundTransparency = 1, BorderSizePixel = 0,
			ClipsDescendants = true, Position = TabArea.Position, Size = TabArea.Size, ZIndex = 4, Parent = MainSectionInner })
		local ActiveLine = Library:Create("Frame", { Name = "ActiveTabLine", BackgroundColor3 = Library.AccentColor,
			BorderSizePixel = 0, Position = UDim2.fromOffset(0, 26), Size = UDim2.fromOffset(0, 2),
			Visible = false, ZIndex = 4, Parent = IndicatorViewport })
		Library:AddToRegistry(ActiveLine, { BackgroundColor3 = "AccentColor" })
		if Library.Appearance then Library.Appearance:AddGradient(ActiveLine) end
		Window.TabIndicator, Window.TabArea = ActiveLine, TabArea
		local selectedButton
		local function moveIndicator(animate)
			if not selectedButton then return end
			local goals = { Position = UDim2.fromOffset((selectedButton.AbsolutePosition.X - TabArea.AbsolutePosition.X) / Library.UIScale, 26),
				Size = UDim2.fromOffset(selectedButton.AbsoluteSize.X / Library.UIScale, 2) }
			if animate and ActiveLine.Visible then Library:Animate(ActiveLine, goals, 0.2)
			else
				local previous = Library.Motion[ActiveLine]
				local remaining
				if previous then
					remaining = table.clone(previous.goals)
					remaining.Position, remaining.Size = nil, nil
					previous.connection:Disconnect(); previous.tween:Cancel(); Library.Motion[ActiveLine] = nil
				end
				for key, value in pairs(goals) do ActiveLine[key] = value end
				if remaining and next(remaining) then Library:Animate(ActiveLine, remaining) end
			end
			local wasVisible = ActiveLine.Visible
			ActiveLine.Visible = true
			if not wasVisible and Library.Appearance then Library.Appearance:QueueVisible() end
		end
		TabArea:GetPropertyChangedSignal("CanvasPosition"):Connect(function() moveIndicator(false) end)

		local TabContainer = Library:Create("Frame", {
			BackgroundColor3 = Library.BackgroundColor,
			BackgroundTransparency = 1,
			BorderColor3 = Library.OutlineColor,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(0, 30),
			Size = UDim2.new(1, 0, 1, -30),
			ZIndex = 2,
			Parent = MainSectionInner,
		})

		Library:AddToRegistry(TabContainer, {
			BackgroundColor3 = "BackgroundColor",
			BorderColor3 = "OutlineColor",
		})

		local windowTitle, configDirty = Config.Title, false
		function Window:SetWindowTitle(Title)
			windowTitle = Title
			WindowLabel.Text = windowTitle .. (configDirty and " *" or "")
		end
		function Window:SetConfigDirty(dirty)
			configDirty = dirty == true
			WindowLabel.Text = windowTitle .. (configDirty and " *" or "")
		end

		---Add a tab to the window.
		---@param Name string
		---@return table
		function Window:AddTab(Name)
			local Tab = {
				Name = Name,
				GroupboxCount = 0,
				TabboxCount = 0,
				Groupboxes = {},
				Tabboxes = {},
			}

			local TabButtonWidth = Library:GetTextBounds(Name, Library.Font, 13)

			local TabButton = Library:Create("Frame", {
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				BackgroundColor3 = Library.BackgroundColor,
				BorderColor3 = Library.OutlineColor,
				Size = UDim2.new(0, TabButtonWidth, 1, 0),
				ZIndex = 1,
				Parent = TabArea,
			})

			Library:AddToRegistry(TabButton, {
				BackgroundColor3 = "BackgroundColor",
				BorderColor3 = "OutlineColor",
			})

			local TabButtonLabel = Library:CreateLabel({
				Position = UDim2.new(0, 0, 0, 0),
				Size = UDim2.new(1, 0, 1, -1),
				Text = Name,
				TextSize = 13,
				TextTransparency = 0.35,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 1,
				Parent = TabButton,
			})

			local Blocker = Library:Create("Frame", {
				BackgroundColor3 = Library.MainColor,
				BorderSizePixel = 0,
				Position = UDim2.new(0, 0, 1, 0),
				Size = UDim2.new(1, 0, 0, 1),
				BackgroundTransparency = 1,
				ZIndex = 3,
				Parent = TabButton,
			})

			Library:AddToRegistry(Blocker, {
				BackgroundColor3 = "MainColor",
			})
			Tab.Button, Tab.Label = TabButton, TabButtonLabel
			local hovering = false
			local function updateTabHover()
				Library:Animate(TabButtonLabel, { TextTransparency = (Window.SelectedTab == Name or hovering) and 0 or 0.35 })
			end
			TabButton.MouseEnter:Connect(function() hovering = true; updateTabHover() end)
			TabButton.MouseLeave:Connect(function() hovering = false; updateTabHover() end)
			for _, property in ipairs({ "AbsolutePosition", "AbsoluteSize" }) do
				TabButton:GetPropertyChangedSignal(property):Connect(function()
					if selectedButton == TabButton and not Library.Interface.drag and not Library.Interface.resize then moveIndicator(false) end
				end)
			end

			local TabFrame = Library:Create("Frame", {
				Name = "TabFrame",
				BackgroundTransparency = 1,
				Position = UDim2.new(0, 0, 0, 0),
				Size = UDim2.new(1, 0, 1, 0),
				Visible = false,
				ZIndex = 2,
				Parent = TabContainer,
			})

			local LeftSide = Library:Create("ScrollingFrame", {
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Position = UDim2.new(0, 8 - 1, 0, 8 - 1),
				Size = UDim2.new(0.5, -12 + 2, 1, -14),
				CanvasSize = UDim2.new(0, 0, 0, 0),
				BottomImage = "",
				TopImage = "",
				ScrollBarThickness = 0,
				ZIndex = 2,
				Parent = TabFrame,
			})

			local RightSide = Library:Create("ScrollingFrame", {
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Position = UDim2.new(0.5, 4 + 1, 0, 8 - 1),
				Size = UDim2.new(0.5, -12 + 2, 1, -14),
				CanvasSize = UDim2.new(0, 0, 0, 0),
				BottomImage = "",
				TopImage = "",
				ScrollBarThickness = 0,
				ZIndex = 2,
				Parent = TabFrame,
			})

			Library:Create("UIListLayout", {
				Padding = UDim.new(0, 6),
				FillDirection = Enum.FillDirection.Vertical,
				SortOrder = Enum.SortOrder.LayoutOrder,
				HorizontalAlignment = Enum.HorizontalAlignment.Center,
				Parent = LeftSide,
			})

			Library:Create("UIListLayout", {
				Padding = UDim.new(0, 6),
				FillDirection = Enum.FillDirection.Vertical,
				SortOrder = Enum.SortOrder.LayoutOrder,
				HorizontalAlignment = Enum.HorizontalAlignment.Center,
				Parent = RightSide,
			})

			for _, Side in next, { LeftSide, RightSide } do
				Library:Create("UIPadding", { PaddingTop = UDim.new(0, 1), PaddingBottom = UDim.new(0, 1), Parent = Side })
				Side:GetPropertyChangedSignal("CanvasPosition"):Connect(function() if Library.Appearance then Library.Appearance:QueueVisible() end end)
				Side:WaitForChild("UIListLayout"):GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
					Side.CanvasSize = UDim2.fromOffset(0, Side.UIListLayout.AbsoluteContentSize.Y / Library.UIScale)
				end)
			end

			function Tab:ShowTab()
				Window.SelectedTab = Name
				selectedButton = TabButton
				for _, Tab in next, Window.Tabs do
					if Tab.Name ~= Name then Tab:HideTab() end
				end

				Blocker.BackgroundTransparency = 1
				TabButtonLabel.TextColor3 = Library.AccentColor
				updateTabHover()
				Library.RegistryMap[TabButtonLabel].Properties.TextColor3 = "AccentColor"
				moveIndicator(true)
				TabButton.BackgroundColor3 = Library.MainColor
				Library.RegistryMap[TabButton].Properties.BackgroundColor3 = "MainColor"
				TabFrame.Visible = true
				if Library.Appearance then Library.Appearance:QueueVisible() end
				if Tab.RefreshStatuses then Tab:RefreshStatuses() end
			end

			function Tab:HideTab()
				TabButtonLabel.TextColor3 = Library.FontColor
				updateTabHover()
				Library.RegistryMap[TabButtonLabel].Properties.TextColor3 = "FontColor"
				Blocker.BackgroundTransparency = 1
				if selectedButton == TabButton then ActiveLine.Visible = false; selectedButton = nil end
				TabButton.BackgroundColor3 = Library.BackgroundColor
				Library.RegistryMap[TabButton].Properties.BackgroundColor3 = "BackgroundColor"
				TabFrame.Visible = false
			end

			function Tab:SetLayoutOrder(Position)
				TabButton.LayoutOrder = Position
				TabListLayout:ApplyLayout()
			end

			function Tab:AddGroupbox(Info)
				local Groupbox = { Name = Info.Name, OwnerTab = Tab, SearchSection = Info.Category }

				local BoxOuter = Library:Create("Frame", {
					BackgroundColor3 = Library.InnerBoxColor,
					BorderColor3 = Library.OutlineColor,
					BorderMode = Enum.BorderMode.Inset,
					Position = UDim2.fromOffset(1, 1), Size = UDim2.new(1, -2, 0, 507 + 2),
					ZIndex = 2,
					Parent = Info.Parent or (Info.Side == 1 and LeftSide or RightSide),
				})

				Library:AddToRegistry(BoxOuter, {
					BackgroundColor3 = "InnerBoxColor",
					BorderColor3 = "OutlineColor",
				})

				local BoxInner = Library:Create("Frame", {
					BackgroundColor3 = Library.InnerBoxColor,
					BorderColor3 = Color3.new(0, 0, 0),
					-- BorderMode = Enum.BorderMode.Inset;
					Size = UDim2.new(1, -2, 1, -2),
					Position = UDim2.new(0, 1, 0, 1),
					ZIndex = 4,
					Parent = BoxOuter,
				})

				Library:AddToRegistry(BoxInner, {
					BackgroundColor3 = "InnerBoxColor",
				})

				Library:StyleSurface(BoxOuter, 4, 0.55)
				if Library.Appearance then Library.Appearance:RegisterSurface(BoxOuter, "InnerBoxColor") end
				BoxInner.BackgroundTransparency = 1
				BoxInner.BorderSizePixel = 0

				local GroupboxLabel = Library:CreateLabel({
					Size = UDim2.new(1, -GroupInset * 2, 0, 18),
					Position = UDim2.new(0, GroupInset, 0, 7),
					TextSize = 13,
					Text = Info.Name,
					TextTruncate = Enum.TextTruncate.AtEnd,
					TextXAlignment = Enum.TextXAlignment.Left,
					ZIndex = 5,
					Parent = BoxInner,
				})

				local Container = Library:Create("Frame", {
					BackgroundTransparency = 1,
					Position = UDim2.new(0, GroupInset, 0, GroupHeaderHeight),
					Size = UDim2.new(1, -GroupInset * 2, 1, -GroupHeaderHeight),
					ZIndex = 1,
					Parent = BoxInner,
				})

				Library:Create("UIListLayout", {
					FillDirection = Enum.FillDirection.Vertical,
					SortOrder = Enum.SortOrder.LayoutOrder,
					Parent = Container,
				})

				function Groupbox:Resize()
					local Size = 0

					for _, Element in next, Groupbox.Container:GetChildren() do
						if (not Element:IsA("UIListLayout")) and Element.Visible then
							Size = Size + Element.Size.Y.Offset
						end
					end

					BoxOuter.Size = UDim2.new(1, -2, 0, GroupHeaderHeight + Size + 6)
				end

				Groupbox.Outer, Groupbox.TitleLabel = BoxOuter, GroupboxLabel
				function Groupbox:SetStatus(Text, Active)
					if not self.StatusLabel then
						GroupboxLabel.Size = UDim2.new(1, -(77 + GroupInset * 2 + 5), 0, 18)
						GroupboxLabel.TextTruncate = Enum.TextTruncate.AtEnd
						self.StatusLabel = Library:CreateLabel({ Text = "", Size = UDim2.fromOffset(77, 18),
							Position = UDim2.new(1, -(77 + GroupInset), 0, 7), TextSize = 11, TextXAlignment = Enum.TextXAlignment.Right,
							ZIndex = 5, Parent = BoxInner })
					end
					if self.StatusLabel.Text == Text then return end
					self.StatusLabel.Text = Text
					self.StatusLabel.TextTransparency = Active and 0 or 0.4
					local color = Active and "AccentColor" or "FontColor"
					self.StatusLabel.TextColor3 = Library[color]
					Library.RegistryMap[self.StatusLabel].Properties.TextColor3 = color
				end
				if Info.Category then
					table.insert(Info.Category.Boxes, Groupbox)
					BoxOuter.Visible = Tab.ActiveCategory == Info.Category.Name
				end
				Groupbox.Container = Container
				setmetatable(Groupbox, BaseGroupbox)

				Groupbox:AddBlank(3)
				Groupbox:Resize()

				Tab.GroupboxCount = Tab.GroupboxCount + 1
				Tab.Groupboxes[Info.Name] = Groupbox

				return Groupbox
			end

			Tab.Categories = {}
			local HeaderHeight = 0
			local CategoryBar
			local CategoryLine
			local CategoryButtons = {}
			local CategoryHeight = 30
			local function moveCategoryIndicator(animate)
				local selected = Tab.Categories[Tab.ActiveCategory]
				if not selected then return end
				local button = selected.Button
				-- Relative geometry follows window resize/scale without per-frame layout reads.
				local goals = { Position = UDim2.new(button.Position.X.Scale, button.Position.X.Offset, 1, -2),
					Size = UDim2.new(button.Size.X.Scale, button.Size.X.Offset, 0, 2) }
				if animate and CategoryLine.Visible then Library:Animate(CategoryLine, goals, 0.2)
				else
					local motion = Library.Motion[CategoryLine]
					local remaining
					if motion then
						remaining = table.clone(motion.goals)
						remaining.Position, remaining.Size = nil, nil
						motion.connection:Disconnect(); motion.tween:Cancel(); Library.Motion[CategoryLine] = nil
					end
					for key, value in pairs(goals) do CategoryLine[key] = value end
					if remaining and next(remaining) then Library:Animate(CategoryLine, remaining) end
				end
				CategoryLine.Visible = true
			end
			local function layoutCategories()
				local top = 7 + HeaderHeight + (CategoryBar and CategoryHeight + 8 or 0)
				for _, side in ipairs({ LeftSide, RightSide }) do
					side.Position = UDim2.new(side.Position.X.Scale, side.Position.X.Offset, 0, top)
					side.Size = UDim2.new(side.Size.X.Scale, side.Size.X.Offset, 1, -top - 7)
				end
				if CategoryBar then CategoryBar.Position = UDim2.fromOffset(7, 7 + HeaderHeight) end
			end

			function Tab:AddHeaderGroupbox(Name, Compact)
				local Holder = Library:Create("Frame", { BackgroundTransparency = 1,
					Position = UDim2.fromOffset(7, 7), Size = UDim2.new(1, -14, 0, 0), Parent = TabFrame })
				local Box = self:AddGroupbox({ Name = Name, Parent = Holder })
				if Compact then
					Box.Outer.BackgroundTransparency = 1
					Box.Outer.AeroOutline.Transparency = 1
					Box.TitleLabel.Visible = false
					Box.Container.Position = UDim2.fromOffset(0, 0)
					Box.Container.Size = UDim2.new(1, 0, 1, 0)
				end
				local resize = Box.Resize
				function Box:Resize()
					resize(self)
					if Compact then self.Outer.Size = UDim2.new(1, 0, 0, math.max(24, self.Outer.Size.Y.Offset - GroupHeaderHeight)) end
					HeaderHeight = self.Outer.Size.Y.Offset + 8
					Holder.Size = UDim2.new(1, -14, 0, HeaderHeight - 8)
					layoutCategories()
				end
				Box:Resize()
				return Box
			end

			function Tab:AddCategory(Name)
				if not CategoryBar then
					CategoryBar = Library:Create("Frame", { Name = "Categories", BackgroundColor3 = Library.InnerBoxColor,
						BorderColor3 = Library.OutlineColor, BackgroundTransparency = 0.24,
						Size = UDim2.new(1, -14, 0, CategoryHeight), ZIndex = 3, Parent = TabFrame })
					Library:AddToRegistry(CategoryBar, { BackgroundColor3 = "InnerBoxColor", BorderColor3 = "OutlineColor" })
					Library:StyleSurface(CategoryBar, 6, 0.65)
					CategoryLine = Library:Create("Frame", { Name = "ActiveCategoryLine", BackgroundColor3 = Library.AccentColor,
						BorderSizePixel = 0, Size = UDim2.fromOffset(0, 2), Visible = false, ZIndex = 6, Parent = CategoryBar })
					Library:AddToRegistry(CategoryLine, { BackgroundColor3 = "AccentColor" })
					Tab.CategoryIndicator = CategoryLine
					if Library.Appearance then Library.Appearance:AddGradient(CategoryLine) end
					layoutCategories()
				end
				local Category = { Name = Name, Boxes = {}, Count = 0, Scroll = { left = Vector2.zero, right = Vector2.zero } }
				local Button = Library:Create("TextButton", { Name = "CategoryButton", Text = Name, FontFace = Library.Font, TextSize = 12,
					TextColor3 = Library.FontColor, AutoButtonColor = false, BackgroundColor3 = Library.MainColor,
					BackgroundTransparency = 1, BorderSizePixel = 0, TextTransparency = 0.35,
					BorderColor3 = Library.OutlineColor, ZIndex = 5, Parent = CategoryBar })
				Library:AddToRegistry(Button, { TextColor3 = "FontColor", BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
				Library:StyleSurface(Button, 5, 0.7)
				Category.Button = Button
				Category.SetActiveBorder = Library:BindControlBorder(Button)
				Button.MouseEnter:Connect(function()
					Library:Animate(Button, { TextTransparency = 0, BackgroundTransparency = Tab.ActiveCategory == Name and 0.08 or 0.55 }, 0.12)
				end)
				Button.MouseLeave:Connect(function()
					local active = Tab.ActiveCategory == Name
					Library:Animate(Button, { TextTransparency = active and 0 or 0.35, BackgroundTransparency = active and 0.08 or 1 }, 0.12)
				end)
				function Category:Show(skipScrollRestore)
					if Tab.ActiveCategory ~= Name then
						local previous = Tab.Categories[Tab.ActiveCategory]
						if previous then previous.Scroll = { left = LeftSide.CanvasPosition, right = RightSide.CanvasPosition } end
						Library.Interface:CloseInputs()
						Tab.ActiveCategory = Name
						for key, item in pairs(Tab.Categories) do
							for _, box in ipairs(item.Boxes) do box.Outer.Visible = key == Name end
							item.SetActiveBorder(key == Name)
							local color = key == Name and "AccentColor" or "FontColor"
							item.Button.TextColor3 = Library[color]
							Library.RegistryMap[item.Button].Properties.TextColor3 = color
							Library:Animate(item.Button, { TextTransparency = key == Name and 0 or 0.35,
								BackgroundTransparency = key == Name and 0.08 or 1 }, 0.14)
						end
						moveCategoryIndicator(true)
						local scroll = self.Scroll
						Tab.CategoryEpoch = (Tab.CategoryEpoch or 0) + 1
						local epoch = Tab.CategoryEpoch
						if not skipScrollRestore then task.defer(function()
							RenderStepped:Wait()
							if Tab.CategoryEpoch ~= epoch or Tab.ActiveCategory ~= Name then return end
							for side, offset in pairs({ [LeftSide] = scroll.left, [RightSide] = scroll.right }) do
								local maximum = math.max(0, side.CanvasSize.Y.Offset - side.AbsoluteSize.Y / Library.UIScale)
								side.CanvasPosition = Vector2.new(0, math.clamp(offset.Y, 0, maximum))
							end
						end) end
					end
					if Library.Appearance then Library.Appearance:QueueVisible() end
				if Tab.RefreshStatuses then Tab:RefreshStatuses() end
				end
				function Category:AddGroupbox(Info)
					Info.Category = self
					self.Count = self.Count + 1
					return Tab:AddGroupbox(Info)
				end
				function Category:AddDynamicGroupbox(Title)
					return self:AddGroupbox({ Name = Title, Side = self.Count % 2 + 1 })
				end
				Button.Activated:Connect(function() Category:Show() end)
				Tab.Categories[Name] = Category
				CategoryButtons[#CategoryButtons + 1] = Button
				for index, child in ipairs(CategoryButtons) do
					child.Position = UDim2.new((index - 1) / #CategoryButtons, 0, 0, 0)
					child.Size = UDim2.new(1 / #CategoryButtons, -3, 1, 0)
				end
				moveCategoryIndicator(false)
				local pending = Window.PendingInterface and Window.PendingInterface.categories[Tab.Name]
				if not Tab.ActiveCategory or pending == Name then Category:Show(pending == Name) end
				return Category
			end

			local function useFullWidth()
				LeftSide.Size = UDim2.new(1, -14, 1, -14)
				RightSide.Visible = false
			end

			function Tab:AddFullGroupbox(Name)
				useFullWidth()
				return Tab:AddLeftGroupbox(Name)
			end

			function Tab:AddFullTabbox(Name)
				useFullWidth()
				return Tab:AddLeftTabbox(Name)
			end

			function Tab:AddDynamicGroupbox(Name)
				if (Tab.GroupboxCount + Tab.TabboxCount) % 2 == 0 then
					return Tab:AddLeftGroupbox(Name)
				else
					return Tab:AddRightGroupbox(Name)
				end
			end

			function Tab:AddLeftGroupbox(Name)
				return Tab:AddGroupbox({ Side = 1, Name = Name })
			end

			function Tab:AddRightGroupbox(Name)
				return Tab:AddGroupbox({ Side = 2, Name = Name })
			end

			function Tab:AddTabbox(Info)
				local OwnerTab = Tab
				local Key = Info.StateKey or (Tab.Name .. "/" .. tostring(Info.Side) .. "/" .. (Info.Name or tostring(Tab.TabboxCount + 1)))
				local Tabbox = {
					Tabs = {},
				}

				local BoxOuter = Library:Create("Frame", {
					BackgroundColor3 = Library.InnerBoxColor,
					BorderColor3 = Library.OutlineColor,
					BorderMode = Enum.BorderMode.Inset,
					Position = UDim2.fromOffset(1, 1), Size = UDim2.new(1, -2, 0, 0),
					ZIndex = 2,
