				Library:AddToRegistry(BoxOuter, {
					BackgroundColor3 = "InnerBoxColor",
					BorderColor3 = "OutlineColor",
				})

				local BoxInner = Library:Create("Frame", {
					BackgroundColor3 = Library.InnerBoxColor,
					BorderColor3 = Color3.new(0, 0, 0),
					-- BorderMode = Enum.BorderMode.Inset;
					Size = UDim2.new(1, -2, 1, -2),
					Position = UDim2.new(0, 1, 0, 1),
					ZIndex = 4,
					Parent = BoxOuter,
				})

				Library:AddToRegistry(BoxInner, {
					BackgroundColor3 = "InnerBoxColor",
				})

				Library:StyleSurface(BoxOuter, 4, 0.55)
				if Library.Appearance then Library.Appearance:RegisterSurface(BoxOuter, "InnerBoxColor") end
				BoxInner.BackgroundTransparency = 1
				BoxInner.BorderSizePixel = 0

				local TabboxButtons = Library:Create("Frame", {
					BackgroundTransparency = 1,
					Position = UDim2.fromOffset(GroupInset, 5),
					Size = UDim2.new(1, -GroupInset * 2, 0, GroupHeaderHeight - 6),
					ZIndex = 5,
					Parent = BoxInner,
				})

				Library:Create("UIListLayout", {
					FillDirection = Enum.FillDirection.Horizontal,
					HorizontalAlignment = Enum.HorizontalAlignment.Left,
					SortOrder = Enum.SortOrder.LayoutOrder,
					Parent = TabboxButtons,
				})

				Window.Tabboxes[Key] = Tabbox
				local function layoutButtons()
					local total = 0
					for _, item in pairs(Tabbox.Tabs) do total = total + item.ButtonWidth end
					local available = math.max(1, TabboxButtons.AbsoluteSize.X / Library.UIScale)
					local factor = total > available and available / total or 1
					for _, item in pairs(Tabbox.Tabs) do
						item.Button.Size = UDim2.new(0, item.ButtonWidth * factor, 1, 0)
					end
				end
				TabboxButtons:GetPropertyChangedSignal("AbsoluteSize"):Connect(layoutButtons)

				function Tabbox:AddTab(Name)
					local Tab = { Name = Name, OwnerTab = OwnerTab }

					local Button = Library:Create("Frame", {
						BackgroundColor3 = Library.MainColor,
						BorderColor3 = Color3.new(0, 0, 0),
						BackgroundTransparency = 1, BorderSizePixel = 0,
						Size = UDim2.new(0, 0, 1, 0),
						ZIndex = 6,
						Parent = TabboxButtons,
					})

					Library:AddToRegistry(Button, {
						BackgroundColor3 = "MainColor",
					})

					local ButtonLabel = Library:CreateLabel({
						Size = UDim2.new(1, 0, 1, 0),
						TextSize = 12,
						Text = Name,
						TextTruncate = Enum.TextTruncate.AtEnd,
						TextXAlignment = Enum.TextXAlignment.Left,
						ZIndex = 7,
						Parent = Button,
					})

					Tab.Button = Button
					Tab.ButtonWidth = Library:GetTextBounds(Name, Library.Font, 12) + 12
					local Block = Library:Create("Frame", {
						BackgroundColor3 = Library.InnerBoxColor,
						BorderSizePixel = 0,
						Position = UDim2.new(0, 0, 1, 0),
						Size = UDim2.new(1, 0, 0, 1),
						Visible = false,
						ZIndex = 9,
						Parent = Button,
					})

					Library:AddToRegistry(Block, {
						BackgroundColor3 = "InnerBoxColor",
					})

					local Container = Library:Create("Frame", {
						BackgroundTransparency = 1,
						Position = UDim2.new(0, GroupInset, 0, GroupHeaderHeight),
						Size = UDim2.new(1, -GroupInset * 2, 1, -GroupHeaderHeight),
						ZIndex = 1,
						Visible = false,
						Parent = BoxInner,
					})

					Library:Create("UIListLayout", {
						FillDirection = Enum.FillDirection.Vertical,
						SortOrder = Enum.SortOrder.LayoutOrder,
						Parent = Container,
					})

					function Tab:Show()
						Tabbox.ActiveTab = Name
						for _, Tab in next, Tabbox.Tabs do
							Tab:Hide()
						end

						Container.Visible = true
						Block.Visible = false
						ButtonLabel.TextColor3 = Library.AccentColor
						ButtonLabel.TextTransparency = 0
						Library.RegistryMap[ButtonLabel].Properties.TextColor3 = "AccentColor"

						Button.BackgroundColor3 = Library.InnerBoxColor
						Library.RegistryMap[Button].Properties.BackgroundColor3 = "InnerBoxColor"

						Tab:Resize()
					end

					function Tab:Hide()
						ButtonLabel.TextColor3 = Library.FontColor
						ButtonLabel.TextTransparency = 0.35
						Library.RegistryMap[ButtonLabel].Properties.TextColor3 = "FontColor"
						Container.Visible = false
						Block.Visible = false

						Button.BackgroundColor3 = Library.MainColor
						Library.RegistryMap[Button].Properties.BackgroundColor3 = "MainColor"
					end

					function Tab:Resize()
						layoutButtons()

						if not Container.Visible then
							return
						end

						local Size = 0

						for _, Element in next, Tab.Container:GetChildren() do
							if (not Element:IsA("UIListLayout")) and Element.Visible then
								Size = Size + Element.Size.Y.Offset
							end
						end

						BoxOuter.Size = UDim2.new(1, -2, 0, GroupHeaderHeight + Size + 6)
					end

					Button.InputBegan:Connect(function(Input)
						if
							Input.UserInputType == Enum.UserInputType.MouseButton1
							and not Library:MouseIsOverOpenedFrame()
						then
							Tab:Show()
							Tab:Resize()
						end
					end)

					Tab.Container = Container
					Tabbox.Tabs[Name] = Tab

					setmetatable(Tab, BaseGroupbox)

					Tab:AddBlank(3)
					Tab:Resize()

					-- Show first tab (number is 2 cus of the UIListLayout that also sits in that instance)
					if #TabboxButtons:GetChildren() == 2 then
						Tab:Show()
					end

					if Window.PendingInterface and Window.PendingInterface.subtabs[Key] == Name then Tab:Show() end
					return Tab
				end

				Tab.Tabboxes[Info.Name or ""] = Tabbox
				Tab.TabboxCount = Tab.TabboxCount + 1

				return Tabbox
			end

			function Tab:AddLeftTabbox(Name)
				return Tab:AddTabbox({ Name = Name, Side = 1 })
			end

			function Tab:AddRightTabbox(Name)
				return Tab:AddTabbox({ Name = Name, Side = 2 })
			end

			function Tab:AddDynamicTabbox(Name)
				if (Tab.GroupboxCount + Tab.TabboxCount) % 2 == 0 then
					return Tab:AddLeftTabbox(Name)
				else
					return Tab:AddRightTabbox(Name)
				end
			end

			TabButton.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					Window.UserTabIntent = true
					Tab:ShowTab()
				end
			end)

			-- This was the first tab added, so we show it by default.
			if #TabContainer:GetChildren() == 1 then
				Tab:ShowTab()
			end

			Tab.LeftSide, Tab.RightSide = LeftSide, RightSide
			Window.Tabs[Name] = Tab
			Library.Interface:RestoreTab(Name)
			return Tab
		end

		local ModalElement = Library:Create("TextButton", {
			BackgroundTransparency = 1,
			Size = UDim2.new(0, 0, 0, 0),
			Visible = true,
			Text = "",
			Modal = false,
			Parent = ScreenGui,
		})

		local TransparencyCache = setmetatable({}, { __mode = "k" })
		local Fading = false
		local fadeEpoch = 0
		function Window:SetSurfaceTransparency(object, value)
			local cached = TransparencyCache[object]
			if cached then cached.BackgroundTransparency = value end
			local motion = Library.Motion[object]
			if Fading and Toggled and motion and motion.goals.BackgroundTransparency ~= nil then
				local goals = table.clone(motion.goals)
				goals.BackgroundTransparency = value
				Library:Animate(object, goals, Config.MenuFadeTime)
			elseif not Fading or Toggled then
				object.BackgroundTransparency = value
			end
		end

		function Library:Toggle()
			local FadeTime = Config.MenuFadeTime
			local ShouldFade = FadeTime > 0.01
			local wasFading = Fading
			Fading = ShouldFade
			fadeEpoch = fadeEpoch + 1
			local epoch = fadeEpoch

			Toggled = not Toggled
			ModalElement.Modal = Toggled

			if Toggled then
				Outer.Visible = true
			end

			if not Toggled then
				Library.Interface:Close()
				Library.Interface:CloseInputs()
				for _, ColorPicker in next, ColorPickers do
					ColorPicker:Hide()
				end

				for _, ContextMenu in next, ContextMenus do
					ContextMenu:Hide()
				end

				for _, Tooltip in next, Tooltips do
					Tooltip.Visible = false
				end

				for _, ModeSelectFrame in next, ModeSelectFrames do
					ModeSelectFrame.Visible = false
				end
			end

			if ShouldFade then
				local descendants = Outer:GetDescendants()
				table.insert(descendants, Outer)
				for _, Desc in next, descendants do
					local Properties = {}

					if Desc:IsA("ImageLabel") or Desc:IsA("ImageButton") then
						table.insert(Properties, "ImageTransparency")
						table.insert(Properties, "BackgroundTransparency")
					elseif Desc:IsA("TextLabel") or Desc:IsA("TextBox") or Desc:IsA("TextButton") then
						table.insert(Properties, "TextTransparency")
						table.insert(Properties, "BackgroundTransparency")
					elseif Desc:IsA("Frame") or Desc:IsA("ScrollingFrame") then
						table.insert(Properties, "BackgroundTransparency")
					elseif Desc:IsA("UIStroke") then
						table.insert(Properties, "Transparency")
					end

					if #Properties > 0 then
						local Cache = TransparencyCache[Desc]
						if not Cache then
							Cache = {}
							TransparencyCache[Desc] = Cache
						end
						local goals = {}
						for _, Prop in next, Properties do
							if Cache[Prop] == nil or (not Toggled and not wasFading) then
								Cache[Prop] = Desc[Prop]
							end
							if Toggled and not wasFading and Desc[Prop] ~= 1 then
								Desc[Prop] = 1
							end
							goals[Prop] = Toggled and Cache[Prop] or 1
						end
						Library:Animate(Desc, goals, FadeTime)
					end
				end
				task.delay(FadeTime, function()
					if epoch ~= fadeEpoch or not Outer.Parent then return end
					Outer.Visible = Toggled
					Fading = false
				end)
			else
				Outer.Visible = Toggled
			end
		end

		Library:GiveSignal(InputService.InputBegan:Connect(function(Input, Processed)
			if type(Library.ToggleKeybind) == "table" and Library.ToggleKeybind.Type == "KeyPicker" then
				if
					Input.UserInputType == Enum.UserInputType.Keyboard
					and Input.KeyCode.Name == Library.ToggleKeybind.Value
				then
					Window.UserTabIntent = true
					task.spawn(Library.Toggle)
				end
			elseif
				Input.KeyCode == Enum.KeyCode.RightControl
				or (Input.KeyCode == Enum.KeyCode.RightShift and not Processed)
			then
				Window.UserTabIntent = true
				task.spawn(Library.Toggle)
			end
		end))

		if Config.AutoShow then
			task.spawn(Library.Toggle)
		end

		Window.Holder = Outer
		if Library.Appearance then Library.Appearance:Attach(Window) end
		Library.Interface:Attach(Window, Outer)

		if not Library.ArrayListController then
			Library.ArrayListController = require("GUI/EnabledList")(Library)
		end
		return Window
	end

	local function OnPlayerChange()
		local PlayerList = GetPlayersString()

		for _, Value in next, Options do
			if Value.Type == "Dropdown" and Value.SpecialType == "Player" then
				Value:SetValues(PlayerList)
			end
		end
	end

	Players.PlayerAdded:Connect(OnPlayerChange)
	Players.PlayerRemoving:Connect(OnPlayerChange)

	require("GUI/Appearance")(Library)
	require("GUI/Notifications")(Library, Options)
	require("GUI/Cursor")(Library, CoreGuiManager)
	for _,frame in ipairs({Library.Watermark, Library.InfoLoggerFrame, Library.KeybindFrame}) do
		Library.Cursor:WatchWidget(frame)
	end

	getgenv().Library = Library
	return Library
end)()

end)
__bundle_register("GUI/Cursor", function(require, _LOADED, __bundle_register, __bundle_modules)
-- High-layer cursor for Aero's menu and draggable widgets; idle when they are not in use.
return function(library, coreGuiManager)
 local input=game:GetService("UserInputService")
 local gui=coreGuiManager.imark(Instance.new("ScreenGui"))
 gui.Name="AeroCursor";gui.IgnoreGuiInset=true;gui.ResetOnSpawn=false;gui.DisplayOrder=100001;gui.Enabled=false
 gui.ZIndexBehavior=Enum.ZIndexBehavior.Global
 local arrow=library:Create("Frame",{Name="Pointer",BackgroundTransparency=1,BorderSizePixel=0,
  Size=UDim2.fromOffset(18,22),ZIndex=1,Parent=gui})
 -- Small pixel arrow: black edge and white interior, with no external image dependency.
 for y=0,13 do
  local width=math.floor(y*0.72)+3
  library:Create("Frame",{BackgroundColor3=Color3.new(0,0,0),BorderSizePixel=0,
   Position=UDim2.fromOffset(0,y),Size=UDim2.fromOffset(width,1),ZIndex=2,Parent=arrow})
  if y>1 and width>3 then library:Create("Frame",{BackgroundColor3=Color3.new(1,1,1),BorderSizePixel=0,
   Position=UDim2.fromOffset(1,y),Size=UDim2.fromOffset(width-2,1),ZIndex=3,Parent=arrow}) end
 end
 library:Create("Frame",{BackgroundColor3=Color3.new(0,0,0),BorderSizePixel=0,
  Position=UDim2.fromOffset(6,11),Size=UDim2.fromOffset(5,9),Rotation=-25,ZIndex=2,Parent=arrow})
 library:Create("Frame",{BackgroundColor3=Color3.new(1,1,1),BorderSizePixel=0,
  Position=UDim2.fromOffset(7,11),Size=UDim2.fromOffset(3,8),Rotation=-25,ZIndex=3,Parent=arrow})
 local pointer={gui=gui,arrow=arrow,widgets=setmetatable({}, {__mode="k"})}
 local watched=setmetatable({}, {__mode="k"})
 local connections={}
 local moving,priorIcon,alive=nil,nil,true
 local function connect(signal,fn) local c=signal:Connect(fn);connections[#connections+1]=c;return c end
 local function effectiveVisible(frame)
  local node=frame
  while node do
   if (node:IsA("GuiObject") and not node.Visible) or (node:IsA("ScreenGui") and node.Enabled==false) then return false end
   node=node.Parent
  end
  return frame.Parent~=nil
 end
 local function place()
  local point=input:GetMouseLocation();arrow.Position=UDim2.fromOffset(point.X,point.Y)
 end
 local function update()
  if not alive then return end
  local active=pointer.menu and effectiveVisible(pointer.menu) or false
  if not active then for frame,hover in pairs(pointer.widgets) do if hover and effectiveVisible(frame) then active=true;break end end end
  active=active and input.MouseEnabled~=false
  if active and not gui.Enabled then
   priorIcon=input.MouseIconEnabled;input.MouseIconEnabled=false
   gui.Enabled=true;place()
   moving=input.InputChanged:Connect(function(event) if event.UserInputType==Enum.UserInputType.MouseMovement then place() end end)
  elseif not active and gui.Enabled then
   gui.Enabled=false
   if moving then moving:Disconnect();moving=nil end
   if input.MouseIconEnabled==false and priorIcon~=nil then input.MouseIconEnabled=priorIcon end
   priorIcon=nil
  end
 end
 function pointer:WatchMenu(frame)
  self.menu=frame
  connect(frame:GetPropertyChangedSignal("Visible"),update)
  connect(library.ScreenGui:GetPropertyChangedSignal("Enabled"),update)
  update()
 end
 function pointer:WatchWidget(frame)
  if watched[frame] then return end
  watched[frame]=true;self.widgets[frame]=false
  connect(frame.MouseEnter,function() self.widgets[frame]=true;update() end)
  connect(frame.MouseLeave,function() self.widgets[frame]=false;update() end)
  connect(frame:GetPropertyChangedSignal("Visible"),function() if not frame.Visible then self.widgets[frame]=false end;update() end)
  local node=frame.Parent
  while node do
   if node:IsA("ScreenGui") then
    local screen=node
    connect(screen:GetPropertyChangedSignal("Enabled"),function() if not screen.Enabled then self.widgets[frame]=false end;update() end)
    break
   end
   node=node.Parent
  end
