  if not alive then return end
  pointer.menu=nil;table.clear(pointer.widgets);update();alive=false
  if moving then moving:Disconnect();moving=nil end
  for _,connection in ipairs(connections) do connection:Disconnect() end
  gui:Destroy()
 end})
 library.Cursor=pointer
 return pointer
end

end)
__bundle_register("GUI/Notifications", function(require, _LOADED, __bundle_register, __bundle_modules)
return function(library, options)
	options = options or Options or {}
	local active, refreshers = {}, {}
	local sequence = 0
	local function escape(text)
		return tostring(text):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"):gsub('"', "&quot;")
	end
	function library:FormatWatermarkText()
		local text = self.WatermarkPlainText or ""
		local name, rest = text:match("^(.-)( |.*)$")
		return '<font color="#' .. self.AccentColor:ToHex() .. '">' .. escape(name or text) .. '</font>' .. escape(rest or "")
	end
	function library:SetWatermark(text)
		self.WatermarkPlainText = text
		self.WatermarkText.Text = self:FormatWatermarkText()
		local width, height = self:GetTextBounds(text, self.Font, 12)
		self.Watermark.Size = UDim2.fromOffset(math.min(width + 20, self:GetInterfaceViewport().X - 16), math.max(24, height + 10))
	end
	local watermarkRegistry = library.RegistryMap[library.WatermarkText]
	if watermarkRegistry then
		watermarkRegistry.Properties.Text = function() return library:FormatWatermarkText() end
		watermarkRegistry.Properties.TextColor3 = "FontColor"
		if library.HudRegistry and not table.find(library.HudRegistry, watermarkRegistry) then table.insert(library.HudRegistry, watermarkRegistry) end
	else
		library:AddToRegistry(library.WatermarkText, { Text = function() return library:FormatWatermarkText() end, TextColor3 = "FontColor" }, true)
	end

	local function measure(text)
		local scale = math.clamp(tonumber(options.NotificationScale and options.NotificationScale.Value) or 100, 50, 300) / 100
		local maximum = math.max(40, math.min(520 * scale, library:GetInterfaceViewport().X - 16))
		local width, height = library:GetTextBounds(text, library.Font, 12 * scale, Vector2.new(math.max(1, maximum - 20 * scale), 100000))
		width, height = math.min(maximum, width + 20 * scale), height + 14 * scale
		return width, height, scale
	end
	function library:RefreshNotifications()
		for _, refresh in pairs(refreshers) do refresh() end
		if self.Interface then self.Interface:RenderNotificationHistory() end
	end
	local function create(text, duration)
		local state = shared.Aero or shared.Lycoris
		if state and state.silent then return end
		if library.Interface then library.Interface:RecordNotification(text) end
		local width, height, scale = measure(text)
		sequence = sequence + 1
		local outer = library:Create("Frame", { Name = "Notification", BackgroundTransparency = 1, BorderSizePixel = 0,
			Size = UDim2.fromOffset(0, height), ClipsDescendants = true, LayoutOrder = sequence, ZIndex = 100, Parent = library.NotificationArea })
		local inner = library:Create("Frame", { Name = "NotificationBody", BackgroundColor3 = library.BackgroundColor,
			BorderSizePixel = 0, Size = UDim2.fromOffset(width, height), ZIndex = 101, Parent = outer })
		library:AddToRegistry(inner, { BackgroundColor3 = "BackgroundColor" }, true)
		local label = library:CreateLabel({ Text = text, TextSize = 12 * scale, TextStrokeTransparency = 1, TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center,
			Position = UDim2.fromOffset(10 * scale, 0), Size = UDim2.new(1, -20 * scale, 1, 0), ZIndex = 102, Parent = inner }, true)
		local accent = library:Create("Frame", { Name = "NotificationAccent", BackgroundColor3 = library.AccentColor, BorderSizePixel = 0,
			Size = UDim2.new(0, 3, 1, 0), ZIndex = 103, Parent = inner })
		library:AddToRegistry(accent, { BackgroundColor3 = "AccentColor" }, true)
		local closed = false
		local tweenTime = duration and duration < 1.1 and 0.1 or 0.2
		local function resize(target)
			local ok, accepted = pcall(function()
				return outer:TweenSize(target, "Out", "Quad", tweenTime, true)
			end)
			if not ok or accepted == false then outer.Size = target end
		end
		local function close(immediate)
			if closed then return end
			closed = true
			active[outer], refreshers[outer] = nil, nil
			if immediate == true then outer:Destroy(); return end
			resize(UDim2.fromOffset(0, height))
			task.delay(tweenTime, function() outer:Destroy() end)
		end
		refreshers[outer] = function()
			width, height, scale = measure(text)
			inner.Size = UDim2.fromOffset(width, height)
			library:Create(label, { TextSize = 12 * scale, Position = UDim2.fromOffset(10 * scale, 0), Size = UDim2.new(1, -20 * scale, 1, 0) })
			outer.Size = UDim2.fromOffset(width, height)
		end
		active[outer] = close
		inner.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then close() end
		end)
		inner.MouseEnter:Connect(function()
			if game:GetService("UserInputService"):IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then close() end
		end)
		resize(UDim2.fromOffset(width, height))
		if duration then task.delay(duration, close) end
		return close
	end
	function library:ManuallyManagedNotify(text) return create(text) end
	function library:Notify(text, duration) create(text, duration or 5) end
	library:GiveSignal({ Disconnect = function()
		for _, close in pairs(active) do close(true) end
	end })
end

end)
__bundle_register("GUI/Appearance", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Menu typography and optional decoration; all animated work stops when hidden.
return function(library)
	local appearance = { texts = setmetatable({}, { __mode = "k" }), fontName = "Gotham", fontScale = 1,
		shadow = 100, shadowEnabled = true, shadowSize = 28, glowStrength = 40, glowSize = 16, glowUseAccent = true, glowColor = library.AccentColor, animated = false, effect = "Sweep", speed = 1, gradients = {}, visibleGradients = {}, phase = 0, glow = false }
	appearance.gradientColor = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
		ColorSequenceKeypoint.new(0.5, Color3.new(0.65, 0.65, 0.65)), ColorSequenceKeypoint.new(1, Color3.new(1, 1, 1)) })
	appearance.transparency = { BackgroundColor = 0, InnerBoxColor = 0, MainColor = 0 }
	appearance.surfaces = setmetatable({}, { __mode = "k" })
	library.Appearance = appearance
	local originalCreate = library.Create
	local function textObject(object)
		return object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")
	end
	function library:Create(class, properties)
		local object = originalCreate(self, class, properties)
		if textObject(object) then
			local base = properties.TextSize or appearance.texts[object] or object.TextSize
			appearance.texts[object] = base
			object.FontFace = self.Font
			object.TextSize = base * appearance.fontScale
		end
		return object
	end
	for _, object in ipairs(library.ScreenGui:GetDescendants()) do
		if textObject(object) then appearance.texts[object] = object.TextSize end
	end

	function appearance:RegisterSurface(object, key)
		self.surfaces[object] = key
		object.BackgroundTransparency = self.transparency[key] or 0
	end
	function appearance:SetTransparency(key, value)
		if self.transparency[key] == nil then return end
		value = math.clamp(value, 0, 1)
		if self.transparency[key] == value then return end
		self.transparency[key] = value
		for object, category in pairs(self.surfaces) do
			if category == key and object.Parent then
				if self.window and self.window.SetSurfaceTransparency then
					self.window:SetSurfaceTransparency(object, value)
				else object.BackgroundTransparency = value end
			end
		end
	end

	function appearance:SetFont(name, percent)
		self.fontName = name
		self.fontScale = math.clamp(percent / 100, 0.75, 1.25)
		library.Font = Font.fromEnum(Enum.Font[name])
		library.FontEnum = Enum.Font[name]
