__bundle_register("GUI/EnabledList", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Enabled-feature HUD for the classic UI. Keeps the existing configuration keys.
return function(library)
	local controller = { visible = false, background = true }
	local frame = library:Create("Frame", {
		Name = "EnabledFeatures",
		BackgroundTransparency = 1,
		Position = UDim2.new(1, -240, 0, 80),
		Size = UDim2.fromOffset(220, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
		Parent = library.ScreenGui,
	})
	library:Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 2),
		Parent = frame,
	})
	library:AddUIScale(frame)
	library:MakeDraggable(frame, math.huge)
	local rows = {}

	function controller:Refresh()
		if not self.visible then
			frame.Visible = false
			return
		end
		local active = {}
		for id, toggle in pairs(Toggles) do
			if toggle.Value and toggle.ArrayList ~= false then
				active[#active + 1] = { id = id, text = toggle.Text or id }
			end
		end
		table.sort(active, function(a, b)
			if a.text == b.text then return a.id < b.id end
			return a.text < b.text
		end)
		local present = {}
		for order, entry in ipairs(active) do
			present[entry.id] = true
			local row = rows[entry.id]
			if not row then
				row = library:CreateLabel({
					Name = "EnabledFeature", TextSize = 12,
					BackgroundColor3 = library.BackgroundColor,
					BackgroundTransparency = self.background and 0.18 or 1,
					Size = UDim2.new(1, 0, 0, 22),
					TextXAlignment = Enum.TextXAlignment.Right,
					Parent = frame,
				}, true)
				library:AddToRegistry(row, { BackgroundColor3 = "BackgroundColor", TextColor3 = "AccentColor" }, true)
				library:Create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = row })
				library:Create("UIPadding", { PaddingRight = UDim.new(0, 8), Parent = row })
				rows[entry.id] = row
			end
			row.Text = entry.text
			row.LayoutOrder = order
			row.BackgroundTransparency = self.background and 0.18 or 1
		end
		for id, row in pairs(rows) do
			if not present[id] then
				library:RemoveFromRegistry(row)
				row:Destroy()
				rows[id] = nil
			end
		end
		frame.Visible = #active > 0
	end

	function controller:SetVisible(value)
		self.visible = value
		self:Refresh()
	end

	function controller:SetBackgroundEnabled(value)
		self.background = value
		self:Refresh()
	end

	local elapsed = 0
	library:GiveSignal(game:GetService("RunService").Heartbeat:Connect(function(dt)
		elapsed = elapsed + dt
		if elapsed >= 0.15 then
			elapsed = 0
			controller:Refresh()
		end
	end))
	return controller
end

end)
__bundle_register("GUI/Interface", function(require, _LOADED, __bundle_register, __bundle_modules)
local Model = require("GUI/UIModel")

return function(library)
	local input = game:GetService("UserInputService")
	local runService = game:GetService("RunService")
	local guiService = game:GetService("GuiService")
	local interface = { entries = {}, order = {}, closers = {}, folds = {}, epoch = 0, notificationHistory = {}, unreadNotifications = 0 }
	library.Interface = interface
	library.ScaledObjects = setmetatable({}, { __mode = "k" })
	library.DragBlockers = setmetatable({}, { __mode = "k" })

	local function viewport()
		return workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
	end

	local function screenOrigin()
		if library.ScreenGui.IgnoreGuiInset then return Vector2.zero end
		return guiService:GetGuiInset()
	end

	function library:GetInterfaceViewport()
		return viewport() - screenOrigin()
	end

	function library:AddUIScale(instance)
		local scale = instance:FindFirstChild("AeroUIScale")
		if not scale then scale = self:Create("UIScale", { Name = "AeroUIScale", Parent = instance }) end
		scale.Scale = self.UIScale
		self.ScaledObjects[scale] = true
		return scale
	end

	function library:SetUIScale(value)
		if not Model.finite(value) then return end
		interface:EndResize(true)
		interface:EndDrag(true)
		self.UIScale = math.clamp(value, 0.65, 1.5)
		for scale in pairs(self.ScaledObjects) do
			if scale.Parent then scale.Scale = self.UIScale else self.ScaledObjects[scale] = nil end
		end
		if Options.InterfaceScale then Options.InterfaceScale:SetRawValue(self.UIScale * 100) end
		interface:FitWindow()
	end

	function library:IsOverDragBlocker(point, scope)
		point = point or input:GetMouseLocation() - screenOrigin()
		for frame in pairs(self.DragBlockers) do
			if frame.Parent and frame.Visible then
				local visible, inScope, node = true, scope == nil or frame == scope, frame.Parent
				while node do
					if node == scope then inScope=true end
					if (node:IsA("GuiObject") and not node.Visible) or (node:IsA("ScreenGui") and node.Enabled == false) then visible=false;break end
					node=node.Parent
				end
				if visible and inScope then
					local p, s = frame.AbsolutePosition, frame.AbsoluteSize
					if point.X >= p.X and point.X <= p.X + s.X and point.Y >= p.Y and point.Y <= p.Y + s.Y then return true end
				end
			end
		end
		return false
	end

	function interface:SetInteracting()
		if library.Appearance then library.Appearance.interacting = self.drag ~= nil or self.resize ~= nil; library.Appearance:UpdateAnimation() end
	end

	function interface:ApplyDrag()
		local drag = self.drag
		if not drag then return end
		if not drag.frame.Parent or not drag.frame.Visible then self:EndDrag(true); return end
		local delta = drag.pending - drag.point
		local x = math.clamp(drag.topLeft.X + delta.X, 0, math.max(0, drag.area.X - drag.size.X))
		local y = math.clamp(drag.topLeft.Y + delta.Y, 0, math.max(0, drag.area.Y - drag.size.Y))
		if drag.lastX == x and drag.lastY == y then return end
		drag.lastX, drag.lastY = x, y
		drag.frame.Position = UDim2.fromOffset(x + drag.size.X * drag.frame.AnchorPoint.X, y + drag.size.Y * drag.frame.AnchorPoint.Y)
	end
	function interface:EndDrag(cancel)
		if not cancel and self.drag then self:ApplyDrag() end
		if self.dragConnection then self.dragConnection:Disconnect(); self.dragConnection = nil end
		self.drag = nil
		self:SetInteracting()
	end
	function interface:BindDrag(frame, cutoff)
		frame.Active = true
		frame.InputBegan:Connect(function(event)
			if event.UserInputType ~= Enum.UserInputType.MouseButton1 and event.UserInputType ~= Enum.UserInputType.Touch then return end
			if self.drag or self.resize or not frame.Visible then return end
			local touch = event.UserInputType == Enum.UserInputType.Touch and event or nil
			local point = touch and (Vector2.new(event.Position.X, event.Position.Y) - screenOrigin()) or input:GetMouseLocation() - screenOrigin()
			if (frame == self.outer and library:IsOverDragBlocker(point)) or library:IsOverDragBlocker(point, frame) then return end
			local p, size = frame.AbsolutePosition, frame.AbsoluteSize
			local scale = frame:FindFirstChild("AeroUIScale") and library.UIScale or 1
			if point.Y < p.Y or point.Y > p.Y + cutoff * scale then return end
			self:Close(); self:CloseInputs()
			self.drag = { frame = frame, touch = touch, point = point, pending = point, size = size,
				topLeft = p, area = library:GetInterfaceViewport(), lastX = p.X, lastY = p.Y }
			self:SetInteracting()
			self.dragConnection = runService.RenderStepped:Connect(function() self:ApplyDrag() end)
		end)
		frame:GetPropertyChangedSignal("Visible"):Connect(function()
			if not frame.Visible and self.drag and self.drag.frame == frame then self:EndDrag(true) end
		end)
	end
	library:GiveSignal(input.InputChanged:Connect(function(event)
		local drag = interface.drag
		if not drag then return end
		if drag.touch then
			if event == drag.touch then drag.pending = Vector2.new(event.Position.X, event.Position.Y) - screenOrigin() end
		elseif event.UserInputType == Enum.UserInputType.MouseMovement then drag.pending = input:GetMouseLocation() - screenOrigin() end
	end))
	library:GiveSignal(input.InputEnded:Connect(function(event)
		local drag = interface.drag
		if drag and ((drag.touch and event == drag.touch) or (not drag.touch and event.UserInputType == Enum.UserInputType.MouseButton1)) then interface:EndDrag() end
	end))
	library:GiveSignal(input.WindowFocusReleased:Connect(function() interface:EndDrag() end))

	function interface:RegisterInputCloser(close)
		self.closers[#self.closers + 1] = close
	end

	function interface:CloseInputs()
		for _, close in ipairs(self.closers) do close() end
	end

	function interface:Register(groupbox, kind, id, text, frame, tooltip)
		if not groupbox or not frame or type(text) ~= "string" or text == "" then return end
		local owner = groupbox.OwnerTab
		if not owner then return end
		local path = owner.Name .. " / " .. (groupbox.Name or "")
		local key = kind .. ":" .. (id and tostring(id) or path .. "/" .. text)
		if not self.entries[key] then self.order[#self.order + 1] = key end
		self.sortedEntries = nil
		self.entries[key] = { id = key, text = text, path = path, groupbox = groupbox,
			frame = frame, search = text .. " " .. path .. " " .. (tooltip or "") }
		if self.panel and self.panel.Visible and not self.renderQueued then
			self.renderQueued = true
			task.defer(function()
				self.renderQueued = false
				if self.panel.Parent and self.panel.Visible then self:Render() end
			end)
		end
	end

	function interface:Results(query)
		if not self.sortedEntries then
			self.sortedEntries = {}
			for _, key in ipairs(self.order) do self.sortedEntries[#self.sortedEntries + 1] = self.entries[key] end
			table.sort(self.sortedEntries, function(a, b)
				if a.text == b.text then return a.id < b.id end
				return a.text < b.text
			end)
		end
		local found = {}
		for _, entry in ipairs(self.sortedEntries) do
			if entry.frame.Parent and Model.matches(entry.search, query) then found[#found + 1] = entry end
		end
		return found
	end

	function interface:Close(keepFocus)
		if not self.panel then return end
		self.panel.Visible = false
		library.OpenedFrames[self.panel] = nil
		self.firstResult = nil
		if not keepFocus then self.search:ReleaseFocus() end
	end

	function interface:Focus(entry)
		local section = entry.groupbox
		if self.window then self.window.UserTabIntent = true end
		section.OwnerTab:ShowTab()
		local reveal = section.SearchSection or section
		if reveal.Show then reveal:Show() end
		self:Close()
		local epoch = self.epoch
		task.defer(function()
			runService.RenderStepped:Wait()
			if epoch ~= self.epoch or not entry.frame.Parent then return end
			local parent = entry.frame
			while parent and parent ~= self.outer do
				if parent:IsA("GuiObject") and not parent.Visible then
					library:Notify("This option is hidden by its dependencies.", 3)
					return
				end
				parent = parent.Parent
			end
			local scroll = entry.frame:FindFirstAncestorWhichIsA("ScrollingFrame")
			if scroll then
				local offset = (entry.frame.AbsolutePosition.Y - scroll.AbsolutePosition.Y) / library.UIScale + scroll.CanvasPosition.Y
				local maximum = math.max(0, scroll.CanvasSize.Y.Offset - scroll.AbsoluteSize.Y / library.UIScale)
				scroll.CanvasPosition = Vector2.new(0, math.clamp(offset - 30, 0, maximum))
			end
			local stroke = library:Create("UIStroke", { Color = library.AccentColor, Thickness = 2, Parent = entry.frame })
			task.delay(0.8, function() stroke:Destroy() end)
		end)
	end

	local function accentHover(target, property, trigger)
		local function setColor(color)
			target[property] = library[color]
			library.RegistryMap[target].Properties[property] = color
		end
		trigger = trigger or target
		library:GiveSignal(trigger.MouseEnter:Connect(function() setColor("AccentColor") end))
		library:GiveSignal(trigger.MouseLeave:Connect(function() setColor("FontColor") end))
	end

	local function button(parent, text, position, size)
		local object = library:Create("TextButton", {
			BackgroundColor3 = library.MainColor, BackgroundTransparency = 1, BorderSizePixel = 0, BorderColor3 = library.OutlineColor,
			TextColor3 = library.FontColor, FontFace = library.Font, TextSize = 12,
			AutoButtonColor = false, Text = text, Position = position, Size = size, ZIndex = 62, Parent = parent,
		})
		library:AddToRegistry(object, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor", TextColor3 = "FontColor" })
		accentHover(object, "TextColor3")
		library:Create("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6), Parent = object })
		return object
	end

	function interface:CloseNotificationHistory()
		if not self.historyPanel then return end
		self.historyPanel.Visible = false
		library.OpenedFrames[self.historyPanel] = nil
	end

	function interface:RecordNotification(text)
		-- A missing/restricted clock must not discard the message or its toast.
		local ok, timestamp = pcall(function() return os.date("%H:%M:%S") end)
		if not ok or type(timestamp) ~= "string" then timestamp = "--:--:--" end
		table.insert(self.notificationHistory, 1, { text = tostring(text), time = timestamp })
		if #self.notificationHistory > 100 then table.remove(self.notificationHistory) end
		if self.historyPanel and self.historyPanel.Visible and self.outer.Visible then
			self.unreadNotifications = 0
		else
			self.unreadNotifications = math.min(100, self.unreadNotifications + 1)
		end
		if self.notificationDot then self.notificationDot.Visible = self.unreadNotifications > 0 end
		self:RenderNotificationHistory()
	end

	function interface:RenderNotificationHistory()
		if not self.historyPanel or not self.historyPanel.Visible then return end
		local width = self.historyPanel.Size.X.Offset - 26
		local offset = 0
		self.historyRows = self.historyRows or {}
		for index, entry in ipairs(self.notificationHistory) do
			local row = self.historyRows[index]
			if not row then
				row = library:CreateLabel({ Name = "HistoryEntry", TextSize = 12, TextWrapped = true,
					TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
					TextStrokeTransparency = 1, ZIndex = 64, Parent = self.historyList })
				self.historyRows[index] = row
			end
			local text = entry.time .. "  ·  " .. entry.text
			local _, height = library:GetTextBounds(text, library.Font, 12, Vector2.new(math.max(1, width), 100000))
			height = math.max(18, height + 8)
			library:Create(row, { Text = text, Position = UDim2.fromOffset(4, offset),
				Size = UDim2.fromOffset(width, height), Visible = true })
			offset = offset + height + 4
		end
		for index = #self.notificationHistory + 1, #self.historyRows do self.historyRows[index].Visible = false end
		self.historyEmpty.Visible = #self.notificationHistory == 0
		self.historyList.CanvasSize = UDim2.fromOffset(0, offset)
	end

	function interface:ToggleNotificationHistory()
		if self.historyPanel.Visible then self:CloseNotificationHistory(); return end
		self:Close()
		self:CloseInputs()
		self.historyPanel.Visible = true
		library.OpenedFrames[self.historyPanel] = true
		self.unreadNotifications = 0
		self.notificationDot.Visible = false
		self.historyList.CanvasPosition = Vector2.zero
		self:SizeSearch()
	end

	function interface:Render()
		if not self.panel then return end
		local results = self:Results(self.search.Text)
		self.resultCount = #results
		self.firstResult = results[1]
		self.empty.Visible = #results == 0
		self.rows = self.rows or {}
		for index = 1, math.min(#results, 60) do
			local row = self.rows[index]
			if not row then
				local target = button(self.results, "", UDim2.fromOffset(0, 0), UDim2.new(1, -4, 0, 20))
				row = { target = target }
				self.rows[index] = row
				target.LayoutOrder = index
				target.TextXAlignment = Enum.TextXAlignment.Left
				target.TextTruncate = Enum.TextTruncate.AtEnd
				target.Activated:Connect(function() if row.entry then self:Focus(row.entry) end end)
			end
			row.entry = results[index]
			row.target.Text = row.entry.text .. "  ·  " .. row.entry.groupbox.OwnerTab.Name
			row.target.Visible = true
		end
		for index = math.min(#results, 60) + 1, #self.rows do
			self.rows[index].entry = nil
			self.rows[index].target.Visible = false
		end
		self.results.CanvasPosition = Vector2.zero
		self.results.CanvasSize = UDim2.fromOffset(0, math.min(#results, 60) * 22)
		self:SizeSearch()
	end

	function interface:SizeSearch()
		local width = math.max(1, math.min(144, self.outer.Size.X.Offset - 54))
		local panelWidth = math.min(260, self.outer.Size.X.Offset - 20)
		self.search.Size = UDim2.fromOffset(width, 24)
		self.search.Position = UDim2.new(1, -width - 10, 0, 7)
		self.notificationButton.Position = UDim2.new(1, -width - 40, 0, 7)
		local historyWidth = math.max(1, math.min(320, self.outer.Size.X.Offset - 20))
		self.historyPanel.Position = UDim2.new(1, -historyWidth - 10, 0, 39)
		self.historyPanel.Size = UDim2.fromOffset(historyWidth, math.min(280, math.max(1, self.outer.Size.Y.Offset - 49)))
		self:RenderNotificationHistory()
		self.panel.Position = UDim2.new(1, -panelWidth - 10, 0, 39)
		local count = self.panel.Visible and math.min(self.resultCount or 0, 8) or 0
		self.panel.Size = UDim2.fromOffset(panelWidth, math.min(math.max(1, count) * 22 + 8,
			math.max(1, self.outer.Size.Y.Offset - 41)))
	end

	function interface:Open()
		self:CloseNotificationHistory()
		if not string.find(self.search.Text, "%S") then self:Close(true); return end
		self.panel.Visible = true
		library.OpenedFrames[self.panel] = true
		self:Render()
	end

	function interface:FitWindow()
		if not self.outer then return end
		self:EndResize(true)
		self:EndDrag(true)
		local outer = self.outer
		local size = viewport() - screenOrigin()
		local width, height = Model.size(outer.Size.X.Offset, outer.Size.Y.Offset, size, library.UIScale)
		local p, anchor = outer.Position, outer.AnchorPoint
		local x = p.X.Scale * size.X + p.X.Offset - width * library.UIScale * anchor.X
		local y = p.Y.Scale * size.Y + p.Y.Offset - height * library.UIScale * anchor.Y
		outer.Size = UDim2.fromOffset(width, height)
		x = math.clamp(x, 0, math.max(0, size.X - width * library.UIScale))
		y = math.clamp(y, 0, math.max(0, size.Y - height * library.UIScale))
		outer.Position = UDim2.fromOffset(x + width * library.UIScale * anchor.X,
			y + height * library.UIScale * anchor.Y)
		self:SizeSearch()
	end

	function interface:RestoreTab(name)
		local window, epoch = self.window, self.epoch
		local state = window and window.PendingInterface
		if not state then return end
		local tab = window.Tabs[name]
		if state.selectedTab == name then tab:ShowTab() end
		local offsets = state.scroll[name]
		if not offsets then return end
		task.defer(function()
			runService.RenderStepped:Wait()
			if epoch ~= self.epoch or not self.outer.Parent then return end
			for side, key in pairs({ LeftSide = "left", RightSide = "right" }) do
				local frame = tab[side]
				local maximum = math.max(0, frame.CanvasSize.Y.Offset - frame.AbsoluteSize.Y / library.UIScale)
				frame.CanvasPosition = Vector2.new(0, math.clamp(offsets[key], 0, maximum))
			end
		end)
	end

	function interface:UpdateResizeVisual()
		if not self.resizeHandle or not self.resizeHandle.Parent then return end
		local active = self.resize ~= nil or self.resizeHover == true
		local color = active and "AccentColor" or "FontColor"
		for _, line in ipairs(self.resizeLines) do
			line.BackgroundColor3 = library[color]
			library.RegistryMap[line].Properties.BackgroundColor3 = color
		end
		self.resizeSize.Visible = active
		if active then
			self.resizeSize.Text = string.format("%d x %d", math.floor(self.outer.Size.X.Offset + 0.5), math.floor(self.outer.Size.Y.Offset + 0.5))
		end
	end

	function interface:ApplyResize()
		local resize, outer = self.resize, self.outer
		if not resize then return end
		if not outer.Parent or not outer.Visible then self:EndResize(true); return end
		local delta = (resize.pending - resize.point) / resize.scale
		local width, height = Model.size(resize.size.X.Offset + delta.X, resize.size.Y.Offset + delta.Y, resize.area, resize.scale)
		width = math.min(width, math.max(1, (resize.area.X - resize.topLeft.X) / resize.scale))
		height = math.min(height, math.max(1, (resize.area.Y - resize.topLeft.Y) / resize.scale))
		if resize.width == width and resize.height == height then return end
		resize.width, resize.height = width, height
		local preview = self.resizePreview
		preview.Position = UDim2.fromOffset(resize.topLeft.X, resize.topLeft.Y)
		preview.Size = UDim2.fromOffset(width * resize.scale, height * resize.scale)
		preview.Visible = true
		self.resizeSize.Text = string.format("%d x %d", math.floor(width + 0.5), math.floor(height + 0.5))
	end

	function interface:EndResize(cancel)
		local resize = self.resize
		if not cancel and resize then
			self:ApplyResize()
			if resize.width then
				self.outer.Size = UDim2.fromOffset(resize.width, resize.height)
				self.outer.Position = UDim2.fromOffset(resize.topLeft.X + resize.width * resize.scale * self.outer.AnchorPoint.X,
					resize.topLeft.Y + resize.height * resize.scale * self.outer.AnchorPoint.Y)
				self:SizeSearch()
			end
		end
		if self.resizePreview then self.resizePreview.Visible = false end
		if self.resizeConnection then self.resizeConnection:Disconnect(); self.resizeConnection = nil end
		self.resize = nil
		self:SetInteracting()
		if resize and library.Appearance then library.Appearance:QueueVisible() end
		self:UpdateResizeVisual()
	end

	function interface:Attach(window, outer)
		self:EndResize(true)
		self.rows, self.resultCount, self.folds = {}, 0, {}
		self.window, self.outer = window, outer
		if library.Cursor then library.Cursor:WatchMenu(outer) end
		library:AddUIScale(outer)
		self.search = library:Create("TextBox", {
			Name = "GlobalSearch", Text = "", PlaceholderText = "Search...", ClearTextOnFocus = false,
			FontFace = library.Font, TextSize = 12, TextColor3 = library.FontColor,
			BackgroundColor3 = library.BackgroundColor, BorderColor3 = library.OutlineColor,
			Position = UDim2.new(1, -154, 0, 7), Size = UDim2.fromOffset(144, 24), ZIndex = 60, Parent = outer,
		})
		library:AddToRegistry(self.search, { TextColor3 = "FontColor", BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" })
		library:BindControlBorder(self.search, self.search)
		library:StyleSurface(self.search, 4)
		library:Create("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6), Parent = self.search })
		library.DragBlockers[self.search] = true
		self.panel = library:Create("Frame", { Name = "SearchDropdown", BackgroundColor3 = library.BackgroundColor,
			BorderColor3 = library.OutlineColor, Visible = false, ZIndex = 60, Parent = outer })
		library:AddToRegistry(self.panel, { BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" })
		library:StyleSurface(self.panel, 4)
		library.DragBlockers[self.panel] = true
		self.empty = library:CreateLabel({ Text = "No results", Position = UDim2.fromOffset(5, 4),
			Size = UDim2.new(1, -10, 0, 22), TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 62, Parent = self.panel })
		self.results = library:Create("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0,
			Position = UDim2.fromOffset(4, 4), Size = UDim2.new(1, -8, 1, -8), CanvasSize = UDim2.fromOffset(0, 0),
			ScrollBarThickness = 3, ClipsDescendants = true, ZIndex = 61, Parent = self.panel })
		self.results.ScrollBarImageColor3 = library.AccentColor
		library:AddToRegistry(self.results, { ScrollBarImageColor3 = "AccentColor" })
		library:Create("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder, Parent = self.results })
		self.notificationButton = library:Create("TextButton", { Name = "NotificationBell", Text = "", AutoButtonColor = false,
			BackgroundColor3 = library.BackgroundColor, BorderColor3 = library.OutlineColor,
			Size = UDim2.fromOffset(24, 24), ZIndex = 60, Parent = outer })
		library:AddToRegistry(self.notificationButton, { BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" })
		library:BindControlBorder(self.notificationButton)
		library:StyleSurface(self.notificationButton, 4)
		library.DragBlockers[self.notificationButton] = true
		-- Bell from the same Lucide atlas already shipped in icons.lua.
		local icon = library:Create("ImageLabel", { Name = "BellIcon", BackgroundTransparency = 1,
			Image = "rbxassetid://16898612819", ImageRectSize = Vector2.new(48, 48), ImageRectOffset = Vector2.new(820, 257),
			ImageColor3 = library.FontColor, Position = UDim2.fromOffset(4, 4), Size = UDim2.fromOffset(16, 16),
			ZIndex = 61, Parent = self.notificationButton })
		library:AddToRegistry(icon, { ImageColor3 = "FontColor" })
		accentHover(icon, "ImageColor3", self.notificationButton)
		self.notificationDot = library:Create("Frame", { Name = "UnreadDot", BackgroundColor3 = library.AccentColor,
			BorderSizePixel = 0, Position = UDim2.fromOffset(17, 2), Size = UDim2.fromOffset(5, 5),
			Visible = self.unreadNotifications > 0, ZIndex = 62, Parent = self.notificationButton })
		library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = self.notificationDot })
		library:AddToRegistry(self.notificationDot, { BackgroundColor3 = "AccentColor" })
		self.historyPanel = library:Create("Frame", { Name = "NotificationHistory", BackgroundColor3 = library.BackgroundColor,
			BorderColor3 = library.OutlineColor, Visible = false, ZIndex = 62, Parent = outer })
		library:AddToRegistry(self.historyPanel, { BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" })
		library:StyleSurface(self.historyPanel, 4)
		library.DragBlockers[self.historyPanel] = true
		library:CreateLabel({ Text = "Notifications", TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.fromOffset(10, 5), Size = UDim2.new(1, -80, 0, 22), ZIndex = 64, Parent = self.historyPanel })
		self.historyClear = button(self.historyPanel, "Clear", UDim2.new(1, -62, 0, 5), UDim2.fromOffset(54, 22))
		self.historyClear.ZIndex = 65
		self.historyClear.Activated:Connect(function()
			table.clear(self.notificationHistory)
			self.unreadNotifications = 0
			self.notificationDot.Visible = false
			self.historyList.CanvasPosition = Vector2.zero
			self:RenderNotificationHistory()
		end)
		self.historyList = library:Create("ScrollingFrame", { Name = "HistoryList", BackgroundTransparency = 1, BorderSizePixel = 0,
			Position = UDim2.fromOffset(6, 34), Size = UDim2.new(1, -12, 1, -40), CanvasSize = UDim2.fromOffset(0, 0),
			ScrollBarThickness = 3, ScrollBarImageColor3 = library.AccentColor, ClipsDescendants = true, ZIndex = 63, Parent = self.historyPanel })
		library:AddToRegistry(self.historyList, { ScrollBarImageColor3 = "AccentColor" })
		self.historyEmpty = library:CreateLabel({ Text = "No notifications yet", TextSize = 12,
			Position = UDim2.fromOffset(4, 0), Size = UDim2.new(1, -8, 0, 22), ZIndex = 64, Parent = self.historyList })
		self.historyRows = {}
		self.notificationButton.Activated:Connect(function() self:ToggleNotificationHistory() end)
		self:RegisterInputCloser(function() self:CloseNotificationHistory() end)
		self.search.Focused:Connect(function() self:Open() end)
		self.search:GetPropertyChangedSignal("Text"):Connect(function()
			if self.search:IsFocused() then self:Open() end
		end)
		self.search.FocusLost:Connect(function(enter)
			if enter and self.panel.Visible and self.firstResult then self:Focus(self.firstResult) end
		end)
		outer:GetPropertyChangedSignal("Visible"):Connect(function()
			if not outer.Visible then self.resizeHover = false; self:EndResize(true); self:Close(); self:CloseInputs() end
		end)

		local handle = library:Create("TextButton", { Name = "ResizeHandle", Text = "", AutoButtonColor = false,
			BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.new(1, -24, 1, -24),
			Size = UDim2.fromOffset(24, 24), ZIndex = 70, Parent = outer })
		self.resizeHandle = handle
		self.resizeLines = {}
		for row = 1, 3 do
			for col = 1, row do
				local dot = library:Create("Frame", { Name = "GripDot", BackgroundColor3 = library.FontColor,
					BackgroundTransparency = 0.35, BorderSizePixel = 0, Position = UDim2.fromOffset(20 - col * 4, 8 + row * 4),
					Size = UDim2.fromOffset(2, 2), ZIndex = 71, Parent = handle })
				library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = dot })
				library:AddToRegistry(dot, { BackgroundColor3 = "FontColor" })
				self.resizeLines[#self.resizeLines + 1] = dot
			end
		end
		self.resizePreview = library:Create("Frame", { Name = "ResizePreview", BackgroundTransparency = 1, BorderSizePixel = 0,
			Visible = false, ZIndex = 69, Parent = library.ScreenGui })
		library:Create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = self.resizePreview })
		local previewStroke = library:Create("UIStroke", { Color = library.AccentColor, Thickness = 1, Parent = self.resizePreview })
		library:AddToRegistry(previewStroke, { Color = "AccentColor" })

		self.resizeSize = library:CreateLabel({ Name = "ResizeSize", Text = "", TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Right, BackgroundColor3 = library.BackgroundColor,
			BorderColor3 = library.OutlineColor, Position = UDim2.new(1, -122, 1, -22),
			Size = UDim2.fromOffset(92, 18), Visible = false, ZIndex = 70, Parent = outer })
		library:AddToRegistry(self.resizeSize, { TextColor3 = "FontColor", BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" })
		handle.MouseEnter:Connect(function() self.resizeHover = true; self:UpdateResizeVisual() end)
		handle.MouseLeave:Connect(function() self.resizeHover = false; self:UpdateResizeVisual() end)
		handle.InputBegan:Connect(function(event)
			if event.UserInputType ~= Enum.UserInputType.MouseButton1 and event.UserInputType ~= Enum.UserInputType.Touch then return end
			if self.resize or self.drag then return end
			self:FitWindow()
			self:Close()
			self:CloseInputs()
			local touch = event.UserInputType == Enum.UserInputType.Touch and event or nil
			local point = touch and Vector2.new(event.Position.X, event.Position.Y) or input:GetMouseLocation()
			local size, scale, area = outer.Size, library.UIScale, library:GetInterfaceViewport()
			local p, anchor = outer.Position, outer.AnchorPoint
			self.resize = { point = point, pending = point, size = size, touch = touch, scale = scale, area = area,
				topLeft = Vector2.new(p.X.Scale * area.X + p.X.Offset - size.X.Offset * scale * anchor.X,
					p.Y.Scale * area.Y + p.Y.Offset - size.Y.Offset * scale * anchor.Y) }
			self:SetInteracting()
			self.resizeConnection = runService.RenderStepped:Connect(function() self:ApplyResize() end)
			self:UpdateResizeVisual()
		end)
		library:GiveSignal(input.InputChanged:Connect(function(event)
			local resize = self.resize
			if not resize then return end
			if resize.touch then
				if event == resize.touch then resize.pending = Vector2.new(event.Position.X, event.Position.Y) end
			elseif event.UserInputType == Enum.UserInputType.MouseMovement then resize.pending = input:GetMouseLocation() end
		end))
		library:GiveSignal(input.InputEnded:Connect(function(event)
			local resize = self.resize
			if resize and ((resize.touch and event == resize.touch) or (not resize.touch and event.UserInputType == Enum.UserInputType.MouseButton1)) then
				self:EndResize()
			end
		end))
		library:GiveSignal(input.WindowFocusReleased:Connect(function() self:EndResize() end))
		library:GiveSignal(input.InputBegan:Connect(function(event)
			if not outer.Visible or (not self.panel.Visible and not self.historyPanel.Visible) then return end
			if event.KeyCode == Enum.KeyCode.Escape then self:Close(); self:CloseNotificationHistory()
			elseif event.UserInputType == Enum.UserInputType.MouseButton1 or event.UserInputType == Enum.UserInputType.Touch then
				local point = event.UserInputType == Enum.UserInputType.Touch and Vector2.new(event.Position.X, event.Position.Y)
					or input:GetMouseLocation()
				point = point - screenOrigin()
				local function contains(frame)
					local p, size = frame.AbsolutePosition, frame.AbsoluteSize
					return point.X >= p.X and point.X <= p.X + size.X and point.Y >= p.Y and point.Y <= p.Y + size.Y
				end
				if not contains(self.search) and not contains(self.panel) then self:Close() end
				if not contains(self.notificationButton) and not contains(self.historyPanel) then self:CloseNotificationHistory() end
			end
		end))
		local cameraSignal
		local function WatchCamera()
			if cameraSignal then cameraSignal:Disconnect() end
			if workspace.CurrentCamera then
				cameraSignal = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function() self:FitWindow() end)
				library:GiveSignal(cameraSignal)
			end
			self:FitWindow()
		end
		library:GiveSignal(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(WatchCamera))
		WatchCamera()
	end

	function library:GetInterfaceState()
		local window, outer = interface.window, interface.outer
		if not window then return nil end
		local subtabs, scroll, categories, folds = {}, {}, {}, {}
		for id, box in pairs(window.Tabboxes) do subtabs[id] = box.ActiveTab end
		for id, section in pairs(interface.folds) do folds[id] = section.Expanded end
		for name, tab in pairs(window.Tabs) do
			scroll[name] = { left = tab.LeftSide.CanvasPosition.Y, right = tab.RightSide.CanvasPosition.Y }
			categories[name] = tab.ActiveCategory
		end
		return { version = 1, scale = self.UIScale, subtabs = subtabs, scroll = scroll, categories = categories, folds = folds,
			selectedTab = window.SelectedTab, window = { width = outer.Size.X.Offset, height = outer.Size.Y.Offset,
				position = { xScale = outer.Position.X.Scale, xOffset = outer.Position.X.Offset,
					yScale = outer.Position.Y.Scale, yOffset = outer.Position.Y.Offset },
				anchor = { x = outer.AnchorPoint.X, y = outer.AnchorPoint.Y } } }
	end

	function library:ApplyInterfaceState(value, preserveSelectedTab)
		local state = Model.layout(value)
		if not state or not interface.window then return end
		-- Startup autoload may finish after the user has already opened or navigated the menu.
		if preserveSelectedTab then state.selectedTab = nil end
		local aliases = { ESP = "Visuals", Utility = "Game", Config = "Settings" }
		state.selectedTab = aliases[state.selectedTab] or state.selectedTab
		interface.epoch = interface.epoch + 1
		local outer, window = interface.outer, interface.window
		window.PendingInterface = state
		if state.anchor then outer.AnchorPoint = Vector2.new(state.anchor.x, state.anchor.y) end
		if state.position then
			local p = state.position
			outer.Position = UDim2.new(p.xScale, p.xOffset, p.yScale, p.yOffset)
		end
		outer.Size = UDim2.fromOffset(state.width or outer.Size.X.Offset, state.height or outer.Size.Y.Offset)
		self:SetUIScale(state.scale)
		for key, expanded in pairs(state.folds) do
			local section = interface.folds[key]
			if section then section:SetExpanded(expanded) end
		end
		for key, name in pairs(state.subtabs) do
			local box = window.Tabboxes[key]
			if box and box.Tabs[name] then box.Tabs[name]:Show() end
		end
		for key, name in pairs(state.categories) do
			local tab = window.Tabs[key]
			if tab and tab.Categories[name] then tab.Categories[name]:Show(true) end
		end
		if state.selectedTab and window.Tabs[state.selectedTab] then window.Tabs[state.selectedTab]:ShowTab() end
		for name in pairs(window.Tabs) do interface:RestoreTab(name) end
		if interface.panel.Visible then interface:Render() end
	end
	library:GiveSignal({ Disconnect = function()
		interface:CloseNotificationHistory()
		table.clear(interface.notificationHistory)
		interface.unreadNotifications = 0
		if interface.notificationDot then interface.notificationDot.Visible = false end
	end })

end

end)
__bundle_register("GUI/UIModel", function(require, _LOADED, __bundle_register, __bundle_modules)
-- State and input rules shared by the interface and its config serializer.
local Model = {}

function Model.finite(value)
	return type(value) == "number" and value == value and math.abs(value) < math.huge
end

function Model.matches(text, query)
	text = string.lower(tostring(text))
	for word in string.gmatch(string.lower(query), "%S+") do
		if not string.find(text, word, 1, true) then return false end
	end
	return true
end

function Model.numeric(text, minimum, maximum, rounding)
	local value = tonumber(text)
	if not Model.finite(value) then return nil end
	value = math.clamp(value, minimum, maximum)
	if rounding == 0 then value = math.floor(value)
	else value = tonumber(string.format("%." .. rounding .. "f", value)) end
	return math.clamp(value, minimum, maximum)
end

function Model.size(width, height, viewport, scale)
	local maxWidth = math.max(1, (viewport.X - 16) / scale)
	local maxHeight = math.max(1, (viewport.Y - 16) / scale)
	return math.clamp(width, math.min(500, maxWidth), maxWidth),
		math.clamp(height, math.min(360, maxHeight), maxHeight)
end

local function bounded(value, minimum, maximum)
	if Model.finite(value) then return math.clamp(value, minimum, maximum) end
end

function Model.layout(value)
	if type(value) ~= "table" or value.version ~= 1 then return nil end
	local result = { version = 1, subtabs = {}, scroll = {}, categories = {}, folds = {} }
	result.scale = bounded(value.scale, 0.65, 1.5) or 1
	if type(value.window) == "table" then
		local window = value.window
		local position, anchor = window.position, window.anchor
		if type(position) == "table" and Model.finite(position.xScale) and Model.finite(position.xOffset)
			and Model.finite(position.yScale) and Model.finite(position.yOffset) then
			result.position = {
				xScale = math.clamp(position.xScale, -1, 1), xOffset = math.clamp(position.xOffset, -100000, 100000),
				yScale = math.clamp(position.yScale, -1, 1), yOffset = math.clamp(position.yOffset, -100000, 100000),
			}
		end
		if type(anchor) == "table" and Model.finite(anchor.x) and Model.finite(anchor.y) then
			result.anchor = { x = math.clamp(anchor.x, 0, 1), y = math.clamp(anchor.y, 0, 1) }
		end
		result.width = bounded(window.width, 180, 5000)
		result.height = bounded(window.height, 160, 5000)
	end
	if type(value.selectedTab) == "string" then result.selectedTab = value.selectedTab end
	if type(value.subtabs) == "table" then
		for id, name in pairs(value.subtabs) do
			if type(id) == "string" and type(name) == "string" then result.subtabs[id] = name end
		end
	end
	if type(value.categories) == "table" then
		for id, name in pairs(value.categories) do
			if type(id) == "string" and type(name) == "string" then result.categories[id] = name end
		end
	end
	if type(value.folds) == "table" then
		for id, expanded in pairs(value.folds) do
			if type(id) == "string" and type(expanded) == "boolean" then result.folds[id] = expanded end
		end
	end
	if type(value.scroll) == "table" then
		for id, offsets in pairs(value.scroll) do
			if type(id) == "string" and type(offsets) == "table" then
				result.scroll[id] = { left = bounded(offsets.left, 0, 1000000) or 0,
					right = bounded(offsets.right, 0, 1000000) or 0 }
			end
		end
	end
	return result
end

return Model

end)
__bundle_register("Utility/CoreGuiManager", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: We need to be careful where we use CoreGui because exploits have this weird permission issue. We need consistent setting of the parent.
---@note: All scripts that must access this module should require it at the top of the file where it gets loaded.
local CoreGuiManager = {}

local instances = {}

---@param instance Instance
---@return Instance
function CoreGuiManager.imark(instance)
	instances[#instances + 1] = instance
	return instance
end

---@return table
function CoreGuiManager.set()
	-- Use the same executor GUI root as the farm windows. Some executors expose
	-- a usable gethui() while their CoreGui route does not display the menu.
	local candidates = {}
	local function candidate(resolve)
		local ok, parent = pcall(resolve)
		if ok and typeof(parent) == "Instance" and not table.find(candidates, parent) then
			candidates[#candidates + 1] = parent
		end
	end
	candidate(function() return gethui and gethui() end)
	candidate(function() return game:GetService("CoreGui") end)
	candidate(function()
		local player = game:GetService("Players").LocalPlayer
		return player and player:FindFirstChildOfClass("PlayerGui")
	end)

	for _, instance in next, instances do
		if instance:IsA("ScreenGui") then instance.ResetOnSpawn = false end
		local mounted, lastError = false, "no accessible GUI parent"
		for _, parent in ipairs(candidates) do
			local ok, err = pcall(function()
				instance.Parent = parent
				assert(instance.Parent == parent, "GUI parent assignment was ignored")
			end)
			if ok then mounted = true; break end
			lastError = err
		end
		if not mounted then error("Aero GUI could not be mounted: " .. tostring(lastError)) end
	end

	return instances
end

function CoreGuiManager.clear()
	for _, instance in next, instances do
		instance:Destroy()
	end

	instances = {}
end

return CoreGuiManager

end)
__bundle_register("Utility/Profiler", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Profiler = {}

	-- Opt-in: set getgenv().LycorisProfile = true before executing. When off, run/wrap are
	-- pass-throughs with no overhead.
	local enabled = getgenv ~= nil and getgenv().LycorisProfile == true
	local reportInterval = 10.0
	local stats = {}

	local function record(label, start)
		local elapsed = os.clock() - start
		local entry = stats[label]

		if not entry then
			entry = { total = 0, calls = 0, max = 0 }
			stats[label] = entry
		end

		entry.total = entry.total + elapsed
		entry.calls = entry.calls + 1

		if elapsed > entry.max then
			entry.max = elapsed
		end
	end

	---Runs a function, forwarding all return values.
	---@param label string
	---@param functionToProfile function
	function Profiler.run(label, functionToProfile, ...)
		if not enabled then
			return functionToProfile(...)
		end

		local start = os.clock()
		local results = table.pack(functionToProfile(...))
		record(label, start)
		return table.unpack(results, 1, results.n)
	end

	---Wrap function to match Profiler.run signature.
	---@param label string
	---@param functionToProfile function
	---@return function
	function Profiler.wrap(label, functionToProfile)
		if not enabled then
			return functionToProfile
		end

		return function(...)
			return Profiler.run(label, functionToProfile, ...)
		end
	end

	---Print the most expensive labels since the last report, then reset.
	---@param count number?
	function Profiler.report(count)
		local sorted = {}

		for label, entry in next, stats do
			sorted[#sorted + 1] = { label = label, entry = entry }
		end

		table.sort(sorted, function(a, b)
			return a.entry.total > b.entry.total
		end)

		warn(string.format("[Profiler] Top labels over the last %.0fs (total ms / calls / avg ms / max ms):", reportInterval))

		for idx = 1, math.min(count or 15, #sorted) do
			local label = sorted[idx].label
			local entry = sorted[idx].entry

			warn(
				string.format(
					"[Profiler] %2d. %-48s %8.2f / %6d / %6.3f / %6.2f",
					idx,
					label,
					entry.total * 1000,
					entry.calls,
					(entry.total / entry.calls) * 1000,
					entry.max * 1000
				)
			)
		end

		table.clear(stats)
	end

	if enabled then
		task.spawn(function()
			while true do
				task.wait(reportInterval)
				Profiler.report()
			end
		end)
	end

	return Profiler
end)()

end)
__bundle_register("Utility/Filesystem", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@class Filesystem
	---@field _path string
	local Filesystem = {}
	Filesystem.__index = Filesystem

	---@return string
	function Filesystem:path()
		if not isfolder(self._path) then
			makefolder(self._path)
		end

		return self._path
	end

	---@param path string
	---@return string
	function Filesystem:append(path)
		return self:path() .. "\\" .. path
	end

	---@param filename string
	---@return boolean
	function Filesystem:file(filename)
		return isfile(self:append(filename))
	end

	---@param filename string
	---@return string
	function Filesystem:read(filename)
		if not self:file(filename) then
			return error("File does not exist or is a folder.", 2)
		end

		return readfile(self:append(filename))
	end

	---@param filename string
	---@return string
	function Filesystem:delete(filename)
		if not self:file(filename) then
			return error("File does not exist or is a folder.", 2)
		end

		return delfile(self:append(filename))
	end

	---@param filename string
	---@param contents string?
	function Filesystem:write(filename, contents)
		writefile(self:append(filename), contents and contents or "")
	end

	---@param raw boolean?
	---@return table
	function Filesystem:list(raw)
		local list = listfiles(self:path())
		if not list then
			return error("File list does not exist.", 2)
		end

		local new = {}

		for idx, path in next, list do
			---@note: Non-raw weird behavior where the path is never detected in the string. Let's manually index remove it.
			new[idx] = raw and path or string.sub(path, #(self:path() .. "\\") + 1, #path)
		end

		return new
	end

	---@param path string
	---@return Filesystem
	function Filesystem.new(path)
		local self = setmetatable({}, Filesystem)
		self._path = path
		return self
	end

	return Filesystem
end)()

end)
__bundle_register("Utility/Signal", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Signal
---@field signal RBXScriptSignal Underlying roblox script signal
local Signal = {}
Signal.__index = Signal

---@module Utility.Profiler
local Profiler = require("Utility/Profiler")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@param label string
---@param eventFunction function
---@return RBXScriptConnection
function Signal:connect(label, eventFunction)
	---@param error string
	local function onEventFunctionError(error)
		Logger.trace("onEventFunctionError - (%s) - %s", label, error)
	end

	local connection = self.signal:Connect(Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			return xpcall(eventFunction, onEventFunctionError, ...)
		end)
	))

	return connection
end

---@param robloxSignal RBXScriptSignal
---@return Signal
function Signal.new(robloxSignal)
	local self = setmetatable({}, Signal)
	self.signal = robloxSignal

	return self
end

return Signal

end)
__bundle_register("Utility/Maid", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Maid
local Maid = {}
Maid.__type = "maid"

---@return Maid
Maid.new = LPH_NO_VIRTUALIZE(function()
	return setmetatable({
		_tasks = {},
	}, Maid)
end)

Maid.__index = LPH_NO_VIRTUALIZE(function(self, index)
	if Maid[index] then
		return Maid[index]
	else
		return self._tasks[index]
	end
end)

---@param index any
---@param newTask any
Maid.__newindex = LPH_NO_VIRTUALIZE(function(self, index, newTask)
	if Maid[index] ~= nil then
		return
	end

	local tasks = self._tasks
	local oldTask = tasks[index]

	if oldTask == newTask then
		return
	end

	tasks[index] = newTask

	if oldTask then
		if typeof(oldTask) == "thread" then
			return coroutine.status(oldTask) == "suspended" and task.cancel(oldTask) or nil
		end

		if type(oldTask) == "function" then
			oldTask()
		elseif typeof(oldTask) == "RBXScriptConnection" then
			oldTask:Disconnect()
		elseif typeof(oldTask) == "Instance" and oldTask:IsA("Tween") then
			oldTask:Pause()
			oldTask:Cancel()
			oldTask:Destroy()
		elseif oldTask.Destroy then
			oldTask:Destroy()
		elseif oldTask.Remove then
			oldTask:Remove()
		elseif oldTask.detach then
			oldTask:detach()
		end
	end
end)

---@param task any
---@return any
Maid.mark = LPH_NO_VIRTUALIZE(function(self, task)
	self:add(task)
	return task
end)

---@param task any
---@return number
Maid.add = LPH_NO_VIRTUALIZE(function(self, task)
	if not task then
		return error("task cannot be false or nil", 2)
	end

	local taskId = #self._tasks + 1
	self[taskId] = task

	return taskId
end)

---@param taskId number
Maid.removeTask = LPH_NO_VIRTUALIZE(function(self, taskId)
	local tasks = self._tasks
	tasks[taskId] = nil
end)

Maid.clean = LPH_NO_VIRTUALIZE(function(self)
	local tasks = self._tasks

	for index, task in pairs(tasks) do
		if typeof(task) == "RBXScriptConnection" then
			tasks[index] = nil
			pcall(task.Disconnect, task)
		end
	end

	local index, _task = next(tasks)

	while _task ~= nil do
		tasks[index] = nil

		if typeof(_task) == "thread" then
			if coroutine.status(_task) == "suspended" then
				pcall(task.cancel, _task)
			end
		else
			pcall(function()
				if type(_task) == "function" then
					_task()
				elseif typeof(_task) == "RBXScriptConnection" then
					_task:Disconnect()
				elseif typeof(_task) == "Instance" and _task:IsA("Tween") then
					_task:Pause()
					_task:Cancel()
					_task:Destroy()
				elseif _task.Destroy then
					_task:Destroy()
				elseif _task.Remove then
					_task:Remove()
				elseif _task.detach then
					_task:detach()
				end
			end)
		end

		index, _task = next(tasks)
	end
end)

return Maid

end)
__bundle_register("Game/Timings/SoundTiming", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Game.Timings.Timing
local Timing = require("Game/Timings/Timing")

---@class SoundTiming: Timing
---@field id string Sound ID.
---@field rpue boolean Repeat parry until end.
---@field _rsd number Repeat start delay in miliseconds. Use :rsd() for seconds.
---@field _rpd number Delay between each repeat parry in miliseconds. Use :rpd() for seconds.
---@field alp boolean Allow local player to be hit.
local SoundTiming = setmetatable({}, { __index = Timing })
SoundTiming.__index = SoundTiming

---@return string
function SoundTiming:id()
	return self._id
end

---@param other SoundTiming
function SoundTiming:equals(other)
	if not Timing.equals(self, other) then
		return false
	end

	if self._id ~= other._id then
		return false
	end

	if self.alp ~= other.alp then
		return false
	end

	return true
end

---@param values table
function SoundTiming:load(values)
	Timing.load(self, values)

	if typeof(values._id) == "string" then
		self._id = values._id
	end

	if typeof(values.alp) == "boolean" then
		self.alp = values.alp
	end
end

---@return SoundTiming
function SoundTiming:clone()
	local clone = setmetatable(Timing.clone(self), SoundTiming)

	clone._id = self._id
	clone.alp = self.alp

	return clone
end

---@return SoundTiming
function SoundTiming:serialize()
	local serializable = Timing.serialize(self)

	serializable._id = self._id
	serializable.alp = self.alp

	return serializable
end

---@param values table?
---@return SoundTiming
function SoundTiming.new(values)
	local self = setmetatable(Timing.new(), SoundTiming)

	self._id = ""
	self.rpue = false
	self._rsd = 0
	self._rpd = 0
	self.alp = false

	if values then
		self:load(values)
	end

	return self
end

return SoundTiming

end)
__bundle_register("Game/Timings/Timing", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Game.Timings.ActionContainer
local ActionContainer = require("Game/Timings/ActionContainer")

---@class Timing
---@field name string
---@field tag string
---@field imdd number Initial minimum distance from position.
---@field imxd number Initial maximum distance from position.
---@field punishable number Punishable window in seconds.
---@field after number After window in seconds.
---@field duih boolean Delay until in hitbox.
---@field actions ActionContainer
---@field hitbox Vector3
---@field umoa boolean Use module over actions.
---@field smn boolean Skip module notification.
---@field srpn boolean Skip repeat notification.
---@field smod string Selected module string.
---@field aatk boolean Allow attacking.
---@field fhb boolean Hitbox facing offset.
---@field hso number Hitbox shift offset. This offset is applied backwards. Positive is backwards, negative is forwards.
---@field ndfb boolean No dash fallback.
---@field cbm boolean A non-saved field to indicate whether this was non-part-timing created by a module.
---@field nvfb boolean No vent fallback.
---@field bfht number Block fallback hold time.
---@field pbfb boolean Prefer block fallback.
---@field forced boolean Hidden field which allows us to force tasks to go through.
---@field htype Enum.PartType Shape of hitbox. Never accessible unless inside of a module or inside of real code. This is never serialized.
---@field rpue boolean Prefer repeat usage.
---@field _rsd number Repeat start delay in milliseconds. Use :rsd() for seconds.
---@field _rpd number Repeat parry delay in milliseconds. Use :rpd() for seconds.
---@field nbfb boolean No block fallback.
---@field ibi boolean Ignore block input gate for this timing.
---@field iapf boolean Ignore auto parry frames for this timing.
---@field uif boolean Use the inhale cue to identify a feint. When set, a pending reaction to this timing is cancelled if the inhale feint sound plays from the same attacker.
---@field nfd boolean Ignore feint detection for this timing. For moves whose animation naturally ends before the real hit lands, this makes auto defense treat the move as never-stopped instead of canceling the parry as a feint.
---@field rsc boolean Skip this timing if the local player recently played 'rsaid' themselves.
---@field rsaid string Animation ID to watch for local self-casts.
---@field rsaw number Recent self-cast window in seconds.
local Timing = {}
Timing.__index = Timing

---@return number
function Timing:rsd()
	return self._rsd / 1000
end

---@return number
function Timing:rpd()
	return self._rpd / 1000
end

---@return string
function Timing:id()
	return self.name
end

---@param id string
function Timing:set(id)
	self.name = id
end

---@param values table
function Timing:load(values)
	if typeof(values.name) == "string" then
		self.name = values.name
	end

	if typeof(values.tag) == "string" then
		self.tag = values.tag
	end

	if typeof(values.imdd) == "number" then
		self.imdd = values.imdd
	end

	if typeof(values.imxd) == "number" then
		self.imxd = values.imxd
	end

	if typeof(values.duih) == "boolean" then
		self.duih = values.duih
	end

	if typeof(values.punishable) == "number" then
		self.punishable = values.punishable
	end

	if typeof(values.after) == "number" then
		self.after = values.after
	end

	if typeof(values.actions) == "table" then
		self.actions:load(values.actions)
	end

	if typeof(values.smn) == "boolean" then
		self.smn = values.smn
	end

	if typeof(values.hitbox) == "table" then
		self.hitbox = Vector3.new(values.hitbox.X or 0, values.hitbox.Y or 0, values.hitbox.Z or 0)
	end

	if typeof(values.umoa) == "boolean" then
		self.umoa = values.umoa
	end

	if typeof(values.srpn) == "boolean" then
		self.srpn = values.srpn
	end

	if typeof(values.smod) == "string" then
		self.smod = values.smod
	end

	if typeof(values.aatk) == "boolean" then
		self.aatk = values.aatk
	end

	if typeof(values.fhb) == "boolean" then
		self.fhb = values.fhb
	end

	if typeof(values.hso) == "number" then
		self.hso = values.hso
