	end

	local char_func_map = {
		['"'] = parse_string,
		["0"] = parse_number,
		["1"] = parse_number,
		["2"] = parse_number,
		["3"] = parse_number,
		["4"] = parse_number,
		["5"] = parse_number,
		["6"] = parse_number,
		["7"] = parse_number,
		["8"] = parse_number,
		["9"] = parse_number,
		["-"] = parse_number,
		["t"] = parse_literal,
		["f"] = parse_literal,
		["n"] = parse_literal,
		["["] = parse_array,
		["{"] = parse_object,
	}

	parse = function(str, idx)
		local chr = str:sub(idx, idx)
		local f = char_func_map[chr]
		if f then
			return f(str, idx)
		end
		decode_error(str, idx, "unexpected character '" .. chr .. "'")
	end

	function json.decode(str)
		if type(str) ~= "string" then
			error("expected argument of type string, got " .. type(str))
		end
		local res, idx = parse(str, next_char(str, 1, space_chars, true))
		idx = next_char(str, idx, space_chars, true)
		if idx <= #str then
			decode_error(str, idx, "trailing garbage")
		end
		return res
	end

	return json
end)()

end)
__bundle_register("Utility/Finder", function(require, _LOADED, __bundle_register, __bundle_modules)
local Finder = {}

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

---@param position Vector3
---@param range number
---@return boolean
Finder.near = LPH_NO_VIRTUALIZE(function(position, range)
	local localCharacter = players.LocalPlayer.Character
	if not localCharacter then
		return false
	end

	local localRootPart = localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return false
	end

	return (position - localRootPart.Position).Magnitude <= range
end)

---@return Model?
Finder.wshrine = LPH_NO_VIRTUALIZE(function()
	local thrown = workspace:FindFirstChild("Thrown")
	local waves = workspace:FindFirstChild("HallowtideWaves")
	local shrine = nil

	while not shrine do
		shrine = waves:FindFirstChild("HallowtideShrine") or thrown:FindFirstChild("HallowtideShrine")

		task.wait()
	end

	return shrine
end)

---@param position Vector3
---@param range number
---@return Model|nil
Finder.enear = LPH_NO_VIRTUALIZE(function(position, range)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end

	for _, entity in next, live:GetChildren() do
		if entity == players.LocalPlayer.Character then
			continue
		end

		if players:GetPlayerFromCharacter(entity) then
			continue
		end

		local rootPart = entity:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		if (position - rootPart.Position).Magnitude > range then
			continue
		end

		return entity
	end

	return nil
end)

---@param position Vector3
---@param range number
---@return Player|nil
Finder.pnear = LPH_NO_VIRTUALIZE(function(position, range)
	for _, player in next, players:GetPlayers() do
		if player == players.LocalPlayer then
			continue
		end

		local character = player.Character
		if not character then
			continue
		end

		local rootPart = character:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		if (position - rootPart.Position).Magnitude > range then
			continue
		end

		return player
	end

	return nil
end)

---@param name string The name of the entity to find. It is matched.
---@return Model?
Finder.entity = LPH_NO_VIRTUALIZE(function(name)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end

	for _, child in next, live:GetChildren() do
		if not child.Name:match(name) then
			continue
		end

		return child
	end
end)

---@param tool Tool
---@return boolean
Finder.cdlocked = LPH_NO_VIRTUALIZE(function(tool)
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return nil
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return nil
	end

	for _, effect in next, effectReplicatorModule.Effects do
		if effect.Value ~= tool then
			continue
		end

		return true
	end

	return false
end)

---@param name string? Specify the name of the mantra to find. It is matched.
---@return Tool?
Finder.ncdm = LPH_NO_VIRTUALIZE(function(name)
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return nil
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return nil
	end

	local backpack = players.LocalPlayer:FindFirstChild("Backpack")
	if not backpack then
		return nil
	end

	for _, item in next, backpack:GetChildren() do
		if not item:IsA("Tool") then
			continue
		end

		if not item.Name:match("Mantra:") or item.Name:match("Recalled") then
			continue
		end

		if name and (not item.Name:match(name)) then
			continue
		end

		if Finder.cdlocked(item) then
			continue
		end

		return item
	end
end)

---@return table
Finder.sprompts = LPH_NO_VIRTUALIZE(function()
	local playerGui = players.LocalPlayer:FindFirstChild("PlayerGui")
	if not playerGui then
		return {}
	end

	local simplePrompt = playerGui:FindFirstChild("SimplePrompt")
	if not simplePrompt then
		return {}
	end

	local prompts = simplePrompt:FindFirstChild("Prompts")
	if not prompts then
		return {}
	end

	local texts = {}

	for _, prompt in next, prompts:GetChildren() do
		if not prompt:IsA("TextLabel") then
			continue
		end

		texts[#texts + 1] = prompt.Text
	end

	return texts
end)

---@param position Vector3 The position to check from.
---@return Model?
Finder.marker = LPH_NO_VIRTUALIZE(function(position)
	local markerWorkspace = replicatedStorage:FindFirstChild("MarkerWorkspace")
	if not markerWorkspace then
		return nil
	end

	local areaMarkers = markerWorkspace:WaitForChild("AreaMarkers")
	if not areaMarkers then
		return nil
	end

	local nearestAreaMarker = nil
	local nearestDistance = nil

	for _, marker in next, areaMarkers:GetDescendants() do
		if not marker:IsA("Part") then
			continue
		end

		local distance = (position - marker.Position).Magnitude

		if nearestDistance and distance >= nearestDistance then
			continue
		end

		nearestAreaMarker = marker
		nearestDistance = distance
	end

	return nearestAreaMarker
end)

---@param name string The name of the tool to find. It is matched.
---@return Tool?
Finder.etool = LPH_NO_VIRTUALIZE(function(name)
	local character = players.LocalPlayer.Character
	if not character then
		return nil
	end

	for _, item in next, character:GetChildren() do
		if not item:IsA("Tool") then
			continue
		end

		if not item.Name:match(name) then
			continue
		end

		return item
	end

	return nil
end)

---@param name string The name of the weapon to find. It is matched.
---@return Tool?
Finder.weweapon = LPH_NO_VIRTUALIZE(function(name)
	local tools = Finder.tools(name, false)

	for _, tool in next, tools do
		local rstats = tool:GetAttribute("RichStats")
		if not rstats then
			continue
		end

		if rstats:match("Enchant") then
			continue
		end

		return tool
	end
end)

---@param name string The name of the tool to find. It is matched.
---@param exact boolean If true, the name must be an exact match.
---@return Tool?
Finder.tool = LPH_NO_VIRTUALIZE(function(name, exact)
	return Finder.tools(name, exact)[1]
end)

---@param name string The name of the tool to find. It is matched.
---@param exact boolean If true, the name must be an exact match.
---@return Tool[]
Finder.tools = LPH_NO_VIRTUALIZE(function(name, exact)
	local backpack = players.LocalPlayer:FindFirstChild("Backpack")
	if not backpack then
		return {}
	end

	local tools = {}

	for _, item in next, backpack:GetChildren() do
		if not item:IsA("Tool") then
			continue
		end

		if exact and (item.Name ~= name) or (not item.Name:match(name)) then
			continue
		end

		tools[#tools + 1] = item
	end

	return tools
end)

---@param position Vector3 The position to check from.
---@param range number The maximum distance to check.
---@return Model?
Finder.chest = LPH_NO_VIRTUALIZE(function(position, range)
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return nil
	end

	local nearestChest = nil
	local nearestDistance = nil

	for _, chest in next, thrown:GetChildren() do
		if not chest:IsA("Model") then
			continue
		end

		local distance = (position - chest:GetPivot().Position).Magnitude

		if range and distance > range then
			continue
		end

		if nearestDistance and distance >= nearestDistance then
			continue
		end

		nearestChest = chest
		nearestDistance = distance
	end

	return nearestChest
end)

---@param instance Instance The instance to check from.
---@param filter fun(part: BasePart): boolean A filter function which returns true if the part should be included.
---@param distance number The maximum distance in studs.
---@return BasePart[]
Finder.sdparts = LPH_NO_VIRTUALIZE(function(instance, filter, distance)
	local localCharacter = players.LocalPlayer.Character
	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	local validParts = {}
	local partsToDistance = {}

	for _, part in next, instance:GetChildren() do
		if not part:IsA("BasePart") then
			continue
		end

		if not filter(part) then
			continue
		end

		local pdistance = (part.Position - instance.Position).Magnitude

		if pdistance > distance then
			continue
		end

		validParts[#validParts + 1] = part
		partsToDistance[part] = pdistance
	end

	table.sort(validParts, function(partOne, partTwo)
		return partsToDistance[partOne] < partsToDistance[partTwo]
	end)

	return validParts
end)

---@param range number
---@return Model[]
Finder.gpir = LPH_NO_VIRTUALIZE(function(range)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end

	local localCharacter = players.LocalPlayer.Character
	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	local playersInRange = {}
	local playersDistance = {}

	for _, player in next, players:GetPlayers() do
		if player == players.LocalPlayer then
			continue
		end

		local character = player.Character
		if not character then
			continue
		end

		local rootPart = character:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		local playerDistance = (rootPart.Position - localRootPart.Position).Magnitude
		if playerDistance > range then
			continue
		end

		table.insert(playersInRange, player)

		playersDistance[player] = playerDistance
	end

	table.sort(playersInRange, function(playerOne, playerTwo)
		return playersDistance[playerOne] < playersDistance[playerTwo]
	end)

	return playersInRange
end)

---@param range number
---@param pfilter boolean If true, filter out all players from the search.
---@return Model[]
Finder.geir = LPH_NO_VIRTUALIZE(function(range, pfilter)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end

	local localCharacter = players.LocalPlayer.Character
	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	local entitiesInRange = {}
	local entitiesDistance = {}

	for _, entity in next, live:GetChildren() do
		if entity == localCharacter then
			continue
		end

		local rootPart = entity:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		local entityDistance = (rootPart.Position - localRootPart.Position).Magnitude
		if entityDistance > range then
			continue
		end

		table.insert(entitiesInRange, entity)

		entitiesDistance[entity] = entityDistance
	end

	table.sort(entitiesInRange, function(mobOne, mobTwo)
		return entitiesDistance[mobOne] < entitiesDistance[mobTwo]
	end)

	if not pfilter then
		return entitiesInRange
	end

	local list = {}

	for _, entity in next, entitiesInRange do
		if players:GetPlayerFromCharacter(entity) then
			continue
		end

		table.insert(list, entity)
	end

	return list
end)

return Finder

end)
__bundle_register("Game/ServerHop", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local ServerHop = {}

local replicatedStorage = game:GetService("ReplicatedStorage")
local players = game:GetService("Players")
local teleportService = game:GetService("TeleportService")
local runService = game:GetService("RunService")

local LOBBY_PLACE_ID = 4111023553
local DEBUGGING_MODE = true
local UNKNOWN_PLAYER_COUNT = 1000000000

-- If the current target server hasn't teleported us in this window, blacklist it and move to the next
-- one (full, or the instance is no longer available).
local SERVER_SWITCH_TIMEOUT = 10

local lastRetry = nil
local currentSlot = nil
local currentServerId = nil
local currentServerSince = nil
local selectionMode = "Small"
local targetServerId = nil
local lobbyStarted = nil
local hopConnection = nil
local failureConnection = nil

local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

---@return table
local function getBlacklist()
	local blacklist = PersistentData.get("sblacklist") or {}

	for key, value in next, blacklist do
		if tick() - value < 300 then
			continue
		end

		telemetryLog("(%s) Removed old entry (%s) from server blacklist.", tostring(key), tostring(value))

		blacklist[key] = nil
	end

	PersistentData.set("sblacklist", blacklist)

	return blacklist
end

---@param id string The server ID (JobId) to add to the blacklist.
local function addBlacklist(id)
	if not id then
		return
	end

	local blacklist = getBlacklist()

	blacklist[id] = tick()

	PersistentData.set("sblacklist", blacklist)
end

-- ============================================================================================
-- UI-driven server picking. Instead of firing PickSlot/PickServer remotes directly (which the game
-- ignored unless its own UI state was set up), we press the actual menu buttons via firesignal, so
-- the game's own handlers run -- exactly like a real player clicking them.
-- ============================================================================================

---LoadingGui.Overlay.Columns.MainFrame, or nil.
---@return Instance?
local function getMainFrame()
	local playerGui = players.LocalPlayer and players.LocalPlayer:FindFirstChild("PlayerGui")
	local loadingGui = playerGui and playerGui:FindFirstChild("LoadingGui")
	local overlay = loadingGui and loadingGui:FindFirstChild("Overlay")
	local columns = overlay and overlay:FindFirstChild("Columns")
	return columns and columns:FindFirstChild("MainFrame")
end

---Click a GUI button the way the game's own UI would (fire its click signals).
---@param button Instance?
local function pressButton(button)
	if not button then
		return
	end

	pcall(function()
		firesignal(button.MouseButton1Click)
	end)
	pcall(function()
		firesignal(button.Activated)
	end)
end

---Press the slot button (MainFrame.Slots.SlotScroll.<slot>) to select the slot and populate its
---server list.
local function pressSlot()
	local mainFrame = getMainFrame()
	local slots = mainFrame and mainFrame:FindFirstChild("Slots")
	local scroll = slots and slots:FindFirstChild("SlotScroll")
	local slotButton = scroll and currentSlot and scroll:FindFirstChild(currentSlot)
	pressButton(slotButton)
end

---Best-effort player count for a server button, parsed from its text / descendant labels. Unknown
---counts sort last so they are not mistaken for the emptiest servers.
---@param button Instance
---@return number
local function parsePlayers(button)
	local texts = {}
	local function addText(text)
		if type(text) == "string" then
			texts[#texts + 1] = text
		end
	end

	pcall(function()
		addText(button.Text)
	end)

	for _, descendant in next, button:GetDescendants() do
		if descendant:IsA("TextLabel") then
			pcall(function()
				addText(descendant.Text)
			end)
		end
	end

	for _, text in ipairs(texts) do
		local ratio = text:match("(%d+)%s*/%s*%d+") -- "12/40"
		if ratio then
			return tonumber(ratio)
		end
	end

	for _, text in ipairs(texts) do
		local count = text:match("(%d+)")
		if count then
			return tonumber(count)
		end
	end

	return UNKNOWN_PLAYER_COUNT
end

---All server buttons in MainFrame.Servers.Servers -- each is a TextButton named by its JobId.
---@return table
local function serverButtons()
	local mainFrame = getMainFrame()
	local serversFrame = mainFrame and mainFrame:FindFirstChild("Servers")
	local scroll = serversFrame and serversFrame:FindFirstChild("Servers")

	local list = {}
	if scroll then
		for _, child in next, scroll:GetChildren() do
			if child:IsA("GuiButton") then
				list[#list + 1] = { id = child.Name, button = child, players = parsePlayers(child) }
			end
		end
	end
	return list
end

---Blacklist the current target so it's never picked again, and drop it so the next tick picks a
---different server.
---@param reason string
local function advanceServer(reason)
	if currentServerId then
		telemetryLog("(%s) %s -- blacklisting and switching servers.", tostring(currentServerId), reason)
		addBlacklist(currentServerId)
	end

	currentServerId = nil
	currentServerSince = nil
end

local function stopTargetHop(reason)
	Logger.longNotify("Serverhop: %s", reason)
	if hopConnection then hopConnection:Disconnect(); hopConnection = nil end
	if failureConnection then failureConnection:Disconnect(); failureConnection = nil end
	PersistentData.set("shslot", nil)
	PersistentData.set("shtarget", nil)
	PersistentData.set("shmode", nil)
	PersistentData.set("shorigin", nil)
end

local function updateServerHopping()
	-- Throttle to once a second.
	if lastRetry and os.clock() - lastRetry <= 1.0 then
		return
	end

	lastRetry = os.clock()
	if targetServerId and os.clock() - lobbyStarted >= 30 then
		stopTargetHop("Target server unavailable or timed out. Reload Aero to try again.")
		return
	end

	-- No servers listed yet -- press the slot button to select it and populate the list.
	local buttons = serverButtons()
	if #buttons == 0 then
		pressSlot()
		return
	end

	-- Filter out blacklisted servers, then sort by (parsed) population.
	local blacklist = getBlacklist()
	local candidates = {}
	for _, server in ipairs(buttons) do
		if (targetServerId and server.id == targetServerId) or (not targetServerId and not blacklist[server.id]) then
			candidates[#candidates + 1] = server
		end
	end

	if #candidates == 0 then
		-- Everything currently listed is blacklisted -- re-select the slot to refresh the list.
		pressSlot()
		return
	end

	table.sort(candidates, function(first, second)
		if first.players == second.players then
			return first.id < second.id
		end
		if first.players == UNKNOWN_PLAYER_COUNT then return false end
		if second.players == UNKNOWN_PLAYER_COUNT then return true end
		if selectionMode == "Large" then return first.players > second.players end
		return first.players < second.players
	end)

	-- Drop a target that got blacklisted since we picked it.
	if not targetServerId and currentServerId and blacklist[currentServerId] then
		currentServerId = nil
	end

	-- Pick the lowest-population non-blacklisted server.
	if not currentServerId then
		currentServerId = candidates[1].id
		currentServerSince = os.clock()
		local playerCount = candidates[1].players == UNKNOWN_PLAYER_COUNT
			and "unknown"
			or tostring(candidates[1].players)
		telemetryLog("(%s) Trying server (%s players).", tostring(currentServerId), playerCount)
	end

	-- Current target hasn't taken us in time -- blacklist it and move on.
	if currentServerSince and os.clock() - currentServerSince >= SERVER_SWITCH_TIMEOUT then
		if targetServerId then
			stopTargetHop("Target server did not respond. Reload Aero to try again.")
			return
		end
		advanceServer("Not joined in time")
		return
	end

	-- Press the current target's button to join it (re-find it each tick in case the list rebuilt).
	local target = nil
	for _, server in ipairs(candidates) do
		if server.id == currentServerId then
			target = server
			break
		end
	end

	if target then
		pressButton(target.button)
	else
		currentServerId = nil -- the button disappeared; re-pick next tick
	end
end

local function onTeleportFailure(...)
	-- A full server (or other teleport failure) -- blacklist it and switch.
	if targetServerId then
		stopTargetHop("Could not join the target server. Reload Aero to try again.")
	else
		advanceServer("Teleport failed")
	end
end

function ServerHop.lobby()
	local shslot = PersistentData.get("shslot")
	if not shslot then
		return error("No server hop slot set in PersistentData.")
	end

	currentSlot = shslot
	currentServerId = nil
	currentServerSince = nil
	lastRetry = nil
	selectionMode = PersistentData.get("shmode") == "Large" and "Large" or "Small"
	targetServerId = PersistentData.get("shtarget")
	lobbyStarted = os.clock()
	if hopConnection then hopConnection:Disconnect() end
	if failureConnection then failureConnection:Disconnect() end

	telemetryLog("(%s) Picking a server by pressing the menu buttons.", tostring(shslot))

	failureConnection = teleportService.TeleportInitFailed:Connect(onTeleportFailure)
	hopConnection = runService.PreRender:Connect(updateServerHopping)
end

function ServerHop.rlobby()
	telemetryLog("Returning to lobby.")

	local requests = replicatedStorage:WaitForChild("Requests")
	local returnToMenu = requests:WaitForChild("ReturnToMenu")
	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")

	while task.wait() do
		returnToMenu:FireServer()

		local prompt = playerGui:FindFirstChild("ChoicePrompt")
		local choicePrompt = prompt and prompt:FindFirstChild("Choice")

		if not choicePrompt then
			continue
		end

		choicePrompt:FireServer(true)
	end
end

---@param slot string The data slot to use.
---@param blacklist boolean If true, blacklist the current server.
function ServerHop.hop(slot, blacklist, mode, target)
	if target ~= nil and (type(target) ~= "string" or target == "") then
		return error("A server ID is required.")
	end
	PersistentData.set("shmode", mode == "Large" and "Large" or "Small")
	PersistentData.set("shtarget", target)
	if game.PlaceId ~= LOBBY_PLACE_ID and type(game.JobId) == "string" and game.JobId ~= "" then
		PersistentData.set("shorigin", game.JobId)
	else
		PersistentData.set("shorigin", nil)
	end
	PersistentData.set("shslot", slot)

	telemetryLog("(%s, %s) Hopping to new server.", tostring(slot), tostring(blacklist))

	if blacklist then
		local blacklisted = getBlacklist()
		local currentServerId = game.JobId
		if currentServerId and currentServerId ~= "" then
			blacklisted[currentServerId] = tick()
		end
		PersistentData.set("sblacklist", blacklisted)
	end

	if game.PlaceId == LOBBY_PLACE_ID then
		return ServerHop.lobby()
	end

	return ServerHop.rlobby()
end

-- Record the departed server only once a different game server has actually loaded.
function ServerHop.arrived()
	local origin = PersistentData.get("shorigin")
	if PersistentData.get("shslot") and type(origin) == "string" and origin ~= "" and type(game.JobId) == "string" and game.JobId ~= "" and game.JobId ~= origin then
		PersistentData.set("shprevious", origin)
	end
	PersistentData.set("shorigin", nil)
	PersistentData.set("shmode", nil)
	PersistentData.set("shtarget", nil)
end

return ServerHop

end)
__bundle_register("Utility/PersistentData", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Serializer
local Serializer = require("Utility/Serializer")

---@module Utility.Deserializer
local Deserializer = require("Utility/Deserializer")

---@module Utility.String
local String = require("Utility/String")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local PersistentData = {
	_data = {
		fli = nil,

		shslot = nil,

		sblacklist = {},

		wdata = nil,

		efdata = nil,
	},
}

local memStorageService = game:GetService("MemStorageService")

---@param field string
---@return any
function PersistentData.get(field)
	return PersistentData._data[field]
end

---@param field string
---@param key string
---@param value any
function PersistentData.stf(field, key, value)
	local tbl = PersistentData.get(field)

	if type(tbl) ~= "table" then
		return error(string.format("PersistentData field '%s' is not a table.", tostring(field)))
	end

	tbl[key] = value

	PersistentData.set(field, tbl)
end

---@param field string
---@param value any
function PersistentData.set(field, value)
	PersistentData._data[field] = value

	local marshalSuccess, payload = pcall(Serializer.marshal, PersistentData._data)
	if not marshalSuccess then
		return Logger.warn("(%s) Failed to marshal PersistentData snapshot.", tostring(payload))
	end

	local saveSuccess, saveResult = pcall(memStorageService.SetItem, memStorageService, "LYCORIS_PERSISTENT_DATA", payload)

	if not saveSuccess then
		return Logger.warn("(%s) Failed to set PersistentData snapshot.", tostring(saveResult))
	end

	if not LPH_OBFUSCATED or shared.Aero.verbose then
		Logger.warn("(%s) Successfully set PersistentData snapshot.", tostring(saveResult))
	end
end

function PersistentData.init()
	local hasSuccess, hasResult = pcall(memStorageService.HasItem, memStorageService, "LYCORIS_PERSISTENT_DATA")
	if not hasSuccess then
		return hasResult and Logger.warn("(%s) Failed to check for PersistentData snapshot.", tostring(hasResult))
	end

	local itemSuccess, itemResult = pcall(memStorageService.GetItem, memStorageService, "LYCORIS_PERSISTENT_DATA")
	if not itemSuccess then
		return Logger.warn("(%s) Failed to get PersistentData snapshot", tostring(itemResult))
	end

	if itemResult == nil or itemResult == "" then
		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("PersistentData snapshot is missing or empty.")
		end

		return
	end

	local success, result = pcall(Deserializer.unmarshal_one, String.tba(itemResult))
	if not success then
		return Logger.warn("(%s) Failed to deserialize PersistentData snapshot.", tostring(result))
	end

	if not LPH_OBFUSCATED or shared.Aero.verbose then
		Logger.warn("(%s) Successfully loaded PersistentData snapshot.", tostring(result))
	end

	PersistentData._data = result
end

return PersistentData

end)
__bundle_register("Game/InputClient", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Never call the roll function from the cache. We only need this to get the last roll move direction.
local InputClient = {
	sprintFunctionCache = nil,
	rollFunctionCache = nil,
}

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Game.SelfFire
local SelfFire = require("Game/SelfFire")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")
local players = game:GetService("Players")
local tweenService = game:GetService("TweenService")

local unreliableFireServer = Instance.new("UnreliableRemoteEvent").FireServer

local inputDataCache = nil

---@return table?
local getEffectModule = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return nil
	end

	return require(effectReplicator)
end)

local freefallTrack = nil
local slideJumpTrack = nil
local cancelLeftTrack = nil
local cancelRightTrack = nil
local jumpAnimTrack = nil
local crouchTrack = nil
local groundslideTrack = nil

local slideBodyVelocity = nil
local slideActive = false

local crouchActive = false
local crouchSession = 0

---@return boolean
local landedCheck = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local humanController = InputClient.getHumanController()
	if not humanController then
		return
	end

	local sprintSpeed = effectReplicatorModule:FindEffect("SprintSpeed")
	if not sprintSpeed then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local inputClient = characterHandler and characterHandler:FindFirstChild("InputClient")
	if not inputClient then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	local torso = character:FindFirstChild("Torso")
	if not torso then
		return
	end

	local groundSensor = humanController.GroundSensor
	if not groundSensor then
		return
	end

	local stopDodge = KeyHandling.getRemote("StopDodge")
	if not stopDodge then
		return
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		return
	end

	local repDebris = replicatedStorage:FindFirstChild("Debris")
	if not repDebris then
		return
	end

	local sounds = replicatedStorage:FindFirstChild("Sounds")
	local sliding = sounds and sounds:FindFirstChild("Sliding")
	if not sliding then
		return
	end

	local modules = replicatedStorage:FindFirstChild("Modules")
	local vectorMaths = modules and modules:FindFirstChild("VectorMaths")
	local vectorMathModule = vectorMaths and require(vectorMaths)
	if not vectorMathModule then
		return
	end

	local sensedPart = groundSensor.SensedPart

	if not effectReplicatorModule:HasAny("Swimming", "ClientSwim", "Gliding", "Knocked") then
		if not sensedPart then
			return false
		end

		if sensedPart and sensedPart.CollisionGroup == "Ship" then
			effectReplicatorModule:EnsureEffect("OnShip")
		elseif effectReplicatorModule:HasEffect("OnShip") then
			effectReplicatorModule:RemoveEffectsOfClass("OnShip")
		end
	end

	if freefallTrack.IsPlaying then
		freefallTrack:Stop(0.15)
	end

	if not effectReplicatorModule:HasEffect("Falling") then
		return true
	end

	effectReplicatorModule:RemoveEffectsOfClass("Falling")
	effectReplicatorModule:RemoveEffectsOfClass("ShipJump")
	effectReplicatorModule:RemoveEffectsOfClass("WingDashCooldown")

	humanoid.Jump = false

	effectReplicatorModule:CreateEffect("Landed"):Debris(0.05)

	if effectReplicatorModule:HasEffect("SlideJumping") and not effectReplicatorModule:HasEffect("GravityField") then
		effectReplicatorModule:RemoveEffectsOfClass("SlideJumping")

		if sprintSpeed and sprintSpeed.Value >= 9 then
			sprintSpeed.Value = sprintSpeed.Value - 3
		end

		local lookVector = root.CFrame.LookVector * 3
		local slideJump = torso:FindFirstChild("SlideJump")

		if slideJump then
			slideJump:Destroy()
		end

		if effectReplicatorModule:HasEffect("Sprinting") then
			humanoid:LoadAnimation(inputClient.SlideJumpTransition):Play(nil, 0.65)
		else
			humanoid:LoadAnimation(inputClient.LandingAnim):Play(nil, 0.65)
		end

		if slideJumpTrack.IsPlaying and effectReplicatorModule:HasEffect("Equipped") then
			slideJumpTrack:Stop(0.15)
		end

		stopDodge:FireServer(inputData, effectReplicatorModule:HasEffect("LightAttack"), true)

		local lookVectorUnitMulti = lookVector.Unit * 50

		if sensedPart and sensedPart.AssemblyMass > root.AssemblyMass then
			lookVectorUnitMulti = lookVectorUnitMulti
				+ vectorMathModule.getVelocityAtPoint(sensedPart, groundSensor.HitFrame.Position)
		end

		local bodyVelocity = Instance.new("BodyVelocity")
		bodyVelocity.Name = "SlideJump2"
		bodyVelocity.Velocity = lookVectorUnitMulti
		bodyVelocity.MaxForce = Vector3.new(80000, 80000, 80000, 0)
		bodyVelocity:AddTag("AllowedBM")
		bodyVelocity.Parent = torso

		repDebris:Fire(bodyVelocity, 0.2)

		local slidingSound = sliding:Clone()
		slidingSound.Parent = root
		slidingSound:Play()

		repDebris:Fire(slidingSound, 0.25)

		tweenService
			:Create(slidingSound, TweenInfo.new(0.25), {
				Volume = 0,
			})
			:Play()
	end

	task.delay(0.1, function()
		effectReplicatorModule:RemoveEffectsOfClass("WallJumpCD")
		effectReplicatorModule:RemoveEffectsOfClass("BigMomentum")
		task.wait(2)
	end)

	return true
end)

local freefallCheck = LPH_NO_VIRTUALIZE(function()
	if landedCheck() then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	if effectReplicatorModule:HasEffect("OnShip") then
		effectReplicatorModule:RemoveEffectsOfClass("OnShip")
		effectReplicatorModule:EnsureEffect("ShipJump"):Debris(5, true)
	end

	effectReplicatorModule:EnsureEffect("Falling")

	local fallTime = tick() - (effectReplicatorModule:GetEffectEpoch("Falling") or 0)

	if
		effectReplicatorModule:HasAny("DashIt", "Jumped", "UsingAbility", "LightAttack", "Action")
		or root.AssemblyLinearVelocity.Y > 0
	then
		return freefallTrack.IsPlaying and freefallTrack:Stop(0.1)
	end

	if freefallTrack.IsPlaying then
		return
	end

	if fallTime > 0.5 and root.AssemblyLinearVelocity.Y < 0 then
		freefallTrack.Priority = Enum.AnimationPriority.Movement
		freefallTrack:Play(0.3)
	end
end)

---@return boolean
local inAirCheck = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	if effectReplicatorModule:HasEffect("Swimming") then
		return false
	elseif humanoid:GetState() == Enum.HumanoidStateType.Freefall then
		return true
	elseif effectReplicatorModule:HasEffect("AirBorne") then
		return true
	else
		return false
	end
end)

---@return boolean
local movementCheck = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if effectReplicatorModule:HasEffect("Action") then
		return false
	elseif effectReplicatorModule:HasEffect("NoParkour") then
		return false
	elseif effectReplicatorModule:HasEffect("Knocked") or effectReplicatorModule:HasEffect("Unconscious") then
		return false
	elseif effectReplicatorModule:HasEffect("Pinned") or effectReplicatorModule:HasEffect("Carried") then
		return false
	else
		return true
	end
end)

---@param tbl table
---@param value any
---@return boolean
local manualTableFind = LPH_NO_VIRTUALIZE(function(tbl, value)
	for _, val in next, tbl do
		if val ~= value then
			continue
		end

		return true
	end
end)

---@param tbl table
---@return boolean
local hasNonBooleans = LPH_NO_VIRTUALIZE(function(tbl)
	for _, value in next, tbl do
		if typeof(value) == "boolean" then
			continue
		end

		return false
	end

	return true
end)

---@param tbl table
local getTableLength = LPH_NO_VIRTUALIZE(function(tbl)
	local count = 0

	for _ in next, tbl do
		count = count + 1
	end

	return count
end)

---@param tbl table
local validateKeys = LPH_NO_VIRTUALIZE(function(tbl)
	local allowedKeys = {
		["Left"] = true,
		["Right"] = true,
		["W"] = true,
		["A"] = true,
		["S"] = true,
		["D"] = true,
		["Thumbstick1"] = true,
		["C"] = true,
		["f"] = true,
		["H"] = true,
		["Space"] = true,
		["ctrl"] = true,
	}

	for key, _ in next, tbl do
		if allowedKeys[key] then
			continue
		end

		return false
	end

	return true
end)

---@return Vector3?
InputClient.getLastRollMoveDirection = LPH_NO_VIRTUALIZE(function()
	local rollFunction = InputClient.rollFunctionCache
	if not rollFunction then
		return nil
	end

	local lastRollMoveDirection = nil

	for _, upvalue in next, debug.getupvalues(rollFunction) do
		if typeof(upvalue) ~= "Vector3" then
			continue
		end

		lastRollMoveDirection = upvalue
		break
	end

	if not lastRollMoveDirection then
		lastRollMoveDirection = Vector3.zero
	end

	if lastRollMoveDirection and typeof(lastRollMoveDirection) ~= "Vector3" then
		return nil
	end

	return lastRollMoveDirection
end)

---@return table?
InputClient.getHumanController = LPH_NO_VIRTUALIZE(function()
	---@note: Shouldn't be too many connections to PreSimulation.
	for _, connection in next, getconnections(runService.PreSimulation) do
		local func = connection.Function
		if not func then
			continue
		end

		if iscclosure(func) or isexecutorclosure(func) then
			continue
		end

		local upvalues = debug.getupvalues(func)
		if not upvalues then
			continue
		end

		for _, upvalue in next, upvalues do
			if typeof(upvalue) ~= "table" then
				continue
			end

			if upvalue.Jumping == nil then
				continue
			end

			return upvalue
		end
	end

	return nil
end)

---@return table?
InputClient.getInputData = LPH_NO_VIRTUALIZE(function()
	return inputDataCache
end)

---@param cframe CFrame
---@param ignoreChecks boolean
InputClient.left = LPH_NO_VIRTUALIZE(function(cframe, ignoreChecks, forceGround)
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	if effectReplicatorModule:HasEffect("InDialogue") then
		return
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		return Logger.warn("Cannot left click without input data.")
	end

	local leftClickRemote = KeyHandling.getRemote("LeftClick")
	if not leftClickRemote then
		return
	end

	if not ignoreChecks then
		if
			effectReplicatorModule:HasEffect("LightAttack")
			or effectReplicatorModule:HasEffect("CriticalAttack")
			or effectReplicatorModule:HasEffect("Followup")
			or effectReplicatorModule:HasEffect("Parried")
		then
			return
		end
	end

	---@note: Missing M1-Hold and Input Buffering functionality but I don't think the caller cares about it.
	-- forceGround forces a grounded m1 (no aerial), matching PR's m1_hold no_aerials behavior.
	local aerial = (not forceGround) and inAirCheck() or false
	-- Mark this as our own fire so the UnreliableFireServer hook passes it through (no re-block / re-mixup)
	-- without needing checkcaller() -- see Game/SelfFire.
	SelfFire.wrap(function()
		unreliableFireServer(leftClickRemote, aerial, cframe, inputData)
	end)
end)

---@param tool Tool
InputClient.amantra = LPH_NO_VIRTUALIZE(function(tool)
	local character = players.LocalPlayer.Character
	if not character then
		return Logger.warn("Cannot activate mantra without character.")
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.warn("Cannot activate mantra without humanoid root part.")
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	if not characterHandler then
		return Logger.warn("Cannot activate mantra without character handler.")
	end

	local requests = characterHandler:FindFirstChild("Requests")
	if not requests then
		return Logger.warn("Cannot activate mantra without requests.")
	end

	local activateMantraRemote = requests:FindFirstChild("ActivateMantra")
	if not activateMantraRemote then
		return Logger.warn("Cannot activate mantra without ActivateMantra remote.")
	end

	if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
		return Logger.warn("Cannot activate mantra without valid tool.")
	end

	activateMantraRemote:FireServer(tool)
end)

InputClient.crouch = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	if not requests then
		return
	end

	local crouchRemote = requests:FindFirstChild("ServerCrouch")
	if not crouchRemote then
		return
	end

	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")

	if crouchTrack then
		crouchTrack:Play()
	end

	crouchRemote:FireServer(true)
	effectReplicatorModule:CreateEffect("ClientCrouch")

	crouchActive = true
	crouchSession = crouchSession + 1
	local session = crouchSession

	task.spawn(function()
		while crouchActive and crouchSession == session and crouchTrack do
			if humanoid and humanoid.MoveDirection.Magnitude < 0.1 then
				crouchTrack:AdjustSpeed(0)
			elseif humanoid then
				crouchTrack:AdjustSpeed(humanoid.WalkSpeed / 15.5)
			end

			task.wait()
		end
	end)
end)

InputClient.uncrouch = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	if not requests then
		return
	end

	local crouchRemote = requests:FindFirstChild("ServerCrouch")
	if not crouchRemote then
		return
	end

	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule then
		return
	end

	crouchActive = false
	crouchRemote:FireServer(false)

	if crouchTrack then
		crouchTrack:Stop()
	end

	effectReplicatorModule:RemoveEffectsOfClass("ClientCrouch")
end)

InputClient.slide = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local serverSlide = KeyHandling.getRemote("ServerSlide")
	if not serverSlide then
		return
	end

	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule then
		return
	end

	local characterHashes = replicatedStorage:FindFirstChild("CharacterHashes")
	local characterHashesModule = characterHashes and require(characterHashes)
	local hashData = characterHashesModule and characterHashesModule.Snap(character)

	local healthPercent = humanoid.Health / humanoid.MaxHealth
	if hashData and hashData["Endurance Runner"] then
		healthPercent = 0.25 + healthPercent * 0.75
	end

	local agility = character:FindFirstChild("PassiveAgility")
	local agilityValue = agility and agility.Value or 0
	local isDanger = effectReplicatorModule:HasEffect("DangerPvP")
	local speed = 20 + agilityValue * (isDanger and 0.4 or 0.5) * healthPercent

	if effectReplicatorModule:HasEffect("ClientDodge") then
		speed = speed + (isDanger and 3 or 10)
	end

	if hashData then
		local kongaRing = hashData["Konga's Clutch Ring"]
		local slick = hashData.Slick

		if kongaRing then
			speed = speed + (isDanger and 5 or 15)
		end

		if slick then
			speed = speed + (isDanger and 0 or 15)
		end

		if not kongaRing and not slick and effectReplicatorModule:FindEffect("BigMomentum") then
			speed = speed + 15
		end
	end

	if effectReplicatorModule:HasEffect("AirBorne") then
		speed = speed + 15
	end

	if effectReplicatorModule:HasEffect("SpeedSlide") then
		speed = speed + 10
	elseif effectReplicatorModule:HasEffect("WardingRadiance") then
		speed = speed + (isDanger and 7.5 or 15)
	end

	local slideEffect = effectReplicatorModule:CreateEffect("ClientSlide2")
	slideEffect:Debris(60)

	if groundslideTrack then
		groundslideTrack:Play()
	end

	serverSlide:FireServer(true)

	local rootCollider = character:FindFirstChild("RootCollider")
	local colliderWeld = rootCollider and rootCollider:FindFirstChild("ColliderWeld")
	if colliderWeld then
		colliderWeld.C0 = CFrame.new(0, -1.9, 0)
	end

	local velocity = root.CFrame.LookVector * speed
	root.AssemblyLinearVelocity = velocity

	local bodyVelocity = Instance.new("BodyVelocity")
	bodyVelocity:AddTag("LocalMover")
	bodyVelocity.Name = "SlideVel"
	bodyVelocity.MaxForce = Vector3.new(100000, 0, 100000)
	bodyVelocity.Velocity = velocity
	bodyVelocity:AddTag("AllowedBM")
	bodyVelocity.Parent = root

	slideBodyVelocity = bodyVelocity
	slideActive = true

	task.spawn(function()
		while slideActive and bodyVelocity.Parent do
			task.wait(0.03)

			local isIce = humanoid.FloorMaterial == Enum.Material.Ice
				and not (
					hashData
					and (
						hashData["Steady Footing"]
						or effectReplicatorModule:HasEffect("WardingRadiance")
					)
				)

			speed = speed - (isIce and 0.25 or 1)
			if speed <= 0 then
				break
			end

			bodyVelocity.Velocity = root.CFrame.LookVector * speed
		end
	end)

	task.delay(3, function()
		if slideActive then
			InputClient.unslide()
		end
	end)
end)

InputClient.unslide = LPH_NO_VIRTUALIZE(function()
	slideActive = false

	local serverSlideStop = KeyHandling.getRemote("ServerSlideStop")
	if serverSlideStop then
		serverSlideStop:FireServer()
	end

	if slideBodyVelocity and slideBodyVelocity.Parent then
		slideBodyVelocity:Destroy()
		slideBodyVelocity = nil
	end

	local character = players.LocalPlayer.Character
	if character then
		local rootCollider = character:FindFirstChild("RootCollider")
		local colliderWeld = rootCollider and rootCollider:FindFirstChild("ColliderWeld")
		if colliderWeld then
			colliderWeld.C0 = CFrame.new()
		end
	end

	if groundslideTrack then
		groundslideTrack:Stop()
	end

	local effectReplicatorModule = getEffectModule()
	if effectReplicatorModule then
		effectReplicatorModule:RemoveEffectsOfClass("ClientSlide2")
	end
end)

InputClient.vent = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return Logger.warn("Cannot vent without character.")
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.warn("Cannot vent without humanoid root part.")
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	if not characterHandler then
		return Logger.warn("Cannot vent without character handler.")
	end

	local requests = characterHandler:FindFirstChild("Requests")
	if not requests then
		return Logger.warn("Cannot vent without requests.")
	end

	local ventRemote = requests:FindFirstChild("Vent")
	if not ventRemote then
		return Logger.warn("Cannot vent without vent remote.")
	end

	ventRemote:FireServer()
end)

---@param options DodgeOptions
InputClient.dodge = LPH_NO_VIRTUALIZE(function(options)
	-- Dodge is now a DIRECT remote (no longer keyed via KeyHandler), so getRemote("Dodge") returns nil.
	-- Resolve it by name from CharacterHandler.Requests (where the other combat remotes live), falling
	-- back to the global ReplicatedStorage.Requests.
	local dodgeCharacter = players.LocalPlayer and players.LocalPlayer.Character
	local dodgeHandler = dodgeCharacter and dodgeCharacter:FindFirstChild("CharacterHandler")
	local dodgeRequests = dodgeHandler and dodgeHandler:FindFirstChild("Requests")
	local dodge = dodgeRequests and dodgeRequests:FindFirstChild("Dodge")
	if not dodge then
		local globalRequests = replicatedStorage:FindFirstChild("Requests")
		dodge = globalRequests and globalRequests:FindFirstChild("Dodge")
	end
	if not dodge then
		return Logger.warn("Cannot dodge without dodge remote.")
	end

	local stopDodge = KeyHandling.getRemote("StopDodge")
	if not stopDodge then
		return Logger.warn("Cannot dodge without stop dodge remote.")
