---@note: I sold my soul to the GC gods because there's no other way. This basically does a ton of intensive stuff. Updates are only done when needed.
InputClient.cache = LPH_NO_VIRTUALIZE(function()
	InputClient.sprintFunctionCache = nil
	InputClient.rollFunctionCache = nil
	inputDataCache = nil

	for _, value in next, getgc() do
		if typeof(value) ~= "function" or iscclosure(value) or isexecutorclosure(value) then
			continue
		end

		local functionName = debug.getinfo(value).name
		if not functionName then
			continue
		end

		if functionName ~= "Sprint" and functionName ~= "Roll" then
			continue
		end

		local upvalues = debug.getupvalues(value)

		if not upvalues or #upvalues <= 0 then
			continue
		end

		if functionName == "Sprint" then
			InputClient.sprintFunctionCache = value

			if not LPH_OBFUSCATED or shared.Aero.verbose then
				Logger.warn("Sprint function (%s) cache successful.", tostring(value))
			end
		end

		if functionName == "Roll" then
			InputClient.rollFunctionCache = value

			if not LPH_OBFUSCATED or shared.Aero.verbose then
				Logger.warn("Roll function (%s) cache successful.", tostring(value))
			end
		end

		if InputClient.sprintFunctionCache and InputClient.rollFunctionCache then
			break
		end
	end

	local inputData = {}

	for _, connection in next, getconnections(runService.RenderStepped) do
		local func = connection.Function
		if not func then
			continue
		end

		if iscclosure(func) then
			continue
		end

		local consts = debug.getconstants(func)
		if not manualTableFind(consts, ".lastHBCheck") then
			continue
		end

		local upvalues = debug.getupvalues(func)

		---@note: Only table with boolean values is the input table. Find a better way to filter this?
		for _, upvalue in next, upvalues do
			if typeof(upvalue) ~= "table" or getrawmetatable(upvalue) then
				continue
			end

			if not hasNonBooleans(upvalue) then
				continue
			end

			if getTableLength(upvalue) >= 1 and not validateKeys(upvalue) then
				continue
			end

			inputData = upvalue
			break
		end
	end

	inputDataCache = inputData

	local assets = replicatedStorage:FindFirstChild("Assets")
	local anims = assets and assets:FindFirstChild("Anims")
	local movement = anims and anims:FindFirstChild("Movement")
	local roll = movement and movement:FindFirstChild("Roll")
	local cancelLeft = roll and roll:FindFirstChild("CancelLeft")
	local cancelRight = roll and roll:FindFirstChild("CancelRight")

	local character = players.LocalPlayer.Character
	local characterHandler = character and character:FindFirstChild("CharacterHandler")
	local inputClient = characterHandler and characterHandler:FindFirstChild("InputClient")
	local freefallAnim = inputClient and inputClient:FindFirstChild("FreefallAnim")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local slideJumpAnim = inputClient and inputClient:FindFirstChild("SlideJump")
	local jumpAnim = inputClient and inputClient:FindFirstChild("Jump")
	local crouchAnim = movement and movement:FindFirstChild("Crouch")
	local groundslideAnim = movement and movement:FindFirstChild("Groundslide")

	if not slideJumpAnim or not jumpAnim or not humanoid or not cancelLeft or not cancelRight or not freefallAnim then
		return false
	end

	---@note: Tracks are reset on CharacterAdded, so retries must not load a fresh copy each time.
	slideJumpTrack = slideJumpTrack or humanoid:LoadAnimation(slideJumpAnim)
	freefallTrack = freefallTrack or humanoid:LoadAnimation(freefallAnim)
	cancelLeftTrack = cancelLeftTrack or humanoid:LoadAnimation(cancelLeft)
	cancelRightTrack = cancelRightTrack or humanoid:LoadAnimation(cancelRight)
	jumpAnimTrack = jumpAnimTrack or humanoid:LoadAnimation(jumpAnim)

	if crouchAnim then
		crouchTrack = crouchTrack or humanoid:LoadAnimation(crouchAnim)
	end

	if groundslideAnim then
		groundslideTrack = groundslideTrack or humanoid:LoadAnimation(groundslideAnim)
	end

	return InputClient.sprintFunctionCache ~= nil and InputClient.rollFunctionCache ~= nil and inputDataCache ~= nil
end)

-- Re-populate the caches on the MAIN thread (serial phase), bounded + retried. This used to be driven by the
-- global `tostring` hook in Hooking.lua, but that hook is invoked from EVERY Luau VM, so the
-- getgc / getconnections / LoadAnimation work inside cache() could run during Deepwoken's parallel Actor
-- phase and Kernel-panic the client (RSL - panic: ...Kernel). A plain task.spawn keeps all of those main-VM
-- ops in the serial phase, where they're legal. cache() returns true only once the game's Sprint/Roll
-- functions and the inputData table exist, so retry until it succeeds (or a newer character supersedes this
-- run via the session bump), then STOP -- steady-state cost is zero, no periodic getgc scanning.
local cacheSession = 0
InputClient.ensureCached = LPH_NO_VIRTUALIZE(function()
	cacheSession = cacheSession + 1
	local session = cacheSession

	task.spawn(function()
		local attempts = 0
		while cacheSession == session and attempts < 40 do
			local ok, success = pcall(InputClient.cache)
			if ok and success then
				break
			end
			attempts = attempts + 1
			task.wait(0.5)
		end
	end)
end)

local characterAddedConnection = players.LocalPlayer.CharacterAdded:Connect(function()
	InputClient.sprintFunctionCache = nil
	InputClient.rollFunctionCache = nil
	inputDataCache = nil

	freefallTrack = nil
	slideJumpTrack = nil
	cancelLeftTrack = nil
	cancelRightTrack = nil
	jumpAnimTrack = nil
	crouchTrack = nil
	groundslideTrack = nil

	if slideBodyVelocity and slideBodyVelocity.Parent then
		slideBodyVelocity:Destroy()
	end

	slideBodyVelocity = nil
	slideActive = false
	crouchActive = false

	-- Re-grab Sprint/Roll/inputData + animation tracks for the new character, on the main thread.
	InputClient.ensureCached()
end)

-- Prime the cache for a character that already exists at load time (re-exec / late inject), since the
-- CharacterAdded above won't fire for it.
if players.LocalPlayer.Character then
	InputClient.ensureCached()
end

function InputClient.detach()
	cacheSession = cacheSession + 1
	characterAddedConnection:Disconnect()
end

return InputClient

end)
__bundle_register("Utility/TaskSpawner", function(require, _LOADED, __bundle_register, __bundle_modules)
local TaskSpawner = {}

---@module Utility.Profiler
local Profiler = require("Utility/Profiler")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local RunService = game:GetService("RunService")

---@param label string
---@param delay function
---@param callback function
---@vararg any
function TaskSpawner.delay(label, delay, callback, ...)
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			local timestamp = os.clock()

			while os.clock() - timestamp < delay() do
				RunService.RenderStepped:Wait()
			end

			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	return task.spawn(taskFunction, ...)
end

---@param label string
---@param callback function
---@vararg any
function TaskSpawner.spawn(label, callback, ...)
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	return task.spawn(taskFunction, ...)
end

return TaskSpawner

end)
__bundle_register("Game/SelfFire", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Shared "aero is firing this remote itself" flag. It replaces checkcaller() inside the process-global
---@note: FireServer hooks. checkcaller() is executor reflection, and when the game fires an attack remote from
---@note: its parallel Actor VM the process-global hook runs there -- reflection mid-parallel-phase is the illegal
---@note: cross-phase op the engine Kernel-panics on (RSL - panic ...Kernel,2090), the same class as the old
---@note: getgc-in-tostring crash. Project Rain never calls checkcaller in a process-global hook; it distinguishes
---@note: its own fires by STATE. So do we: aero sets this flag around its own attack re-fires, and the hook reads
---@note: the flag -- a plain boolean, no reflection, safe to read from any VM -- instead of checkcaller().

local SelfFire = { active = false }

---Run fn with the self-fire flag raised, always lowering it again (even if fn errors). Use this to wrap aero's
---own fires of a remote the FireServer hooks intercept, so the hook treats them as ours and passes them through.
---@param fn function
function SelfFire.wrap(fn)
	SelfFire.active = true

	local ok, err = pcall(fn)

	SelfFire.active = false

	if not ok then
		error(err, 0)
	end
end

return SelfFire

end)
__bundle_register("Game/KeyHandling", function(require, _LOADED, __bundle_register, __bundle_modules)
local KeyHandling = {}

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- KeyHandler bypass, project-rain-oss style. aero used to REIMPLEMENT the game's name-encoder
-- (a full SHA-256) and recompute keys itself -- fragile: the moment the game changes its encoding
-- or keying, every keyed remote silently fails to resolve. Instead we grab the game's OWN encoder
-- and remote table straight out of its live KeyHandler state via getgc, so we always match whatever
-- the game is doing (it's been actively reworking this -- remotes like Dodge/Sprint have left the
-- key system entirely).
--
-- The KeyHandler state table is tagged with a magic constant at index 9 ("heaven key"), and carries
-- the encoded-name -> remote map at [12] and the encoder function at [13]. The heaven_key expression
-- is reproduced verbatim from project-rain-oss so the float value matches the game's byte-for-byte.

local pi = 0.125 + tonumber("3")
local heaven_key = 2754 * (72 % (0.6769230769205024 * 7 * 7 % 5 % 64 % 41 / 66 + 12) / 54 / (4 / 36 + 5.3655660377358485) + 1 * 4 % 52 * 21 / 4 % 35 / 3) / 35 * 38 + (66 + (8 + 4 + 5 + 2 + 19035.52631578947) / 34 + 40 % 41 / 56 % 65 * 57 + 3381) + 420 + 35 * (0.3150684931506849 + 69 + 14 / 56 + 28 + 36) + (pi)

local remotes = nil -- the game's encoded-name -> remote instance table (state[12])
local encf = nil    -- the game's name-encoder function (state[13])
local cache = {}    -- remoteName -> encoded key

---Find the game's KeyHandler state in getgc (identified by the heaven_key tag at index 9) and grab
---its remotes table + encoder.
---@return boolean
local function grabKeyHandler()
	for _, tbl in next, getgc(true) do
		if typeof(tbl) ~= "table" then
			continue
		end
		if getrawmetatable(tbl) then
			continue
		end
		if #tbl ~= 13 or tbl[9] ~= heaven_key then
			continue
		end

		remotes = tbl[12]
		encf = tbl[13]
		return remotes ~= nil and encf ~= nil
	end

	return false
end

---Encode a remote name with the game's own encoder (cached).
---@param remoteName string
---@return any
local function encode(remoteName)
	local encoded = cache[remoteName]
	if encoded == nil then
		local ok, res = pcall(encf, remoteName)
		if not ok then
			return nil
		end
		encoded = res
		cache[remoteName] = encoded
	end
	return encoded
end

KeyHandling.init = LPH_NO_VIRTUALIZE(function()
	local retries = 0

	while true do
		if (remotes and encf) or grabKeyHandler() then
			break
		end

		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("KeyHandler retry (%i attempts) grabbing remotes/enc_f", retries)
		end

		retries = retries + 1

		if retries >= 10 then
			Logger.warn("KeyHandler failed to initialize after 10 attempts.")

			return error("Please report this message to the developers.")
		end

		task.wait(0.5)
	end
end)

---Resolve a keyed remote by its original name via the game's encoder.
---@param remoteName string
---@return Instance|nil
KeyHandling.getRemote = LPH_NO_VIRTUALIZE(function(remoteName)
	if not (remotes and encf) then
		return nil
	end

	local encoded = encode(remoteName)

	return (encoded ~= nil and remotes[encoded]) or nil
end)

---Resolve a keyed remote using ONLY the already-computed key cache -- it never calls the game's encoder.
---This is project-rain-oss's `get_cache`: the process-global FireServer / UnreliableFireServer hooks run on
---every remote fire the game makes, and PR only ever does pure table reads there (cache[name] -> remotes[key]).
---aero used to call getRemote() -> encode() -> pcall(encf, ...) from those hooks, which re-invokes the game's
---grabbed encoder closure on every fire for any name that has left the key system (encode never caches a nil
---result, so it retries forever). That high-frequency game-closure call from the global hook body is the
---always-on divergence from PR. Resolving the keys once up front (KeyHandling.prewarm) and reading the cache
---here keeps the hot path to pure table lookups, exactly like PR. remotes[encoded] stays live, so re-keys are
---still followed; only the encoder call is lifted out of the hook.
---@param remoteName string
---@return Instance|nil
KeyHandling.getCachedRemote = LPH_NO_VIRTUALIZE(function(remoteName)
	if not remotes then
		return nil
	end

	local encoded = cache[remoteName]
	if encoded == nil then
		return nil
	end

	return remotes[encoded] or nil
end)

---Compute and cache the keys for a set of remote names once, from the current (main, synchronized) thread.
---Call this at init so the global fire hooks can resolve those remotes with getCachedRemote without ever
---touching the encoder from the hook context.
---@param names string[]
KeyHandling.prewarm = LPH_NO_VIRTUALIZE(function(names)
	if not (remotes and encf) then
		return
	end

	for _, remoteName in ipairs(names) do
		encode(remoteName)
	end
end)

---Register a remote under its (original) name's key, then it can be renamed by the caller.
---@param remote Instance
KeyHandling.registerRemote = LPH_NO_VIRTUALIZE(function(remote)
	if not (remotes and encf) then
		return
	end

	local encoded = encode(remote.Name)
	if encoded ~= nil then
		remotes[encoded] = remote
	end
end)

return KeyHandling

end)
__bundle_register("Features/Automation/Objects/StateMachine", function(require, _LOADED, __bundle_register, __bundle_modules)
-- StateMachine: a faithful port of project-rain-oss's `src/utility/statemachine.lua`.
-- An event/callback finite state machine. Events declare from->to transitions; firing an event named
-- `foo` (via `fsm:foo(...)`) runs onbefore<foo> / onleave<from> / onenter<to> / onafter<foo> callbacks.
-- Transitions are synchronous unless a leave/enter handler returns StateMachine.ASYNC.
local StateMachine = {}
StateMachine.__index = StateMachine

local NONE = "none"
local ASYNC = "async"

local unpack = table.unpack or unpack

local function callHandler(handler, params)
	if not handler then
		return
	end
	return handler(unpack(params))
end

local function createTransition(name)
	local can, to, from, params

	local function transition(self, ...)
		if self.asyncState == NONE then
			can, to = self:can(name)
			from = self.current
			params = { self, name, from, to, ... }

			if not can then
				self.currentTransitioningEvent = nil
				return false
			end

			self.currentTransitioningEvent = name
			local beforeReturn = callHandler(self["onbefore" .. name], params)
			local leaveReturn = callHandler(self["onleave" .. from], params)

			if not self["onleave" .. from] and self.dexit then
				leaveReturn = self.dexit()
			end

			if beforeReturn == false or leaveReturn == false then
				self.currentTransitioningEvent = nil
				return false
			end

			self.asyncState = name .. "WaitingOnLeave"

			if leaveReturn ~= ASYNC then
				return transition(self, ...)
			end

			return true
		elseif self.asyncState == name .. "WaitingOnLeave" then
			self.current = to

			local enterReturn = callHandler(self["onenter" .. to] or self["on" .. to], params)

			self.asyncState = name .. "WaitingOnEnter"

			if enterReturn ~= ASYNC then
				return transition(self, ...)
			end

			return true
		elseif self.asyncState == name .. "WaitingOnEnter" then
			callHandler(self["onafter" .. name] or self["on" .. name], params)
			callHandler(self["onstatechange"], params)
			self.asyncState = NONE
			self.currentTransitioningEvent = nil
			return true
		else
			if string.find(self.asyncState, "WaitingOnLeave") or string.find(self.asyncState, "WaitingOnEnter") then
				self.asyncState = NONE
				return transition(self, ...)
			end
		end

		self.currentTransitioningEvent = nil
		return false
	end

	return transition
end

local function addToMap(map, event)
	if type(event.from) == "string" then
		map[event.from] = event.to
	else
		for _, from in ipairs(event.from) do
			map[from] = event.to
		end
	end
end

function StateMachine.create(options)
	assert(options.events)

	local fsm = {}
	setmetatable(fsm, StateMachine)

	fsm.options = options
	fsm.current = options.initial or "none"
	fsm.asyncState = NONE
	fsm.events = {}
	fsm.dexit = options.dexit

	for _, event in ipairs(options.events or {}) do
		local name = event.name
		fsm[name] = fsm[name] or createTransition(name)
		fsm.events[name] = fsm.events[name] or { map = {} }
		addToMap(fsm.events[name].map, event)
	end

	for name, callback in pairs(options.callbacks or {}) do
		fsm[name] = callback
	end

	return fsm
end

function StateMachine:is(state)
	return self.current == state
end

function StateMachine:can(e)
	local event = self.events[e]
	local to = event and event.map[self.current] or event.map["*"]
	return to ~= nil, to
end

function StateMachine:cannot(e)
	return not self:can(e)
end

function StateMachine:transition(event)
	if self.currentTransitioningEvent == event then
		return self[self.currentTransitioningEvent](self)
	end
end

function StateMachine:cancelTransition(event)
	if self.currentTransitioningEvent == event then
		self.asyncState = NONE
		self.currentTransitioningEvent = nil
	end
end

StateMachine.NONE = NONE
StateMachine.ASYNC = ASYNC

return StateMachine

end)
__bundle_register("Game/AntiAFK", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@note: You should never leave the service access running here. Use a direct reference because we would want to know if they add any detections targeting this feature.
local AntiAFK = { wanters = {} }

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

local players = game:GetService("Players")

local afkMaid = Maid.new()

function AntiAFK.start(identifier)
	AntiAFK.wanters[identifier] = true
end

function AntiAFK.stop(identifier)
	AntiAFK.wanters[identifier] = nil
end

function AntiAFK.init()
	local idledSignal = Signal.new(players.LocalPlayer.Idled)

	idledSignal:connect("AntiAFK_OnIdled", function()
		if not AntiAFK.wanters or #AntiAFK.wanters == 0 then
			return
		end

		local virtualUser = game:GetService("VirtualUser")
		virtualUser:CaptureController()
		virtualUser:ClickButton2(Vector2.new())
	end)
end

function AntiAFK.detach()
	afkMaid:clean()
end

return AntiAFK
end)()

end)
__bundle_register("Features/Game/Tweening", function(require, _LOADED, __bundle_register, __bundle_modules)
local Tweening = { active = false, queue = {} }

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local players = game:GetService("Players")

---@param dt number
Tweening.update = LPH_NO_VIRTUALIZE(function(dt)
	Tweening.active = false

	local current = Tweening.current()
	if not current then
		return
	end

	local part = typeof(current.goal) == "Instance" and current.goal or nil
	if part and not part.Parent then
		return Tweening.stop(current.identifier)
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	Tweening.active = true

	local startPosition = humanoidRootPart.Position
	local targetCFrame = typeof(current.goal) == "Instance" and current.goal.CFrame or current.goal
	local targetPosition = targetCFrame.Position

	local distanceToTarget = (targetPosition - startPosition).Magnitude

	if distanceToTarget <= 0.01 then
		return
	end

	local direction = (targetPosition - startPosition) / distanceToTarget
	local moveDistance = (Configuration.expectOptionValue("TweenStudsPerSecond") or 200) * dt

	local newPosition = nil

	if moveDistance >= distanceToTarget then
		newPosition = targetPosition
	else
		newPosition = startPosition + (direction * moveDistance)
		if not current.smoothY then
			newPosition = Vector3.new(newPosition.X, targetPosition.Y, newPosition.Z)
		end
	end

	local rotation = (targetCFrame - targetCFrame.Position)

	local _, _, _, m00, m01, m02, m10, m11, m12, m20, m21, m22 = rotation:GetComponents()

	if
		m00 == m00
		and m01 == m01
		and m02 == m02
		and m10 == m10
		and m11 == m11
		and m12 == m12
		and m20 == m20
		and m21 == m21
		and m22 == m22
	then
		humanoidRootPart.CFrame = CFrame.new(newPosition) * rotation
	else
		humanoidRootPart.CFrame = CFrame.new(newPosition)
	end

	local newDistanceToTarget = (targetPosition - newPosition).Magnitude

	current.reached = false

	if newDistanceToTarget >= 1.0 then
		return
	end

	if current.swc then
		return Tweening.stop(current.identifier)
	end

	current.reached = true
end)

---@param identifier string
---@return number, table?
function Tweening.get(identifier)
	for idx, data in next, Tweening.queue do
		if data.identifier ~= identifier then
			continue
		end

		return idx, data
	end

	return nil
end

---@param identifier string
function Tweening.wait(identifier)
	local _, data = Tweening.get(identifier)
	if not data then
		return
	end

	repeat
		task.wait()
	until data.reached
end

---@return table?
function Tweening.current()
	return Tweening.queue[#Tweening.queue]
end

---@param identifier string
---@param goal BasePart|CFrame
---@param swc boolean Whether or not to stop when we reach the goal.
---@param smoothY boolean? Interpolate vertical movement instead of snapping to the target height.
function Tweening.goal(identifier, goal, swc, smoothY)
	local _, data = Tweening.get(identifier)

	if data then
		data.goal = goal
		data.swc = swc
		data.smoothY = smoothY == true
		data.reached = false
	else
		table.insert(Tweening.queue, 1, {
			identifier = identifier,
			goal = goal,
			swc = swc,
			smoothY = smoothY == true,
			reached = false,
		})
	end
end

---@param identifier string
function Tweening.stop(identifier)
	local idx, _ = Tweening.get(identifier)
	if not idx then
		return
	end

	table.remove(Tweening.queue, idx)
end

return Tweening

end)
__bundle_register("Utility/Prompt", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Hardened ProximityPrompt firing.
--
-- Why this exists: bare `fireproximityprompt(prompt)` "works for some users and
-- fails for others" on the SAME executor because the failures are game-state, not
-- executor. Deepwoken runs with StreamingEnabled, so a prompt's part may not be
-- streamed in for a given client yet (slower stream = further away / lower memory /
-- lower graphics / fired too soon after a teleport), and firing against a
-- streamed-out part silently no-ops. On top of that the engine enforces
-- RequiresLineOfSight / MaxActivationDistance / Enabled / HoldDuration at trigger
-- time, and whether those bite depends on the player's camera, morph/accessories
-- obstructing the line of sight, and how the executor implements the function.
--
-- Prompt.fire() removes every one of those variables: it requests streaming around
-- the prompt, forces the prompt open (LOS off, huge distance, no hold, enabled),
-- fires, then restores the originals so the game's own UI/logic is untouched.
local Prompt = {}

local players = game:GetService("Players")

---Request the world region around a part to stream in, so the part is resident
---(has physics + a valid trigger) before we fire. No-op on non-streaming games.
---@param part BasePart?
local function ensureStreamedIn(part)
	if not part then
		return
	end
	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end
	pcall(function()
		if localPlayer.RequestStreamingAround then
			localPlayer:RequestStreamingAround(part.Position)
		end
	end)
end

---Fire a ProximityPrompt reliably.
---@param prompt Instance? A ProximityPrompt, or any instance to search under for one.
---@return boolean fired
function Prompt.fire(prompt)
	if not prompt then
		return false
	end

	-- Accept a model/part and dig out the prompt so callers don't have to.
	if not prompt:IsA("ProximityPrompt") then
		local found = prompt:FindFirstChildWhichIsA("ProximityPrompt", true)
		if not found then
			return false
		end
		prompt = found
	end

	local part = prompt:FindFirstAncestorWhichIsA("BasePart") or prompt.Parent
	if typeof(part) == "Instance" and part:IsA("BasePart") then
		ensureStreamedIn(part)
	end

	local fireProx = fireproximityprompt

	local fired = false
	pcall(function()
		-- Snapshot the properties the engine checks at trigger time and force them
		-- into the state that always allows a fire. ProximityPrompt property writes
		-- from the client are local-only (never replicate), so this only affects our
		-- own trigger path and is restored immediately after.
		local origEnabled = prompt.Enabled
		local origLOS = prompt.RequiresLineOfSight
		local origDist = prompt.MaxActivationDistance
		local origHold = prompt.HoldDuration

		prompt.Enabled = true
		prompt.RequiresLineOfSight = false
		prompt.MaxActivationDistance = math.max(origDist, 1000)
		prompt.HoldDuration = 0

		if fireProx then
			fireProx(prompt)
			fired = true
		elseif prompt.InputHoldBegin then
			prompt:InputHoldBegin()
			task.wait(origHold or 0)
			prompt:InputHoldEnd()
			fired = true
		end

		prompt.Enabled = origEnabled
		prompt.RequiresLineOfSight = origLOS
		prompt.MaxActivationDistance = origDist
		prompt.HoldDuration = origHold
	end)

	return fired
end

-- =========================================================================================================
-- Interact-key press (used by the automations instead of firing ProximityPrompts directly).
--
-- Rather than fireproximityprompt(), the automations press the real interact key -- like a human -- after
-- they've tweened to the target. The key is configurable under the Automations panel ("Interact Key",
-- default E). We still stream the target's part in and read its HoldDuration so a hold-prompt registers.
-- =========================================================================================================
local DEFAULT_INTERACT_KEY = Enum.KeyCode.E

local function resolveInteractKey()
	local picker = Options and Options.AutomationInteractKey
	local name = picker and picker.Value
	if type(name) == "string" and name ~= "" and name ~= "None" and name ~= "N/A" then
		local ok, code = pcall(function()
			return Enum.KeyCode[name]
		end)
		if ok and code then
			return code
		end
	end
	return DEFAULT_INTERACT_KEY
end

---Press the configured interact key. `prompt` is optional, used only to stream the target in and read its
---HoldDuration (so a hold-prompt is held long enough); the actual interaction is the key press.
---@param prompt Instance?
---@return boolean pressed
function Prompt.interact(prompt)
	local holdDuration = 0

	if typeof(prompt) == "Instance" then
		local resolved = prompt
		if not resolved:IsA("ProximityPrompt") then
			resolved = resolved:FindFirstChildWhichIsA("ProximityPrompt", true)
		end
		if resolved and resolved:IsA("ProximityPrompt") then
			holdDuration = resolved.HoldDuration or 0
			local part = resolved:FindFirstAncestorWhichIsA("BasePart")
			if part then
				ensureStreamedIn(part)
			end
		elseif prompt:IsA("BasePart") then
			ensureStreamedIn(prompt)
		end
	end

	local key = resolveInteractKey()
	local pressed = false
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, key, false, game)
		task.wait(holdDuration + 0.06)
		vim:SendKeyEvent(false, key, false, game)
		pressed = true
	end)
	return pressed
end

return Prompt

end)
__bundle_register("Features/Automation/AutoNotes", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Notes (Ministry note farm): a aero port of project-rain-oss's `ministry_notefarm.lua`, on the
-- AutomationStruct + StateMachine framework. Creates an Etris character, shares Knowledge with the
-- Soothsayer, deposits Notes at the bank (or a guild base + treasury), then wipes and repeats. Stops once
-- the bank is full ("max notes").
--
-- Public surface:
--   AutoNotes.start() / .stop() / .inValidPlace()  (overworld / character creation / fragments)
-- Persistence key: "notesdata" { slot, startedAt, maxNotes }.
-- Menu toggle read here: NotesUseGuild.
local AutoNotes = {}

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")
---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")
---@module Game.Wipe
local Wipe = require("Game/Wipe")
---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")
---@module Utility.Prompt
local Prompt = require("Utility/Prompt")
---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.SafeClick
local safeClick = require("Utility/SafeClick")
---@module GUI.Library
local Library = require("GUI/Library")
---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")
---@module Utility.Maid
local Maid = require("Utility/Maid")
---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")
---@module Features.Automation.Objects.StateMachine
local StateMachine = require("Features/Automation/Objects/StateMachine")
---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("Features/Automation/Objects/AutomationStruct")
---@module Features.Automation.Objects.General
local General = require("Features/Automation/Objects/General")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local MAIN_GAME_PLACE_ID = 6032399813 -- overworld (Etrean Luminant) + character creation.
local MOVE_ID = "AutoNotes_Move"

local running = false
local struct = nil
local maid = Maid.new()
local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end
local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function currentArea()
	local lp = localPlayer()
	return lp and lp:GetAttribute("CurrentArea")
end
local function isRunning()
	return running
end
function AutoNotes.inValidPlace()
	return game.PlaceId == MAIN_GAME_PLACE_ID
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "AeroAutoNotesOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()
	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Notes",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })
	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })
	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoNotes.stop()
	end)
	pcall(function()
		Library:MakeDraggable(outer)
	end)
end
local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end
-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("notesdata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.NotesTweenSpeed and Options.NotesTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end
local function tempTween(cframe, speed)
	setSpeed(speed or 250)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end
local function playerCheck(mag, custom)
	local origin = custom or (root() and root().Position)
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character.HumanoidRootPart.Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function playersNear(target, mag)
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (player.Character.HumanoidRootPart.Position - target.Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end
local function playerSafeTween(cf, speed, level)
	if playerCheck(200) then
		serverHop()
		while task.wait() do
		end
		return
	end
	local yLevel = level or -20
	local r = root()
	if not r then
		return
	end
	r.CFrame = r.CFrame + Vector3.new(0, yLevel, 0)
	tempTween(cf + Vector3.new(0, yLevel, 0), speed)
	if playerCheck(200, cf.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
end
local function dialogueChoice(value)
	pcall(function()
		replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ choice = value })
	end)
end
local function dialogueExit()
	pcall(function()
		replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ exit = true })
	end)
end
local function click(btn)
	if btn then
		-- safeClick (handler .Function call) instead of firesignal -- firesignal is a native-crash risk pcall
		-- can't catch (see Utility/SafeClick).
		safeClick(btn)
		task.wait(0.2)
	end
end
local function dialogueOpen()
	local gui = playerGui()
	local dg = gui and gui:FindFirstChild("DialogueGui")
	return dg ~= nil and dg.Enabled
end
local function currencyText(name)
	local gui = playerGui()
	local frame = gui and gui:FindFirstChild("CurrencyGui")
	frame = frame and frame:FindFirstChild("CurrencyFrame")
	local entry = frame and frame:FindFirstChild(name)
	local amount = entry and entry:FindFirstChild("Amount")
	return amount and amount.Text or ""
end
local function currentNotes()
	return tonumber((currencyText("Notes"):gsub("%D", ""))) or 0
end
local function hasKnowledge()
	local k = tonumber(currencyText("ShrinePoints"))
	return k ~= nil and k > 0
end

-- =========================================================================================================
-- Banking.
-- =========================================================================================================
local function setBankAmountAndConfirm(amount)
	local gui = playerGui()
	repeat
		task.wait(0.1)
		gui = playerGui()
	until (gui and gui:FindFirstChild("ChoicePrompt")) or not running
	local cp = gui and gui:FindFirstChild("ChoicePrompt")
	if not cp then
		return false
	end
	local slider = cp:FindFirstChild("ChoiceFrame", true)
	slider = slider and slider:FindFirstChild("DescSheet", true)
	slider = slider and slider:FindFirstChild("SliderSheet", true)
	if not slider then
		return false
	end
	local gen = slider:FindFirstChild("GenericSlider")
	local numberBox = gen and gen:FindFirstChild("Number")
	if numberBox and numberBox:IsA("TextBox") then
		numberBox.Text = tostring(amount)
		task.wait(0.2)
		pcall(function()
			numberBox:CaptureFocus()
			task.wait(0.1)
			numberBox:ReleaseFocus()
		end)
		task.wait(0.2)
	end
	local buttons = slider:FindFirstChild("Buttons")
	local submit = buttons and buttons:FindFirstChild("Submit")
	if submit then
		click(submit)
		return true
	end
	return false
end
local function depositAllNotes()
	local notes = currentNotes()
	if notes == 0 then
		return false
	end
	local bankGui = playerGui() and playerGui():FindFirstChild("BankGui")
	if not bankGui then
		return false
	end
	pcall(function()
		bankGui:WaitForChild("Choice"):FireServer("notes_deposit")
	end)
	task.wait(1)
	return setBankAmountAndConfirm(notes)
end
local function closeBankGui()
	local bankGui = playerGui() and playerGui():FindFirstChild("BankGui")
	if bankGui then
		click(bankGui:FindFirstChild("Close"))
	end
end
local function openBankAndDeposit()
	local banker = workspace.NPCs:FindFirstChild("Banker")
	if not banker then
		return false
	end
	pcall(function()
		replicatedStorage.Requests.InteractPrompt:FireServer(banker.InteractPrompt)
	end)
	task.wait(1)
	repeat
		task.wait(0.1)
	until dialogueOpen() or not running
	dialogueChoice("Can I access my account?")
	task.wait(1)
	repeat
		task.wait(0.5)
	until (playerGui() and playerGui():FindFirstChild("BankGui")) or not running
	task.wait(1)
	local success = depositAllNotes()
	closeBankGui()
	dialogueExit()
	return success
end

-- =========================================================================================================
-- Overworld: share knowledge, deposit notes.
-- =========================================================================================================
local function shareKnowledge()
	if not hasKnowledge() then
		return
	end
	setStage("sharing knowledge")
	local npcCF = CFrame.new(-541.776306, 935.564697, -7180.49707, 0.850063145, 0, 0.526680827, 0, 1, 0, -0.526680827, 0, 0.850063145)
	playerSafeTween(npcCF, 250)

	local soothsayer
	repeat
		soothsayer = workspace.NPCs:FindFirstChild("Soothsayer")
		task.wait()
	until soothsayer or not running
	if not soothsayer then
		return
	end
	repeat
		pcall(function()
			Prompt.interact(soothsayer:FindFirstChildOfClass("ProximityPrompt"))
		end)
		task.wait(0.5)
	until dialogueOpen() or not running
	task.wait(1)
	dialogueChoice("[Share your Knowledge]")
	task.wait(0.5)
	dialogueChoice(tonumber(currencyText("ShrinePoints")))
	task.wait(0.5)
	dialogueExit()
	task.wait(0.5)
end

local function depositNotesAtBank()
	if currentNotes() <= 0 then
		return
	end
	if PersistentData.get("notesdata") and PersistentData.get("notesdata").maxNotes then
		AutoNotes.stop()
		return
	end

	setStage("banking notes")
	local bankerCF = CFrame.new(1563.5769, 164.524414, -4312.33643, -0.104543328, 0, -0.994520426, 0, 1, 0, 0.994520426, 0, -0.104543328)
	playerSafeTween(bankerCF * CFrame.new(0, -5, 0), 170, math.random(10000, 30000))

	local banker
	repeat
		for _, npc in next, workspace.NPCs:GetChildren() do
			if npc.Name:match("Banker") and npc:FindFirstChild("HumanoidRootPart") then
				if not banker then
					banker = npc
				elseif (root().Position - npc.HumanoidRootPart.Position).Magnitude < (root().Position - banker.HumanoidRootPart.Position).Magnitude then
					banker = npc
				end
			end
		end
		task.wait()
	until banker or not running

	openBankAndDeposit()
	task.wait(3.5)
	if currentNotes() > 0 then
		-- Still holding notes -> bank is full.
		PersistentData.stf("notesdata", "maxNotes", true)
		AutoNotes.stop()
	end
end

local function useGuild()
	return Toggles and Toggles.NotesUseGuild and Toggles.NotesUseGuild.Value == true
end

local GUILD_PLACEMENTS = {
	CFrame.new(-996.915771, 998.557617, -7053.39062, 0.20362483, 0, -0.979048967, 0, 1, 0, 0.979048967, 0, 0.20362483),
	CFrame.new(-376.312347, 1109.97266, -6917.1875, 0.830629528, 0, 0.556825459, 0, 1, 0, -0.556825459, 0, 0.830629528),
	CFrame.new(237.318726, 1135.56323, -7003.09619, 0.981070876, 0, 0.193649009, 0, 1, 0, -0.193649009, 0, 0.981070876),
}

---Place the guild base door (Chime of Dwelling) at the first free spot and enter it.
local function placeGuildDoor()
	setStage("placing guild door")
	for _, location in ipairs(GUILD_PLACEMENTS) do
		local near = false
		for _, door in next, workspace:GetChildren() do
			if door:IsA("Part") and door.Name:find("Guild") then
				if (location.Position - door.Position).Magnitude <= 50 or playersNear(location, 400) then
					near = true
					break
				end
			end
		end
		if not near then
			playerSafeTween(location, 250)
			break
		end
	end

	task.wait(1)
	local bp = backpack()
	local chime = bp and bp:FindFirstChild("Chime of Dwelling")
	if chime then
		chime.Parent = character()
		pcall(function()
			character()["Chime of Dwelling"]:Activate()
		end)
	end

	local closest
	repeat
		for _, door in next, workspace:GetChildren() do
			if door:IsA("Part") and door.Name:find("GuildDoor") and door:FindFirstChild("InteractPrompt") then
				if root() and (root().Position - door.Position).Magnitude <= 5 then
					closest = door
					break
				end
			end
		end
		task.wait()
	until closest or not running
	if not closest then
		return
	end

	repeat
		pcall(function()
			Prompt.interact(closest:FindFirstChild("InteractPrompt"))
		end)
		task.wait(0.5)
	until (currentArea() and tostring(currentArea()):find("Base")) or not running
	task.wait(1)
end

---Deposit at the guild bank, then push the overflow into the guild treasury.
local function depositNotesAtGuild()
	placeGuildDoor()
	if not running then
		return
	end

	local guildAttr = localPlayer():GetAttribute("Guild")
	if not guildAttr then
		return
	end
	local guildName = tostring(guildAttr)
		:lower()
		:gsub("%s*%[.-%]%s*", " ")
		:gsub("^%d+", "")
		:gsub("z%w+divider", "")
		:gsub("[^%a%d]", "")

	local banker, treasurer
	for _, npc in next, workspace.NPCs:GetChildren() do
		if banker and treasurer then
			break
		end
		if npc:IsA("Model") and npc:GetAttribute("Guild") and tostring(npc:GetAttribute("Guild")):match(guildName) then
			if npc.Name:match("Banker") then
				banker = npc
			elseif npc.Name:match("Treasurer") then
				treasurer = npc
			end
		end
	end

	local data = PersistentData.get("notesdata")
	if banker and banker:FindFirstChild("HumanoidRootPart") and not (data and data.maxNotes) then
		setStage("guild bank")
		tempTween(banker.HumanoidRootPart.CFrame * CFrame.new(5, 0, 0), 170)
		openBankAndDeposit()
		task.wait(3.5)
		if currentNotes() > 0 then
			PersistentData.stf("notesdata", "maxNotes", true)
		end
	end

	if currentNotes() > 0 and treasurer and treasurer:FindFirstChild("HumanoidRootPart") then
		setStage("guild treasury")
		tempTween(treasurer.HumanoidRootPart.CFrame * CFrame.new(5, 0, 0), 170)
		repeat
			pcall(function()
				Prompt.interact(treasurer:FindFirstChildOfClass("ProximityPrompt"))
			end)
			task.wait(0.5)
		until dialogueOpen() or not running
		dialogueChoice("I'd like to add money to the treasury. [Add to Treasury]")
		task.wait(0.5)
		dialogueChoice(20000)
		task.wait(0.5)
		dialogueExit()
	end
end

local function overworld()
	repeat
		task.wait()
	until character() or not running
	shareKnowledge()
	if not running then
		return
	end
	if currentNotes() > 0 then
		if useGuild() then
			depositNotesAtGuild()
		else
			depositNotesAtBank()
		end
	end
end

-- =========================================================================================================
-- Fragments cash-in (Self [The End]) -- same shape as Echo, no echo counting needed here.
-- =========================================================================================================
local function handleFragments()
	setStage("fragments")
	local self_npc
	local deadline = os.clock() + 40
	repeat
		local npcs = workspace:FindFirstChild("NPCs")
		self_npc = npcs and npcs:FindFirstChild("Self")
		task.wait()
	until self_npc or os.clock() >= deadline or not running
	if not self_npc then
		serverHop()
		return
	end

	local tpLocation = (self_npc:GetPivot() - Vector3.new(0, 15.7, 0))
		* CFrame.Angles(math.rad(180), math.rad(90), math.rad(180))
	if playerCheck(200, tpLocation.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end

	local sendDialogue = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
	local prompt = self_npc:WaitForChild("InteractPrompt", 10)
	local start = tick()
	repeat
		local r = root()
		if r then
			r.CFrame = tpLocation
		end
		if prompt then
			Prompt.interact(prompt)
		end
		pcall(function()
			sendDialogue:FireServer({ choice = "[The End]" })
		end)
		task.wait(0.25)
	until (workspace:FindFirstChild("CharacterCreator") and character() and character().Parent == workspace.CharacterCreator)
		or not (currentArea() and tostring(currentArea()):match("Fragments of Self"))
		or not running
		or tick() - start > 20
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local function isCharacterCreation()
	local cc = workspace:FindFirstChild("CharacterCreator")
	local c = character()
	return cc ~= nil and c ~= nil and c.Parent == cc
end

local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "overworld", from = "_check_area", to = "_overworld" },
		{ name = "fragments", from = "_check_area", to = "_handle_fragments" },
		{ name = "die", from = "_check_area", to = "_die" },
		{ name = "cc", from = "_check_area", to = "_create_character" },
		{ name = "continuation", from = "_create_character", to = "_check_area" },
		{ name = "continuation", from = "_handle_fragments", to = "_check_area" },
		{ name = "continuation", from = "_overworld", to = "_check_area" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			local area = currentArea()
			if area and tostring(area):match("Fragments of Self") then
				return self:fragments()
			end

			if isCharacterCreation() then
				return self:cc()
			end

			if area and tostring(area):match("The Depths") then
				return self:die()
			end

			if game.PlaceId == MAIN_GAME_PLACE_ID then
				-- If we're in a guild base, respawn to the Inn first.
				if area and tostring(area):find("Base") then
					General.respawn()
					repeat
						task.wait()
					until (playerGui() and playerGui():FindFirstChild("SpawnPrompt")) or not running
					pcall(function()
						playerGui().SpawnPrompt.Choice:FireServer("Inn")
					end)
					repeat
						task.wait()
					until character() or not running
				end
				return self:overworld()
			end
		end,
		onenter_create_character = function(self)
			if not running then
				return
			end
			setStage("create character")
			struct:create_character()
			self:continuation()
		end,
		onenter_handle_fragments = function(self)
			if not running then
				return
			end
			handleFragments()
			self:continuation()
		end,
		onenter_overworld = function(self)
			if not running then
				return
			end
			setStage("overworld")
			overworld()
			if not running then
				return
			end
			-- Wipe and reroll.
			local slot = currentSlot() or (PersistentData.get("notesdata") and PersistentData.get("notesdata").slot)
			pcall(function()
				Wipe.invoke(slot)
			end)
		end,
		onenter_die = function(self)
			if not running then
				return
			end
			local slot = currentSlot() or (PersistentData.get("notesdata") and PersistentData.get("notesdata").slot)
			pcall(function()
				Wipe.invoke(slot)
			end)
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_notes",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"mod_detector",
			"fly",
			"auto_equip_weapon",
			"auto_log",
		},
		character_creator_handler_used = true,
		character_creator_handler_opts = {
			origin = "Etris",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================

---Menu Start: wipe the current character first (like Echo Farm), then Aero's resume (notesdata) drops us
---into a fresh farm cycle.
function AutoNotes.invoke()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Notes: no data slot found.")
	end

	PersistentData.set("notesdata", {
		slot = slot,
		startedAt = os.time(),
	})

	-- Wipe the current character on start; the wipe teleports us out and the resume brings us back in.
	pcall(function()
		Wipe.invoke(slot)
	end)
end

function AutoNotes.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Notes: no data slot found.")
	end

	local data = PersistentData.get("notesdata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("notesdata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoNotes")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoNotes.stop()
	if not running then
		return
	end
	running = false
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoNotes")
	end)
	maid:clean()
	destroyOverlay()
	PersistentData.set("notesdata", nil)
end

-- Read-only UI status; uses the same guard as the automation state machine.
AutoNotes.isRunning = isRunning

return AutoNotes

end)
__bundle_register("Game/Wipe", function(require, _LOADED, __bundle_register, __bundle_modules)
local Wipe = {}

local LOBBY_PLACE_ID = 4111023553
local FRAGMENTS_OF_SELF_POS = Vector3.new(2910.00, 1133.03, 1474.00)

---@module Features.Game.Interactions
local Interactions = require("Features/Game/Interactions")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local DEBUGGING_MODE = true

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

function Wipe.pwait()
	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	local startTimestamp = os.clock()

	while task.wait() do
		if os.clock() - startTimestamp >= 30 then
			return ServerHop.hop(wdata.slot, true)
		end

		if Finder.near(FRAGMENTS_OF_SELF_POS, 200) then
			break
		end
	end
end

function Wipe.pitems()
	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	local npcs = workspace:WaitForChild("NPCs")
	local hippocampusPool = npcs:WaitForChild("Hippocampal Pool")

	for _, name in next, wdata.weapons do
		local weapon = Finder.weweapon(name)
		if not weapon then
			continue
		end

		Interactions.etool(weapon)

		Interactions.interact(hippocampusPool, {
			{ choice = "[Inspect]" },
			{ choice = "[Pass down item]" },
			{ exit = true },
		}, true)
	end
end

function Wipe.depths()
	-- Blow through the loading screen by spamming A while the LoadingGui is up (input-only -- the old
	-- Requests.StartMenu.Start remote is an anticheat honeypot, firing it = instant ban). The server
	-- brings us into the depths on its own.
	local function pressKey(keyCode)
		pcall(function()
			local vim = Instance.new("VirtualInputManager")
			vim:SendKeyEvent(true, keyCode, false, game)
			vim:SendKeyEvent(false, keyCode, false, game)
		end)
	end
	local loadingDeadline = os.clock() + 10
	while os.clock() < loadingDeadline do
		local pg = players.LocalPlayer and players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if not (pg and pg:FindFirstChild("LoadingGui")) then
			break
		end
		pressKey(Enum.KeyCode.A)
		task.wait(0.2)
	end

	telemetryLog("(Depths) Waiting for spawn.")

	Wipe.pwait()

	telemetryLog("(Depths) Looking for anyone in the Fragments of Self area.")

	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	if Finder.pnear(FRAGMENTS_OF_SELF_POS, 500) then
		return ServerHop.hop(wdata.slot, true)
	end

	Wipe.pitems()

	local npcs = workspace:WaitForChild("NPCs")
	local selfNpc = npcs:WaitForChild("Self")

	telemetryLog("(Depths) Teleporting and interacting with Self NPC.")

	repeat
		Interactions.interact(selfNpc, {
			{ choice = "[The End]" },
		}, true)

		task.wait()
	until not players.LocalPlayer.Character

	telemetryLog("(Depths) Wiped slot. Removing marker.")

	PersistentData.set("wdata", nil)

	if PersistentData.get("efdata") then
		PersistentData.stf("efdata", "wiped", true)
	end
end

function Wipe.lobby()
	telemetryLog("(Lobby) (Step 1) Wiping slot in lobby.")

	local requests = replicatedStorage:WaitForChild("Requests")
	local wipeSlot = requests:WaitForChild("WipeSlot")

	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	repeat
		task.wait()
	until wipeSlot:InvokeServer(wdata.slot)

	telemetryLog("(Lobby) (Step 2) Wiped slot. Server hopping.")

	ServerHop.hop(wdata.slot, false)
end

---@param slot string The data slot to wipe.
---@param weapons string[]? Optional items to keep. Does not handle any validation.
function Wipe.invoke(slot, weapons)
	PersistentData.set("wdata", {
		slot = slot,
		weapons = weapons or {},
	})

	telemetryLog("(Invoke) (Step 1) Marked slot %s in data.", slot)

	if game.PlaceId == LOBBY_PLACE_ID then
		return Wipe.lobby()
	end

	return ServerHop.rlobby()
end

return Wipe

end)
__bundle_register("Features/Game/Interactions", function(require, _LOADED, __bundle_register, __bundle_modules)
local Interactions = {}

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Prompt
local Prompt = require("Utility/Prompt")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local DEBUGGING_MODE = true

local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

---@param tool Instance
---@param data any Response to interaction to send with the tool use.
function Interactions.utool(tool, data)
	Interactions.etool(tool)

	telemetryLog("Activating tool '%s' until ChoicePrompt appears.", tool.Name)

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local choicePrompt = nil

	while not choicePrompt do
		tool:Activate()

		choicePrompt = playerGui:FindFirstChild("ChoicePrompt")

		task.wait()
	end

	telemetryLog("Firing ChoicePrompt ('%s') with data.", tostring(data))

	local choice = choicePrompt:WaitForChild("Choice")
	choice:FireServer(data)

	telemetryLog("Waiting for ChoicePrompt to disappear...")

	repeat
		task.wait()
	until not choicePrompt.Parent

	telemetryLog("ChoicePrompt has disappeared.")
end

---@param tool Instance
function Interactions.etool(tool)
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	repeat
		humanoid:EquipTool(tool)

		task.wait()
	until tool.Parent == players.LocalPlayer.Character
end

---@param instance Model
---@param actions table
---@param teleport boolean Should we teleport to the instance?
function Interactions.interact(instance, actions, teleport)
	if not instance or not instance.Parent then
		return
	end

	local interactPrompt = instance:FindFirstChild("InteractPrompt")
	if not interactPrompt or not interactPrompt:IsA("ProximityPrompt") then
		return
	end

	telemetryLog("(%s) Interacting until dialogue appears.", instance.Name)

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local dialogueGui = playerGui:WaitForChild("DialogueGui")
	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()

	repeat
		if teleport then
			character:PivotTo(instance:GetPivot())
		end

		Prompt.fire(interactPrompt)

		task.wait()
	until dialogueGui.Enabled

	telemetryLog("(%s) Going through dialogue with %i actions.", instance.Name, #actions)

	local requests = replicatedStorage:WaitForChild("Requests")
	local dialogueEvent = requests:WaitForChild("SendDialogue")

	local dialogueCompleted = false

	dialogueEvent.OnClientEvent:Connect(function()
		dialogueCompleted = true
	end)

	for _, action in next, actions do
		dialogueEvent:FireServer(action)

		dialogueCompleted = false

		telemetryLog(
			"(%s) Sent dialogue action '%s' and now waiting for OnClientEvent to fire.",
			instance.Name,
			action.exit and "[EXIT]" or (action.choice or "N/A")
		)

		if action.exit then
			break
		end

		repeat
			task.wait()
		until dialogueCompleted
	end

	telemetryLog("(%s) Completed dialogue.", instance.Name)
end

return Interactions

end)
__bundle_register("Features/Automation/AutoMooneyrie", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Mooneyrie: a aero port of project-rain-oss's `auto_mooneyrie.lua`, on the AutomationStruct +
-- StateMachine framework. In the Eastern Luminant: heal at a campfire if low, travel to Moon's Eyrie, open
-- the Moon door, kill the Moon Knight(s), loot, then hide/hop. Runs the fight with m1_hold + a kick-anim
-- dodge (attach behind the knight, fly up when he winds up a kick).
--
-- Public surface:
--   AutoMooneyrie.start() / .stop() / .inValidPlace()  (Eastern Luminant)
-- Persistence key: "mooneyriedata" { slot, startedAt }.
local AutoMooneyrie = {}

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")
---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")
---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")
---@module Utility.Prompt
local Prompt = require("Utility/Prompt")
---@module Utility.Logger
local Logger = require("Utility/Logger")
---@module GUI.Library
local Library = require("GUI/Library")
---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")
---@module Utility.Maid
local Maid = require("Utility/Maid")
---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")
---@module Features.Automation.Objects.StateMachine
local StateMachine = require("Features/Automation/Objects/StateMachine")
---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("Features/Automation/Objects/AutomationStruct")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local EASTERN_PLACE_ID = 6473861193 -- Eastern Luminant (Moon's Eyrie).
local DEPTHS_PLACE_ID = 5735553160 -- The Depths (should never be here; stop if we are).
local MOVE_ID = "AutoMooneyrie_Move"

local running = false
local struct = nil
local maid = Maid.new()
local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end
local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function isRunning()
	return running
end
function AutoMooneyrie.inValidPlace()
	return game.PlaceId == EASTERN_PLACE_ID
end
local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "AeroAutoMooneyrieOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()
	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Mooneyrie",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })
	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })
	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoMooneyrie.stop()
	end)
	pcall(function()
		Library:MakeDraggable(outer)
	end)
end
local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end
-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("mooneyriedata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.MooneyrieTweenSpeed and Options.MooneyrieTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end
local function tempTween(cframe, speed)
	setSpeed(speed or 170)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end
local function playerNear()
	local origin = root() and root().Position
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character:GetPivot().Position).Magnitude <= 200 then
				return true
			end
		end
	end
	return false
end
local function playersNear(target, mag)
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (target - player.Character:GetPivot().Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end
local function playerSafeTween(cf, speed)
	if playerNear() then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	local y = math.random(8000, 10000)
	r.CFrame = r.CFrame + Vector3.new(0, y, 0)
	tempTween(cf + Vector3.new(0, y, 0), speed)
	if playersNear(cf.Position, 200) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
	task.wait(1)
end
local function readyWeapon()
	pcall(function()
		character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end
local function m1Hold(state)
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end
local function healthCheck(percent)
	local hum = humanoid()
	return hum ~= nil and hum.Health <= (hum.MaxHealth * percent)
end
local function inDanger()
	local hum = humanoid()
	return hum ~= nil and hum:GetAttribute("DangerExpiration") and hum:GetAttribute("DangerExpiration") > 0
end
local function getClosestMob(name, mag)
	local closest
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end
	for _, mob in next, live:GetChildren() do
		if mob:IsA("Model") and mob.Name:find(name) and mob:FindFirstChild("HumanoidRootPart") then
			local dist = (root().Position - mob.HumanoidRootPart.Position).Magnitude
			if not closest then
				if not mag or dist < mag then
					closest = mob
				end
			elseif dist < (root().Position - closest.HumanoidRootPart.Position).Magnitude then
				closest = mob
			end
		end
	end
	return closest
end
local function getClosestCampfire()
	local closest
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return nil
	end
	for _, campfire in next, thrown:GetChildren() do
		if campfire.Name:match("Campfire") and campfire:IsA("Model") then
			local part = campfire:FindFirstChildOfClass("Part")
			if part then
				if not closest then
					closest = part
				elseif (root().Position - part.Position).Magnitude < (root().Position - closest.Position).Magnitude then
					closest = part
				end
			end
		end
	end
	return closest
end
local function grabChest()
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return
	end
	for _, chest in next, thrown:GetChildren() do
		if chest:FindFirstChild("Lid") then
			tempTween(chest.Lid.CFrame, 170)
			local t = tick()
			repeat
				task.wait(0.5)
				pcall(function()
					Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
				end)
				pcall(function()
					tempTween(chest.Lid.CFrame, 170)
				end)
			until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t > 3 or playerNear()
			if playerNear() then
				break
			end
			local t2 = tick()
			repeat
				task.wait(1)
			until not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t2 > 3 or playerNear()
			break
		end
	end
end

-- =========================================================================================================
-- Kill a Moon Knight: attach behind it, m1, dodge its kick (fly up when the kick anim plays), then vacuum
-- nearby LootDrops.
-- =========================================================================================================
local function killTarget(target)
	if playerNear() or not target or not target:IsA("Model") then
		return false
	end
	if target.Name:match(localPlayer().Name) then
		return false
	end

	readyWeapon()
	if target:FindFirstChild("HumanoidRootPart") then
		tempTween(target.HumanoidRootPart.CFrame, 170)
	end
	if playerNear() then
		return false
	end

	local foundKick = false
	local animator = target:FindFirstChild("Animator", true)
	local kickConn
	if animator then
		kickConn = animator.AnimationPlayed:Connect(function(track)
			local id = track.Animation.AnimationId
			if (id:match("106711913879378") or id:match("111024000122473")) and not foundKick then
				foundKick = true
				task.delay(2, function()
					foundKick = false
				end)
			end
		end)
	end

	-- Attach behind the knight (fly up when it winds up a kick).
	local attach = task.spawn(function()
		while running and not playerNear() do
			if not target.Parent or not target:FindFirstChild("HumanoidRootPart") then
				break
			end
			local r = root()
			if r then
				r.AssemblyLinearVelocity = Vector3.zero
				r.CFrame = target.HumanoidRootPart.CFrame
					* CFrame.new(0, foundKick and 60 or 10, 0)
					* CFrame.Angles(math.rad(-90), 0, 0)
			end
			task.wait()
		end
	end)

	-- Track health stalls (bail if no damage for 20s).
	local healthTick = tick()
	local lastHealth = nil
	local status = task.spawn(function()
		while running do
			pcall(function()
				local hp = target.Humanoid.Health
				if lastHealth == nil or lastHealth ~= hp then
					healthTick = tick()
					lastHealth = hp
				end
			end)
			task.wait()
		end
	end)

	m1Hold(true)
	repeat
		task.wait()
	until not running
		or not target
		or target.Parent == nil
		or playerNear()
		or healthCheck(0.35)
		or (tick() - healthTick >= 20)

	pcall(function()
		if kickConn then
			kickConn:Disconnect()
		end
	end)
	pcall(function()
		task.cancel(attach)
	end)
	pcall(function()
		task.cancel(status)
	end)
	m1Hold(false)

	-- Vacuum LootDrops.
	if running and not playerNear() then
		task.wait(2)
		local thrown = workspace:FindFirstChild("Thrown")
		for _, drop in next, (thrown and thrown:GetChildren() or {}) do
			if drop:IsA("Model") and drop:FindFirstChild("LootDrop") then
				if (root().Position - drop.LootDrop.Position).Magnitude <= 100 and not playersNear(drop.LootDrop.Position, 200) then
					tempTween(drop.LootDrop.CFrame, 120)
					local t = tick()
					repeat
						pcall(function()
							firetouchinterest(drop.LootDrop, root(), 0)
							firetouchinterest(drop.LootDrop, root(), 1)
						end)
						task.wait()
					until drop.Parent == nil or playerNear() or not running or tick() - t >= 3
					if drop.Parent ~= nil then
						pcall(function()
							drop:Destroy()
						end)
					end
				end
			end
		end
		task.wait(0.2)
	end

	if healthCheck(0.35) then
		return false
	end
	if playerNear() or not running then
		return true
	end
	return false
end

-- =========================================================================================================
-- Main handle: heal if low, go to Moon's Eyrie, open the door, kill knights + loot.
-- =========================================================================================================
local function handle()
	-- Heal at a campfire if we're low.
	if healthCheck(0.35) then
		setStage("resting at campfire")
		playerSafeTween(
			CFrame.new(-7632.27881, 980.369873, 421.907501, -0.95457083, 0, 0.297984123, 0, 1, 0, -0.297984123, 0, -0.95457083),
			170
		)
		task.wait(1)
		local campfire = getClosestCampfire()
		local er = getEffectReplicator()
		if campfire then
			repeat
				local r = root()
				if r then
					r.CFrame = campfire.CFrame * CFrame.new(0, 1, 0)
				end
				task.wait(1)
				pcall(function()
					Prompt.interact(campfire.Parent.InteractPrompt)
				end)
				task.wait(1)
			until (er and er:FindEffect("Resting")) or not running
			repeat
				task.wait()
			until (humanoid() and humanoid().Health >= humanoid().MaxHealth * 0.5) or not running
			-- Stand up (E).
			local vim = Instance.new("VirtualInputManager")
			pcall(function()
				vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
				task.wait(0.1)
				vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
			end)
			task.wait(1)
			vim:Destroy()
		end
	end

	if not running then
		return
	end

	-- Travel to Moon's Eyrie.
	setStage("traveling to Moon's Eyrie")
	local marker = replicatedStorage:FindFirstChild("MarkerWorkspace")
	local location = marker
		and marker.AreaMarkers
		and marker.AreaMarkers:FindFirstChild("Moon's Eyrie")
		and marker.AreaMarkers["Moon's Eyrie"].AreaMarker.CFrame
	if not location then
		return
	end
	playerSafeTween(location, 170)

	local door
	repeat
		task.wait()
		door = workspace:FindFirstChild("MoonseyeDoor")
	until door or not running
	if not running then
		return
	end

	readyWeapon()
	playerSafeTween(door.CFrame * CFrame.new(0, -5, 0), 170)

	-- Open the Moon door.
	setStage("opening Moon door")
	repeat
		pcall(function()
			local moonDoor = workspace.NPCs:FindFirstChild("MoonDoor")
			if moonDoor then
				Prompt.interact(moonDoor:FindFirstChild("InteractPrompt"))
			end
		end)
		task.wait(0.5)
	until (playerGui() and playerGui():FindFirstChild("DialogueGui") and playerGui().DialogueGui.Enabled) or not running
	pcall(function()
		replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ choice = "[Interact]" })
	end)

	tempTween(door.CFrame * CFrame.new(0, 0, -100), 170)

	-- Wait for a Moon Knight to appear.
	local waited = 0
	repeat
		task.wait(0.1)
		waited = waited + 0.1
	until waited > 3 or playerNear() or getClosestMob("moonknight", 60) or not running
	if playerNear() or not running then
		return
	end

	setStage("fighting Moon Knight")
	local knight = getClosestMob("moonknight", 60)
	local knightWasNil = knight == nil

	killTarget(knight)

	if running and not playerNear() and not healthCheck(0.35) and not knightWasNil then
		task.wait(0.5)
		grabChest()
	end

	-- A second knight may be further out.
	local knight2 = getClosestMob("moonknight", 3000)
	if knight2 then
		killTarget(knight2)
	end
end

local function toSafety()
	setStage("hiding")
	repeat
		local r = root()
		if r then
			r.CFrame = r.CFrame * CFrame.new(0, math.random(8000, 10000), 0)
		end
		task.wait()
	until not inDanger() or not running
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "moons", from = "_check_area", to = "_moonseyrie" },
		{ name = "hide", from = "_check_area", to = "_hide" },
		{ name = "hide", from = "_moonseyrie", to = "_hide" },
		{ name = "hop", from = "_moonseyrie", to = "_hop" },
		{ name = "hop", from = "_hide", to = "_hop" },
		{ name = "continuation", from = "_hide", to = "_moonseyrie" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")
			if game.PlaceId == DEPTHS_PLACE_ID then
				Logger.notify("Auto Mooneyrie: ended up in the Depths -- stopping.")
				return AutoMooneyrie.stop()
			end
			if game.PlaceId == EASTERN_PLACE_ID then
				return self:moons()
			end
		end,
		onenter_moonseyrie = function(self)
			if not running then
				return
			end
			handle()
			if playerNear() or inDanger() then
				return self:hide()
			end
			self:hop()
		end,
		onenter_hide = function(self)
			if not running then
				return
			end
			toSafety()
			self:hop()
		end,
		onenter_hop = function(self)
			if not running then
				return
			end
			serverHop()
			while task.wait() do
			end
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_mooneyrie",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"no_fire",
			"m1_hold",
			"no_stun",
			"fast_swing",
			"auto_equip_weapon",
			"auto_log",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoMooneyrie.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoMooneyrie.inValidPlace() then
		return Logger.notify("Auto Mooneyrie: not in the Eastern Luminant.")
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Mooneyrie: no data slot found.")
	end

	local data = PersistentData.get("mooneyriedata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("mooneyriedata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoMooneyrie")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoMooneyrie.stop()
	if not running then
		return
	end
	running = false
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoMooneyrie")
	end)
	maid:clean()
	destroyOverlay()
	PersistentData.set("mooneyriedata", nil)
end

-- Read-only UI status; uses the same guard as the automation state machine.
AutoMooneyrie.isRunning = isRunning

return AutoMooneyrie

end)
__bundle_register("Features/Automation/AutoDuke", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Duke: a aero port of project-rain-oss's `auto_duke.lua`, on the ported AutomationStruct +
-- StateMachine framework and the shared General/Teleports substrate. Refills food in the Etrean Luminant,
-- opens the Erisia manor (Manor Key), clears the brainsuckers/cultists, rides the elevator into the Duke
-- dungeon, then fights the golems + the Duke (with attack-pattern dodging + optional void mode) and loots.
--
-- Public surface:
--   AutoDuke.start()        -- menu Start + Aero.lua resume
--   AutoDuke.stop()
--   AutoDuke.inValidPlace() -- resume gate (Etrean/Eastern main-game or the Duke dungeon)
-- Persistence key: "dukedata" { slot, startedAt }.
-- Menu toggles read here: DukeVoids (use void mode on the Duke).
local AutoDuke = {}

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Utility.Prompt
local Prompt = require("Utility/Prompt")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Features.Automation.Objects.StateMachine
local StateMachine = require("Features/Automation/Objects/StateMachine")

---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("Features/Automation/Objects/AutomationStruct")

---@module Features.Automation.Objects.General
local General = require("Features/Automation/Objects/General")

---@module Features.Automation.Objects.Teleports
local Teleports = require("Features/Automation/Objects/Teleports")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")
local collectionService = game:GetService("CollectionService")

local MAIN_GAME_PLACE_ID = 6032399813 -- overworld (Etrean Luminant / Erisia manor).
local EASTERN_PLACE_ID = 6473861193 -- Eastern Luminant.
local DEPTHS_PLACE_ID = 5735553160 -- The Depths (should never be here; stop if we are).

local MOVE_ID = "AutoDuke_Move"
local DUKE_NAME = ".theduke11"

local running = false
local struct = nil
local maid = Maid.new()

local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end
local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function isRunning()
	return running
end

function AutoDuke.inValidPlace()
	if game.PlaceId == MAIN_GAME_PLACE_ID or game.PlaceId == EASTERN_PLACE_ID then
		return true
	end
	-- Also valid if we're inside the Duke dungeon (resume mid-fight).
	local dungeon = localPlayer() and localPlayer():GetAttribute("Dungeon")
	return dungeon ~= nil and tostring(dungeon):match("Duke") ~= nil
end

local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "AeroAutoDukeOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Duke",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })
	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })
	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoDuke.stop()
	end)
	pcall(function()
		Library:MakeDraggable(outer)
	end)
end
local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end
-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("dukedata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement + helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.DukeTweenSpeed and Options.DukeTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---Blocking tween (PR Tween.new(cf, true, speed).wait()).
local function tempTween(cframe, speed)
	setSpeed(speed or 250)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end

---Non-blocking tween goal (used inside tight fight loops so we don't stall on arrival).
local function tweenGoal(cframe, speed)
	setSpeed(speed or 250)
	Tweening.goal(MOVE_ID, cframe, false)
end

local function playerNear()
	local origin = root() and root().Position
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character:GetPivot().Position).Magnitude <= 1000 then
				return true
			end
		end
	end
	return false
end

local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end

---PR's player_safe_tween: hop if anyone near, else go up to altitude, travel, drop.
local function playerSafeTween(cf, speed)
	if playerNear() then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	local y = math.random(8000, 10000)
	r.CFrame = r.CFrame + Vector3.new(0, y, 0)
	tempTween(cf + Vector3.new(0, y, 0), speed)
	if playerNear() then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
	task.wait(1)
end

local function m1Hold(state)
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end

local function readyWeapon()
	pcall(function()
		character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end

-- =========================================================================================================
-- Loot.
-- =========================================================================================================
local function playerGuiHasChoice()
	local lp = localPlayer()
	local gui = lp and lp:FindFirstChildOfClass("PlayerGui")
	return gui and gui:FindFirstChild("ChoicePrompt") ~= nil
end

local function grabChests()
	local looted = false
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return false
	end
	for _, chest in next, thrown:GetChildren() do
		if not running then
			break
		end
		if chest:FindFirstChild("Lid") and not collectionService:HasTag(chest, "looted") then
			tempTween(chest.Lid.CFrame, 170)
			local t = tick()
			repeat
				task.wait(1)
				pcall(function()
					Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
				end)
				pcall(function()
					tempTween(chest.Lid.CFrame, 170)
				end)
			until (playerGuiHasChoice()) or not running or tick() - t > 3
			if playerGuiHasChoice() then
				looted = true
			end
			local t2 = tick()
			repeat
				task.wait(1)
			until not playerGuiHasChoice() or not running or tick() - t2 > 3
			if playerGuiHasChoice() then
				looted = true
				pcall(function()
					localPlayer().PlayerGui.ChoicePrompt.Choice:FireServer("EXIT")
				end)
			end
			collectionService:AddTag(chest, "looted")
		end
	end
	return looted
end

-- =========================================================================================================
-- Refill food (Etrean ingredients).
-- =========================================================================================================
local function refill()
	setStage("refill food")
	local char = character()
	if not char then
		return
	end
	local water = char:FindFirstChild("Water")
	if not water then
		return
	end

	local function isSatiated()
		return water.Value >= (water.MaxValue * 0.5)
	end

	local passives = char:GetAttribute("ssv_Passives")
	if passives and tostring(passives):find("Carnivore") then
		return
	end

	local function closestIngredient(namePart)
		local closest
		local folder = workspace:FindFirstChild("Ingredients")
		if not folder then
			return nil
		end
		for _, ing in next, folder:GetChildren() do
			if ing.Name:match(namePart) then
				if not closest then
					closest = ing
				elseif (root().Position - ing.Position).Magnitude < (root().Position - closest.Position).Magnitude then
					closest = ing
				end
			end
		end
		return closest
	end

	local function collect(ing)
		playerSafeTween(ing.CFrame, 200)
		local cf = ing.CFrame
		repeat
			tempTween(cf, 200)
			pcall(function()
				Prompt.interact(ing:FindFirstChildOfClass("ProximityPrompt"))
			end)
			task.wait()
		until ing.Parent == nil or not running
	end

	local function eat(foodName)
		local item = backpack() and backpack():FindFirstChild(foodName)
		if not item then
			return
		end
		humanoid():EquipTool(item)
		item:Activate()
		task.wait(0.5)
		humanoid():UnequipTools()
	end

	local start = tick()
	while running and not isSatiated() and tick() - start <= 45 do
		local ing = closestIngredient("Dentifilo") or closestIngredient("Calabash")
		if not ing then
			break
		end
		local name = ing.Name
		collect(ing)
		eat(name)
		task.wait()
	end
end

-- =========================================================================================================
-- Create instance (open manor, clear adds, ride elevator into the Duke dungeon).
-- =========================================================================================================
local function createInstance()
	setStage("opening manor")
	local bp = backpack()
	if not bp then
		return
	end
	local manorKey = bp:WaitForChild("Manor Key", 10) or (character() and character():WaitForChild("Manor Key", 10))
	if not manorKey then
		Logger.notify("Auto Duke: need a Manor Key.")
		return
	end
	manorKey.Parent = character()
	local handle = manorKey:WaitForChild("Handle", 10)
	if not handle then
		return
	end

	-- The key has to be "charged" (handle turns white) before it works. If it isn't, wait up to 10s for it
	-- to change; if it still isn't white, this slot's key is spent -> hop to a fresh server.
	if handle.Color.R < 0.99 or handle.Color.G < 0.99 or handle.Color.B < 0.99 then
		local start = tick()
		local old = handle.Color
		repeat
			task.wait()
		until handle.Color ~= old or tick() - start > 10 or not running
		if handle.Color.R < 0.99 or handle.Color.G < 0.99 or handle.Color.B < 0.99 then
			return serverHop()
		end
	end

	playerSafeTween(CFrame.new(1460, 74, 3069), 200)

	local started = false
	task.delay(20, function()
		if not started and running then
			serverHop()
		end
	end)

	maid:mark(workspace.Live.ChildAdded:Connect(function(entity)
		if (entity.Name:find("brainsucker") or entity.Name:find("dukecultist")) then
			if (entity:GetPivot().Position - (root() and root().Position or Vector3.zero)).Magnitude <= 400 then
				started = true
			end
		end
	end))

	setStage("entering manor")
	while running and not started do
		if sethiddenproperty and humanoid() then
			pcall(function()
				sethiddenproperty(humanoid(), "MoveDirectionInternal", Vector3.one)
			end)
		end
		pcall(function()
			Prompt.interact(workspace.Doors.ErisiaDungeonGate.Main.InteractPrompt)
		end)
		task.wait()
	end

	readyWeapon()
	m1Hold(true)

	setStage("clearing adds")
	local done = false
	while running and not done do
		done = true
		for _, entity in next, workspace.Live:GetChildren() do
			if entity.Name:find("brainsucker") or entity.Name:find("dukecultist") then
				if (entity:GetPivot().Position - (root() and root().Position or Vector3.zero)).Magnitude <= 900 then
					local hum = entity:FindFirstChildOfClass("Humanoid")
					while running and hum and hum.Health > 0 and entity:FindFirstChild("HumanoidRootPart") do
						if playerNear() then
							serverHop()
							while task.wait() do
							end
							return
						end
						m1Hold(true)
						tweenGoal(entity.HumanoidRootPart.CFrame * CFrame.new(0, 0, 3), 250)
						task.wait()
					end
					done = false
				end
			end
		end
	end
	m1Hold(false)
	Tweening.stop(MOVE_ID)

	task.delay(30, function()
		if running then
			serverHop()
		end
	end)

	setStage("riding elevator")
	playerSafeTween(CFrame.new(1470, 84, 3586), 200)
	for _ = 1, 300 do
		if not running then
			break
		end
		if playerNear() then
			serverHop()
			while task.wait() do
			end
			return
		end
		tempTween(CFrame.new(1470, 84, 3586), 250)
		pcall(function()
			Prompt.interact(workspace.ErisiaElevator.Switch.InteractPrompt)
		end)
		task.wait(0.1)
	end
end

-- =========================================================================================================
-- Kill the Duke.
-- =========================================================================================================
local function killDuke()
	setStage("fighting duke")
	readyWeapon()
	m1Hold(true)

	-- Dodge the golem laser (GolemLaserFire client effect).
	local nopeTfOut = false
	local clientEffect
	repeat
		clientEffect = replicatedStorage:FindFirstChild("ClientEffect", true)
		if not clientEffect then
			task.wait()
		end
	until clientEffect or not running
	if clientEffect then
		maid:mark(clientEffect.OnClientEvent:Connect(function(effectName)
			if effectName == "GolemLaserFire" then
				nopeTfOut = true
				task.delay(0.4, function()
					nopeTfOut = false
				end)
			end
		end))
	end

	-- Phase 1: clear the prime golems / remaining cultists (Z > 2000, i.e. in the arena).
	local done = false
	while running and not done do
		done = true
		for _, entity in next, workspace.Live:GetChildren() do
			if not running then
				break
			end
			if (entity.Name:find("prime_golem") or entity.Name:find("dukecultist")) then
				if (entity:GetPivot().Position - (root() and root().Position or Vector3.zero)).Magnitude <= 900 and entity:GetPivot().Z >= 2000 then
					local hum = entity:FindFirstChildOfClass("Humanoid")
					while running and hum and hum.Health > 0 do
						m1Hold(true)
						if not entity:FindFirstChild("HumanoidRootPart") then
							break
						end
						if not nopeTfOut then
							tweenGoal(
								entity.HumanoidRootPart.CFrame
									* (entity.Name:find("prime_golem") and CFrame.new(0, 5, 0.35) or CFrame.new(0, 2, 3)),
								250
							)
						else
							tweenGoal(entity.HumanoidRootPart.CFrame * CFrame.new(0, 100, 10), 250)
						end
						task.wait()
					end
					done = false
				end
			end
		end
	end
	m1Hold(false)
	if not running then
		return
	end

	-- Phase 2: start the Duke dialogue -- fire the interact prompt on .theduke11 until dialogue opens.
	local sendDialogue = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
	local got = false
	maid:mark(sendDialogue.OnClientEvent:Connect(function(v)
		got = not (v and v.exit)
	end))

	local vim = Instance.new("VirtualInputManager")
	repeat
		local duke = workspace.Live:FindFirstChild(DUKE_NAME)
		if duke and duke:FindFirstChild("HumanoidRootPart") then
			tempTween(duke.HumanoidRootPart.CFrame * CFrame.new(0, 0, 3), 250)
			pcall(function()
				Prompt.interact(duke.InteractPrompt)
			end)
		end
		pcall(function()
			vim:SendKeyEvent(true, Enum.KeyCode.One, false, game)
			task.wait()
			vim:SendKeyEvent(false, Enum.KeyCode.One, false, game)
		end)
		task.wait()
	until got or not running
	-- Spam the accept key while the dialogue is open.
	while running and got do
		pcall(function()
			vim:SendKeyEvent(true, Enum.KeyCode.One, false, game)
			task.wait()
			vim:SendKeyEvent(false, Enum.KeyCode.One, false, game)
		end)
		task.wait()
	end

	-- Wait for the Duke to actually target us (fight starts).
	repeat
		task.wait()
		local duke = workspace.Live:FindFirstChild(DUKE_NAME)
		if duke and duke:FindFirstChild("Target") and duke.Target.Value then
			break
		end
	until not running
	readyWeapon()

	-- Detect the Duke's dangerous animations.
	task.delay(5, function()
		local duke = workspace.Live:FindFirstChild(DUKE_NAME)
		if duke and duke:FindFirstChildOfClass("Humanoid") then
			maid:mark(duke.Humanoid.AnimationPlayed:Connect(function(anim)
				local id = anim.Animation.AnimationId
				if id:find("8275408994") or id:find("8290899374") or id:find("8294560344") then
					nopeTfOut = true
					task.delay(id:find("8294560344") and 7.5 or 2.5, function()
						nopeTfOut = false
					end)
				end
			end))
		end
	end)

	-- Void mode?
	local voidingMode = Toggles and Toggles.DukeVoids and Toggles.DukeVoids.Value == true
	if Toggles and Toggles.VoidMobs then
		Toggles.VoidMobs:SetValue(voidingMode)
	end

	-- Main Duke loop.
	local duke = workspace.Live:FindFirstChild(DUKE_NAME)
	while running and workspace.Live:FindFirstChild(DUKE_NAME) do
		task.wait()
		duke = workspace.Live:FindFirstChild(DUKE_NAME)
		m1Hold(not General.playing_ap_anims(duke))

		if not duke:FindFirstChild("HumanoidRootPart") or not duke:FindFirstChild("Humanoid") or not duke.Parent or duke.Humanoid.Health <= 0 then
			break
		end

		-- Void mode: cast Frost Grab while safe.
		if voidingMode and not nopeTfOut and not General.playing_ap_anims(duke) then
			local frost = backpack() and backpack():FindFirstChild("Mantra:ChokeIce{{Frost Grab}}")
			if frost then
				pcall(function()
					character().CharacterHandler.Requests.ActivateMantra:FireServer(frost)
				end)
			end
		end

		local hrp = duke.HumanoidRootPart
		if hrp.CFrame.Y <= -1000 then
			continue -- void can fail; don't chase into the void
		end

		local x, y, z = hrp.CFrame:GetComponents()
		local xSin = math.sin(tick() * 2) * 30
		local zCos = math.cos(tick() * 2) * 30

		if General.playing_ap_anims(duke, { "rbxassetid://8085349676" }) or nopeTfOut then
			local critical = KeyHandling.getRemote("CriticalClick")
			if critical then
				pcall(function()
					critical:FireServer({ S = false, NOAERIALS = false, Space = false, Right = false, W = false, Left = true }, false)
				end)
			end
			tweenGoal(CFrame.new(x + xSin, y < 70 and math.random(175, 250) or math.random(0, 10), z + zCos), 250)
		elseif General.playing_ap_anims(duke) then
			tweenGoal(CFrame.new(x + xSin, y < 70 and math.random(175, 250) or math.random(0, 10), z + zCos), 250)
		else
			tweenGoal(hrp.CFrame * CFrame.new(0, -6, 0) * CFrame.Angles(math.rad(90), 0, 0), 250)
		end
	end
	m1Hold(false)
	Tweening.stop(MOVE_ID)
	if not running then
		return
	end

	-- Wait out danger, then loot the chests and respawn out.
	setStage("looting")
	task.delay(60 * 5, function()
		if not running then
			return
		end
		local er = getEffectReplicator()
		repeat
			task.wait()
			tempTween(CFrame.new(2495, 139, 1926), 160)
		until not (er and er:FindEffect("Danger")) or not running
		General.respawn()
	end)

	while running do
		local ok, res = pcall(grabChests)
		if ok and res then
			break
		end
		task.wait(1)
	end

	local er = getEffectReplicator()
	repeat
		task.wait()
		tempTween(CFrame.new(2495, 139, 1926), 160)
	until not (er and er:FindEffect("Danger")) or not running
	General.respawn()
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "refill", from = "_check_area", to = "_refill" },
		{ name = "initiate", from = "_check_area", to = "_initiate" },
		{ name = "initiate", from = "_refill", to = "_initiate" },
		{ name = "kill", from = "_check_area", to = "_kill" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			-- Somehow ended up in the Depths -> stop (PR kicks here).
			if game.PlaceId == DEPTHS_PLACE_ID then
				Logger.notify("Auto Duke: ended up in the Depths -- stopping.")
				return AutoDuke.stop()
			end

			local dungeon = localPlayer() and localPlayer():GetAttribute("Dungeon")
			if dungeon and tostring(dungeon):match("Duke") then
				return self:kill()
			end

			if game.PlaceId == EASTERN_PLACE_ID then
				-- Wrong region -- teleport back to the Etrean Luminant (manor is there).
				Teleports.etrean()
				return
			end

			if game.PlaceId == MAIN_GAME_PLACE_ID then
				self:refill()
				self:initiate()
				return
			end
		end,
		onenter_refill = function(self)
			if not running then
				return
			end
			refill()
			self:initiate()
		end,
		onenter_initiate = function(self)
			if not running then
				return
			end
			createInstance()
		end,
		onenter_kill = function(self)
			if not running then
				return
			end
			killDuke()
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_duke",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"no_kill_bricks",
			"mod_detector",
			"fly",
			"m1_hold",
			"auto_wisp",
			"auto_equip_weapon",
			"auto_log",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoDuke.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoDuke.inValidPlace() then
		return Logger.notify("Auto Duke: not in the Etrean/Eastern Luminant.")
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Duke: no data slot found.")
	end

	local data = PersistentData.get("dukedata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("dukedata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoDuke")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoDuke.stop()
	if not running then
		return
	end
	running = false
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoDuke")
	end)
	maid:clean()
	destroyOverlay()
	PersistentData.set("dukedata", nil)
end

-- Read-only UI status; uses the same guard as the automation state machine.
AutoDuke.isRunning = isRunning

return AutoDuke

end)
__bundle_register("Features/Automation/AutoAuthority", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Authority Missions: a aero port of project-rain-oss's `auto_authority.lua`, on the ported
-- AutomationStruct + StateMachine framework. Runs the Fort Merit authority missions in the Eastern
-- Luminant: talk to Captain Trist, accept a job, identify which one (Hostage / Armament Sabotage / Secure),
-- complete it if it's enabled in the menu, report back, repeat.
--
-- Public surface:
--   AutoAuthority.start()        -- menu Start + Aero.lua resume
--   AutoAuthority.stop()
--   AutoAuthority.inValidPlace() -- resume gate (Eastern Luminant)
-- Persistence key: "authoritydata" { slot, startedAt }.
-- Menu toggles read here: AuthorityHostage / AuthorityBarrels / AuthoritySecure (which jobs to do).
local AutoAuthority = {}

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Utility.Prompt
local Prompt = require("Utility/Prompt")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Features.Automation.Objects.StateMachine
local StateMachine = require("Features/Automation/Objects/StateMachine")

---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("Features/Automation/Objects/AutomationStruct")

---@module Features.Automation.Objects.AutoLog
local AutoLog = require("Features/Automation/Objects/AutoLog")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local AUTHORITY_PLACE_ID = 6473861193 -- Eastern Luminant (Fort Merit / Captain Trist).

local MOVE_ID = "AutoAuthority_Move"
local TRIST_HIGH = CFrame.new(-7502, 2000, 3481)
local TRIST_LOW = CFrame.new(-7502, 11, 3481)
local TWEEN_SPEED = 225
local PLAYER_SAFE_RADIUS = 300
local JOB_SCAN_INTERVAL = 0.5
local MISSION_SCAN_INTERVAL = 0.2
local HOSTAGE_MISSION_TIMEOUT = 150
local HOSTAGE_LOW_HEALTH_RATIO = 0.25

local running = false
local safetyHold = false
local m1Hold
local struct = nil
local maid = Maid.new()

local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end

local function character()
	local lp = localPlayer()
	return lp and lp.Character
end

local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end

local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end

local function isRunning()
	return running
end

function AutoAuthority.inValidPlace()
	return game.PlaceId == AUTHORITY_PLACE_ID
end

local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end

local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "AeroAutoAuthorityOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Authority",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })

	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoAuthority.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)
end

local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end

-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("authoritydata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.AuthorityTweenSpeed and Options.AuthorityTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---Blocking tween to a CFrame (PR's Tween.new(cf, true, speed).wait()).
local function tweenTo(cframe, speed, deadline, continueWhile)
	while running and safetyHold do
		if deadline and os.clock() >= deadline then
			return false
		end
		if continueWhile and not continueWhile() then
			return false
		end
		task.wait()
	end
	if not running then
		return false
	end

	setSpeed(speed or TWEEN_SPEED)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		if deadline and os.clock() >= deadline then
			Tweening.stop(MOVE_ID)
			return false
		end
		if continueWhile and not continueWhile() then
			Tweening.stop(MOVE_ID)
			return false
		end
		if safetyHold then
			Tweening.stop(MOVE_ID)
			repeat
				if deadline and os.clock() >= deadline then
					return false
				end
				task.wait()
			until not running or not safetyHold
			if not running then
				return false
			end
			Tweening.goal(MOVE_ID, cframe, false)
		end
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
	return running
end

local function serverHop()
	local ok, err = pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
	if not ok then
		Logger.warn("Auto Authority server hop failed:", tostring(err))
	end
	return ok
end

-- =========================================================================================================
-- Captain Trist interaction + mission identification.
-- =========================================================================================================
local sendDialogue = nil
local dialogueOpen = false -- PR's `got`
local dialogueFires = 0 -- PR's `fc`

local function connectDialogueListener()
	if sendDialogue then
		return
	end
	pcall(function()
		sendDialogue = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
		maid:mark(sendDialogue.OnClientEvent:Connect(function(v)
			dialogueOpen = not (v and v.exit)
			dialogueFires = dialogueFires + 1
		end))
	end)
end

local function fireDialogue(payload)
	if sendDialogue and not safetyHold then
		pcall(function()
			sendDialogue:FireServer(payload)
		end)
	end
end

---Tween to Captain Trist and fire his prompt until the dialogue opens.
local function reachTrist(deadline, continueWhile)
	setStage("talking to Captain Trist")
	repeat
		if not tweenTo(TRIST_HIGH, TWEEN_SPEED, deadline, continueWhile)
			or not tweenTo(TRIST_LOW, TWEEN_SPEED, deadline, continueWhile)
		then
			return false
		end
		local npcs = workspace:FindFirstChild("NPCs")
		local trist = npcs and npcs:FindFirstChild("Captain Trist")
		local prompt = trist and trist:FindFirstChild("InteractPrompt")
		if prompt and prompt:IsA("ProximityPrompt") and not safetyHold then
			Prompt.fire(prompt)
		end
		task.wait(MISSION_SCAN_INTERVAL)
	until dialogueOpen or not running or (deadline and os.clock() >= deadline)
		or (continueWhile and not continueWhile())
	return dialogueOpen and running and (not continueWhile or continueWhile())
end

---Close any open dialogue (fire exit until the DialogueGui closes).
local function exitDialogue()
	local start = tick()
	repeat
		fireDialogue({ exit = true })
		task.wait(0.5)
	until not (playerGui() and playerGui():FindFirstChild("DialogueGui") and playerGui().DialogueGui.Enabled)
		or not running
		or tick() - start > 8
end

---Identify the accepted job by scanning Terrain for the JobTrackerGui attachment. Returns jobType, cframe.
local function identifyJob()
	local terrain = workspace:FindFirstChild("Terrain")
	if not terrain then
		return nil, nil
	end
	local deadline = os.clock() + 8
	repeat
		for _, entity in next, terrain:GetDescendants() do
			if entity:IsA("Attachment") then
				local jobTracker = entity:FindFirstChild("JobTrackerGui")
				local textLabel = jobTracker and jobTracker:FindFirstChild("TextLabel")
				if textLabel then
					local text = textLabel.Text
					local jobType = (text:find("Hostage") and "hostage")
						or (text:lower():find("secure") and "secure")
						or (text:find("Armanent Sabotage") and "barrels")
					if jobType then
						return jobType, entity.CFrame
					end
				end
			end
		end
		task.wait(JOB_SCAN_INTERVAL)
	until os.clock() >= deadline or not running
	return nil, nil
end

local function wantsJob(jobType)
	local map = {
		hostage = { "AuthorityHostage", "hostage" },
		barrels = { "AuthorityBarrels", "barrels" },
		secure = { "AuthoritySecure", "secure" },
	}
	local toggle = map[jobType]
	if not toggle then
		return false
	end
	local control = Toggles and Toggles[toggle[1]]
	if control then
		return control.Value == true
	end
	local saved = PersistentData.get("authorityMissionToggles")
	return type(saved) ~= "table" or saved[toggle[2]] ~= false
end

m1Hold = function(state)
	if state and safetyHold then
		state = false
	end
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end

-- =========================================================================================================
-- Missions.
-- =========================================================================================================
local function splashSaysReportBack()
	local gui = playerGui() and playerGui():FindFirstChild("SplashGui")
	local frame = gui and gui:FindFirstChild("TimeFrame")
	local label = frame and frame:FindFirstChild("TimeText")
	return label ~= nil and label.Text:lower():find("report back") ~= nil
end

local function missionHostage(object)
	setStage("mission: hostage")
	local deadline = os.clock() + HOSTAGE_MISSION_TIMEOUT

	local function shouldAbort()
		if os.clock() >= deadline then
			return "timed out after " .. HOSTAGE_MISSION_TIMEOUT .. " seconds"
		end
		local humanoid = character() and character():FindFirstChildOfClass("Humanoid")
		if humanoid and humanoid.MaxHealth > 0
			and humanoid.Health <= humanoid.MaxHealth * HOSTAGE_LOW_HEALTH_RATIO
		then
			return "health dropped below 25%"
		end
		return nil
	end

	local function abort(reason)
		m1Hold(false)
		if reason == "health dropped below 25%" then
			Tweening.stop(MOVE_ID)
			local currentRoot = root()
			if currentRoot then
				currentRoot.CFrame = CFrame.new(
					currentRoot.Position.X,
					3000,
					currentRoot.Position.Z
				)
			end
		end
		Logger.warn("Auto Authority hostage mission aborted:", reason)
		serverHop()
		return false
	end

	exitDialogue()

	local abortReason = shouldAbort()
	if abortReason then
		return abort(abortReason)
	end

	if not tweenTo(object * CFrame.new(0, 2000, 0), TWEEN_SPEED, deadline)
		or not tweenTo(object, TWEEN_SPEED, deadline)
	then
		if not running then
			return false
		end
		abortReason = shouldAbort()
		return abort(abortReason or "movement interrupted")
	end

	local live = workspace:FindFirstChild("Live")
	local hostage
	repeat
		local abortReason = shouldAbort()
		if abortReason then
			return abort(abortReason)
		end
		for _, entity in next, (live and live:GetChildren() or {}) do
			if entity.Name:find("%.hostage") and entity:FindFirstChild("HumanoidRootPart") then
				if (entity.HumanoidRootPart.Position - (root() and root().Position or Vector3.zero)).Magnitude <= 1000 then
					if not tweenTo(entity.HumanoidRootPart.CFrame, TWEEN_SPEED, deadline) then
						local abortReason = shouldAbort()
						if abortReason then
							return abort(abortReason)
						end
						return false
					end
					hostage = entity
					break
				end
			end
		end
		task.wait(MISSION_SCAN_INTERVAL)
	until hostage or not running
	if not hostage then
		return false
	end

	if not tweenTo(hostage.HumanoidRootPart.CFrame, TWEEN_SPEED, deadline) then
		local abortReason = shouldAbort()
		if abortReason then
			return abort(abortReason)
		end
		return false
	end

	local er = getEffectReplicator()
	local lastCarryRequest = 0
	local function carryingOrDelivered()
		return dialogueOpen or (er and er:FindEffect("Carrying") ~= nil)
	end
	while running do
		local abortReason = shouldAbort()
		if abortReason then
			return abort(abortReason)
		end
		local carrying = er and er:FindEffect("Carrying")
		if carrying then
			local currentRoot = root()
			if currentRoot and currentRoot.Position.Y < 1996 then
				if not tweenTo(
					CFrame.new(currentRoot.Position.X, 2000, currentRoot.Position.Z),
					TWEEN_SPEED,
					deadline,
					carryingOrDelivered
				) then
					abortReason = shouldAbort()
					if abortReason then
						return abort(abortReason)
					end
				end
			end
			if carryingOrDelivered() and reachTrist(deadline, carryingOrDelivered) then
				return true
			end
		else
			local hostageRoot = hostage and hostage.Parent and hostage:FindFirstChild("HumanoidRootPart")
			if hostageRoot then
				local currentRoot = root()
				if currentRoot and (currentRoot.Position - hostageRoot.Position).Magnitude > 10 then
					if not tweenTo(hostageRoot.CFrame, TWEEN_SPEED, deadline) then
						abortReason = shouldAbort()
						if abortReason then
							return abort(abortReason)
						end
					end
				end
			end
			local handler = character() and character():FindFirstChild("CharacterHandler")
			local requests = handler and handler:FindFirstChild("Requests")
			local carry = requests and requests:FindFirstChild("Carry")
			local now = tick()
			if carry and now - lastCarryRequest >= 4 then
				lastCarryRequest = now
				if not safetyHold then
					pcall(function()
						carry:FireServer()
					end)
				end
			end
		end
		task.wait(MISSION_SCAN_INTERVAL)
	end
	return false
end

local function missionBarrels(object)
	setStage("mission: barrels")
	exitDialogue()

	if not safetyHold then
		pcall(function()
			character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
		end)
	end
	tweenTo(object * CFrame.new(0, 1500, 0), TWEEN_SPEED)
	tweenTo(object * CFrame.new(0, 200, 0), TWEEN_SPEED)

	local destructibles = workspace:FindFirstChild("Destructibles")
	while running do
		if splashSaysReportBack() then
			break
		end
		local crates = {}
		local crateDistances = {}
		local rp = root() and root().Position or Vector3.zero
		if destructibles then
			for _, crate in next, destructibles:GetChildren() do
				if crate.Name:find("KhanCrate") and crate:IsA("Model") then
					local pivot = crate:GetPivot().Position
					local distance = (Vector3.new(pivot.X, 0, pivot.Z) - Vector3.new(rp.X, 0, rp.Z)).Magnitude
					if distance < 1200 then
						table.insert(crates, crate)
						crateDistances[crate] = distance
					end
				end
			end
		end
		table.sort(crates, function(a, b)
			return crateDistances[a] < crateDistances[b]
		end)
		for _, crate in ipairs(crates) do
			while running and crate:GetAttribute("StructureHealth") and crate:GetAttribute("StructureHealth") > 0 do
				m1Hold(true)
				tweenTo(CFrame.new((crate:GetPivot() * CFrame.new(0, -5, 0)).Position) * CFrame.Angles(math.rad(90), 0, 0), TWEEN_SPEED)
				task.wait(MISSION_SCAN_INTERVAL)
			end
			m1Hold(false)
		end
		task.wait(MISSION_SCAN_INTERVAL)
	end
	m1Hold(false)

	reachTrist()
end

local function missionSecure(object)
	setStage("mission: secure")

	tweenTo(object * CFrame.new(0, 1500, 0), TWEEN_SPEED)
	tweenTo(object, TWEEN_SPEED)

	local banner
	repeat
		for _, model in next, workspace:GetChildren() do
			if model.Name == "Authority Checkpoint" and model:IsA("Model") then
				local pivot = model:GetPivot().Position
				local rp = root() and root().Position or Vector3.zero
				if (Vector3.new(pivot.X, 0, pivot.Z) - Vector3.new(rp.X, 0, rp.Z)).Magnitude < 1200 then
					banner = model
				end
			end
		end
		task.wait(MISSION_SCAN_INTERVAL)
	until banner or not running
	if not banner then
		return
	end

	-- PR's 3-phase capture loop: sit on the banner (0-35s), fly high above it (35-125s), sit again
	-- (125-155s), each phase bailing out the moment the objective completes ("report back").
	while running do
		tweenTo(banner:GetPivot() * CFrame.new(0, 8, 0), TWEEN_SPEED)
		local start = tick()
		local stop = false

		repeat
			task.wait(MISSION_SCAN_INTERVAL)
			if splashSaysReportBack() then
				stop = true
				break
			end
		until tick() - start > 35 or not running
		if stop then
			break
		end

		repeat
			task.wait(MISSION_SCAN_INTERVAL)
			if splashSaysReportBack() then
				stop = true
				break
			end
			tweenTo(banner:GetPivot() * CFrame.new(0, 3000, 0), TWEEN_SPEED)
		until tick() - start > 90 + 35 or not running
		if stop then
			break
		end

		repeat
			task.wait(MISSION_SCAN_INTERVAL)
			if splashSaysReportBack() then
				stop = true
				break
			end
			tweenTo(banner:GetPivot() * CFrame.new(0, 8, 0), TWEEN_SPEED)
		until tick() - start > 120 + 35 or not running
		if stop then
			break
		end

		if splashSaysReportBack() then
			break
		end
	end

	reachTrist()
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local function runPlayerSafeWatch()
	-- Pause mission activity while a nearby player is a threat, then hop after Danger clears or they leave.
	maid:mark(task.spawn(function()
		local er = getEffectReplicator()
		local radius = math.max(PLAYER_SAFE_RADIUS, AutoLog.get("auto_authority"))

		local function nearbyPlayer()
			local r = root()
			if not r then
				return nil
			end
			local position = Vector3.new(r.Position.X, 0, r.Position.Z)
			for _, player in ipairs(players:GetPlayers()) do
				if player ~= localPlayer() then
					local otherRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
					if otherRoot then
						local otherPosition = Vector3.new(otherRoot.Position.X, 0, otherRoot.Position.Z)
						if (position - otherPosition).Magnitude <= radius then
							return player
						end
					end
				end
			end
			return nil
		end

		while running do
			if nearbyPlayer() then
				safetyHold = true
				m1Hold(false)
				Tweening.stop(MOVE_ID)
				if er and er:HasEffect("Danger") then
					repeat
						local r = root()
						if r then
							r.CFrame = CFrame.new(r.CFrame.X, 3000, r.CFrame.Z)
						end
						task.wait(0.1)
					until not running or not nearbyPlayer() or not (er and er:HasEffect("Danger"))
				end
				if not running then
					return
				end
				if not serverHop() then
					safetyHold = false
					task.wait(1)
				else
					return
				end
			end
			task.wait(MISSION_SCAN_INTERVAL)
		end
	end))
end

local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "continuation", from = "_check_area", to = "_check_area" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			if game.PlaceId ~= AUTHORITY_PLACE_ID then
				return
			end

			pcall(function()
				replicatedStorage:WaitForChild("Requests"):WaitForChild("UpdateUXSettings"):FireServer("FriendlyFire", true)
			end)

			connectDialogueListener()

			-- Talk to Captain Trist + accept the job.
			reachTrist()
			if not running then
				return
			end

			-- Advance past the intro with "Yes, Sir." until the dialogue state moves on.
			setStage("accepting job")
			local startFires = dialogueFires
			repeat
				fireDialogue({ choice = "Yes, Sir." })
				task.wait(MISSION_SCAN_INTERVAL)
			until startFires ~= dialogueFires or not running

			-- Background: keep the conversation closed once accepted.
			maid:mark(task.spawn(function()
				while running and dialogueOpen do
					fireDialogue({ exit = true })
					task.wait(MISSION_SCAN_INTERVAL)
				end
			end))

			-- Figure out which job we accepted.
			setStage("identifying job")
			local jobType, object = identifyJob()

			if not jobType or not object or not wantsJob(jobType) then
				-- Rejoining is faster than doing an unwanted job.
				serverHop()
				return
			end

			if jobType == "hostage" then
				if not missionHostage(object) then
					return
				end
			elseif jobType == "barrels" then
				missionBarrels(object)
			elseif jobType == "secure" then
				missionSecure(object)
			end

			exitDialogue()
			self:continuation()
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_authority",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"fly",
			"noclip",
			"no_fall",
			"no_kill_bricks",
			"m1_hold",
			"no_fire",
			"auto_equip_weapon",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoAuthority.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoAuthority.inValidPlace() then
		return Logger.notify("Auto Authority: not in the Eastern Luminant.")
	end

	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Authority: no data slot found.")
	end

	local data = PersistentData.get("authoritydata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("authoritydata", data)

	running = true
	safetyHold = false
	dialogueOpen = false
	dialogueFires = 0
	buildOverlay()
	AntiAFK.start("AutoAuthority")

	maid:mark(task.spawn(runElapsed))
	runPlayerSafeWatch()

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoAuthority.stop()
	if not running then
		return
	end
	running = false

	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end

	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoAuthority")
	end)

	maid:clean()
	sendDialogue = nil
	destroyOverlay()

	PersistentData.set("authoritydata", nil)
end

-- Read-only UI status; uses the same guard as the automation state machine.
AutoAuthority.isRunning = isRunning

return AutoAuthority

end)
__bundle_register("Features/Automation/AutoTitus", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AutoTitus (RELICS farm): a aero port of project-rain-oss's `titus_relicfarm.lua`, built on the ported
-- AutomationStruct + StateMachine framework. Constructs a struct with PR's relic feature set and drives the
-- same state machine: create character -> (bank relics / refill food) -> enter the Titus dungeon -> break
-- Titus (mob_ai_breaker) -> loot the relic chest -> respawn out -> repeat. Relics held in stacks of >= 25
-- get deposited at the Banker.
--
-- NOTE: faithful to PR, the relic farm does NOT run the `jesus` anti-water feature (only the echo farm does
-- in PR). It also keeps its character between cycles (no wipe) so relics accumulate for banking.
--
-- Public surface kept identical for aero's menu + resume wiring:
--   AutoTitus.start()        -- menu Start + Aero.lua resume
--   AutoTitus.stop()         -- stop + cleanup
--   AutoTitus.inValidPlace() -- resume gate (merit hub or Titus dungeon)
-- Persistence key: "titusdata" { slot, startedAt }.
local AutoTitus = {}

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Features.Automation.Objects.AutoLog
local AutoLog = require("Features/Automation/Objects/AutoLog")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Utility.Prompt
local Prompt = require("Utility/Prompt")

---@module Features.Automation.AutoLoot
local AutoLoot = require("Features/Automation/AutoLoot")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Features.Automation.Objects.StateMachine
local StateMachine = require("Features/Automation/Objects/StateMachine")

---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("Features/Automation/Objects/AutomationStruct")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")

local EASTERN_PLACE_ID = 6473861193 -- Fort Merit hub.
local DUNGEON_PLACE_ID = 8668476218 -- The Titus (Detainment) dungeon.

local MOVE_ID = "AutoTitus_Move"
local ENTRANCE = CFrame.new(-6875.86, 336.2, 2827.95)
local ENTRANCE_SPEED = 50
local PLAYER_SAFE_RADIUS = 200
local APPROACH_Y = 288
local ATTACH_DISTANCE = 35
local BANK_THRESHOLD = 25
local BANK_COOLDOWN = 45

local running = false
local struct = nil
local maid = Maid.new()
local lastBank = 0
local actionStartedAt = 0 -- os.clock() when the current stage began (0 = disarmed); per-action watchdog.
local ACTION_TIMEOUT = 60 -- a stage stalling longer than this REJOINS (server-hops) to reset the cycle.
local VOID_TIMEOUT = 45 -- shorter cap for the Titus voiding phase ("fighting titus") specifically.
local currentActionTimeout = ACTION_TIMEOUT -- active timeout for the current stage (set per-stage in setStage).

local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Local-player accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end

local function character()
	local lp = localPlayer()
	return lp and lp.Character
end

local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end

local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end

local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end

local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end

local function currentArea()
	local lp = localPlayer()
	return lp and lp:GetAttribute("CurrentArea")
end

local function isRunning()
	return running
end

function AutoTitus.inValidPlace()
	return game.PlaceId == EASTERN_PLACE_ID or game.PlaceId == DUNGEON_PLACE_ID
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end

local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

local function buildOverlay()
	if screenGui then
		return
	end

	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "AeroAutoTitusOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Titus (Relics)",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })

	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoTitus.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)
end

local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end

-- Stage text was removed, but setStage now re-arms the per-action watchdog on every stage change (the void
-- phase, "fighting titus", gets the shorter VOID_TIMEOUT cap). Same mechanism as the echo farm.
local function setStage(name)
	actionStartedAt = os.clock()
	currentActionTimeout = (name == "fighting titus") and VOID_TIMEOUT or ACTION_TIMEOUT
end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("titusdata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement primitives (ported from PR's autotitus table).
-- =========================================================================================================
local function setSpeed(value, force)
	-- Normally the per-automation Tween Speed slider wins; `force` lets a specific move (the dungeon-door
	-- travel) pin an exact speed regardless of the slider.
	if not force then
		value = (Options and Options.TitusTweenSpeed and Options.TitusTweenSpeed.Value) or 100
	end
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---When `force` is set (the dungeon-door travel), step the root toward the goal at an EXACT studs/second
---ourselves instead of going through the shared Tween Speed slider. That slider is clamped (Min) and shared
---across every automation, so it can't reliably pin a speed at runtime -- this keeps the door approach at
---the speed we actually ask for (e.g. 50 studs/s) no matter what the slider says.
local function tempTween(cframe, speed, force)
	if force then
		Tweening.stop(MOVE_ID) -- make sure the engine isn't also driving us toward a stale goal
		local targetPos = cframe.Position
		local studsPerSecond = speed or 150
		local dt = task.wait()
		while running do
			local r = root()
			if not r then
				return
			end
			r.AssemblyLinearVelocity = Vector3.zero
			local pos = r.Position
			local toTarget = targetPos - pos
			local dist = toTarget.Magnitude
			if dist <= 1 then
				break
			end
			local stepDist = studsPerSecond * dt
			if stepDist >= dist then
				r.CFrame = CFrame.new(targetPos)
				break
			end
			r.CFrame = CFrame.new(pos + (toTarget / dist) * stepDist)
			dt = task.wait()
		end
		return
	end

	setSpeed(speed or 150, force)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 10 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end

local function playerCheck(mag, position)
	local origin = position or (root() and root().Position)
	if not origin then
		return false
	end
	for _, other in next, players:GetPlayers() do
		if other == localPlayer() or not other.Character then
			continue
		end
		local hrp = other.Character:FindFirstChild("HumanoidRootPart")
		if hrp and (origin - hrp.Position).Magnitude <= mag then
			return true
		end
	end
	return false
end

local function serverHop()
	-- currentSlot() reads the live DataSlot attribute, which is often absent inside the Titus dungeon;
	-- fall back to the farm's persisted slot so the rejoin resolves a real save slot instead of no-opping
	-- on nil.
	local data = PersistentData.get("titusdata")
	local slot = currentSlot() or (data and data.slot)
	pcall(function()
		ServerHop.hop(slot, true)
	end)
end

---Per-action watchdog (same mechanism as the echo farm): if a stage stalls past its cap -- the Titus void
---("fighting titus") gets VOID_TIMEOUT, everything else ACTION_TIMEOUT -- server-hop to rejoin a fresh server
---and re-enter (titusdata resume brings the farm back). Unlike the echo farm this REJOINS rather than wiping:
---a relic-farm character must survive, so it never obliterates.
local function runActionWatchdog()
	while running do
		if actionStartedAt > 0 and os.clock() - actionStartedAt > currentActionTimeout then
			actionStartedAt = 0 -- disarm so we only fire once
			serverHop()
			return
		end
		task.wait(0.25)
	end
end

---Player-safe tween: hop if anyone is near, else fly there at altitude and snap down (PR relic version).
---@param groundLevel boolean? when true, travel at ground level (no altitude lift) instead of high up.
local function playerSafeTween(cf, speed, groundLevel, force)
	if playerCheck(PLAYER_SAFE_RADIUS) then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	if groundLevel then
		-- Match the dungeon door's Y: snap to the target's height, then tween horizontally across to it at
		-- that same Y level (no altitude lift).
		r.CFrame = CFrame.new(r.Position.X, cf.Position.Y, r.Position.Z)
		tempTween(cf, speed, force)
	else
		local y = math.random(8000, 10000)
		r.CFrame = r.CFrame + Vector3.new(0, y, 0)
		tempTween(cf + Vector3.new(0, y, 0), speed, force)
	end
	if playerCheck(PLAYER_SAFE_RADIUS, cf.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
end

-- =========================================================================================================
-- Relic helpers.
-- =========================================================================================================
local function countItem(name)
	local bp = backpack()
	if not bp then
		return 0
	end
	local qty = 0
	for _, item in next, bp:GetChildren() do
		if item.Name == name then
			qty = qty + 1
		end
	end
	return qty
end

local function bankItems()
	-- aero menu dropdown "TitusBankItems" -> a set { [name] = true }.
	if Options and Options.TitusBankItems then
		return Options.TitusBankItems.Value or {}
	end
	return {}
end

local function needFood()
	local c = character()
	if not c then
		return false
	end
	local water = c:FindFirstChild("Water")
	local stomach = c:FindFirstChild("Stomach")
	if not water or not stomach then
		return false
	end
	return (water.Value <= (water.MaxValue * 0.3)) and (stomach.Value <= (stomach.MaxValue * 0.3))
end

local function refillFood()
	setStage("refill food")
	local c = character()
	local water = c and c:FindFirstChild("Water")
	if not water then
		return
	end

	local function nearestWell()
		local closest
		local terrain = workspace:FindFirstChild("Terrain")
		local waterFolder = terrain and terrain:FindFirstChild("Water")
		if not waterFolder then
			return nil
		end
		for _, well in next, waterFolder:GetChildren() do
			if well.Name:match("DrinkingWater") then
				if not closest then
					closest = well
				else
					local cd = (root().Position - closest:GetPivot().Position).Magnitude
					local d = (root().Position - well:GetPivot().Position).Magnitude
					if d < cd then
						closest = well
					end
				end
			end
		end
		return closest
	end

	if not (water.Value >= (water.MaxValue * 0.75)) then
		local well = nearestWell()
		if not well then
			return
		end
		playerSafeTween(well:GetPivot(), 250)
		repeat
			well = nearestWell()
			task.wait()
		until well or not running
		repeat
			pcall(function()
				Prompt.interact(well.InteractPrompt)
			end)
			task.wait(0.2)
		until (water.Value >= (water.MaxValue * 0.75)) or not running
	end
end

-- =========================================================================================================
-- Dungeon flow.
-- =========================================================================================================
local function enterDungeon()
	setStage("enter dungeon")
	-- Force noclip on for the trip to the dungeon door so geometry can't snag us on the way in.
	pcall(function()
		if Toggles and Toggles.NoClip then
			Toggles.NoClip:SetValue(true)
		end
	end)
	pcall(function()
		replicatedStorage.Requests.UpdateUXSettings:FireServer("FriendlyFire", true)
	end)

	-- Keep noclip enforced for the WHOLE trip to the door (not just once we're there): re-assert the NoClip
	-- toggle and brute-force every character part CanCollide=false each frame while we travel, so geometry
	-- can't snag us on the way in.
	local travelNoclip = runService.Heartbeat:Connect(function()
		if Toggles and Toggles.NoClip and not Toggles.NoClip.Value then
			Toggles.NoClip:SetValue(true)
		end
		local c = character()
		if c then
			for _, part in next, c:GetDescendants() do
				if part:IsA("BasePart") and part.CanCollide then
					part.CanCollide = false
				end
			end
		end
	end)

	playerSafeTween(ENTRANCE, ENTRANCE_SPEED, true, true) -- ground level (y=0) to the door; force 50 studs/s regardless of the Tween Speed slider
	pcall(function()
		travelNoclip:Disconnect()
	end)
	pcall(function()
		replicatedStorage.Requests.UpdateUXSettings:FireServer("FriendlyFire", true)
	end)

	local entry = workspace:WaitForChild("Map", 10)
	entry = entry and entry:WaitForChild("MeritEntry", 10)

	local holdConn = runService.Heartbeat:Connect(function()
		local r = root()
		if r then
			r.CFrame = ENTRANCE
		end
		-- Brute-force noclip for the door approach: force every character part CanCollide=false each frame so
		-- geometry can't snag us (doesn't rely on the NoClip toggle / Movement loop).
		local c = character()
		if c then
			for _, part in next, c:GetDescendants() do
				if part:IsA("BasePart") and part.CanCollide then
					part.CanCollide = false
				end
			end
		end
	end)

	local start = tick()
	repeat
		-- Keep noclip ON for the whole door approach (re-assert each pass -- a one-shot set can get cleared by
		-- the fresh-character spawn / feature management, same reason the no-fall loop re-asserts).
		if Toggles and Toggles.NoClip and not Toggles.NoClip.Value then
			Toggles.NoClip:SetValue(true)
		end
		if playerCheck(PLAYER_SAFE_RADIUS, ENTRANCE.Position) then
			if holdConn then
				holdConn:Disconnect()
			end
			serverHop()
			while task.wait() do
			end
			return
		end
		if entry and entry:FindFirstChild("InteractPrompt") then
			Prompt.interact(entry.InteractPrompt)
		end
		task.wait(0.1)
	until tick() - start > 30 or game.PlaceId ~= EASTERN_PLACE_ID or not running

	if holdConn then
		holdConn:Disconnect()
	end
end

-- Old pathfind (mob_ai) breaker, baked straight into the Titus fight (no toggle). Every Heartbeat we
-- snapshot the root's real velocity, then slam it straight down (0, -9e11, 0); we restore the snapshot
-- BEFORE the next physics step so we never actually fall -- the slam lives for one tick, just long enough
-- to replicate the fling. The restore runs on PreRender AND PreSimulation: PreRender covers the focused
-- case, PreSimulation also fires while the window is UNFOCUSED (PreRender doesn't), so an AFK/tabbed-out
-- session can't skip the restore and let the slam rocket us into the void / null zone.
local titusBreakerHB = nil
local titusBreakerPR = nil
local titusBreakerPS = nil
local titusBreakerLastVel = nil

local function stopTitusBreaker()
	if titusBreakerHB then
		pcall(function()
			titusBreakerHB:Disconnect()
		end)
		titusBreakerHB = nil
	end
	if titusBreakerPR then
		pcall(function()
			titusBreakerPR:Disconnect()
		end)
		titusBreakerPR = nil
	end
	if titusBreakerPS then
		pcall(function()
			titusBreakerPS:Disconnect()
		end)
		titusBreakerPS = nil
	end
	if titusBreakerLastVel then
		local r = root()
		if r then
			pcall(function()
				r.AssemblyLinearVelocity = titusBreakerLastVel
			end)
		end
		titusBreakerLastVel = nil
	end
end

local function startTitusBreaker()
	stopTitusBreaker()

	-- Restore the pre-slam velocity. Runs on every pre-physics tick so the slam is always undone before
	-- physics integrates it (otherwise -9e11 would carry us straight into the void).
	local function restoreBreakerVelocity()
		if not titusBreakerLastVel then
			return
		end
		local r = root()
		if r then
			r.AssemblyLinearVelocity = titusBreakerLastVel
		end
		titusBreakerLastVel = nil
	end

	titusBreakerHB = runService.Heartbeat:Connect(function()
		local r = root()
		if not r then
			return
		end
		titusBreakerLastVel = r.AssemblyLinearVelocity
		r.AssemblyLinearVelocity = Vector3.new(0, -9e11, 0)
	end)

	-- PreRender restores while the window is focused; PreSimulation (falling back to Stepped) also fires
	-- when it's unfocused, so the restore can never be skipped and let the slam fling us to the null zone.
	titusBreakerPR = runService.PreRender:Connect(restoreBreakerVelocity)
	local preSim = runService.PreSimulation or runService.Stepped
	if preSim then
		titusBreakerPS = preSim:Connect(restoreBreakerVelocity)
	end
end

local function attachToTitus()
	setStage("fighting titus")

	local titus
	repeat
		for _, ent in next, workspace.Live:GetChildren() do
			if ent.Name:lower():find("titus") and ent.Name:find("%.") then
				titus = ent
				break
			end
		end
		task.wait()
	until titus or not running
	if not titus then
		return
	end

	local torso = titus:WaitForChild("Torso")
	if not torso then
		return
	end

	local playerRoot = root()
	if not playerRoot then
		return
	end

	maid:mark(task.spawn(function()
		while titus and titus.Parent and running do
			pcall(function()
				InputClient.dodge({ direct = true })
			end)
			task.wait(0.35)
		end
	end))

	local targetCF = CFrame.new(torso.CFrame.X, APPROACH_Y, torso.CFrame.Z)
	playerRoot.AssemblyLinearVelocity = Vector3.zero
	tempTween(targetCF, 250)
	task.wait(0.5)
	tempTween(targetCF, 250)

	-- Kill by ramming up and down THROUGH Titus's torso: oscillate between his torso and a point VOID_SWING
	-- studs above it (position-only target -- a straight vertical lookAt is degenerate and NaNs the CFrame).
	-- The pathfind breaker does the damage; this just drives the motion. Done when he dies, or hop if he
	-- somehow gets flung up off the map.
	startTitusBreaker()
	-- Ram hard and FAST through Titus's torso at a fixed, slider-independent speed (the shared Tween Speed
	-- slider can't be trusted to hold a value at runtime, and the old setSpeed(200) was non-force so it
	-- silently ran at the ~100 slider default). Step the root straight between his torso and VOID_SWING studs
	-- above it, flipping the instant we reach an end, slamming the whole time via the breaker.
	local VOID_SWING = 100
	local RAM_SPEED = 900
	-- If Titus gets flung farther than this from us, stop chasing him. He's on his way out (flung/voiding),
	-- and gliding across the map after his torso is exactly the bug we're fixing. Hold position instead and
	-- keep swinging; he dies or comes back, and the per-action watchdog server-hops if the fight truly stalls.
	local MAX_RAM_DISTANCE = 10000
	local voidGoingIn = true
	local dt = task.wait()
	while running do
		if not titus or not titus.Parent or not torso.Parent then
			break
		end
		if torso.Position.Y > 2000 then
			stopTitusBreaker()
			serverHop()
			return
		end

		playerRoot = root()
		if playerRoot then
			playerRoot.AssemblyLinearVelocity = Vector3.zero

			local ramPos = torso.Position + Vector3.new(0, voidGoingIn and VOID_SWING or 0, 0)
			local toTarget = ramPos - playerRoot.Position
			local dist = toTarget.Magnitude
			-- Only ram/move while he's close. Flung too far -> don't chase; lift up to Y=1000 and wait him out.
			if dist <= MAX_RAM_DISTANCE then
				local stepDist = RAM_SPEED * dt
				if dist <= stepDist or dist < 3 then
					playerRoot.CFrame = CFrame.new(ramPos)
					voidGoingIn = not voidGoingIn
				else
					playerRoot.CFrame = CFrame.new(playerRoot.Position + (toTarget / dist) * stepDist)
				end
			else
				-- Titus flung past MAX_RAM_DISTANCE: sit at Y=1000 (keep our X/Z) instead of gliding after him.
				local pos = playerRoot.Position
				playerRoot.CFrame = CFrame.new(pos.X, 1000, pos.Z)
			end
			pcall(function()
				character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
			end)
		end

		dt = task.wait()
	end
	stopTitusBreaker()
	Tweening.stop(MOVE_ID)
end

---Loot the relic chest (relic: open + force LOOT_ALL, then EXIT).
local function grabChest()
	setStage("looting chest")

	-- Find the chest (wait for it to spawn after the kill).
	local chest
	local findStart = tick()
	repeat
		local thrown = workspace:FindFirstChild("Thrown")
		if thrown then
			for _, object in next, thrown:GetChildren() do
				if object:FindFirstChild("Lid") then
					chest = object
					break
				end
			end
		end
		if not chest then
			task.wait()
		end
	until chest or not running or (tick() - findStart > 15)
	if not chest then
		return
	end

	local previousAutoLootIgnore = AutoLoot.ignore
	AutoLoot.ignore = true
	local ok, err = xpcall(function()
		-- Chest appeared: snap straight onto it and hold there. After the post-kill teleport we're ~1300 studs
		-- up, so don't rely on a slow descend tween -- lock onto the chest position immediately, then the
		-- re-tween loop below keeps us glued to it while we open + loot.
		do
			local rr = root()
			if rr then
				rr.AssemblyLinearVelocity = Vector3.zero
				rr.CFrame = CFrame.new(chest.Lid.CFrame.Position)
			end
		end

		-- The farm sends LOOT_ALL itself; keep generic AutoLoot from closing this prompt with EXIT.
		tempTween(chest.Lid.CFrame, 170)
		local promptStart = tick()
		repeat
			task.wait(0.1)
			pcall(function()
				Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
			end)
			pcall(function()
				tempTween(chest.Lid.CFrame, 170)
			end)
		until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or (tick() - promptStart > 15)

		if not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) then
			return
		end

		-- Force Loot All while the ChoicePrompt is up, then EXIT to close.
		local time = tick()
		repeat
			task.wait()
			local gui = playerGui()
			local cp = gui and gui:FindFirstChild("ChoicePrompt")
			if cp then
				pcall(function()
					cp:FindFirstChild("Choice"):FireServer("LOOT_ALL")
				end)
			end
		until not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or (tick() - time >= 3)

		local gui = playerGui()
		local cp = gui and gui:FindFirstChild("ChoicePrompt")
		if cp then
			pcall(function()
				cp:FindFirstChild("Choice"):FireServer("EXIT")
			end)
		end
		-- Intentionally NOT tweening back down to Y=0 -- stay at altitude after looting.
	end, debug.traceback)
	AutoLoot.ignore = previousAutoLootIgnore
	if not ok then
		error(err, 0)
	end
end

---Deposit relic stacks (>= BANK_THRESHOLD) at the Banker.
local function bankRelics()
	setStage("banking relics")

	local npcs = workspace:FindFirstChild("NPCs")
	local banker = npcs and npcs:WaitForChild("Banker", 10)
	if not banker then
		return
	end

	pcall(function()
		playerSafeTween(banker.HumanoidRootPart.CFrame * CFrame.new(0, -6, 0), 150)
	end)
	pcall(function()
		local r = root()
		if r then
			r.CFrame = banker.HumanoidRootPart.CFrame * CFrame.new(0, -6, 0)
		end
	end)

	local sendDialogue = replicatedStorage.Requests.SendDialogue
	local dl = tick()
	repeat
		local dg = playerGui() and playerGui():FindFirstChild("DialogueGui")
		if dg and dg.Enabled then
			pcall(function()
				sendDialogue:FireServer({ choice = "Can I access my account?" })
			end)
		else
			pcall(function()
				Prompt.interact(banker.InteractPrompt)
			end)
		end
		task.wait(0.5)
	until (playerGui() and playerGui():FindFirstChild("BankGui")) or tick() - dl > 15 or not running

	local bankGui = playerGui() and playerGui():FindFirstChild("BankGui")
	if not bankGui then
		return
	end

	local function bankFull()
		local cp = playerGui() and playerGui():FindFirstChild("ChoicePrompt")
		if not cp then
			return false
		end
		local ds = cp:FindFirstChild("DescSheet", true)
		if not ds or not ds:FindFirstChild("Ok") then
			return false
		end
		local dc = ds:FindFirstChild("Desc", true)
		return dc ~= nil and dc.Text == "You don't have any bank slots free."
	end

	local function confirmMax()
		local cp = playerGui() and playerGui():FindFirstChild("ChoicePrompt")
		if not cp then
			return false
		end
		local mx = cp:GetAttribute("Max")
		local ch = cp:FindFirstChild("Choice")
		if mx and ch then
			task.spawn(function()
				pcall(function()
					ch:InvokeServer(mx)
				end)
			end)
			return true
		end
		return false
	end

	for name, selected in pairs(bankItems()) do
		if selected and countItem(name) >= BANK_THRESHOLD then
			local n = 0
			while countItem(name) > 0 and n < 6 and running do
				n = n + 1
				local before = countItem(name)
				local deposit = {}
				for _, item in next, backpack():GetChildren() do
					if item.Name == name then
						deposit[#deposit + 1] = item
					end
				end
				if #deposit == 0 then
					break
				end
				pcall(function()
					bankGui:WaitForChild("Choice"):FireServer("deposit", deposit)
				end)
				local bt = tick()
				repeat
					if bankFull() then
						Logger.notify("Bank full -- Auto Titus stopped.")
						AutoTitus.stop()
						return
					end
					confirmMax()
					task.wait(0.3)
				until countItem(name) < before or tick() - bt > 8 or not running
			end
		end
	end
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local function isCharacterCreation()
	local cc = workspace:FindFirstChild("CharacterCreator")
	local c = character()
	return cc ~= nil and c ~= nil and c.Parent == cc
end

---Tap a key once via VirtualInputManager (input-only; no remote).
local function pressKey(keyCode)
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, keyCode, false, game)
		vim:SendKeyEvent(false, keyCode, false, game)
	end)
end

---Blow through the loading screen and wait for our character to spawn into workspace.Live. While the
---LoadingGui is up, spams A to click through it (input-only -- the old Requests.StartMenu.Start remote
---is an anticheat honeypot, firing it = instant ban). Skipped in character creation.
local function requestStart()
	local deadline = os.clock() + 25
	repeat
		if isCharacterCreation() then
			return
		end
		local c = character()
		if c and c.Parent and c.Parent.Name == "Live" then
			return
		end
		local pg = players.LocalPlayer and players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if pg and pg:FindFirstChild("LoadingGui") then
			pressKey(Enum.KeyCode.A)
		end
		task.wait(0.2)
	until not running or os.clock() >= deadline
end

-- Kept the name (callers unchanged); tears down the inline pathfind breaker (the Titus kill mechanism).
local function disableBreaker()
	stopTitusBreaker()
end

-- Ferryman-style auto log: throughout the entire farm, hop the moment another player comes within the
-- per-automation auto-log distance (adjustable 0-2000 in the menu; 0 = off). Saved per automation.
local function watchForPlayers()
	while running do
		task.wait(1)
		if not running then
			break
		end
		-- Don't hop mid-creation (lobby players would softlock the character creator).
		if isCharacterCreation() then
			continue
		end
		local dist = AutoLog.get("auto_titus")
		if dist > 0 and playerCheck(dist) then
			serverHop()
			return
		end
	end
end

local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "continuation", from = "_create_character", to = "_check_area" },
		{ name = "continuation", from = "_bank_relics", to = "_check_area" },
		{ name = "bank", from = "_check_area", to = "_bank_relics" },
		{ name = "cc", from = "_check_area", to = "_create_character" },
		{ name = "enter", from = "_check_area", to = "_enter_dungeon" },
		{ name = "run", from = "_check_area", to = "_run_dungeon" },
		{ name = "exit", from = "_run_dungeon", to = "_exit" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			-- Merit / dungeon: existing character here, so it's safe to blow through the loading screen.
			if game.PlaceId == EASTERN_PLACE_ID then
				requestStart()
				-- Bank first if we're holding a full stack of any selected relic (cooldown-gated).
				for name, selected in pairs(bankItems()) do
					if selected and countItem(name) >= BANK_THRESHOLD and tick() - lastBank > BANK_COOLDOWN then
						lastBank = tick()
						return self:bank()
					end
				end
				-- No wipe: turn the breaker off in the hub, refill food if low, then enter.
				disableBreaker()
				if needFood() then
					refillFood()
				end
				return self:enter()
			end

			if game.PlaceId == DUNGEON_PLACE_ID then
				requestStart()
				return self:run()
			end

			-- Anywhere else (lobby / character creator): DO NOT fire StartMenu.Start -- that would rush the
			-- character creator and roll the wrong character. Wait patiently for the creator to come up.
			local deadline = os.clock() + 20
			repeat
				if isCharacterCreation() then
					return self:cc()
				end
				task.wait()
			until os.clock() >= deadline or not running
		end,

		onenter_create_character = function(self)
			if not running then
				return
			end
			setStage("create character")
			struct:create_character()
			self:continuation()
		end,

		onenter_enter_dungeon = function(self)
			if not running then
				return
			end
			enterDungeon()
		end,

		onenter_run_dungeon = function(self)
			if not running then
				return
			end
			setStage("run dungeon")

			local startTime = tick()
			repeat
				task.wait(0.2)
			until (currentArea() and tostring(currentArea()):match("Detainment")) or not running

			task.wait(1)
			attachToTitus()

			-- Re-arm the watchdog off the shorter void cap now the fight's over, so the exit-wait + loot get a
			-- fresh ACTION_TIMEOUT instead of inheriting "fighting titus"'s 45s.
			setStage("boss defeated")

			-- Titus is down: reset the 30s DungeonExitFinal cap to measure from the KILL, not the dungeon-run
			-- start, so a slow fight can't eat the window the run gets to wait for the exit to spawn.
			startTime = tick()

			local hum = humanoid()
			if hum then
				hum.Died:Connect(function()
					serverHop()
				end)
			end

			local finished = false
			local core = workspace:WaitForChild("DetainmentCore", 10)
			local conn
			if core then
				conn = core.ChildAdded:Connect(function(child)
					if child.Name == "DungeonExitFinal" then
						finished = true
					end
				end)
			end

			repeat
				task.wait(0.2)
				if tick() - startTime > 30 then
					if conn then
						conn:Disconnect()
					end
					serverHop()
					while task.wait() do
					end
					return
				end
			until finished or not running

			if conn then
				conn:Disconnect()
			end

			task.wait(0.5)

			disableBreaker()

			local r = root()
			if r then
				r.CFrame = r.CFrame * CFrame.new(0, 1300, 0)
			end

			xpcall(function()
				grabChest()
			end, function(err)
				Logger.notify("AutoTitus loot error: %s", tostring(err))
			end)

			task.wait(2)

			r = root()
			if r then
				r.CFrame = r.CFrame * CFrame.new(0, 1300, 0)
			end

			local hum2 = humanoid()
			if hum2 and hum2:GetAttribute("DangerExpiration") and hum2:GetAttribute("DangerExpiration") > 0 then
				repeat
					task.wait()
				until not (hum2:GetAttribute("DangerExpiration") and hum2:GetAttribute("DangerExpiration") > 0)
					or not running
			end

			self:exit()
		end,

		onenter_bank_relics = function(self)
			if not running then
				return
			end
			bankRelics()
			self:continuation()
		end,

		onenter_exit = function(self)
			if not running then
				return
			end
			setStage("respawn")
			-- Fast way out: replicate the Kill signal, then void ourselves if we somehow survived.
			if replicatesignal then
				pcall(function()
					replicatesignal(localPlayer().Kill)
				end)
				task.delay(1, function()
					local hum = humanoid()
					if hum and hum.Health <= 1 then
						return
					end
					local r = root()
					if r then
						r.CFrame = r.CFrame * CFrame.new(0, 9e9, 0)
					end
				end)
			else
				local r = root()
				if r then
					r.CFrame = r.CFrame * CFrame.new(0, 9e9, 0)
				end
			end
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_titus",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"auto_loot",
			"auto_equip_weapon",
		},
		character_creator_handler_used = true,
		character_creator_handler_opts = {
			origin = "Merit",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoTitus.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoTitus.inValidPlace() then
		return Logger.notify("Auto Titus: Not in Eastern Luminant")
	end

	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Titus: no data slot found.")
	end

	local data = PersistentData.get("titusdata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("titusdata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoTitus")

	maid:mark(task.spawn(runElapsed))

	-- Keep No Fall Damage forced on for the entire farm (respawns / new characters can drop it).
	maid:mark(task.spawn(function()
		while running do
			if Toggles and Toggles.NoFallDamage and not Toggles.NoFallDamage.Value then
				Toggles.NoFallDamage:SetValue(true)
			end
			task.wait(0.25)
		end
	end))

	-- Ferryman-style auto log: hop if any player comes within 1000 studs.
	maid:mark(task.spawn(watchForPlayers))

	-- Per-action watchdog: rejoin if a stage (esp. the Titus void) stalls past its cap.
	maid:mark(task.spawn(runActionWatchdog))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoTitus.stop()
	if not running then
		return
	end
	running = false

	stopTitusBreaker()

	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end

	Tweening.stop(MOVE_ID)

	pcall(function()
		AntiAFK.stop("AutoTitus")
	end)

	maid:clean()
	destroyOverlay()

	PersistentData.set("titusdata", nil)
end

-- Read-only UI status; uses the same guard as the automation state machine.
AutoTitus.isRunning = isRunning

return AutoTitus

end)
__bundle_register("Features/Automation/AutoLoot", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.JSON
local JSON = require("Utility/JSON")

---@module Utility.Table
local Table = require("Utility/Table")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Features.Automation.Objects.AutoLootOptions
local AutoLootOptions = require("Features/Automation/Objects/AutoLootOptions")

local AutoLoot = { ignore = false }

local lastTimestamp = os.clock()

local autoLootMaid = Maid.new()

local choiceRemote = nil

local currentPrompt = nil

local currentChoice = nil

local lootQueue = {}

local lootAll = false

local players = game:GetService("Players")
local runService = game:GetService("RunService")

---@param options ScrollingFrame
---@param remote RemoteEvent
local function waitForChoiceDeletion(options, remote)
	local choiceObject = options:FindFirstChild(currentChoice)

	remote:FireServer(currentChoice)

	if choiceObject and choiceObject.Parent then
		return
	end

	if lootQueue[1] ~= currentChoice then
		error("We assumed that the current choice was the first in the queue, was the queue modified?")
	end

	table.remove(lootQueue, 1)

	currentChoice = nil
end

local function resetAutoLoot()
	choiceRemote = nil
	lootQueue = {}
	currentChoice = nil
	currentPrompt = nil
	lootAll = false
end

---@param descendant Instance
local function onPlayerGuiDescendantAdded(descendant)
	if descendant.Name ~= "ChoicePrompt" then
		return
	end

	if AutoLoot.ignore then
		return
	end

	if not Configuration.expectToggleValue("AutoLoot") then
		return
	end

	descendant:WaitForChild("ChoiceFrame"):WaitForChild("Options")

	if AutoLoot.ignore or not Configuration.expectToggleValue("AutoLoot") then
		return
	end

	AutoLoot.process(
		descendant,
		AutoLootOptions.new(
			Configuration.expectOptionValue("AutoLootStarsMin") or 0,
			Configuration.expectOptionValue("AutoLootStarsMax") or 0,
			Configuration.expectOptionValues("ItemNameList") or {},
			Configuration.expectToggleValue("AutoLootAll") or false
		)
	)
end

---@param prompt ScreenGui
---@param remote RemoteEvent
---@param param string
local function waitForPromptDeletion(prompt, remote, param)
	repeat
		remote:FireServer(param)

		task.wait()
	until not prompt.Parent

	resetAutoLoot()
end

---@return boolean
function AutoLoot.active()
	return choiceRemote ~= nil and currentPrompt ~= nil and #lootQueue > 0
end

function AutoLoot.update()
	if os.clock() - lastTimestamp <= 0.15 then
		return
	end

	lastTimestamp = os.clock()

	if AutoLoot.ignore or not Configuration.expectToggleValue("AutoLoot") then
		return resetAutoLoot()
	end

	if not choiceRemote or not choiceRemote.Parent then
		return resetAutoLoot()
	end

	if not currentPrompt or not currentPrompt.Parent then
		return resetAutoLoot()
	end

	local choiceFrame = currentPrompt:FindFirstChild("ChoiceFrame")
	local options = choiceFrame and choiceFrame:FindFirstChild("Options")
	if not options then
		return resetAutoLoot()
	end

	if lootAll then
		return waitForPromptDeletion(currentPrompt, choiceRemote, "LOOT_ALL")
	end

	if currentChoice then
		return waitForChoiceDeletion(options, choiceRemote)
	end

	local itemToLoot = lootQueue[1]
	if not itemToLoot then
		return waitForPromptDeletion(currentPrompt, choiceRemote, "EXIT")
	end

	currentChoice = itemToLoot

	choiceRemote:FireServer(itemToLoot)
end

---@param prompt ScreenGui The choice prompt to process.
---@param options AutoLootOptions The options to use.
function AutoLoot.process(prompt, options)
	local remote = prompt:FindFirstChild("Choice")
	if not remote or not remote:IsA("RemoteEvent") then
		return
	end

	local jsonLootData = prompt:GetAttribute("LootData")
	if typeof(jsonLootData) ~= "string" then
		return
	end

	local lootData = JSON.decode(jsonLootData)
	if typeof(lootData) ~= "table" then
		return
	end

	resetAutoLoot()

	currentPrompt = prompt
	choiceRemote = remote
	lootAll = options.lall

	for _, item in next, lootData do
		local rich = item.rich:gsub("%$%S*", "")
		local text = item.text

		if not text then
			continue
		end

		-- Always-loot list: matched items are queued regardless of the star filter.
		local alwaysWanted, _ = Table.find(options.always or {}, function(value, _)
			return rich:match(value)
		end)
		if alwaysWanted then
			lootQueue[#lootQueue + 1] = text
			continue
		end

		local matched = text:match("★")
		local stars = matched and #matched or 0

		if stars < options.smin or stars > options.smax then
			continue
		end

		local wanted, _ = Table.find(options.wanted, function(value, _)
			return rich:match(value)
		end)

		if not wanted then
			continue
		end

		lootQueue[#lootQueue + 1] = text
	end
end

function AutoLoot.init()
	local localPlayer = players.LocalPlayer
	local playerGui = localPlayer:WaitForChild("PlayerGui")

	local preRender = Signal.new(runService.PreRender)
	local playerGuiDescendantAdded = Signal.new(playerGui.DescendantAdded)

	autoLootMaid:mark(playerGuiDescendantAdded:connect("AutoLoot_PlayerGuiDescendantAdded", onPlayerGuiDescendantAdded))
	autoLootMaid:mark(preRender:connect("AutoLoot_PreRender", AutoLoot.update))
end

function AutoLoot.detach()
	autoLootMaid:clean()
end

return AutoLoot

end)
__bundle_register("Features/Automation/Objects/AutoLootOptions", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class AutoLootOptions
---@field smin number Minimum stars to loot.
---@field smax number Maximum stars to loot.
---@field wanted string[] List of wanted item names.
---@field lall boolean Whether to loot everything.
---@field always string[] Item names always looted regardless of the star filter.
local AutoLootOptions = {}

---@param smin number Minimum stars to loot.
---@param smax number Maximum stars to loot.
---@param wanted string[] List of wanted item names.
---@param lall boolean Whether to loot everything.
---@param always string[]? Item names always looted regardless of the star filter.
---@return AutoLootOptions
function AutoLootOptions.new(smin, smax, wanted, lall, always)
	local self = setmetatable({}, AutoLootOptions)
	self.smin = smin
	self.smax = smax
	self.wanted = wanted
	self.lall = lall
	self.always = always or {}
	return self
end

return AutoLootOptions

end)
__bundle_register("Utility/Table", function(require, _LOADED, __bundle_register, __bundle_modules)
local Table = {}

---@param input any[]
---@param start number
---@param stop number
---@return any[]
Table.slice = LPH_NO_VIRTUALIZE(function(input, start, stop)
	local out = {}

	if start == nil then
		start = 1
	elseif start < 0 then
		start = #input + start + 1
	end
	if stop == nil then
		stop = #input
	elseif stop < 0 then
		stop = #input + stop + 1
	end

	for idx = start, stop do
		table.insert(out, input[idx])
	end

	return out
end)

---@param input any[]
---@param predicate fun(value: any, index: number): boolean
---@return number, any
Table.find = LPH_NO_VIRTUALIZE(function(input, predicate)
	for idx, value in next, input do
		if not predicate(value, idx) then
			continue
		end

		return idx, value
	end
end)

return Table

end)
