local function isMantraAllowed(mantra, optionKey)
	local selectedMantras = Configuration.expectOptionValue(optionKey)
	if type(selectedMantras) ~= "table" then
		return true
	end

	local isEmpty = true
	for _, v in pairs(selectedMantras) do
		if v then
			isEmpty = false
			break
		end
	end

	if isEmpty then
		return false
	end

	local defaultName = mantra and mantra.GetAttribute and mantra:GetAttribute("DefaultName")
	if not defaultName then
		return false
	end

	return selectedMantras[defaultName] == true
end

---@param optionName string
---@param randomize boolean? If true, pick a random off-cooldown mantra instead of the first in order.
local function getSelectedMantraTool(optionName, randomize)
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return nil
	end

	local selectedMantras = Configuration.expectOptionValue(optionName)
	if type(selectedMantras) ~= "table" then
		return nil
	end

	-- Selected mantra names (the multi-dropdown stores a { [name] = true } set); ignore any that
	-- were toggled off, and sort so "the next mantra" is a stable, predictable fallback order.
	local names = {}
	for name, selected in next, selectedMantras do
		if selected then
			names[#names + 1] = name
		end
	end

	if #names == 0 then
		return nil
	end

	table.sort(names)

	-- DefaultNames of every mantra currently on cooldown (a ToolLockCD effect whose Value names the tool).
	local onCooldown = {}
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	if effectReplicatorModule and effectReplicatorModule.GetEffects then
		for _, effect in pairs(effectReplicatorModule:GetEffects()) do
			if type(effect) ~= "table" then
				continue
			end

			local class = effect.Class or (effect.index and effect.index.Class)
			local value = effect.Value or (effect.index and effect.index.Value)

			if class == "ToolLockCD" and value then
				local tool = backpack:FindFirstChild(tostring(value))
				local defaultName = tool and tool:GetAttribute("DefaultName")
				if defaultName then
					onCooldown[defaultName] = true
				end
			end
		end
	end

	---Find the backpack Tool for a mantra DefaultName.
	local function toolFor(name)
		for _, tool in pairs(backpack:GetChildren()) do
			if tool:IsA("Tool") and tool:GetAttribute("DefaultName") == name then
				return tool
			end
		end
		return nil
	end

	if randomize then
		-- Collect every selected mantra that exists and is off cooldown, then pick one at random.
		local available = {}
		for _, name in ipairs(names) do
			if not onCooldown[name] then
				local tool = toolFor(name)
				if tool then
					available[#available + 1] = tool
				end
			end
		end

		if #available == 0 then
			return nil
		end

		return available[math.random(1, #available)]
	end

	-- Walk the selection in order and return the first mantra that exists and is off cooldown,
	-- skipping straight past any that are still cooling down.
	for _, name in ipairs(names) do
		if not onCooldown[name] then
			local tool = toolFor(name)
			if tool then
				return tool
			end
		end
	end

	return nil
end

local function tryActivateBackstabMovestack()
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return false
	end

	local tool = getSelectedMantraTool("BackstabMovestackMantras")
	if not tool then
		return false
	end

	local localPlayer = game:GetService("Players").LocalPlayer
	local character = localPlayer and localPlayer.Character
	local characterHandler = character and character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	local activateMantra = requests and requests:FindFirstChild("ActivateMantra")

	if activateMantra then
		activateMantra:FireServer(tool)
		return true
	end

	return false
end

-- ---- Auto Mixup: Roll Cancel Behind Back ----
-- Nearest living, non-ally enemy's root part within range (self-contained, no aimbot config needed).
local function getNearestEnemyRoot()
	local character = localPlayer and localPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return nil
	end

	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end

	local best, bestDistance = nil, math.huge
	for _, entity in next, live:GetChildren() do
		if entity == character then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		local entityRoot = entity:FindFirstChild("HumanoidRootPart")
		if not humanoid or not entityRoot or humanoid.Health <= 0 then
			continue
		end

		local player = players:GetPlayerFromCharacter(entity)
		if player and PlayerScanning.isAlly(player) then
			continue
		end

		-- Optionally restrict roll-behind to real players (skip NPCs/mobs).
		if Configuration.expectToggleValue("AutoMixupRollBehindPlayersOnly") and not player then
			continue
		end

		local distance = (entityRoot.Position - root.Position).Magnitude
		if distance <= 60 and distance < bestDistance then
			best = entityRoot
			bestDistance = distance
		end
	end

	return best
end

-- Roll -> lock onto the opponent through the roll -> roll cancel -> m1 again (the Easy Roll Cancel path).
local performRollCancelBehindBack = LPH_NO_VIRTUALIZE(function(targetRoot)
	-- Dodge gate over the whole sequence: if we can't dodge right now, do nothing -- no roll, no
	-- roll cancel, no m1 -- rather than feinting and m1ing on a roll that never happened.
	if not StateListener.cdodge() then
		return
	end

	-- Re-entry guard: this routine holds a ~0.5s camera lock (Heartbeat:Wait loops below), and it has two
	-- drivers -- the m1 remote-hook mixup path and the Roll Parry alias (Defense.rollCancelBehindBack). If a
	-- second call enters while the first is still mid-lock, both BindToRenderStep the SAME name with a fresh
	-- closure, so they stack (2-3 deep) and Roblox warns "removed different functions with same reference name
	-- AutoMixup_RollBehindLockOn N times" every unbind -- the churn that saturated the crash log. One at a time.
	if rollBehindActive then
		return
	end

	-- Suppress Easy Roll Cancel / Easy Mantra Feint for the duration so they don't stack their own
	-- feint + m1 on top of this sequence's roll cancel.
	rollBehindActive = true

	local intensity = math.clamp((Configuration.expectOptionValue("AutoMixupRollBehindLockOnIntensity") or 50) / 100, 0.0, 1.0)

	-- How long before the roll cancel, and how long the camera stays locked on overall.
	local ROLL_CANCEL_DELAY = 0.18
	local LOCK_ON_DURATION = 0.5

	-- Roll -- same rolling logic as the auto-defense roll (honors the Blatant Roll setting). We do
	-- the cancel ourselves below (Easy Roll Cancel path), so leave the dodge's own rollCancel off.
	local rollOptions = DodgeOptions.new()
	rollOptions.direct = Configuration.expectToggleValue("BlatantRoll")
	InputClient.dodge(rollOptions)

	-- Lock onto the opponent with the CAMERA. Bound just above the camera render step so our aim is
	-- the last write each frame. Lock On Intensity = lerp strength.
	local bindName = "AutoMixup_RollBehindLockOn"
	-- Always clear any prior bind under this name before re-binding, so a run that errored out of its wait
	-- loop before reaching the unbind below can never leave a stale closure stacked under the same name.
	pcall(runService.UnbindFromRenderStep, runService, bindName)
	if intensity > 0 then
		pcall(function()
			runService:BindToRenderStep(bindName, Enum.RenderPriority.Camera.Value + 1, function()
				local camera = workspace.CurrentCamera
				if camera and targetRoot and targetRoot.Parent then
					camera.CFrame = camera.CFrame:Lerp(CFrame.lookAt(camera.CFrame.Position, targetRoot.Position), intensity)
				end
			end)
		end)
	end

	local lockStart = os.clock()

	-- Short window before the roll cancel.
	while os.clock() - lockStart < ROLL_CANCEL_DELAY do
		runService.Heartbeat:Wait()
	end

	-- Roll cancel + m1 again (Easy Roll Cancel path), aimed via the camera (mouse hit).
	local character = localPlayer and localPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if root then
		-- Only feint if we're actually still mid-roll (Dodge / ClientDodge effect); otherwise a stray
		-- feint would get buffered onto the m1 below and feint it.
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		if effectReplicatorModule and (effectReplicatorModule:HasEffect("Dodge") or effectReplicatorModule:HasEffect("ClientDodge")) then
			InputClient.feint()
			task.wait()
		end

		local mouse = localPlayer and localPlayer:GetMouse()
		local aim = (mouse and mouse.Hit) or root.CFrame
		InputClient.left(aim, true)
	end

	-- Hold the camera lock for the rest of the set lock-on duration, then release it.
	while os.clock() - lockStart < LOCK_ON_DURATION do
		runService.Heartbeat:Wait()
	end

	pcall(function()
		runService:UnbindFromRenderStep(bindName)
	end)

	rollBehindActive = false
end)

-- Public alias so other modules (e.g. the Roll Parry defense option) can run the roll-behind ->
-- roll cancel -> m1 sequence against a given target root.
Defense.rollCancelBehindBack = performRollCancelBehindBack

-- Called from the m1 remote hook. Rolls each enabled Auto Mixup action's probability, then picks
-- ONE of the actions that hit at random -- no fixed priority order. Returns true to BLOCK the
-- manual m1 (roll-cancel-behind-back takes over), false to let it fire (a feint / feint-into-mantra
-- rides on the m1 that goes out).
Defense.tryAutoMixup = LPH_NO_VIRTUALIZE(function()
	if not Configuration.expectToggleValue("AutoMixup") then
		return false
	end

	if os.clock() - lastAutoMixupAt < 0.2 then
		return false
	end

	if not (localPlayer and localPlayer.Character) then
		return false
	end

	-- Only mix up while the weapon is actually drawn. "Equipped" is the drawn-weapon effect (same one
	-- weapon-draw detection keys off). Sheathed / no weapon out -> leave the manual m1 alone.
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not (effectReplicatorModule and effectReplicatorModule:HasEffect("Equipped")) then
		return false
	end

	-- Build the pool of actions that rolled this m1. Each is gated by its own feasibility check so
	-- we never queue something the player can't actually do.
	local candidates = {}
	local mantraTool = nil
	local enemyRoot = nil

	local feintChance = Configuration.expectOptionValue("AutoMixupFeintProbability") or 0.0
	if feintChance > 0 and Random.new():NextNumber(1.0, 100.0) <= feintChance and StateListener.cfeint() then
		candidates[#candidates + 1] = "feint"
	end

	local mantraChance = Configuration.expectOptionValue("AutoMixupFeintIntoMantraProbability") or 0.0
	if mantraChance > 0 and Random.new():NextNumber(1.0, 100.0) <= mantraChance then
		mantraTool = getSelectedMantraTool("AutoMixupMantras", true)
		if mantraTool then
			candidates[#candidates + 1] = "mantra"
		end
	end

	local rollChance = Configuration.expectOptionValue("AutoMixupRollBehindProbability") or 0.0
	-- Never roll-cancel-behind if the player can't dodge right now (NoRoll cooldown / stun / blocked).
	if rollChance > 0 and Random.new():NextNumber(1.0, 100.0) <= rollChance and StateListener.cdodge() then
		enemyRoot = getNearestEnemyRoot()
		if enemyRoot then
			candidates[#candidates + 1] = "rollbehind"
		end
	end

	if #candidates == 0 then
		return false
	end

	local choice = candidates[Random.new():NextInteger(1, #candidates)]
	lastAutoMixupAt = os.clock()

	if choice == "rollbehind" then
		-- Off the UnreliableFireServer hook callstack: enqueue to the shared Heartbeat pump (a table insert, no
		-- scheduler touch) and still return true synchronously so the manual m1 is swallowed now. Was task.defer,
		-- which registered a thread from inside the hook body -- a Kernel,2090 nesting candidate on 0.742+.
		EffectDispatcher.defer(function()
			performRollCancelBehindBack(enemyRoot)
		end)
		return true
	end

	if choice == "mantra" then
		local mantraDelay = Configuration.expectOptionValue("AutoMixupFeintIntoMantraDelay") or 0.0
		EffectDispatcher.defer(function()
			if mantraDelay > 0 then
				task.wait(mantraDelay)
			end
			InputClient.amantra(mantraTool)
		end)
		return false
	end

	if choice == "feint" then
		EffectDispatcher.defer(function()
			task.wait() -- let the manual m1 go out first, then feint it
			InputClient.feint()
		end)
		return false
	end

	return false
end)

local function isBackstabActionLocked()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not effectReplicatorModule then
		return false
	end

	return effectReplicatorModule:HasAny("Action", "MobileAction", "UsingAbility", "LightAttack")
end

local function getBackstabMovestackDelay()
	local delay = Configuration.expectOptionValue("BackstabMovestackDelay") or 0.05
	return math.max(delay, 0.0)
end

local function scheduleBackstabMovestackActivation(label)
	TaskSpawner.delay(label, function()
		return getBackstabMovestackDelay()
	end, function()
		backstabMovestackReady = false
		tryActivateBackstabMovestack()
	end)
end

local function isBackstabTriggerAnimationTrack(track)
	if not track or not track.Animation then
		return false
	end

	local aid = tostring(track.Animation.AnimationId)
	if aid == BACKSTAB_TRIGGER_ANIMATION_ID then
		return true
	end

	local numericId = aid:match("%d+")
	return numericId == BACKSTAB_TRIGGER_ANIMATION_NUMERIC_ID
end

local onBackstabLocalAnimationPlayed = LPH_NO_VIRTUALIZE(function(track)
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return
	end

	if not isBackstabTriggerAnimationTrack(track) then
		return
	end

	if os.clock() - backstabAnimationTriggerTimestamp <= 0.15 then
		return
	end

	backstabMovestackReady = true
	backstabAnimationTriggerTimestamp = os.clock()

	if not isBackstabActionLocked() and tryActivateBackstabMovestack() then
		backstabMovestackReady = false
		return
	end

	TaskSpawner.spawn("Defense_BackstabMovestackImmediateRetry", function()
		local startedAt = os.clock()

		while os.clock() - startedAt <= 0.35 do
			if not backstabMovestackReady then
				return
			end

			if not Configuration.expectToggleValue("BackstabMovestack") then
				return
			end

			if not isBackstabActionLocked() and tryActivateBackstabMovestack() then
				backstabMovestackReady = false
				return
			end

			runService.RenderStepped:Wait()
		end

		scheduleBackstabMovestackActivation("Defense_BackstabMovestackFromAnimation")
	end)
end)

local function bindBackstabAnimationListener(character)
	if not character then
		return
	end

	local animator = character:FindFirstChildWhichIsA("Animator", true)
	if not animator then
		return
	end

	local animationPlayed = Signal.new(animator.AnimationPlayed)
	defenseMaid["Defense_BackstabAnimationPlayed"] =
		animationPlayed:connect("Defense_BackstabAnimationPlayed", onBackstabLocalAnimationPlayed)
end

local function onBackstabCharacterAdded(character)
	if not character then
		return
	end

	bindBackstabAnimationListener(character)

	local descendantAdded = Signal.new(character.DescendantAdded)
	defenseMaid["Defense_BackstabCharacterDescendantAdded"] = descendantAdded:connect(
		"Defense_BackstabCharacterDescendantAdded",
		function(descendant)
			if not descendant:IsA("Animator") then
				return
			end

			bindBackstabAnimationListener(character)
		end
	)
end

---@param effect table
local function onBackstabEffectAdded(effect)
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return
	end

	if effect.Class == "backstabDebounce" then
		backstabMovestackReady = true
		task.delay(3, function()
			backstabMovestackReady = false
		end)
	end
end

---@param effect table
local function onBackstabEffectRemoved(effect)
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return
	end

	if os.clock() - backstabAnimationTriggerTimestamp <= 1.0 then
		return
	end

	if effect.Class ~= "Action" or not backstabMovestackReady then
		return
	end

	scheduleBackstabMovestackActivation("Defense_BackstabMovestack")
end



local function attemptRollCast(mantra)
	if not isMantraAllowed(mantra, "RollCastMantrasList") then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if effectReplicatorModule:HasAny(
		"AirCombo",
		"NoSlide",
		"Action",
		"MobileAction",
		"UsingAbility",
		"LightAttack",
		"Blocking",
		"Parried",
		"ClientSlide2",
		"ClientSwim"
	) then
		return
	end

	local keybindsModule = replicatedStorage:FindFirstChild("KeyBinds")
	if not keybindsModule then
		return
	end

	local Keybinds = require(keybindsModule)
	if not Keybinds or not Keybinds.ForceActionDown then
		return
	end

	Keybinds.ForceActionDown("Dodge")
	Keybinds.ForceActionUp("Dodge")

	task.delay(0.09, function()
		local clientFeint = effectReplicatorModule:CreateEffect("ClientFeint")
		if clientFeint then
			clientFeint:Debris(0.1)
		end
	end)
end

local function attemptSlideCast(mantra)
	if not isMantraAllowed(mantra, "SlideCastMantrasList") then
		return
	end

	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local ether = character:FindFirstChild("Ether")
	local spellCost = mantra and mantra:GetAttribute("SpellCost")
	if not ether or not spellCost or ether.Value <= spellCost then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if effectReplicatorModule:HasAny(
		"AirCombo",
		"NoSlide",
		"Action",
		"MobileAction",
		"UsingAbility",
		"LightAttack",
		"Blocking",
		"Parried",
		"ClientSlide2",
		"ClientSwim"
	) then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	local moveDirection = humanoid.MoveDirection
	if moveDirection.Magnitude <= 0.1 then
		return
	end

	local rootPart = character:FindFirstChild("HumanoidRootPart")
	if not rootPart then
		return
	end

	local hitPart = workspace:FindPartOnRayWithIgnoreList(
		Ray.new(rootPart.Position, Vector3.new(0, -10, 0)),
		{ workspace:FindFirstChild("Live"), workspace:FindFirstChild("NPCs"), workspace:FindFirstChild("Thrown") }
	)

	if not hitPart then
		return
	end

	if not effectReplicatorModule:FindEffect("Sprinting") then
		return
	end

	local keybindsModule = replicatedStorage:FindFirstChild("KeyBinds")
	if not keybindsModule then
		return
	end

	local Keybinds = require(keybindsModule)
	if not Keybinds or not Keybinds.ForceActionDown then
		return
	end

	if not effectReplicatorModule:FindEffect("CastingSpell") then
		local castingSpell = effectReplicatorModule:CreateEffect("CastingSpell")
		if castingSpell then
			castingSpell:Debris(0.05)
		end
	end

	Keybinds.ForceActionDown("Crouch")
	Keybinds.ForceActionUp("Crouch")
end

local function updateMantraRequests()
	local mantra = StateListener.lMantraActivated
	if not mantra then
		return
	end

	local activatedAt = StateListener.lMantraActivatedAt
	if activatedAt == lastMantraActivatedAt then
		return
	end

	lastMantraActivatedTool = mantra
	lastMantraActivatedAt = activatedAt

	if Configuration.expectToggleValue("RollCastMantras") then
		attemptRollCast(mantra)
	end

	if Configuration.expectToggleValue("SlideCastMantras") then
		attemptSlideCast(mantra)
	end
end

local updateAutoAirCounter = LPH_NO_VIRTUALIZE(function()
	if not Configuration.expectToggleValue("AutoAirCounter") then
		return
	end

	if os.clock() - lastAutoAirCounterUpdate < 0.1 then
		return
	end
	lastAutoAirCounterUpdate = os.clock()

	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	local antiAir = requests and requests:FindFirstChild("AntiAir")
	if not antiAir then
		return
	end

	local rootPart = character:FindFirstChild("HumanoidRootPart")
	if not rootPart then
		return
	end

	if not Configuration.expectToggleValue("AutoAirCounterOnGround") then
		local isGrounded = false
		local controllerManager = character:FindFirstChild("ControllerManager")
		if controllerManager then
			local groundSensor = controllerManager:FindFirstChild("GroundSensor")
			if groundSensor and groundSensor.SensedPart then
				isGrounded = true
			end
		end
		
		if not isGrounded then
			local humanoid = character:FindFirstChildWhichIsA("Humanoid")
			if humanoid and humanoid.FloorMaterial ~= Enum.Material.Air then
				isGrounded = true
			end
		end

		if not isGrounded then
			local raycastParams = RaycastParams.new()
			raycastParams.FilterType = Enum.RaycastFilterType.Exclude
			raycastParams.FilterDescendantsInstances = { workspace:FindFirstChild("Live"), workspace:FindFirstChild("NPCs"), workspace:FindFirstChild("Thrown") }
			local hit = workspace:Raycast(rootPart.Position, Vector3.new(0, -4, 0), raycastParams)
			if hit and hit.Instance then
				isGrounded = true
			end
		end

		if isGrounded then
			return
		end
	end

	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end

	local range = Configuration.expectOptionValue("AutoAirCounterRange") or 60
	local allyCheck = Configuration.expectToggleValue("AutoAirCounterAllyCheck")

	for _, entity in next, live:GetChildren() do
		if entity == character then
			continue
		end

		if entity.Name:sub(1, 1) == "." then
			continue
		end

		local entityRoot = entity:FindFirstChild("HumanoidRootPart")
		if not entityRoot then
			continue
		end

		local distance = (entityRoot.Position - rootPart.Position).Magnitude
		if distance > range then
			continue
		end

		if allyCheck then
			local entityPlayer = players:GetPlayerFromCharacter(entity)
			if entityPlayer then
				local pvpAttribute = entity:GetAttribute("PVPEnabled")
				if pvpAttribute == false or PlayerScanning.isAlly(entityPlayer) then
					continue
				end
			end
		end

		antiAir:FireServer(entity)
	end
end)

Defense.visualizations = LPH_NO_VIRTUALIZE(function()
	for _, object in next, defenderObjects do
		for _, hitbox in next, object.hmaid._tasks do
			if typeof(hitbox) ~= "Instance" then
				continue
			end

			hitbox.Transparency = Configuration.expectToggleValue("EnableVisualizations") and 0.2 or 1.0
		end
	end
end)

local updateVisualizations = LPH_NO_VIRTUALIZE(function()
	if not Configuration.expectToggleValue("EnableVisualizations") then
		return
	end

	if os.clock() - lastVisualizationUpdate <= 5.0 then
		return
	end

	lastVisualizationUpdate = os.clock()

	for _, object in next, defenderObjects do
		for idx, hitbox in next, object.hmaid._tasks do
			if typeof(hitbox) ~= "Instance" then
				continue
			end

			---@note: We call :Debris so we don't have to clean it up ourselves. We just unregister it from the maid.
			if hitbox.Parent then
				continue
			end

			object.hmaid._tasks[idx] = nil
		end
	end
end)

---@param position number
---@param str string
local hssp = LPH_NO_VIRTUALIZE(function(position, str)
	if autoWispLocked then
		return Logger.warn("Auto Wisp is locked.")
	end

	if position <= 0 or position > #str then
		return Logger.warn("Invalid position (%i vs. %i) for Auto Wisp.", position, #str)
	end

	local delay = Configuration.expectOptionValue("AutoWispDelay") or 0

	if lastAutoWispShift and os.clock() - lastAutoWispShift <= 0.15 + delay then
		return Logger.warn(
			"(%.2f - %.2f = %.2f vs. %.2f) Auto Wisp shift is on forced cooldown.",
			os.clock(),
			lastAutoWispShift,
			os.clock() - lastAutoWispShift,
			0.15 + delay
		)
	end

	local character = str:sub(position, position)
	if character ~= "Z" and character ~= "X" and character ~= "C" and character ~= "V" then
		return Logger.warn("Invalid character (%s) for Auto Wisp.", tostring(character))
	end

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	local mantras = replicatedStorage:FindFirstChild("Requests")
	mantras = mantras and mantras:FindFirstChild("Mantras")
	local spellInput = mantras and mantras:FindFirstChild("RitualSpellInput")
	if not spellInput then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if not effectReplicatorModule:HasEffect("RitualCastingSpell") then
		return Logger.warn("RitualCastingSpell effect not found.")
	end

	if effectReplicatorModule:HasEffect("Knocked") then
		return Logger.warn("Knocked effect found.")
	end

	Logger.warn("Sending event for character (%s) with position (%i) and string (%s).", character, position, str)

	autoWispLocked = true
	lastAutoWispUpdate = os.clock()

	pcall(function()
		spellInput:FireServer(WISP_INPUT_MAP[character] or character)
	end)

	task.delay(0.5 + delay, function()
		autoWispLocked = false
	end)
end)

local updateDefenders = LPH_NO_VIRTUALIZE(function()
	Defense.updateBlockInputState()

	if Configuration.expectToggleValue("M1Hold") and leftClickState and not Defense.shouldBlockInput("M1s") then
		-- Held m1s are fired by our own code, so they bypass the m1 hook's Auto Mixup (which only runs
		-- on non-checkcaller input). Run the mixup here too: if it takes over (roll-cancel-behind), skip
		-- this held m1; otherwise fire it (a feint / feint-into-mantra rides on it).
		if not Defense.tryAutoMixup() then
			InputClient.left(players.LocalPlayer:GetMouse().Hit, true)
		end
	end

	if Configuration.expectToggleValue("AutoWisp") and cwp and cws then
		hssp(cwp, cws)
	end

	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return
	end

	for _, object in next, defenderAnimationObjects do
		object:update()
	end

	for _, object in next, defenderPartObjects do
		object:update()
	end
end)

---@param part BasePart
---@param timing PartTiming?
---@return PartDefender?
Defense.cdpo = LPH_NO_VIRTUALIZE(function(part, timing)
	local partDefender = PartDefender.new(part, timing)
	if not partDefender then
		return nil
	end

	defenderObjects[part] = partDefender
	defenderPartObjects[part] = partDefender

	return partDefender
end)

---@param entity Instance
---@return AnimatorDefender?
Defense.dao = LPH_NO_VIRTUALIZE(function(entity)
	for _, object in next, defenderAnimationObjects do
		if object.entity ~= entity then
			continue
		end

		return object
	end
end)

local function isThreatImminent(object, timing)
	local entity = object.entity
	if not entity then
		return true
	end

	if not entity:FindFirstChild("HumanoidRootPart") then
		return true
	end

	local root = entity:FindFirstChild("HumanoidRootPart")

	if Configuration.expectOptionValue("BlockInputRangeCheck") == "Inside Hitbox" then
		local hoptions = HitboxOptions.new(root, timing)
		hoptions.visualize = false
		-- Enlarge the detection hitbox by 1.2x so it triggers a touch more leniently than the exact hitbox
		-- (hc reads the size from options:hitbox(), which returns this cache).
		hoptions.cache = hoptions:hitbox() * 1.2

		if hoptions:hitbox().Magnitude > 0 then
			return object:hc(hoptions, nil) == true
		end
	end

	local distance = object:distance(entity)
	if not distance then
		return true
	end

	return distance <= (timing.imxd or math.huge)
end

---@note: Runs on a safe thread (postSimulation) so the input hooks only ever read the cached
Defense.updateBlockInputState = LPH_NO_VIRTUALIZE(function()
	if
		not Configuration.expectToggleValue("EnableAutoDefense")
		or not Configuration.expectToggleValue("BlockInput")
	then
		blockInputActive = {}
		return
	end

	local allowedTargets = Configuration.expectOptionValue("BlockInputAllowedTargets") or {
		PVE = true,
		PVP = true,
	}

	local useTargeting = Configuration.expectToggleValue("BlockInputTargeting")
	local criticalPunishTime = (Configuration.expectOptionValue("BlockInputCriticalPunishmentTime") or 0) / 1000
	local m1PunishTime = (Configuration.expectOptionValue("BlockInputM1PunishmentTime") or 0) / 1000
	local halfPing = Latency.rdelay()

	local active = {}

	for object in next, Defender.armed do
		local timing = object.timing
		if timing and timing.ibi then
			continue
		end

		local ownerModel = object.entity or object.owner
		if not ownerModel and object.part then
			ownerModel = object.part:FindFirstAncestorWhichIsA("Model")
		end

		local isPvp = ownerModel and players:GetPlayerFromCharacter(ownerModel) ~= nil
		if isPvp and not allowedTargets.PVP then
			continue
		end

		if not isPvp and not allowedTargets.PVE then
			continue
		end

		if useTargeting and not (ownerModel and Targeting.find(ownerModel, BLOCK_INPUT_TARGETING_KEYS)) then
			continue
		end

		if timing and not isThreatImminent(object, timing) then
			continue
		end

		if object:blocking() then
			active.Mantras = true
		end

		for _, tsk in next, object.tasks do
			if coroutine.status(tsk.thread) == "dead" then
				continue
			end

			local when = tsk:when()
			local tail = when + tsk.after

			if os.clock() >= when - criticalPunishTime - halfPing and os.clock() <= tail then
				active.Criticals = true
			end

			if os.clock() >= when - m1PunishTime - halfPing and os.clock() <= tail then
				active.M1s = true
			end
		end
	end

	blockInputActive = active
end)

---@note: Cheap read only (booleans + option table) so it is safe to call from input hooks.
---@param moveType string
---@return boolean
Defense.shouldBlockInput = LPH_NO_VIRTUALIZE(function(moveType)
	local blockedMoves = Configuration.expectOptionValue("BlockedSafeInputUserMoves") or {}
	return blockedMoves[moveType] == true and blockInputActive[moveType] == true
end)

---@param aid string
---@return PlaybackData?
Defense.agpd = LPH_NO_VIRTUALIZE(function(aid)
	---@note: Grabbing from 'rpbdata' means that we know that the data has been fully recorded.
	for _, object in next, defenderAnimationObjects do
		local pbdata = object.rpbdata[aid]
		if not pbdata then
			continue
		end

		return pbdata
	end

	---@note: Fallback to deleted playback data if that doesn't exist.
	for _, rpbdata in next, deletedPlaybackData do
		local pbdata = rpbdata[aid]
		if not pbdata then
			continue
		end

		return pbdata
	end
end)

---@param name string
---@param data any?
local onSpellEvent = LPH_NO_VIRTUALIZE(function(name, data)
	if name == "close" then
		cws = nil
		cwp = nil
		lastAutoWispUpdate = nil
		lastAutoWispShift = nil
		autoWispLocked = false
	end

	if name == "start" then
		cws = data
		cwp = 1
		lastAutoWispUpdate = nil
		lastAutoWispShift = nil
		autoWispLocked = false
	end

	if cws and cwp and name == "shift" then
		cwp = cwp + 1
		lastAutoWispShift = os.clock()
		autoWispLocked = false
	end
end)

function Defense.fflourish()
	if not Configuration.expectToggleValue("FeintFlourish") then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return Logger.warn("EffectReplicator not found for FeintFlourish.")
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return Logger.warn("EffectReplicator module not found for FeintFlourish.")
	end

	if not effectReplicatorModule:FindEffect("MidAttack") then
		return Logger.warn("Not MidAttack effect for FeintFlourish.")
	end

	local mantra = Finder.ncdm()
	if not mantra then
		return Logger.warn("No mantra found for FeintFlourish.")
	end

	if effectReplicatorModule:FindEffect("FeintCool") then
		return Logger.warn("No avaliable feint for FeintFlourish.")
	end

	local lastAnimationTiming = StateListener.lAnimTiming
	if not lastAnimationTiming then
		return Logger.warn("No last animation timing found for FeintFlourish.")
	end

	if not lastAnimationTiming.smod:match("Flourish") then
		return Logger.warn("Last animation is not a flourish for FeintFlourish.")
	end

	Logger.warn("(%s) FeintFlourish activated mantra.", mantra.Name)

	InputClient.amantra(mantra)

	task.wait(0.1)

	Logger.warn("(%s) FeintFlourish feinted mantra.", mantra.Name)

	InputClient.feint()
end

function Defense.init()
	local WAIT = 30

	local assetFolder = replicatedStorage:WaitForChild("Assets", WAIT)
	local animationFolder = assetFolder and assetFolder:WaitForChild("Anims", WAIT)
	local mobsAnimationFolder = animationFolder and animationFolder:WaitForChild("Mobs", WAIT)

	for _, animation in next, mobsAnimationFolder and mobsAnimationFolder:QueryDescendants("Animation") or {} do
		if animation.Name == "RunningAttack" then
			continue
		end

		mobAnimations[animation.AnimationId] = animation
	end

	local requests = replicatedStorage:WaitForChild("Requests", WAIT)
	local clientEffect = requests and requests:WaitForChild("ClientEffect", WAIT)
	local clientEffectLarge = requests and requests:WaitForChild("ClientEffectLarge", WAIT)
	local clientEffectDirect = requests and requests:WaitForChild("ClientEffectDirect", WAIT)
	local mantras = requests and requests:WaitForChild("Mantras", WAIT)
	local spell = mantras and mantras:WaitForChild("RitualSpellInput", WAIT)

	local gameDescendantAdded = Signal.new(game.DescendantAdded)
	local gameDescendantRemoved = Signal.new(game.DescendantRemoving)
	local characterAdded = Signal.new(localPlayer.CharacterAdded)
	local inputBegan = Signal.new(userInputService.InputBegan)
	local inputEnded = Signal.new(userInputService.InputEnded)
	local renderStepped = Signal.new(runService.RenderStepped)
	local postSimulation = Signal.new(runService.PostSimulation)
	local clientEffectEvent = clientEffect and Signal.new(clientEffect.OnClientEvent)
	local clientEffectLargeEvent = clientEffectLarge and Signal.new(clientEffectLarge.OnClientEvent)
	local cientEffectDirect = clientEffectDirect
		and Signal.new(clientEffectDirect:IsA("BindableEvent") and clientEffectDirect.Event or clientEffectDirect.OnClientEvent)
	local spellEvent = spell and Signal.new(spell.OnClientEvent)

	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator", WAIT)
	if not effectReplicator then
		return error("EffectReplicator not found.")
	end

	local effectReplicatorModule = require(effectReplicator)
	local effectAddedSignal = Signal.new(effectReplicatorModule.EffectAdded)
	local effectRemovedSignal = Signal.new(effectReplicatorModule.EffectRemoved)

	---@note: Need this to detect UI presses / game processed inputs.
	defenseMaid:mark(inputBegan:connect("Defense_OnInputBegan", function(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.UserInputType == Enum.UserInputType.MouseButton2 then
			TaskSpawner.delay("StateListener_FeintFlourish", function()
				return 0.07
			end, Defense.fflourish)
		end

		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		do
			local character = localPlayer.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			-- Skip while Auto Mixup's roll-behind runs its own roll cancel, so we don't stack a second
			-- feint + m1 on it. Time-bounded so a stuck flag can't disable Easy Roll Cancel for good.
			local mixupBusy = rollBehindActive and (os.clock() - lastAutoMixupAt) < 1.0
			if root and not mixupBusy and (os.clock() - lastEasyFeint) > 0.3 and StateListener.cfeint() then
				if
					Configuration.expectToggleValue("EasyMantraFeint")
					and (effectReplicatorModule:HasEffect("UsingSpell") or effectReplicatorModule:HasEffect("CastingSpell"))
				then
					lastEasyFeint = os.clock()
					task.spawn(function()
						InputClient.feint()
						task.wait()
						InputClient.left(root.CFrame, true)
					end)
				elseif
					Configuration.expectToggleValue("EasyRollCancel")
					and (effectReplicatorModule:HasEffect("Dodge") or effectReplicatorModule:HasEffect("ClientDodge"))
				then
					lastEasyFeint = os.clock()
					task.spawn(function()
						InputClient.feint()
						task.wait()
						InputClient.left(root.CFrame, true)
					end)
				end
			end
		end

		leftClickState = true
	end))

	defenseMaid:mark(inputEnded:connect("Defense_OnInputEnded", function(input, _)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		leftClickState = false
	end))

	defenseMaid:mark(gameDescendantAdded:connect("Defense_OnDescendantAdded", onGameDescendantAdded))
	defenseMaid:mark(gameDescendantRemoved:connect("Defense_OnDescendantRemoved", onGameDescendantRemoved))

	-- Per-entity animator tracking off workspace.Live (replaces the game-wide Animator branch of
	-- handleGameDescendant). One AnimatorDefender per live entity, torn down the instant it leaves Live --
	-- ChildRemoved fires on a reparent-out too, which game.DescendantRemoving misses. Spawned so a missing
	-- Live folder can't block init.
	defenseMaid:mark(task.spawn(function()
		local live = workspace:WaitForChild("Live", 30)
		if not live then
			return
		end

		defenseMaid:mark(Signal.new(live.ChildAdded):connect("Defense_LiveEntityAdded", trackLiveEntity))
		defenseMaid:mark(Signal.new(live.ChildRemoved):connect("Defense_LiveEntityRemoved", untrackLiveEntity))

		for _, entity in next, live:GetChildren() do
			trackLiveEntity(entity)
		end
	end))

	defenseMaid:mark(renderStepped:connect("Defense_UpdateVisualizations", updateVisualizations))
	defenseMaid:mark(renderStepped:connect("Defense_UpdateHistory", updateHistory))
	defenseMaid:mark(renderStepped:connect("Defense_UpdateGoldenTongue", updateGoldenTongue))
	defenseMaid:mark(renderStepped:connect("Defense_UpdateAutoArdour", updateAutoArdour))
	defenseMaid:mark(postSimulation:connect("Defense_UpdateDefenders", updateDefenders))
	defenseMaid:mark(postSimulation:connect("Defense_UpdateMantraRequests", updateMantraRequests))
	defenseMaid:mark(postSimulation:connect("Defense_UpdateAutoAirCounter", updateAutoAirCounter))

	if clientEffectEvent then
		defenseMaid:mark(clientEffectEvent:connect("Defense_ClientEffectEvent", onClientEffectEvent))
	end

	if clientEffectLargeEvent then
		defenseMaid:mark(clientEffectLargeEvent:connect("Defense_ClientEffectEventLarge", onClientEffectEvent))
	end

	if cientEffectDirect then
		defenseMaid:mark(cientEffectDirect:connect("Defense_ClientEffectEventDirect", onClientEffectEvent))
	end

	if spellEvent then
		defenseMaid:mark(spellEvent:connect("Defense_SpellEvent", onSpellEvent))
	end
	defenseMaid:mark(characterAdded:connect("Defense_BackstabCharacterAdded", onBackstabCharacterAdded))
	defenseMaid:mark(effectAddedSignal:connect("Defense_BackstabEffectAdded", onBackstabEffectAdded))
	defenseMaid:mark(effectRemovedSignal:connect("Defense_BackstabEffectRemoved", onBackstabEffectRemoved))

	onBackstabCharacterAdded(localPlayer.Character)

	-- Initial catch-up sweep for parts/sounds/animators that already exist. This walks the ENTIRE
	-- DataModel (tens of thousands of instances, most of them BaseParts that miss every timing) and
	-- was the single biggest chunk of startup (~425ms, fully blocking). Run it in the background with
	-- a ~4ms/frame budget instead: game.DescendantAdded (connected just above) already covers anything
	-- that appears while we sweep, so nothing is missed -- pre-existing static hazards just get their
	-- defender within a few frames instead of blocking the whole load.
	defenseMaid:mark(task.spawn(function()
		local descendants = game:GetDescendants()
		local budgetStart = os.clock()

		for index = 1, #descendants do
			onGameDescendantAdded(descendants[index])

			if os.clock() - budgetStart > 0.004 then
				runService.Heartbeat:Wait()
				budgetStart = os.clock()
			end
		end
	end))

	if not LPH_OBFUSCATED or shared.Aero.verbose then
		Logger.warn("Defense initialized.")
	end
end

function Defense.detach()
	for _, object in next, defenderObjects do
		object:detach()
	end

	table.clear(defenderObjects)
	table.clear(defenderPartObjects)
	table.clear(defenderAnimationObjects)
	table.clear(deletedPlaybackData)

	defenseMaid:clean()

	Logger.warn("Defense detached.")
end

return Defense

end)
__bundle_register("Features/Combat/Objects/HitboxOptions", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class HitboxOptions
---@note: Options for the hitbox check.
---@field part BasePart? If this is specified and it exists, it will be used for the position.
---@field cframe CFrame? Else, the part's CFrame will be used.
---@field timing Timing|AnimationTiming|SoundTiming
---@field action Action?
---@field cache Vector3 Cached hitbox size.
---@field filter Instance[]
---@field spredict boolean If true, a check will run for predicted positions.
---@field ptime number? The predicted time in seconds for extrapolation.
---@field entity Model? The entity for extrapolation.
---@field phcolor Color3 The color for predicted hitboxes.
---@field pmcolor Color3 The color for predicted missed hitboxes.
---@field hcolor Color3 The color for hitboxes.
---@field mcolor Color3 The color for missed hitboxes.
---@field hmid number? Hitbox visualization ID for normal hitbox check.
---@field visualize boolean Whether to visualize the hitbox.
local HitboxOptions = {}
HitboxOptions.__index = HitboxOptions

local players = game:GetService("Players")

---@return Color3
HitboxOptions.ghcolor = LPH_NO_VIRTUALIZE(function(self, result)
	return result and self.hcolor or self.mcolor
end)

---@return Color3
HitboxOptions.gphcolor = LPH_NO_VIRTUALIZE(function(self, result)
	return result and self.phcolor or self.pmcolor
end)

---@return HitboxOptions
HitboxOptions.clone = LPH_NO_VIRTUALIZE(function(self)
	local options = setmetatable({}, HitboxOptions)
	options.action = self.action
	options.spredict = self.spredict
	options.entity = self.entity
	options.ptime = self.ptime
	options.entity = self.entity
	options.phcolor = self.phcolor
	options.pmcolor = self.pmcolor
	options.hcolor = self.hcolor
	options.mcolor = self.mcolor
	options.hmid = self.hmid
	options.filter = self.filter
	options.part = self.part
	options.cframe = self.cframe
	options.timing = self.timing
	options.visualize = self.visualize
	return options
end)

HitboxOptions.ucache = LPH_NO_VIRTUALIZE(function(self)
	if not self.timing then
		return error("HitboxOptions:update - no timing specified")
	end

	local hitbox = self.action and self.action.hitbox or self.timing.hitbox

	if self.timing.duih then
		hitbox = self.timing.hitbox
	end

	if not hitbox then
		self.cache = Vector3.new(0, 0, 0)
	else
		self.cache = Vector3.new(hitbox.X, hitbox.Y, hitbox.Z)
	end
end)

---@return Vector3
HitboxOptions.hitbox = LPH_NO_VIRTUALIZE(function(self)
	if not self.cache then
		self:ucache()
	end

	return self.cache
end)

---@return CFrame
HitboxOptions.extrapolate = LPH_NO_VIRTUALIZE(function(self)
	if not self.part then
		return error("HitboxOptions.extrapolate - unimplemented for CFrame")
	end

	if not self.ptime then
		return error("HitboxOptions.extrapolate - no predicted time specified")
	end

	return self.part.CFrame + (self.part.AssemblyLinearVelocity * self.ptime)
end)

---@return CFrame
HitboxOptions.pos = LPH_NO_VIRTUALIZE(function(self)
	if self.cframe then
		return self.cframe
	end

	if self.part then
		return self.part.CFrame
	end

	return error("HitboxOptions.pos - impossible condition")
end)

---@param target Instance|CFrame
---@param timing Timing|AnimationTiming|SoundTiming
---@param filter Instance[]?
---@return HitboxOptions
HitboxOptions.new = LPH_NO_VIRTUALIZE(function(target, timing, filter)
	local self = setmetatable({}, HitboxOptions)
	self.part = typeof(target) == "Instance" and target:IsA("BasePart") and target
	self.cframe = typeof(target) == "CFrame" and target
	self.timing = timing
	self.action = nil
	self.filter = filter or {}
	self.cache = Vector3.zero
	self.spredict = false
	self.hmid = nil
	self.entity = nil
	self.phcolor = Color3.new(1, 0, 1)
	self.pmcolor = Color3.new(0.349019, 0.345098, 0.345098)
	self.hcolor = Color3.new(0, 1, 0)
	self.mcolor = Color3.new(1, 0, 0)
	self.ptime = nil
	self.visualize = true

	if not self.part and not self.cframe or not self.timing then
		return error("HitboxOptions: No part or CFrame or timing specified.")
	end

	self:ucache()

	if filter then
		return self
	end

	local character = players.LocalPlayer.Character
	if not character then
		return self
	end

	self.filter = { character }

	return self
end)

return HitboxOptions

end)
__bundle_register("Features/Combat/Targeting", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Glorified extended non-utility Entities file.
local Targeting = {}

local DEFAULT_KEYS = {
	fov = "FOVLimit",
	distance = "DistanceLimit",
	maxTargets = "MaxTargets",
	selectionType = "PlayerSelectionType",
}

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.PlayerScanning
local PlayerScanning = require("Game/PlayerScanning")

---@module Features.Combat.Objects.Target
local Target = require("Features/Combat/Objects/Target")

---@module Utility.Table
local Table = require("Utility/Table")

local players = game:GetService("Players")
local userInputService = game:GetService("UserInputService")

---@return Target[]
Targeting.viable = LPH_NO_VIRTUALIZE(function(keys)
	keys = keys or DEFAULT_KEYS

	local live = workspace:FindFirstChild("Live")
	if not live then
		return {}
	end

	local localCharacter = players.LocalPlayer.Character
	if not localCharacter then
		return {}
	end

	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return {}
	end

	local currentCamera = workspace.CurrentCamera
	if not currentCamera then
		return {}
	end

	local targets = {}

	local fieldOfViewLimit = Configuration.expectOptionValue(keys.fov)
	local distanceLimit = Configuration.expectOptionValue(keys.distance)
	if not fieldOfViewLimit or not distanceLimit or fieldOfViewLimit <= 0 then
		return targets
	end

	local fieldOfViewCos = math.cos(math.rad(fieldOfViewLimit))

	for _, entity in next, live:GetChildren() do
		if entity == localCharacter then
			continue
		end

		local playerFromCharacter = players:GetPlayerFromCharacter(entity)
		if not playerFromCharacter and Configuration.expectToggleValue("IgnoreMobs") then
			continue
		end

		if playerFromCharacter and Configuration.expectToggleValue("IgnorePlayers") then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		if not humanoid then
			continue
		end

		local rootPart = entity:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		if humanoid.Health <= 0 then
			continue
		end

		if
			playerFromCharacter
			and PlayerScanning.isAlly(playerFromCharacter)
			and Configuration.expectToggleValue("IgnoreAllies")
		then
			continue
		end

		local fieldOfViewToEntity =
			currentCamera.CFrame.LookVector:Dot((localRootPart.Position - rootPart.Position).Unit)

		if (fieldOfViewToEntity * -1) <= fieldOfViewCos then
			continue
		end

		local currentDistance = (rootPart.Position - localRootPart.Position).Magnitude
		if currentDistance > distanceLimit then
			continue
		end

		local mousePosition = userInputService:GetMouseLocation()
		local unitRay = workspace.CurrentCamera:ScreenPointToRay(mousePosition.X, mousePosition.Y)
		local distanceToCrosshair = unitRay:Distance(rootPart.Position)

		targets[#targets + 1] =
			Target.new(entity, humanoid, rootPart, distanceToCrosshair, fieldOfViewToEntity, currentDistance)
	end

	return targets
end)

---@return Target[]
Targeting.best = LPH_NO_VIRTUALIZE(function(keys)
	keys = keys or DEFAULT_KEYS

	local targets = Targeting.viable(keys)
	local sortType = Configuration.expectOptionValue(keys.selectionType)
	local sortFunction = nil

	if sortType == "Closest To Crosshair" then
		sortFunction = function(first, second)
			return first.dc < second.dc
		end
	end

	if sortType == "Closest In Distance" then
		sortFunction = function(first, second)
			return first.du < second.du
		end
	end

	if sortType == "Least Health" then
		sortFunction = function(first, second)
			return first.humanoid.Health < second.humanoid.Health
		end
	end

	if sortFunction then
		table.sort(targets, sortFunction)
	end

	return Table.slice(targets, 1, Configuration.expectOptionValue(keys.maxTargets))
end)

---@param model Model
---@return Target?
Targeting.find = LPH_NO_VIRTUALIZE(function(model, keys)
	for _, target in next, Targeting.best(keys) do
		if target.character ~= model then
			continue
		end

		return target
	end
end)

return Targeting

end)
__bundle_register("Features/Combat/Objects/Target", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Typed object that represents a target. It's not really a true class but just needs to store the correct data.
---@class Target
---@field character Model
---@field humanoid Humanoid
---@field root BasePart
---@field dc number Distance to crosshair.
---@field fov number Field of view to target.
---@field du number Distance to us.
local Target = {}

---@param character Model
---@param humanoid Humanoid
---@param root BasePart
---@param dc number
---@param fov number
---@param du number
---@return Target
Target.new = LPH_NO_VIRTUALIZE(function(character, humanoid, root, dc, fov, du)
	local self = setmetatable({}, Target)
	self.character = character
	self.humanoid = humanoid
	self.root = root
	self.dc = dc
	self.fov = fov
	self.du = du
	return self
end)

return Target

end)
__bundle_register("Game/Latency", function(require, _LOADED, __bundle_register, __bundle_modules)
local Latency = {}

local stats = game:GetService("Stats")

---@note: Perhaps one day, we can get better approximations for these.

local smoothedRtt = nil
local EMA_ALPHA = 0.25

local OUTLIER_JUMP_MULTIPLIER = 2.0
local OUTLIER_JUMP_FLOOR = 0.05

---@note: https://devforum.roblox.com/t/in-depth-information-about-robloxs-remoteevents-instance-replication-and-physics-replication-w-sources/1847340
---@note: The forum post above is misleading, not only is it the RTT time, please note that this also takes into account all delays like frame time.
---@return number?
local function rawRtt()
	local network = stats:FindFirstChild("Network")
	if not network then
		return
	end

	local serverStatsItem = network:FindFirstChild("ServerStatsItem")
	if not serverStatsItem then
		return
	end

	local dataPingItem = serverStatsItem:FindFirstChild("Data Ping")
	if not dataPingItem then
		return
	end

	return dataPingItem:GetValue() / 1000
end

---@return number
function Latency.rdelay()
	return math.max(Latency.rtt() / 2, 0.0)
end

---@return number
function Latency.sdelay()
	return math.max(Latency.rtt() / 2, 0.0)
end

---@note: This is our round-trip time (e.g double the ping) since we have a receiving delay (replication) and a sending delay when we send the input to the server.
---@todo: For every usage, the sending delay needs to be continously updated. The receiving one must be calculated once at initial send for AP ping compensation.
---@return number?
function Latency.rtt()
	local raw = rawRtt()
	if not raw then
		return smoothedRtt
	end

	if not smoothedRtt then
		smoothedRtt = raw
		return smoothedRtt
	end

	local deviation = raw - smoothedRtt
	local maxJump = math.max(smoothedRtt * OUTLIER_JUMP_MULTIPLIER, OUTLIER_JUMP_FLOOR)

	if math.abs(deviation) > maxJump then
		deviation = maxJump * (deviation < 0 and -1 or 1)
	end

	smoothedRtt = smoothedRtt + EMA_ALPHA * deviation

	return smoothedRtt
end

return Latency
end)
__bundle_register("Features/Combat/EntityHistory", function(require, _LOADED, __bundle_register, __bundle_modules)
local EntityHistory = {}

local histories = setmetatable({}, { __mode = "k" })

local MAX_HISTORY_SECS = 3.0

---@param idx any
---@param position CFrame
---@param velocity Vector3
---@param timestamp number
EntityHistory.add = LPH_NO_VIRTUALIZE(function(idx, position, velocity, timestamp)
	local history = histories[idx] or {}

	if not histories[idx] then
		histories[idx] = history
	end

	history[#history + 1] = {
		position = position,
		timestamp = timestamp,
		velocity = velocity,
	}

	while true do
		local tail = history[1]
		if not tail then
			break
		end

		if tick() - tail.timestamp <= MAX_HISTORY_SECS then
			break
		end

		table.remove(history, 1)
	end
end)

---@param index any
---@param time number
---@return Vector3[]?
EntityHistory.vall = LPH_NO_VIRTUALIZE(function(index, time)
	local history = histories[index]
	if not history then
		return nil
	end

	local out = {}

	for _, data in next, history do
		if tick() - data.timestamp > time then
			continue
		end

		out[#out + 1] = data.velocity
	end

	return out
end)

---@param index any
---@return number?
EntityHistory.yrate = LPH_NO_VIRTUALIZE(function(index)
	local history = histories[index]
	if not history or #history < 2 then
		return nil
	end

	local latest = history[#history]
	local previous = history[#history - 1]
	local dt = latest.timestamp - previous.timestamp
	if dt <= 1e-4 then
		return nil
	end

	local prevLook = Vector3.new(previous.position.LookVector.X, 0, previous.position.LookVector.Z).Unit
	local latestLook = Vector3.new(latest.position.LookVector.X, 0, latest.position.LookVector.Z).Unit
	local dot = prevLook:Dot(latestLook)
	local crossY = prevLook:Cross(latestLook).Y
	local angle = math.atan2(crossY, dot)
	return angle / dt
end)

---@param idx any
---@param steps number
---@param phds number History second limit for past hitbox detection.
---@return CFrame[]?
EntityHistory.pstepped = LPH_NO_VIRTUALIZE(function(idx, steps, phds)
	local history = histories[idx]
	if not history or #history == 0 then
		return nil
	end

	if not steps or steps <= 0 then
		return nil
	end

	local vhistory = {}
	local vhtime = history[#history].timestamp

	for _, data in next, history do
		if vhtime - data.timestamp > phds then
			continue
		end

		vhistory[#vhistory + 1] = data.position
	end

	if #vhistory == 0 then
		return {}
	end

	local count = math.min(steps, #vhistory)
	local out = table.create(count)

	for cidx = 1, count do
		out[cidx] = vhistory[math.max(math.floor((cidx * #vhistory) / count), 1)]
	end

	return out
end)

---@param idx any
---@param timestamp number
---@return CFrame?
EntityHistory.pclosest = LPH_NO_VIRTUALIZE(function(idx, timestamp)
	if not histories[idx] then
		return nil
	end

	local closestDelta = nil
	local closestPosition = nil

	for _, data in next, histories[idx] do
		local delta = math.abs(timestamp - data.timestamp)

		if closestDelta and delta >= closestDelta then
			continue
		end

		closestPosition = data.position
		closestDelta = delta
	end

	return closestPosition
end)

return EntityHistory

end)
__bundle_register("Game/EffectDispatcher", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Unified EffectReplicator handler -- the whole script's SINGLE connection to the game's EffectReplicator,
---@note: mirroring Project Rain's EffectReplicatorHandler. Consumers register "added"/"removed" hooks via
---@note: EffectDispatcher.hook(...) instead of each opening its own EffectAdded connection.
---@note:
---@note: Added hooks run INLINE (plain xpcall) -- no task.spawn, no task.defer, no setthreadidentity. Both
---@note: scheduler primitives were tried here and both crashed: spawning/deferring a thread from inside the
---@note: deferred-lane scheduler step the game fires EffectAdded from can enter a second guarded job under
---@note: Roblox's 0.742+ STM scheduler and trip its per-thread re-entrancy guard ("RSL - panic ...Kernel,2090").
---@note: Running inline touches the scheduler not at all. Removed hooks already run inline. The whole connection
---@note: is rebuilt when the server clears/rebuilds its effect container
---@note: (Requests.EffectReplication._update "clear"/"updatecontainer"), so nothing ever rides a stale container.

local EffectDispatcher = {}

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")

local hooks = {}
local reconnectCallbacks = {}
local pendingReactions = {} -- reactions handed over by hook bodies via EffectDispatcher.defer, drained on Heartbeat
local effectMaid = Maid.new() -- EffectAdded/EffectRemoved connections -- torn down and rebuilt on reconnect
local lifecycleMaid = Maid.new() -- the _update reconnect listener -- set up once
local reactionPumpConnection = nil -- Heartbeat drain for pendingReactions -- set up once in init
local connected = false

---@param err string
local function onHookError(err)
	Logger.trace("EffectDispatcher_HookError - %s", err)
end

-- Reaction offloading. Added/removed hooks run INLINE on the game's deferred-lane EffectAdded/EffectRemoved
-- dispatch thread (see header note). A hook body must therefore do ONLY cheap, scheduler-free work on that
-- callstack -- any remote fire, task.wait or follow-up spawn done there can nest a second guarded STM job and trip
-- Roblox 0.742+'s per-thread re-entrancy guard (RSL panic Kernel,2090). When a hook needs to DO such a thing it
-- hands a closure to EffectDispatcher.defer, which only appends to a table (zero scheduler touch); the Heartbeat
-- pump below runs it on its OWN top-level scheduler step -- a fresh scheduler entry, never nested inside the
-- dispatch -- where firing/yielding is safe (the same place Hooking.maintainNoFall already fires remotes). Each
-- reaction runs on its own task.spawn'd thread so one that yields (e.g. a wait-loop) can't block the others;
-- task.spawn is safe HERE precisely because this is NOT a hook callstack -- it is the Heartbeat job itself.
---@param fn fun()
function EffectDispatcher.defer(fn)
	pendingReactions[#pendingReactions + 1] = fn
end

local function drainReactions()
	if #pendingReactions == 0 then
		return
	end
	local batch = pendingReactions
	pendingReactions = {}
	for _, fn in next, batch do
		task.spawn(pcall, fn)
	end
end

-- Disconnect helper for both real RBXScriptConnections and Deepwoken's custom EffectReplicator signal connections
-- (EffectAdded/EffectRemoved are NOT RBXScriptSignals -- their connections are tables/functions Maid won't clean on
-- its own). Wrapping it in a cleanup function makes a reconnect actually drop the old handler, no duplicates.
local function markConnection(maid, connection)
	maid:mark(function()
		pcall(function()
			if type(connection) == "function" then
				connection()
			elseif typeof(connection) == "RBXScriptConnection" then
				connection:Disconnect()
			elseif type(connection) == "table" then
				local disconnect = connection.Disconnect or connection.disconnect or connection.Destroy
				if disconnect then
					disconnect(connection)
				end
			end
		end)
	end)

	return connection
end

---Register an effect hook.
---@param hookType string "added" | "removed"
---@param callback fun(effect: table)
---@return table hook  -- call hook:remove() to unregister
function EffectDispatcher.hook(hookType, callback)
	local hook = { type = hookType, call = callback }

	function hook:remove()
		local at = table.find(hooks, self)
		if at then
			table.remove(hooks, at)
		end
	end

	table.insert(hooks, hook)
	return hook
end

---Run callback (serial, pcall-guarded) on every (re)connect, before existing effects are replayed. Used for
---state that must be wiped when the server rebuilds its container (e.g. EffectTimers.clear).
---@param callback fun()
function EffectDispatcher.onReconnect(callback)
	table.insert(reconnectCallbacks, callback)
end

---@return table effectReplicatorModule
function EffectDispatcher.module()
	return require(replicatedStorage:WaitForChild("EffectReplicator"))
end

---@param effect table
local function dispatchAdded(effect)
	-- Run each added hook INLINE -- no task.spawn, no task.defer, no setthreadidentity. Both scheduler primitives
	-- (spawn AND defer) have been tried here and BOTH crashed: they register/resume a thread with the task
	-- scheduler, and doing that from inside the deferred-lane scheduler step the game fires EffectAdded from is a
	-- candidate for entering a second guarded STM job (Roblox 0.742+ per-thread re-entrancy guard -> RSL panic
	-- Kernel,2090). So we don't touch the scheduler at all: a plain xpcall runs hook.call directly on the thread
	-- the game's own Signal already handed us, with per-hook error isolation but zero new threads. hook.call
	-- (EffectTimers.track + StateListener.onEffectReplicated) never yields on the always-on path -- its reactive
	-- branches defer their own work -- so running inline cannot stall the dispatch.
	for _, hook in next, hooks do
		if hook.type == "added" and hook.call then
			xpcall(hook.call, onHookError, effect)
		end
	end
end

---@param effect table
local function dispatchRemoved(effect)
	for _, hook in next, hooks do
		if hook.type == "removed" and hook.call then
			xpcall(hook.call, onHookError, effect)
		end
	end
end

local function connect()
	effectMaid:clean()

	for _, callback in next, reconnectCallbacks do
		pcall(callback)
	end

	local effectReplicatorModule = EffectDispatcher.module()

	markConnection(effectMaid, effectReplicatorModule.EffectAdded:Connect(dispatchAdded))
	markConnection(effectMaid, effectReplicatorModule.EffectRemoved:Connect(dispatchRemoved))

	-- No replay of already-active effects. Project Rain's EffectReplicatorHandler only wires EffectAdded/
	-- EffectRemoved and never re-dispatches EffectReplicator.Effects on (re)connect -- it takes the inject-time
	-- gap instead of running a synchronous burst of every added hook over every live effect inside connect()
	-- (which, on an _update "clear"/"updatecontainer", fires inline within that OnClientEvent callback). Match it.
end

---Connect (replaying current effects to all registered hooks) and wire the container-rebuild reconnect. Call
---ONCE, after every always-on consumer has registered its hooks.
function EffectDispatcher.init()
	connect()

	if connected then
		return
	end
	connected = true

	if not reactionPumpConnection then
		reactionPumpConnection = runService.Heartbeat:Connect(drainReactions)
	end

	task.spawn(pcall, function()
		local update = replicatedStorage
			:WaitForChild("Requests")
			:WaitForChild("EffectReplication")
			:WaitForChild("_update")

		lifecycleMaid:mark(update.OnClientEvent:Connect(function(payload)
			if type(payload) == "table" and (payload.updateType == "clear" or payload.updateType == "updatecontainer") then
				connect()
			end
		end))
	end)
end

function EffectDispatcher.detach()
	effectMaid:clean()
	lifecycleMaid:clean()
	if reactionPumpConnection then
		pcall(function()
			reactionPumpConnection:Disconnect()
		end)
		reactionPumpConnection = nil
	end
	table.clear(hooks)
	table.clear(reconnectCallbacks)
	table.clear(pendingReactions)
	connected = false
end

return EffectDispatcher

end)
__bundle_register("Features/Combat/StateListener", function(require, _LOADED, __bundle_register, __bundle_modules)
local StateListener = {
	lMantraActivated = nil,
	lAnimTiming = nil,
	lAnimFaction = nil,
	lAnimTimestamp = nil,
	chainStacks = nil,
	lastVent = nil,
	lastPaybackDelay = 0,
	lAnimLatency = nil,

	lADAction = nil,
	lADAnimation = nil,

	lRecentAnims = {},
}

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Game.Timings.ModuleManager
local ModuleManager = require("Game/Timings/ModuleManager")

---@module Game.Latency
local Latency = require("Game/Latency")

---@module Game.EffectTimers
local EffectTimers = require("Game/EffectTimers")

---@module Game.EffectDispatcher
local EffectDispatcher = require("Game/EffectDispatcher")

---@module Utility.Table
local Table = require("Utility/Table")

local stateMaid = Maid.new()

-- Per-effect timestamps for withinTime(). Deepwoken's effect objects are owned by the game (effect.index lives
-- in the game's VM, likely an Actor), so writing a field back into effect.index from our thread is an illegal
-- cross-boundary write and the Luau kernel aborts with "RSL - panic ...Kernel,2090" (AFK: mobs spew LightAttack/
-- Stun nonstop at random timing; threads+mem stay flat so it isn't a leak). EffectTimers already demonstrates the
-- safe shape -- it listens to the same EffectAdded signal INLINE and only READS effect fields into a weak Lua
-- table -- so we keep our stamps the same way and never write into the effect object. Weak keys => entries drop
-- when the effect is GC'd, no manual cleanup, no leak.
local stamps = setmetatable({}, { __mode = "k" })

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local userInputService = game:GetService("UserInputService")

local CHIME_ARENA_PLACE_ID = 6832944305

local ATTACK_EFFECT_CLASSES = {
	"LightAttack",
	"HeavyAttack",
	"OffhandAttack",
	"UsingAbility",
	"CastingSpell",
}

---@param track AnimationTrack
---@param timing AnimationTiming
local handleModuleData = LPH_NO_VIRTUALIZE(function(track, timing)
	if timing.tag ~= "M1" then
		return
	end

	if typeof(ModuleManager) ~= "table" or typeof(ModuleManager.get) ~= "function" then
		return
	end

	local lf = ModuleManager.get(timing.smod)
	if not lf then
		return
	end

	local extracted = {}
	local fake = {
		tmaid = Maid.new(),
		track = track,
		entity = players.LocalPlayer.Character,
		action = function(_, _, action)
			table.insert(extracted, action)
		end,
	}

	lf(fake, timing)

	fake.tmaid:clean()

	StateListener.lAnimFaction = extracted[1]
end)

---@param track AnimationTrack
local onLocalAnimationPlayed = LPH_NO_VIRTUALIZE(function(track)
	local aid = tostring(track.Animation.AnimationId)

	StateListener.lRecentAnims[aid] = os.clock()

	local data = SaveManager.as:index(aid)
	if not data then
		return
	end

	StateListener.lAnimTimestamp = os.clock()
	StateListener.lAnimationValidTrack = track
	StateListener.lAnimTiming = data
	StateListener.lAnimLatency = Latency.rtt()

	if data.umoa then
		return handleModuleData(track, data)
	end

	StateListener.lAnimFaction = data.actions:stack()[1]
end)

---@param effect table
---@param time number? If the number is unspecified, it will use the Debris time.
---@param offset boolean If the number is specified, should we use it as an offset from the Debris time?
---@return boolean
local withinTime = LPH_NO_VIRTUALIZE(function(effect, time, offset)
	local timestamp = stamps[effect]
	if not timestamp then
		return false
	end

	if not effect.index then
		return false
	end

	local dtime = effect.index.DebrisTime
	if not dtime then
		return false
	end

	if offset and time then
		return os.clock() - timestamp <= (dtime + time)
	end

	return os.clock() - timestamp <= (time or dtime)
end)

---@return boolean
local function getKeyCode(name)
	return Enum.KeyCode[name]
end

StateListener.hblock = LPH_NO_VIRTUALIZE(function()
	local keybinds = replicatedStorage:FindFirstChild("KeyBinds")
	if not keybinds then
		return false
	end

	local keybindsModule = require(keybinds)
	if not keybindsModule or not keybindsModule.Current then
		return false
	end

	local bindings = keybindsModule:GetBindings() or {}

	for _, keybind in next, bindings["Block"] do
		local success, keyCode = pcall(getKeyCode, tostring(keybind))

		if not success or not keyCode then
			continue
		end

		if not userInputService:IsKeyDown(keyCode) then
			continue
		end

		return true
	end

	return false
end)

---@return boolean
StateListener.csb = LPH_NO_VIRTUALIZE(function()
	if not StateListener.lMantraActivated then
		return false
	end

	local name = tostring(StateListener.lMantraActivated)
	if not name or not name:match("Sightless Beam") then
		return false
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not character then
		return false
	end

	local hrp = character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return false
	end

	if hrp:FindFirstChild("REP_SOUND_376107250") then
		return true
	end

	for _, child in next, hrp:GetChildren() do
		if not child:IsA("Sound") then
			continue
		end

		if child.Name ~= "Telekin" then
			continue
		end

		if not child.IsPlaying then
			continue
		end

		return true
	end

	return false
end)

---@return boolean
StateListener.astun = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local lightAttackEffect = effectReplicatorModule:FindEffect("LightAttack")
	local usingCriticalEffect = effectReplicatorModule:FindEffect("UsingCritical")
	local usingSpellEffect = effectReplicatorModule:FindEffect("UsingSpell")

	if lightAttackEffect and withinTime(lightAttackEffect, 0.5, false) then
		return true
	end

	if usingCriticalEffect and withinTime(usingCriticalEffect, -0.1, true) then
		return true
	end

	if usingSpellEffect then
		return true
	end

	return false
end)

---@return boolean
StateListener.cvent = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local ventCooldownEffect = effectReplicatorModule:FindEffect("NoBurst")

	if Configuration.expectToggleValue("BlockVentState") then
		return false
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not character then
		return false
	end

	if StateListener.lastVent and (os.clock() - StateListener.lastVent) <= 8.0 then
		return false
	end

	local tempo = character:FindFirstChild("Tempo")
	if not tempo then
		return false
	end

	if tempo.Value < 40 then
		return false
	end

	if not effectReplicatorModule:FindEffect("Equipped") then
		return false
	end

	if ventCooldownEffect then
		return false
	end

	return true
end)

---@return boolean
StateListener.cparry = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local parryCooldownEffect = effectReplicatorModule:FindEffect("ParryCool")

	if Configuration.expectToggleValue("EffectLogging") then
		local classes = {}
		for _, effect in next, effectReplicatorModule:GetEffects() do
			table.insert(classes, string.format("%s(%s)", tostring(effect.Class), tostring(effect.Value)))
		end
		table.sort(classes)
		Logger.warn("[cparry] active effects: %s", table.concat(classes, ", "))
	end

	if Configuration.expectToggleValue("BlockParryState") then
		return false
	end

	if not effectReplicatorModule:FindEffect("Equipped") then
		return false
	end

	if parryCooldownEffect then
		local remaining = EffectTimers.remaining(parryCooldownEffect)

		if Configuration.expectToggleValue("EffectLogging") then
			Logger.warn(
				"[ParryCool] DebrisTime=%s remaining=%s rdelay=%.3f sdelay=%.3f",
				tostring(parryCooldownEffect.DebrisTime),
				tostring(remaining),
				Latency.rdelay() or -1,
				Latency.sdelay() or -1
			)
		end

		if not remaining then
			return false
		end

		if remaining > (Latency.rdelay() or 0) + Latency.sdelay() then
			return false
		end
	end

	return true
end)

---@return boolean
StateListener.cfeint = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local feintCooldownEffect = effectReplicatorModule:FindEffect("FeintCool")

	if feintCooldownEffect then
		return false
	end

	return true
end)

---@return boolean
StateListener.cblock = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not character then
		return false
	end

	if Configuration.expectToggleValue("NoBlockingState") then
		return false
	end

	local breakMeter = character:FindFirstChild("BreakMeter")
	if not breakMeter then
		return false
	end

	if breakMeter.Value / breakMeter.MaxValue > 0.6 then
		return false
	end

	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)

	if effectReplicatorModule:FindEffect("ShakyBlock") then
		return false
	end

	if effectReplicatorModule:FindEffect("CancelBlock") then
		return false
	end

	return true
end)

---@return boolean
StateListener.cdodge = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local dodgeCooldownEffect = effectReplicatorModule:FindEffect("NoRoll")
	local stunCooldownEffect = effectReplicatorModule:FindEffect("Stun")

	if Configuration.expectToggleValue("BlockDodgeState") then
		return false
	end

	if dodgeCooldownEffect then
		return false
	end

	if stunCooldownEffect and withinTime(stunCooldownEffect, nil, false) then
		return false
	end

	return true
end)

---@param aid string Animation ID (e.g. "rbxassetid://...").
---@param window number? Seconds. Defaults to 4.
---@return boolean
StateListener.recentlyCast = LPH_NO_VIRTUALIZE(function(aid, window)
	if not aid or #aid <= 0 then
		return false
	end

	local timestamp = StateListener.lRecentAnims[aid]
	if not timestamp then
		return false
	end

	return os.clock() - timestamp <= (window or 4.0)
end)

---@return boolean
StateListener.ccd = LPH_NO_VIRTUALIZE(function()
	return game.PlaceId == CHIME_ARENA_PLACE_ID and workspace.DistributedGameTime < 15
end)

---@param effect table
local onEffectReplicated = LPH_NO_VIRTUALIZE(function(effect)
	if Configuration.expectToggleValue("NoAttackingClientChecks") and table.find(ATTACK_EFFECT_CLASSES, effect.Class) then
		-- Off the dispatch callstack: EffectDispatcher.defer appends to a table here (no scheduler touch) and runs
		-- the removal on the Heartbeat pump, so effect:Remove never fires from inside the EffectAdded dispatch.
		EffectDispatcher.defer(function()
			effect:Remove(true)
		end)
	end

	if effect.Class == "Knocked" or effect.Class == "Ragdoll" then
		if Configuration.expectToggleValue("AutoRagdollRecover") then
			-- feint fires remotes -- run it on the Heartbeat pump, not synchronously on the dispatch callstack.
			EffectDispatcher.defer(InputClient.feint)
		end
	end

	if effect.Class == "MantraCasted" then
		-- Was TaskSpawner.spawn (= task.spawn) fired straight from the dispatch callstack on EVERY MantraCasted
		-- effect, toggle-checked only inside the thread -- an unconditional scheduler touch on the always-on effect
		-- path. Now we only enqueue (a table insert); the Heartbeat pump runs this body on its own thread.
		EffectDispatcher.defer(function()
			---@module Game.QueuedBlocking
			local QueuedBlocking = require("Game/QueuedBlocking")

			if not Configuration.expectToggleValue("AutoMantraFollowup") then
				return
			end

			local track = StateListener.lAnimationValidTrack
			if not track or not track.IsPlaying then
				return
			end

			local instance = StateListener.lMantraActivated
			if not instance then
				return
			end

			local faction = StateListener.lAnimFaction
			if not faction then
				return
			end

			if not instance.ToolTip:match("Press @Block@") then
				return
			end

			local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
			local effectReplicatorModule = require(effectReplicator)

			if
				Configuration.expectToggleValue("CheckIfMoveHit")
				and not effectReplicatorModule:FindEffect("DamagedAnother")
			then
				return
			end

			QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "AutoMantraFollowup", nil)

			repeat
				task.wait()
			until os.clock() - StateListener.lAnimTimestamp >= (faction:when() + 0.100) - Latency.rtt()

			QueuedBlocking.stop("AutoMantraFollowup")
		end)
	end

	if effect.Class == "LightAttack" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "Stun" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "DodgeCool" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "ParryCool" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "Vented" then
		StateListener.lastVent = os.clock()
	end

	if effect.Class == "DelayedPayback" then
		StateListener.lastPaybackDelay = tick()
	end

	if effect.Class == "PerfectStack" then
		StateListener.chainStacks = 0
	end

	if effect.Class == "PerfectionCool" and StateListener.chainStacks then
		StateListener.chainStacks = math.min(StateListener.chainStacks + 1, 20)
	end
end)

---@param effect table
local onEffectRemoving = LPH_NO_VIRTUALIZE(function(effect)
	if effect.Class == "PerfectStack" then
		StateListener.chainStacks = nil
	end
end)

-- Disconnect helper that works for both real RBXScriptConnections and Deepwoken's custom signal connections.
-- EffectReplicator.EffectAdded/EffectRemoved are NOT RBXScriptSignals, so their connections are plain tables with
-- a :Disconnect (or :disconnect/:Destroy) method that Maid won't recognise on its own -- wrap them in a cleanup
-- function (which Maid does call) so a reconnect actually drops the old handlers instead of stacking duplicates.
local function markConnection(maid, connection)
	maid:mark(function()
		pcall(function()
			if type(connection) == "function" then
				connection()
			elseif typeof(connection) == "RBXScriptConnection" then
				connection:Disconnect()
			elseif type(connection) == "table" then
				local disconnect = connection.Disconnect or connection.disconnect or connection.Destroy
				if disconnect then
					disconnect(connection)
				end
			end
		end)
	end)

	return connection
end

function StateListener.init()
	-- Effects are handled through the shared EffectDispatcher: one EffectReplicator connection for the whole
	-- script (PR-style -- deferred + identity-8 added dispatch, inline removed, rebuilt on container clear/
	-- updatecontainer). We register our hooks here; EffectDispatcher.init() (called once from Aero.init after
	-- every always-on consumer has registered) does the connect + replay. EffectTimers tracking rides these hooks.
	EffectDispatcher.onReconnect(EffectTimers.clear)

	EffectDispatcher.hook("added", function(effect)
		EffectTimers.track(effect)
		onEffectReplicated(effect)
	end)

	EffectDispatcher.hook("removed", function(effect)
		EffectTimers.untrack(effect)
		onEffectRemoving(effect)
	end)

	-- Local-character animator listening. We only ever want the LOCAL player's OWN Animator -- it drives the
	-- AnimationPlayed timings this module reads -- and it appears once per respawn. This used to watch
	-- workspace.Live.DescendantAdded: a server-wide, recursive firehose (every nested part/bone/particle/sound of
	-- every entity in the server -- hundreds-to-thousands per second in a populated place), with a per-event
	-- IsA("Animator") routed back through our own game.__namecall hook and a setthreadidentity(8)+task.spawn per
	-- Animator. That is pure waste (we discard every descendant that isn't the local Animator) and the single
	-- biggest always-on aero-only engine interaction -- Project Rain runs nothing like it. Scope it to the local
	-- character instead, Project-Rain-style: find its Animator directly and rebind on every respawn, with the only
	-- fallback watch bounded to the local character's own descendants (tiny volume, self-terminating).
	local function bindLocalAnimator(character)
		if not character then
			return
		end

		local function tryBind()
			local animator = character:FindFirstChildWhichIsA("Animator", true)
			if not animator then
				return false
			end

			local animationPlayed = Signal.new(animator.AnimationPlayed)
			stateMaid["LocalPlayerAnimListener"] =
				animationPlayed:connect("StateListener_AnimationPlayed", onLocalAnimationPlayed)

			return true
		end

		if tryBind() then
			return
		end

		-- Animator not parented yet. Watch ONLY this character's own descendants (not the whole Live folder) until
		-- it appears, bind once, then drop the watch. Still inline -- no setthreadidentity, no task.spawn.
		local watch
		watch = character.DescendantAdded:Connect(function(descendant)
			if not descendant:IsA("Animator") then
				return
			end

			if tryBind() then
				pcall(function()
					watch:Disconnect()
				end)
			end
		end)

		stateMaid["LocalAnimatorWatch"] = function()
			pcall(function()
				watch:Disconnect()
			end)
		end
	end

	local localPlayer = players.LocalPlayer
	if localPlayer then
		bindLocalAnimator(localPlayer.Character)
		markConnection(stateMaid, localPlayer.CharacterAdded:Connect(bindLocalAnimator))
	end

	if not LPH_OBFUSCATED or shared.Aero.verbose then
		Logger.warn("StateListener initialized.")
	end
end

function StateListener.detach()
	stateMaid:clean()
	EffectTimers.detach()
end

return StateListener

end)
__bundle_register("Game/QueuedBlocking", function(require, _LOADED, __bundle_register, __bundle_modules)
-- QueuedBlocking module. Allows of easy control of blocking without failure (e.g constant blocking randomly or w/e) and being frame-perfect.
local QueuedBlocking = {
	BLOCK_TYPE_DEFLECT = 1, -- For parry/deflect frames. This means it will get removed as soon as we are considered as blocking.
	BLOCK_TYPE_NORMAL = 2, -- For normal blocking. This means it will stay in the queue until dead time expires or manually removed.
}

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

-- Maids.
local qiMaid = Maid.new()

-- Queue.
local blockQueue = {}

-- Call with direct functions so our hooks call...
local fireServer = Instance.new("RemoteEvent").FireServer

---Random unblock hold time.
---@return number
local function unblockHoldTime()
	return Random.new():NextNumber(0.075, 0.115)
end

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")

-- Cached references.
local cachedStateListener = nil

---Get cached StateListener module.
local function getStateListener()
	if cachedStateListener then
		return cachedStateListener
	end

	local success, result = pcall(require, "Features/Combat/StateListener")
	if success and result then
		cachedStateListener = result
	end

	return cachedStateListener
end

---On render stepped.
local onRenderStepped = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local blockRemote = KeyHandling.getRemote("Block")
	if not blockRemote then
		return
	end

	local unblockRemote = KeyHandling.getRemote("Unblock")
	if not unblockRemote then
		return
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		return
	end

	local stateListener = getStateListener()
	if stateListener and stateListener.hblock() then
		return QueuedBlocking.empty()
	end

	-- Are we blocking?
	local blocking = effectReplicatorModule:HasEffect("Blocking")

	-- Set up input data.
	inputData["f"] = true

	-- Process entries that need to be killed.
	for id, data in next, blockQueue do
		local dead = data.dt and os.clock() - data.start >= data.dt
		local deflected = data.type == QueuedBlocking.BLOCK_TYPE_DEFLECT and blocking

		if not deflected and not dead then
			continue
		end

		QueuedBlocking.stop(id)
	end

	-- Calculate if we have something in the queue.
	local blockQueueLength = 0

	for _, _ in next, blockQueue do
		blockQueueLength = blockQueueLength + 1
	end

	-- Handle blocking input.
	inputData["f"] = blockQueueLength > 0

	if blocking then
		return blockQueueLength <= 0 and fireServer(unblockRemote)
	end

	if not effectReplicatorModule:FindEffect("Action") and not effectReplicatorModule:FindEffect("Knocked") then
		return blockQueueLength > 0 and fireServer(blockRemote)
	end
end)

---Invoke a block action.
---@param type number The block type.
---@param id string Identifier tied to this action.
---@param dt number?
function QueuedBlocking.invoke(type, id, dt)
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local blockRemote = KeyHandling.getRemote("Block")
	if not blockRemote then
		return Logger.warn("QueuedBlocking.invoke(...) - Missing block remote.")
	end

	local sprintFunction = InputClient.sprintFunctionCache
	local inputData = InputClient.getInputData()

	if not sprintFunction or not inputData then
		return Logger.warn(
			"QueuedBlocking.invoke(...) - (%s, %s) - Missing important data.",
			tostring(sprintFunction),
			tostring(inputData)
		)
	end

	local bufferEffect = effectReplicatorModule:FindEffect("M1Buffering")

	if bufferEffect then
		bufferEffect:Remove()
	end

	if effectReplicatorModule:HasEffect("CastingSpell") then
		return
	end

	blockRemote:FireServer()

	inputData["f"] = true

	sprintFunction(false)

	Logger.warn(
		"QueuedBlocking.invoke(...) - (at %.3f) Invoking block action '%s' of type %d with dead time (%s) to queue.",
		os.clock(),
		tostring(id),
		type,
		tostring(dt)
	)

	local effectiveDt = dt and (dt + unblockHoldTime()) or nil

	Logger.warn("QueuedBlocking.invoke(...) - '%s' effective dead time: %s (requested: %s)", tostring(id), tostring(effectiveDt), tostring(dt))

	blockQueue[id] = {
		start = os.clock(),
		type = type,
		dt = effectiveDt,
	}
end

---Empty the block queue.
function QueuedBlocking.empty()
	blockQueue = {}
end

---Stop a block action from the queue.
---@param id string The block action ID.
function QueuedBlocking.stop(id)
	if not blockQueue[id] then
		return
	end

	-- Log.
	Logger.warn("QueuedBlocking.stop(...) - Stopping block action '%s' in queue.", tostring(id))

	-- Remove.
	blockQueue[id] = nil
end

---Initialize QueuedBlocking module.
function QueuedBlocking.init()
	local renderStepped = Signal.new(runService.RenderStepped)
	qiMaid:mark(renderStepped:connect("QueuedInputs_Update", onRenderStepped))
end

---Detach QueuedBlocking module.
function QueuedBlocking.detach()
	qiMaid:clean()
end

-- Return QueuedBlocking module.
return QueuedBlocking
end)
__bundle_register("Game/EffectTimers", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Answers "what is the server's effect state right now" locally, by mirroring the server's effect
---@note: timestamps into a weak Lua table. Tracking is DRIVEN by StateListener's Project-Rain-style
---@note: EffectReplicator connection (setthreadidentity(8) + task.spawn + reconnect on container rebuild);
---@note: this module no longer connects to EffectAdded/EffectRemoved itself, so the whole script keeps exactly
---@note: one effect connection. StateListener calls track/untrack/clear; everything else just reads `tracked`.

---@module Game.Latency
local Latency = require("Game/Latency")

local EffectTimers = {}

local tracked = setmetatable({}, { __mode = "k" })

---@param effect table
function EffectTimers.track(effect)
	if not effect then
		return
	end

	tracked[effect] = { at = os.clock(), debris = effect.DebrisTime }
end

---@param effect table
function EffectTimers.untrack(effect)
	if not effect then
		return
	end

	tracked[effect] = nil
end

---Drop every tracked effect (used when the server clears/rebuilds its effect container).
function EffectTimers.clear()
	table.clear(tracked)
end

---@param effect table
---@return number
function EffectTimers.elapsed(effect)
	if not effect then
		return 0
	end

	local info = tracked[effect]
	if not info then
		return 0
	end

	return (os.clock() - info.at) + (Latency.rdelay() or 0)
end

---@param effect table
---@return number?
function EffectTimers.remaining(effect)
	if not effect then
		return nil
	end

	local info = tracked[effect]
	if not info or not info.debris then
		return nil
	end

	return math.max(0, info.debris - (os.clock() - info.at))
end

---@param effectReplicatorModule table
---@param class string
---@return number? elapsed
---@return number? remaining
function EffectTimers.forClass(effectReplicatorModule, class)
	local effect = effectReplicatorModule:FindEffect(class)
	if not effect then
		return nil, nil
	end

	return EffectTimers.elapsed(effect), EffectTimers.remaining(effect)
end

function EffectTimers.detach()
	table.clear(tracked)
end

return EffectTimers

end)
__bundle_register("Game/Timings/ModuleManager", function(require, _LOADED, __bundle_register, __bundle_modules)
local INTERNAL_MODULES = {
    ["AirForce"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:BlastWind{{Air Force}}")
        	local range = data.perfect * 8 + data.crystal * 6
        	local size = data.stratus * 1.5 + data.cloud * 1

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.hitbox = Vector3.new(20 + size, 20 + size, 50 + range)
        	action.name = "Dynamic Air Force Timing"

        	timing.ffh = true

        	self:action(timing, action)
        end
    end,
    ["AraneaCrit"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate.Name == "AraneaProjectile_" .. self.entity.Name
        	end)

        	task.wait(0.05 - Latency.rtt())

        	if self:distance(self.entity) <= 25 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 500
        		action.name = "Arrow Close Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.name = "Arrow Part"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.name = "ArrowProjectile"
        	pt.hitbox = Vector3.new(10, 10, 10)
        	pt.actions:push(action)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
