        	end)

        	task.wait(math.max(0, 0.5 - Latency.rtt()))

        	if self:distance(self.entity) <= 20 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 100
        		action.name = "Arc Beam Close Timing"
        		action.ihbc = true
        		action.fhb = true
        		return self:action(timing, action)
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
