        	local action = Action.new()
        	action._when = 0
        	action._type = "Dodge"
        	action.name = "Putrid Edenstaff Part"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = true
        	pt.name = "PutridEdenstaffProjectile"
        	pt.hitbox = Vector3.new(20, 20, 32)
