    ["IceCarve"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---@class Signal
        local Signal = getfenv().Signal

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
            local mantra = Mantra.data(self.entity, "Mantra:CarveIce{{Ice Carve}}")

            if mantra and mantra.spring then
                local distance = self:distance(self.entity)

                timing.iae = true
                timing.mat = 1000
                timing.hitbox = Vector3.new(40, 32, 50)

                local action = Action.new()
                action._when = math.min(600 + distance * 10, 1000)
                action._type = "Dodge"
                action.name = string.format("(%.2f) Ice Carve Spring Spark", distance)
                self:action(timing, action)

                return self:action(timing, action)
            end

            timing.ffh = true
            timing.pfh = true
            timing.fhb = true
            timing.rpue = false
            timing.duih = true
            timing.hitbox = Vector3.new(32, 32, 50)

            local action = Action.new()
            action._when = 300
            action._type = "Start Block"
            action.name = "Ice Carve Start"
            self:action(timing, action)

            local hrp = self.entity:FindFirstChild("HumanoidRootPart")
            local humanoid = self.entity:FindFirstChildOfClass("Humanoid")
            if not hrp or not humanoid then return end

            repeat task.wait() until not self.track.IsPlaying

            local activeAnim = nil
            for _, animTrack in next, humanoid:GetPlayingAnimationTracks() do
                if animTrack.Animation.AnimationId ~= "rbxassetid://15714151635" then
                    continue
                end
                activeAnim = animTrack
                break
            end

            if activeAnim then
                repeat task.wait() until not activeAnim.IsPlaying
                task.wait(0.6)
            end

            local actionEnd = Action.new()
            actionEnd._when = 0
            actionEnd._type = "End Block"
            actionEnd.ihbc = true
            actionEnd.name = "Ice Carve End"
            self:action(timing, actionEnd)
        end
    end,
    ["IceDaggers"] = function()
        local Players = game:GetService("Players")
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@type Signal
        local Signal = getfenv().Signal

        ---@module Utility.TaskSpawner
        local TaskSpawner = getfenv().TaskSpawner

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Combined module for IceDaggers & FleetingSparks
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	timing.forced = true

        	-- Track either IceDagger or FleetingSparks
        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate and candidate.Name and (candidate.Name == "IceDagger" or candidate.Name == "LightningMote")
        	end)

        	task.wait(0.5 - Latency.rtt())

        	local hrp = self.entity:FindFirstChild("HumanoidRootPart")
        	if not hrp then
        		return
        	end

        	local thread = TaskSpawner.spawn("ProjectileWaiter", function()
        		local projectile = tracker:wait()
        		if not projectile or not projectile:IsA("BasePart") then
        			return
        		end

        		local name = projectile.Name

        		-- === FleetingSparks logic ===
        		if name == "LightningMote" then
        			TaskSpawner.spawn("FleetingSparks_MoveStack", function()
        				local onDescendantAdded = Signal.new(Players.LocalPlayer.Character.DescendantAdded)

        				task.wait(0.05 - Latency.rtt())

        				if self:distance(self.entity) <= 5 then
        					local action = Action.new()
        					action._when = 0
        					action.ihbc = true
        					action._type = "Parry"
        					action.name = "Fleeting Sparks Close"
        					return self:action(timing, action)
        				end

        				local isFirstTarget = true
        				local listenerConn = onDescendantAdded:connect("FleetingSparks_EffectListener", function(child)
        					if child.Name ~= "Targeted" then
        						return
        					end

        					if not child.Parent or not child.Parent:IsA("Attachment") then
        						return
        					end

        					if isFirstTarget then
        						isFirstTarget = false
        						return
        					end

        					local action = Action.new()
        					action._when = 0
        					action.ihbc = true
        					action._type = "Parry"
        					action.name = "Fleeting Sparks Effect"
        					return self:action(timing, action)
        				end)

        				task.wait(1.2)

        				listenerConn:Disconnect()
        			end)
        		-- === IceDaggers logic ===
        		elseif name == "IceDagger" then
        			TaskSpawner.spawn("IceDagger_MoveStack", function()
        				local onDescendantAdded = Signal.new(Players.LocalPlayer.Character.DescendantAdded)

        				local listenerConn = onDescendantAdded:connect("IceDaggers_EffectListener", function(child)
        					if child.Name ~= "Targeted" then
        						return
        					end

        					if not child.Parent or not child.Parent:IsA("Attachment") then
        						return
        					end

        					local distance = self:distance(self.entity)

        					local action = Action.new()
        					action._when = math.min(200 + distance * 5, 1000)
        					action.ihbc = true
        					action._type = "Parry"
        					action.name = "Ice Daggers Effect"
        					return self:action(timing, action)
        				end)

        				task.wait(1.2)

        				listenerConn:Disconnect()
        			end)
        		end
        	end)

        	local onDescendantAdded = Signal.new(self.entity.DescendantAdded)

        	self.tmaid:add(onDescendantAdded:connect("IceDaggersClose", function(child)
        		if child.Name ~= "REP_SOUND_5033484755" then
        			return
        		end

        		local distance = self:distance(self.entity)
        		if distance > 10 then
        			return
        		end

        		-- Cancel thread.
        		task.cancel(thread)

        		-- Parry close.
        		local action = Action.new()
        		action.ihbc = true
        		action._when = 0
        		action._type = "Start Block"
        		action.name =
        			string.format("(%.2f) (%.2f) Ice Daggers Close Timing", distance, hrp.AssemblyLinearVelocity.Magnitude)
        		self:action(timing, action)

        		local actionTwo = Action.new()
        		actionTwo._when = 600
        		actionTwo.ihbc = true
        		actionTwo._type = "End Block"
        		actionTwo.name = "Ice Daggers Close End"
        		return self:action(timing, actionTwo)
        	end))

        	self.tmaid:add(thread)
        end
    end,
    ["IceEruption"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local distance = self:distance(self.entity)
        	local data = Mantra.data(self.entity, "Mantra:EruptionMetal{{Metal Eruption}}")
        	local range = data.stratus * 2.5 + data.cloud * 1.5
        	local hrp = self.entity:FindFirstChild("HumanoidRootPart")
        	if not hrp then
        		return
        	end

        	if hrp:WaitForChild("REP_SOUND_13263429067", 0.1) then
        		local action = Action.new()
        		action._when = math.min(200 + distance * 15)
        		action._type = "Parry"
        		action.hitbox = Vector3.new(23 + range, 20, 30 + range)
        		action.name = string.format("(%.2f) Dynamic Metal Eruption Timing", distance)
        		return self:action(timing, action)
        	else
        		local action = Action.new()
        		action._when = math.min(525 + distance * 13.5)
        		action._type = "Dodge"
        		action.hitbox = Vector3.new(22, 20, 30)
        		action.name = string.format("(%.2f) Dynamic Ice Eruption Timing", distance)
        		return self:action(timing, action)
        	end
        end
    end,
    ["IceForgeCast"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---@module Utility.TaskSpawner
        local TaskSpawner = getfenv().TaskSpawner

        ---Check if cubes have all been destroyed.
        local function areCubesStillAlive(cubes)
        	for _, cube in next, cubes do
        		if not cube.Parent then
        			continue
        		end

        		if cube.Transparency >= 0.5 then
        			continue
        		end

        		return true
        	end

        	return false
        end

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local entity = self.entity
        	if not entity then
        		return
        	end

        	local hrp = entity:FindFirstChild("HumanoidRootPart")
        	if not hrp then
        		return
        	end

        	timing.iae = false

        	if hrp:WaitForChild("REP_SOUND_15214335898", 0.1) then
        		local action = Action.new()
        		action._when = 0
        		action._type = "Parry"
        		action.hitbox = Vector3.new(50, 50, 50)
        		action.name = "Storm Blades Timing"
        		return self:action(timing, action)
        	end

        	TaskSpawner.spawn("IceCubes_Spawn", function()
        		task.wait(1.9 - Latency.rtt())

        		if not hrp:FindFirstChild("REP_SOUND_13692212248") then
        			return
        		end

        		local thrown = workspace:FindFirstChild("Thrown")
        		if not thrown then
        			return
        		end

        		local cubes = {}

        		for _, part in pairs(thrown:GetChildren()) do
        			if not part:IsA("BasePart") then
        				continue
        			end

        			if not part.Name:match("Cube") then
        				continue
        			end

        			cubes[#cubes + 1] = part
        		end

        		if #cubes <= 0 then
        			return
        		end

        		local fcube = cubes[1]

        		repeat
        			task.wait()
        		until fcube:FindFirstChild("BodyVelocity")

        		local blockStarted = false

        		timing.mat = 5000
        		timing.iae = true

        		while task.wait() do
        			for _, cube in next, cubes do
        				if not areCubesStillAlive(cubes) then
        					local secondAction = Action.new()
        					secondAction._when = 0
        					secondAction._type = "End Block"
        					secondAction.name = "Ice Cubes End"
        					secondAction.ihbc = true
        					return self:action(timing, secondAction)
        				end

        				if not cube or not cube.Parent then
        					continue
        				end

        				if self:distance(cube) >= 16 then
        					continue
        				end

        				if blockStarted then
        					continue
        				end

        				local action = Action.new()
        				action._when = 0
        				action._type = "Start Block"
        				action.name = "Ice Cubes Start"
        				action.ihbc = true
        				self:action(timing, action)

        				blockStarted = true
        			end
        		end
        	end)
        end
    end,
    ["IceForgeNewCharge"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	task.spawn(function()
        		local thrown = workspace:FindFirstChild("Thrown")
        		if not thrown then
