        			action.hitbox = Vector3.new(15, 15, 90)
        			action.name = "Shared Soul Beam End"
        			return self:action(timing, action)
        		end
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.hitbox = Vector3.new(15, 15, 90)
        	action.name = "Dynamic Lightning Beam Timing"
        	return self:action(timing, action)
        end
    end,
