        	local fallbackAction = Action.new()
        	fallbackAction._when = 150
        	fallbackAction._type = "Dodge"
        	fallbackAction.hitbox = Vector3.new(20, 30, 20)
        	fallbackAction.name = "Metal Kick Slow Dodge"
        	self:action(timing, fallbackAction)
        end
    end,
    ["MetalRain"] = function()
