    ["ShadowEncircle"] = function()
        -- Timestamp.
        local lastEncircleTimestamp = nil

        ---@class Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	if self:distance(self.entity) > 12 then
        		return
        	end


        	if lastEncircleTimestamp and os.clock() - lastEncircleTimestamp <= 1.0 then
        		return
        	end

        	self:hook("target", function()
        		return true
        	end)

        	lastEncircleTimestamp = os.clock()

        	local players = game:GetService("Players")
        	local humanoid = players.LocalPlayer
        		and players.LocalPlayer.Character
        		and players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid")

        	if not humanoid then
        		return
        	end

        	local effect = self.entity:FindFirstChild("AirCounter")
        	if effect then
        		return
        	end

        	timing.fhb = false

        	local action = Action.new()
        	action._when = 750
        	action._type = "Parry"
        	action.ihbc = true
        	action.name = "Shadow Encircle Timing"
        	self:action(timing, action)
        end
    end,
    ["ShadowEruptionCast"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local distance = self:distance(self.entity)
        	local data = Mantra.data(self.entity, "Mantra:EruptionShadow{{Shadow Eruption}}")
        	local dataTwo = Mantra.data(self.entity, "Mantra:RestraintShadow{{Shadow Chains}}")
        	local size = data.stratus * 5.5 + data.cloud * 4.5
        	local range = dataTwo.perfect * 8 + dataTwo.crystal * 6

        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	local root = self.entity:FindFirstChild("HumanoidRootPart")
        	if not root then
        		return
        	end

        	local action = Action.new()
        	action._type = "Parry"

        	if root:FindFirstChild("REP_SOUND_5188185503") then
        		action._when = 1200
        		action.hitbox = Vector3.new(10, 10, 15)
        		action.name = "Ice Chains Timing"
        		timing.iae = true
        		timing.fhb = true
        	elseif thrown:FindFirstChild("ChainPortalShadow") then
        		action._when = math.min(200 + distance * 6)
        		action.hitbox = Vector3.new(55 + range, 55 + range, 55 + range)
        		action.name = "Shadow Chains Timing"
        		timing.fhb = false
        	else
        		action._when = 50
        		action.hitbox = Vector3.new(35 + size, 35 + size, 35 + size)
        		action.name = "Shadow Eruption Timing"
        		timing.fhb = false
        	end

        	self:action(timing, action)
        end
    end,
    ["ShadowGun"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:GunShadow{{Shadow Gun}}")
        	local range = data.perfect * 7 + data.crystal * 5
        	local size = data.stratus * 0.4 + data.cloud * 0.3

        	local action = Action.new()
        	action._when = 650
        	action._type = "Parry"
        	action.hitbox = Vector3.new(10 + size, 10 + size, 25 + range)
        	action.name = "Dynamic Shadow Gun Timing"

        	if data.blast then
        		action.hitbox = Vector3.new(action.hitbox.X * 2.5, action.hitbox.Y * 2.5, action.hitbox.Z)
        	end

        	timing.iae = true
        	timing.ieae = true
        	timing.duih = false
        	timing.mat = 1000
        	timing.ffh = true

        	self:action(timing, action)
        end
    end,
    ["ShadowMetero"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@type Maid
        local Maid = getfenv().Maid

        ---@type Signal
        local Signal = getfenv().Signal

        -- Services.
        local players = game:GetService("Players")

        local SHADOW_METEOR_ANIM = "rbxassetid://6701095669"

        local RECENT_WINDOW = 4

        local lastCastAt = -math.huge

        local animMaid = Maid.new()


        ---@param character Model
        local function hookCharacter(character)
        	animMaid:clean()

        	local humanoid = character:FindFirstChildOfClass("Humanoid")
        	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        	if not animator then
        		return
        	end

        	local animationPlayed = Signal.new(animator.AnimationPlayed)
        	animMaid:mark(animationPlayed:connect("ShadowMetero_LocalCast", function(track)
        		local animation = track and track.Animation
        		if animation and animation.AnimationId == SHADOW_METEOR_ANIM then
        			lastCastAt = os.clock()
        		end
        	end))
        end

        do
        	local localPlayer = players.LocalPlayer
        	if localPlayer.Character then
        		hookCharacter(localPlayer.Character)
        	end
        	Signal.new(localPlayer.CharacterAdded):connect("ShadowMetero_CharacterAdded", hookCharacter)
        end

        ---Module function.
        ---@param self PartDefender
        ---@param timing PartTiming
        return function(self, timing)
        	if os.clock() - lastCastAt <= RECENT_WINDOW then
        		return
        	end

        	local action = Action.new()
        	action._when = 500
        	action._type = "Parry"
        	action.ihbc = true
        	action.name = "Shadow Metero Timing"
        	return self:action(timing, action)
        end
    end,
    ["ShadowPuppet"] = function()
