    ["SilentheartWarn"] = [[
---@type Action
local Action = getfenv().Action

-- Services.
local players = game:GetService("Players")

---Look for attachment -> recolor.
---@return ParticleEmitter?
local function getRecolorEmitter()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local hrp = character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	for _, child in next, hrp:GetChildren() do
		if not child:IsA("Attachment") then
			continue
		end

		local recolor = child:FindFirstChild("Recolor")
		if not recolor then
			continue
		end

		return recolor
	end
end

---Module function.
---@param self EffectDefender
---@param timing EffectTiming
return function(self, timing)
	local hrp = players.LocalPlayer.Character and players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	local recolor = nil

	repeat
		-- Wait.
		task.wait()

		-- Get recolor emitter.
		recolor = getRecolorEmitter()
	until recolor

	local action = Action.new()
	action._when = 250
	action._type = "Parry"
	action.ihbc = true
	action.name = string.format("(%.6f - %.6f) Dynamic Relentless Hunt Timing", recolor.Speed.Min, recolor.Speed.Max)
	return self:action(timing, action)
end

]],
    ["SinisterHalo"] = [[
---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = getfenv().RepeatInfo

---@module Game.Latency
local Latency = getfenv().Latency

---@module Game.Timings.PartTiming
local PartTiming = getfenv().PartTiming

-- Services.
local players = game:GetService("Players")

---Module function.
---@param self PartDefender
---@param timing PartTiming
return function(self, timing)
	local humanoid = players.LocalPlayer
		and players.LocalPlayer.Character
		and players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid")

	if not humanoid then
		return
	end

	for _, track in next, humanoid:GetPlayingAnimationTracks() do
		if track.Animation.AnimationId == "rbxassetid://9919986614" then
			return
		end
	end

	local ntiming = PartTiming.new()
	ntiming.name = "SinisterHaloRepeat"
	ntiming.duih = true
	ntiming.hitbox = Vector3.new(20, 20, 20)
	ntiming.fhb = false
	ntiming.ndfb = true
	ntiming._rsd = 0
	ntiming._rpd = 125
	ntiming.imxd = 120
	ntiming.imdd = 0
	ntiming.mrt = 1.75

	ntiming.rsd = function()
		return ntiming._rsd / 1000
	end

	ntiming.rpd = function()
		return ntiming._rpd / 1000
	end

	local info = RepeatInfo.new(ntiming, Latency.rdelay(), self:uid(10))
	self:srpue(self.part, ntiming, info)
end

]],
