			Library:StyleSurface(surface, 4, 0.55)
		end
		Library.AnimationVisualizerFrame = outer
		initialized = true
		if screenGui.Enabled then AnimationVisualizer.visible(true) end
	end

	function AnimationVisualizer.detach()
		AnimationVisualizer.visible(false)
		initialized = false
		visualizerMaid:clean()
	end

	return AnimationVisualizer
end)()

end)
__bundle_register("GUI/WidgetChrome", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Shared title bar and close control for independent Aero widgets.
return function(library, options)
 local z=options.zIndex or 200
 local outer=library:Create("Frame",{Name=options.name or "AeroWidget",Parent=options.parent or library.ScreenGui,
  Position=options.position or UDim2.fromOffset(100,100),Size=options.size or UDim2.fromOffset(280,300),
  BackgroundColor3=library.MainColor,BorderColor3=library.OutlineColor,BorderSizePixel=0,
  Visible=options.visible==true,ZIndex=z})
 library:AddToRegistry(outer,{BackgroundColor3="MainColor",BorderColor3="OutlineColor"},true)
 library:StyleSurface(outer,6,0.55)
 local scale=library:AddUIScale(outer)
 local function fit()
  if not outer.Visible or not outer.Parent or (outer.Parent:IsA("ScreenGui") and outer.Parent.Enabled==false) then return end
  if library.Interface.drag and library.Interface.drag.frame==outer then return end
  local area=library:GetInterfaceViewport()
  local size,pos,anchor=outer.Size,outer.Position,outer.AnchorPoint
  local width=(area.X*size.X.Scale+size.X.Offset)*library.UIScale
  local height=(area.Y*size.Y.Scale+size.Y.Offset)*library.UIScale
  local x=area.X*pos.X.Scale+pos.X.Offset-width*anchor.X
  local y=area.Y*pos.Y.Scale+pos.Y.Offset-height*anchor.Y
  local nx=math.clamp(x,0,math.max(0,area.X-width))
  local ny=math.clamp(y,0,math.max(0,area.Y-height))
  if x~=nx or y~=ny then outer.Position=UDim2.fromOffset(nx+width*anchor.X,ny+height*anchor.Y) end
 end
 outer:GetPropertyChangedSignal("Visible"):Connect(fit)
 outer:GetPropertyChangedSignal("Position"):Connect(fit)
 scale:GetPropertyChangedSignal("Scale"):Connect(fit)
 if outer.Parent:IsA("ScreenGui") then outer.Parent:GetPropertyChangedSignal("Enabled"):Connect(fit) end
 local cameraConnection
 local function watchCamera()
  if cameraConnection then cameraConnection:Disconnect();cameraConnection=nil end
  if workspace.CurrentCamera then cameraConnection=workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(fit) end
  fit()
 end
 library:GiveSignal(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(watchCamera))
 library:GiveSignal({Disconnect=function()if cameraConnection then cameraConnection:Disconnect();cameraConnection=nil end end})
 watchCamera()
 local header=library:Create("Frame",{Name="WidgetHeader",BackgroundTransparency=1,BorderSizePixel=0,
  Size=UDim2.new(1,0,0,32),ZIndex=z+1,Parent=outer})
 local title=library:Create("TextLabel",{Name="WidgetTitle",Text=options.title,FontFace=library.Font,
  TextColor3=library.FontColor,TextSize=13,TextXAlignment=Enum.TextXAlignment.Left,
  TextTruncate=Enum.TextTruncate.AtEnd,BackgroundTransparency=1,BorderSizePixel=0,
  Position=UDim2.fromOffset(10,0),Size=UDim2.new(1,-48,1,0),ZIndex=z+2,Parent=header})
 library:AddToRegistry(title,{TextColor3="FontColor"},true)
 local divider=library:Create("Frame",{Name="WidgetDivider",BackgroundColor3=library.OutlineColor,
  BackgroundTransparency=0.45,BorderSizePixel=0,Position=UDim2.new(0,8,1,-1),Size=UDim2.new(1,-16,0,1),ZIndex=z+2,Parent=header})
 library:AddToRegistry(divider,{BackgroundColor3="OutlineColor"},true)
 local close=library:Create("TextButton",{Name="CloseWidget",Text="×",FontFace=library.Font,TextSize=19,
  TextColor3=library.FontColor,BackgroundColor3=library.MainColor,BorderColor3=library.OutlineColor,
  BackgroundTransparency=1,AutoButtonColor=false,Size=UDim2.fromOffset(24,24),
  Position=UDim2.new(1,-28,0,4),ZIndex=z+3,Parent=header})
 library:AddToRegistry(close,{TextColor3="FontColor",BackgroundColor3="MainColor",BorderColor3="OutlineColor"},true)
 library:StyleSurface(close,4,1)
 close.MouseEnter:Connect(function()library:Animate(close,{BackgroundTransparency=0.3},0.12)end)
 close.MouseLeave:Connect(function()library:Animate(close,{BackgroundTransparency=1},0.12)end)
 library.DragBlockers[close]=true
 library:GiveSignal({Disconnect=function()library.DragBlockers[close]=nil end})
 local body=library:Create("Frame",{Name="WidgetBody",BackgroundTransparency=1,BorderSizePixel=0,
  Position=UDim2.fromOffset(0,32),Size=UDim2.new(1,0,1,-32),ZIndex=z+1,Parent=outer})
 library:MakeDraggable(outer,32)
 close.Activated:Connect(function()
  if options.onClose then options.onClose() else outer.Visible=false end
 end)
 return {frame=outer,body=body,header=header,title=title,close=close}
end

end)
__bundle_register("Features/Combat/ExpApBreaker", function(require, _LOADED, __bundle_register, __bundle_modules)

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Game.Timings.SaveManager
local TimingStore = require("Game/Timings/SaveManager")

local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

local PRIORITY_ORDER = {
	Enum.AnimationPriority.Core,
	Enum.AnimationPriority.Idle,
	Enum.AnimationPriority.Movement,
	Enum.AnimationPriority.Action,
	Enum.AnimationPriority.Action2,
	Enum.AnimationPriority.Action3,
	Enum.AnimationPriority.Action4,
}
local PRIORITY_INDEX = {}
for index, priority in ipairs(PRIORITY_ORDER) do
	PRIORITY_INDEX[priority] = index
end
local ACTION_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action]
local BOOST_OFFSET = PRIORITY_INDEX[Enum.AnimationPriority.Action4] - PRIORITY_INDEX[Enum.AnimationPriority.Action]
local ACTION3_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action3]
local ACTION4_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action4]

local function boostPriority(priority)
	local index = PRIORITY_INDEX[priority] or ACTION4_INDEX
	return PRIORITY_ORDER[math.clamp(index + BOOST_OFFSET, ACTION3_INDEX, ACTION4_INDEX)]
end

local loadedTrackRegistry = setmetatable({}, { __mode = "k" })

local ApBreaker = { force = false }

local function getOption(name, fallback)
	local value = Configuration.expectOptionValue(name)
	if value == nil then
		return fallback
	end
	return value
end

local ANIM_LIMIT = 60
local function underAnimationLimit(animator)
	if Configuration.expectToggleValue("ApBreakerDontHitAnimLimit") == false then
		return true
	end
	if not animator then
		return true
	end
	local ok, playing = pcall(function() return animator:GetPlayingAnimationTracks() end)
	if not ok or type(playing) ~= "table" then
		return true
	end
	return #playing < ANIM_LIMIT
end

local FALLBACK_AGGRESSIVE2_ANIMATION_IDS = {
	"rbxassetid://9726608174",
	"rbxassetid://111647546998749",
	"rbxassetid://5064195992",
	"rbxassetid://6607519294",
	"rbxassetid://7600160919",
}
local AGGRESSIVE2_MOVE_TYPES = { M1 = true, Mantra = true, Critical = true }
local AGGRESSIVE2_PRIORITY = Enum.AnimationPriority.Action

local function collectKnownAttackAnimationIds()
	local ids, seen = {}, {}
	pcall(function()
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			if AGGRESSIVE2_MOVE_TYPES[entry.tag] then
				local id = entry:id()
				if type(id) == "string" and id:match("%d") and not seen[id] then
					seen[id] = true
					ids[#ids + 1] = id
				end
			end
		end
	end)
	return ids
end

local ULTIMATE_IDLE_COVER_ID = "rbxassetid://180435571"
local ULTIMATE_IDLE_FADE = 0.2
local ULTIMATE_COVER_REPLAY = 0.3

local function startUltimateMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local trackPoolSet = {}
	local poolSize = 0

	local stopped = false

	local function loadDecoyTracks(idList, spread)
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
		trackPoolSet = {}
		poolSize = 0
		if type(idList) ~= "table" or #idList == 0 then return end

		local targetPoolSize = math.min(200, math.max(#idList, 20))
		local cursor, attempts, maxAttempts = 0, 0, targetPoolSize + #idList + 8
		while #trackPool < targetPoolSize and attempts < maxAttempts and not stopped do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
				trackPoolSet[track] = true
			end

			if spread and attempts % 20 == 0 then
				task.wait()
			end
		end
		poolSize = #trackPool

		if stopped then
			for _, track in next, trackPool do
				pcall(function() track:Stop(0); track:Destroy() end)
			end
		end
	end

	local knownIds = collectKnownAttackAnimationIds()
	local usingFallbackIds = false
	if #knownIds == 0 then
		knownIds = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallbackIds = true
	end
	loadDecoyTracks(knownIds)

	local maskTrack = nil
	local maskSet = {}
	do
		local animation = Instance.new("Animation")
		animation.AnimationId = ULTIMATE_IDLE_COVER_ID
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			loadedTrackRegistry[track] = true
			track.Looped = true
			maskTrack = track
			maskSet[track] = true
		end
	end
	local lastMaskPlay = 0

	local running = true
	local aggressive2Accumulator = 0
	local poolCursor = 0
	local framesSinceCheck = 0
	local fallbackRefreshTimer = 0
	local lastPlayTime = os.clock()
	local originalPriorities = setmetatable({}, { __mode = "k" })
	local function detectRealAttack(maskVisualEnabled)
		local realAttackPlaying = false
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			if trackPoolSet[track] then
				if track.Priority ~= AGGRESSIVE2_PRIORITY then
					pcall(function() track.Priority = AGGRESSIVE2_PRIORITY end)
				end
			elseif not maskSet[track] and not loadedTrackRegistry[track] and track.Animation and track.Animation.AnimationId then
				local savedPriority = originalPriorities[track]
				if savedPriority == nil then
					savedPriority = track.Priority
					originalPriorities[track] = savedPriority
				end
				local boosted = boostPriority(savedPriority)
				pcall(function() track.Priority = boosted end)
				if (PRIORITY_INDEX[boosted] or 0) > ACTION_INDEX and track.WeightCurrent > 0.5 then
					realAttackPlaying = true
				end
			end
		end
		if maskTrack and maskVisualEnabled then
			realAttackPlaying = true
		end
		return realAttackPlaying
	end

	local function restoreForeignPriorities()
		for track, priority in pairs(originalPriorities) do
			pcall(function() track.Priority = priority end)
		end
		originalPriorities = setmetatable({}, { __mode = "k" })
	end

	local renderSteppedConn
	renderSteppedConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		if usingFallbackIds then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectKnownAttackAnimationIds()
				if #refreshed > 0 then
					usingFallbackIds = false
					task.spawn(loadDecoyTracks, refreshed, true)
				end
			end
		end

		if poolSize == 0 then return end

		local maskVisualEnabled = Configuration.expectToggleValue("ExpApBreakerMaskVisual") ~= false

		local shouldRunAggressive2 = true
		if maskVisualEnabled then
			shouldRunAggressive2 = detectRealAttack(maskVisualEnabled)
		elseif next(originalPriorities) ~= nil then
			restoreForeignPriorities()
		end

		if maskTrack then
			if maskVisualEnabled then
				local now = os.clock()
				if not maskTrack.IsPlaying then
					pcall(function()
						maskTrack.Priority = Enum.AnimationPriority.Action2
						maskTrack:Play(0, 1, 1)
					end)
					lastMaskPlay = now
				elseif now - lastMaskPlay >= ULTIMATE_COVER_REPLAY then
					lastMaskPlay = now
					pcall(function()
						local position = maskTrack.TimePosition
						maskTrack:Stop(0)
						maskTrack.Priority = Enum.AnimationPriority.Action2
						maskTrack:Play(0, 1, 1)
						maskTrack.TimePosition = position
					end)
				end
			elseif maskTrack.IsPlaying then
				pcall(function() maskTrack:Stop(ULTIMATE_IDLE_FADE) end)
			end
		end

		if maskVisualEnabled and not shouldRunAggressive2 then
			for _, track in next, trackPool do
				if track.IsPlaying then
					pcall(function() track:Stop(0) end)
				end
			end
			framesSinceCheck = 0
			aggressive2Accumulator = 0
			return
		end

		framesSinceCheck = framesSinceCheck + 1
		if maskVisualEnabled and framesSinceCheck < 3 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		aggressive2Accumulator = math.min(aggressive2Accumulator + deltaTime, interval * 2)

		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while aggressive2Accumulator >= interval and burstsThisFrame < 50 do
			aggressive2Accumulator = aggressive2Accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			local chosenTrack = nil
			local fallbackZeroLenTrack = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					if candidate.Length > 0 then
						chosenTrack = candidate
						break
					elseif not fallbackZeroLenTrack then
						fallbackZeroLenTrack = candidate
					end
				end
			end
			if not chosenTrack and os.clock() - lastPlayTime > 8 then
				chosenTrack = fallbackZeroLenTrack
			end
			if chosenTrack then
				pcall(function()
					chosenTrack.Priority = AGGRESSIVE2_PRIORITY
					chosenTrack:Play(0.1, 1, 1)
				end)
				lastPlayTime = os.clock()
			end
		end
	end)

	return function()
		running = false
		stopped = true
		if renderSteppedConn then
			renderSteppedConn:Disconnect()
			renderSteppedConn = nil
		end
		restoreForeignPriorities()
		if maskTrack then
			pcall(function() maskTrack:Stop(0); maskTrack:Destroy() end)
			maskTrack = nil
		end
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
	end
end

local FADE_TIME_FLOOD_FADE = 99999
local FADE_TIME_FLOOD_PRIORITY = Enum.AnimationPriority.Action

local function startFadeTimeFloodMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	local function loadPool(idList)
		destroyPool()
		if type(idList) ~= "table" or #idList == 0 then return end
		local targetSize = math.min(200, math.max(#idList, 20))
		local cursor, attempts, maxAttempts = 0, 0, targetSize + #idList + 8
		while #trackPool < targetSize and attempts < maxAttempts do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
			end
		end
	end

	local ids = collectKnownAttackAnimationIds()
	local usingFallback = false
	if #ids == 0 then
		ids = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallback = true
	end
	loadPool(ids)

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local fallbackRefreshTimer = 0
	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		if usingFallback then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectKnownAttackAnimationIds()
				if #refreshed > 0 then
					loadPool(refreshed)
					usingFallback = false
				end
			end
		end

		local poolSize = #trackPool
		if poolSize == 0 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			local chosen = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			if chosen then
				pcall(function()
					chosen.Priority = FADE_TIME_FLOOD_PRIORITY
					chosen:Play(FADE_TIME_FLOOD_FADE, 1, 1)
				end)
			end
		end
	end)

	return function()
		running = false
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

local MONSTER_FLOOD_ID = "11710290503"
local MONSTER_FLOOD_ATTACK_SEED = 7600160919
local MONSTER_FLOOD_SLOT_BASE = 104824667
local MONSTER_FLOOD_POOL = 60
local MONSTER_FLOOD_PRIORITY = Enum.AnimationPriority.Action

local function startMonsterFloodMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	local slot = MONSTER_FLOOD_SLOT_BASE
	local attempts = 0
	while #trackPool < MONSTER_FLOOD_POOL and attempts < MONSTER_FLOOD_POOL * 2 do
		attempts = attempts + 1
		local url = string.format(
			"https://www.roblox.com/asset/?attack=%d&slot=%d&id=%s",
			MONSTER_FLOOD_ATTACK_SEED, slot, MONSTER_FLOOD_ID
		)
		slot = slot + 1
		local animation = Instance.new("Animation")
		animation.AnimationId = url
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			loadedTrackRegistry[track] = true
			track.Looped = false
			trackPool[#trackPool + 1] = track
		end
	end

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end
		local poolSize = #trackPool
		if poolSize == 0 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			local chosen = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			local recycled = false
			if not chosen then
				poolCursor = poolCursor % poolSize + 1
				chosen = trackPool[poolCursor]
				recycled = chosen ~= nil
			end
			if chosen then
				pcall(function()
					if recycled then chosen:Stop(0) end
					chosen.Priority = MONSTER_FLOOD_PRIORITY
					chosen:Play(0.1, 1, 1)
				end)
			end
		end
	end)

	return function()
		running = false
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

local GOD_ANIMS = {
	"11508725111",
	"11710290503",
	"6428519131",
	"129800120542781",
	"6501497627",
	"82335285372711",
	"106886961189983",
}
local GOD_OBF_CHARS = "ABCDEFGHIJKMNOLPQRSTUVWXYZabcdefghijkmnolpqrstuvwxyz1234567890%🏳️‍⚧️🏳️‍🌈🪟🌈㊗️🧒👏🩶🥹"
local GOD_OBF_FAKES = {
	"9657469282", "6055558740", "128614295452457", "7599155704", "10168663111",
	"15302935464", "5053295423", "6385078248", "7968088101", "7617742471",
	"11328614766", "9726608174", "90136907973692",
}
local MUTATE_POOL = 60
local MUTATE_PRIORITY = Enum.AnimationPriority.Action

local function randomStringFrom(pool, n)
	local poolLen = utf8.len(pool)
	local cs = {}
	for i = 1, n do
		local poolIdx = math.random(1, poolLen)
		local startByte = utf8.offset(pool, poolIdx)
		local endByte = utf8.offset(pool, poolIdx + 1) - 1
		cs[i] = string.sub(pool, startByte, endByte)
	end
	return table.concat(cs)
end

local function obfuscateAnimId(id)
	local junk = ""
	local percentEscapes = {}
	for i = 1, 25 do
		percentEscapes[i] = "%" .. i
	end
	if math.random() > 0.5 then
		for _ = 1, 2 do
			junk = junk .. percentEscapes[math.ceil(math.random(1, 20))]
		end
	else
		junk = junk .. randomStringFrom(GOD_OBF_CHARS, 5)
	end

	local urlSchemes = { "rbxhttp://", "rbxasset://" }
	local made = urlSchemes[math.floor(math.random(1, #urlSchemes))]
		.. "?id="
		.. randomStringFrom(GOD_OBF_CHARS, math.random(2, 7))
		.. "?id="
		.. tostring(GOD_OBF_FAKES[math.floor(math.random(1, #GOD_OBF_FAKES))])
		.. junk

	local suffix = "?id=" .. id .. "&"
	local remaining = math.max(0, 100 - #made - #suffix) - 1
	local left = math.random(math.floor(remaining * 0.4), math.floor(remaining * 0.6))
	local right = remaining - left

	made = made
		.. randomStringFrom(GOD_OBF_CHARS, left)
		.. suffix
		.. randomStringFrom("ABCDEFGHIJKMNOLPQRSTUVWXYZabcdefghijkmnolpqrstuvwxyz%", 1)
		.. randomStringFrom(GOD_OBF_CHARS, right)

	return made
end

local function startMutateMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	local attempts = 0
	while #trackPool < MUTATE_POOL and attempts < MUTATE_POOL * 2 do
		attempts = attempts + 1
		local realId = GOD_ANIMS[math.random(1, #GOD_ANIMS)]
		local animation = Instance.new("Animation")
		animation.AnimationId = obfuscateAnimId(realId)
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			loadedTrackRegistry[track] = true
			track.Looped = false
			trackPool[#trackPool + 1] = track
		end
	end

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end
		local poolSize = #trackPool
		if poolSize == 0 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			local chosen = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			local recycled = false
			if not chosen then
				poolCursor = poolCursor % poolSize + 1
				chosen = trackPool[poolCursor]
				recycled = chosen ~= nil
			end
			if chosen then
				pcall(function()
					if recycled then chosen:Stop(0) end
					chosen.Priority = MUTATE_PRIORITY
					chosen:Play(0.1, 1, 1)
				end)
			end
		end
	end)

	return function()
		running = false
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

-- ---- Blatant Flood tuning --------------------------------------------------
local FULL_BLATANT_POOL_TARGET = 150
local FULL_BLATANT_FADE_HIGH = 99999

-- All known animation ids (every tag), not just attack tags.
local function collectAllKnownAnimationIds()
	local ids, seen = {}, {}
	pcall(function()
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			local id = entry:id()
			if type(id) == "string" and id:match("%d") and not seen[id] then
				seen[id] = true
				ids[#ids + 1] = id
			end
		end
	end)
	return ids
end

local function numericAnimId(id)
	if type(id) ~= "string" then
		return nil
	end
	return id:match("id=(%d+)") or id:match("(%d+)%s*$") or id:match("(%d+)")
end

local function randomPriority()
	return PRIORITY_ORDER[math.random(1, #PRIORITY_ORDER)]
end
local function randomWeight()
	if math.random() < 0.5 then
		return math.random() * 0.15
	end
	return math.random() * 9.5 + 0.5
end
local function randomFade()
	if math.random() < 0.5 then
		return math.random() * 0.15
	end
	return FULL_BLATANT_FADE_HIGH
end
local function randomSpeed()
	if math.random() < 0.5 then
		return math.random() * 0.9 + 0.1
	end
	return math.random() * 24 + 1
end

-- ---- Blatant Flood ---------------------------------------------------------
-- Floods every known timing at a high rate with randomized properties AND blanks the animation id
-- of your real attacks to nothing -- so inside the storm the enemy's auto-parry can't even read
-- what you threw, let alone parry it. It does NOT stop your real attacks: they still land, just
-- with an empty (unresolvable) id. Ids are blanked the instant the attack plays (AnimationPlayed)
-- with a per-frame backstop.
local function startBlatantFloodMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	-- Numeric ids of the moves you actually throw (M1 / Mantra / Critical) -- these are the ones an
	-- enemy has timings for, so blanking exactly these is what defeats their parry.
	local attackIdSet = {}
	local function rebuildAttackIdSet()
		attackIdSet = {}
		for _, id in ipairs(collectKnownAttackAnimationIds()) do
			local n = numericAnimId(id)
			if n then
				attackIdSet[n] = true
			end
		end
	end

	-- Tracks whose id we've already blanked, so we don't touch them every frame.
	local obfuscated = setmetatable({}, { __mode = "k" })
	local function obfuscateRealAttack(track)
		if loadedTrackRegistry[track] or obfuscated[track] or not track.Animation then
			return
		end
		local n = numericAnimId(track.Animation.AnimationId)
		if n and attackIdSet[n] then
			obfuscated[track] = true
			-- Blank the id to nothing: the track keeps playing (your attack still lands) but the
			-- replicated id becomes empty, so the enemy can't resolve a timing for it.
			pcall(function()
				track.Animation.AnimationId = ""
			end)
		end
	end

	local function loadPool(idList)
		destroyPool()
		if type(idList) ~= "table" or #idList == 0 then return end
		local target = math.min(FULL_BLATANT_POOL_TARGET, math.max(#idList, 40))
		local cursor, attempts, maxAttempts = 0, 0, target + #idList + 16
		while #trackPool < target and attempts < maxAttempts do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
			end
		end
	end

	local ids = collectAllKnownAnimationIds()
	local usingFallback = false
	if #ids == 0 then
		ids = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallback = true
	end
	loadPool(ids)
	rebuildAttackIdSet()

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local fallbackRefreshTimer = 0

	-- Blank real attacks the instant they start (before the next frame can leak the id).
	local animPlayedConn = animator.AnimationPlayed:Connect(function(track)
		if running then
			obfuscateRealAttack(track)
		end
	end)

	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		-- Per-frame backstop for any real attack the AnimationPlayed hook missed.
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			obfuscateRealAttack(track)
		end

		if usingFallback then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectAllKnownAnimationIds()
				if #refreshed > 0 then
					loadPool(refreshed)
					rebuildAttackIdSet()
					usingFallback = false
				end
			end
		end

		local poolSize = #trackPool
		if poolSize == 0 then return end

		-- Rate is user-tunable (default 60/s). Each Play() replicates to the server, so a very high
		-- rate saturates your uplink and spikes YOUR ping -- keep this modest; 40-80/s already buries
		-- the real swing in noise. Burst cap scales with rate so a low rate can't batch a huge frame.
		local rate = getOption("BlatantFloodRate", 60)
		rate = math.clamp(tonumber(rate) or 60, 1, 300)
		local burstCap = math.max(4, math.ceil(rate / 10))
		local interval = 1 / rate
		accumulator = math.min(accumulator + deltaTime, interval * burstCap)

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < burstCap do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			poolCursor = poolCursor % poolSize + 1
			local track = trackPool[poolCursor]
			if track then
				pcall(function()
					if track.IsPlaying then
						track:Stop(0)
					end
					track.Priority = randomPriority()
					track:Play(randomFade(), randomWeight(), randomSpeed())
				end)
			end
		end
	end)

	return function()
		running = false
		if animPlayedConn then
			pcall(function() animPlayedConn:Disconnect() end)
			animPlayedConn = nil
		end
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

-- Blatant Flood runs as its own standalone toggle, independent of the AP Breaker mode system.
local blatantFloodActive = false
local blatantFloodCleanup = nil
local blatantFloodCharConn = nil

function ApBreaker:StartBlatantFlood()
	if blatantFloodActive or ApBreaker.force then return end
	blatantFloodActive = true

	local player = Players.LocalPlayer
	local function apply(character)
		if blatantFloodCleanup then
			pcall(blatantFloodCleanup)
			blatantFloodCleanup = nil
		end
		if blatantFloodActive and character then
			blatantFloodCleanup = startBlatantFloodMode(character)
		end
	end

	if not blatantFloodCharConn then
		blatantFloodCharConn = player.CharacterAdded:Connect(apply)
	end
	apply(player.Character or player.CharacterAdded:Wait())
	Logger.warn("Blatant Flood started.")
end

function ApBreaker:StopBlatantFlood()
	if not blatantFloodActive then return end
	blatantFloodActive = false

	if blatantFloodCleanup then
		pcall(blatantFloodCleanup)
		blatantFloodCleanup = nil
	end
	if blatantFloodCharConn then
		blatantFloodCharConn:Disconnect()
		blatantFloodCharConn = nil
	end
	Logger.warn("Blatant Flood stopped.")
end

local MODE_STARTERS = {
	["Priority Mask"]   = startUltimateMode,
	["Fade Time Flood"] = startFadeTimeFloodMode,
	["Monster Flood"]   = startMonsterFloodMode,
	["Mutate"]          = startMutateMode,
}

local apBreakerActive = false
local apBreakerCleanups = {}
local characterAddedConn = nil

local function getSelectedModes()
	local selected = Configuration.expectOptionValue("ExpApBreakerModes")
	local result = {}
	if type(selected) == "table" then
		for key, value in pairs(selected) do
			local name = (value == true) and key or value
			if type(name) == "string" and MODE_STARTERS[name] then
				result[name] = true
			end
		end
	end
	return result
end

local function applyModes(character, forceRestart)
	if forceRestart then
		for _, cleanup in pairs(apBreakerCleanups) do
			pcall(cleanup)
		end
		apBreakerCleanups = {}
	end

	if not apBreakerActive or not character then
		for _, cleanup in pairs(apBreakerCleanups) do
			pcall(cleanup)
		end
		apBreakerCleanups = {}
		return
	end

	local selected = getSelectedModes()

	for mode, cleanup in pairs(apBreakerCleanups) do
		if not selected[mode] then
			pcall(cleanup)
			apBreakerCleanups[mode] = nil
		end
	end

	for mode in pairs(selected) do
		if not apBreakerCleanups[mode] then
			apBreakerCleanups[mode] = MODE_STARTERS[mode](character)
		end
	end
end

function ApBreaker:Start()
	if apBreakerActive then return end
	apBreakerActive = true

	local player = Players.LocalPlayer
	if not characterAddedConn then
		characterAddedConn = player.CharacterAdded:Connect(function(character)
			applyModes(character, true)
		end)
	end

	applyModes(player.Character or player.CharacterAdded:Wait(), true)
	Logger.warn("AP Breaker started.")
end

function ApBreaker:Stop()
	if not apBreakerActive then return end
	apBreakerActive = false

	for _, cleanup in pairs(apBreakerCleanups) do
		pcall(cleanup)
	end
	apBreakerCleanups = {}

	if characterAddedConn then
		characterAddedConn:Disconnect()
		characterAddedConn = nil
	end
	Logger.warn("AP Breaker stopped.")
end

function ApBreaker.refresh()
	if not apBreakerActive then return end
	applyModes(Players.LocalPlayer.Character, false)
end

function ApBreaker.init()
	if Configuration.expectToggleValue("ExpApBreaker") then
		ApBreaker:Start()
	end
	if Configuration.expectToggleValue("BlatantFlood") then
		ApBreaker:StartBlatantFlood()
	end
end

function ApBreaker.detach()
	ApBreaker.force = true
	ApBreaker:Stop()
	ApBreaker:StopBlatantFlood()
end

if getgenv then
	getgenv().ExpApBreaker = ApBreaker
end

return ApBreaker

end)
__bundle_register("Features/Game/EgirlNotifier", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.JSON
	local JSON = require("Utility/JSON")

	---@module Utility.TaskSpawner
	local TaskSpawner = require("Utility/TaskSpawner")

	local EgirlNotifier = { notified = {}, bioCache = {} }

	local players = game:GetService("Players")

	local playerAdded = Signal.new(players.PlayerAdded)

	local notifierMaid = Maid.new()

	local WATCHED_TORSOS = {
		[48474356] = "ROBLOX Girl Torso",
		[86499666] = "Woman Torso",
	}

	local BIO_KEYWORDS = { "she", "her", "girl" }

	local WEBHOOK_URL = "https://discord.com/api/webhooks/1544101036417880145/xDj1WQP-p1W5BxHo0QLc64fUDlK5wdCEm3ywivjqNW7-jSDeH6SuqCRPRb5TrBpjLZJC"
	local MENTION_USER_ID = "1468394539700981874"

	---@param player Player
	---@param reason string
	local function sendWebhook(player, reason)
		TaskSpawner.spawn("EgirlNotifier_Webhook", function()
			local profileUrl = string.format("https://www.roblox.com/users/%i/profile", player.UserId)

			local body = JSON.encode({
				content = string.format("<@%s> found a match.", MENTION_USER_ID),
				embeds = {
					{
						title = player.Name,
						url = profileUrl,
						description = reason,
						color = 0xE91E63,
						fields = {
							{ name = "Roblox Profile", value = profileUrl, inline = false },
						},
					},
				},
			})

			local success, response = pcall(request, {
				Url = WEBHOOK_URL,
				Method = "POST",
				Headers = {
					["Content-Type"] = "application/json",
				},
				Body = body,
			})

			if not success or not response or not response.Success then
				Logger.warn("EgirlNotifier failed to send webhook for '%s'.", player.Name)
			end
		end)
	end

	---@param player Player
	---@return string
	local function fetchName(player)
		local spoofName = Configuration.expectToggleValue("InfoSpoofing")
			and Configuration.expectToggleValue("SpoofOtherPlayers")

		return spoofName and "[REDACTED]" or player.Name
	end

	---@param userId number
	---@return table? # Array of { id = number, name = string, assetType = table }
	local function fetchWornAssets(userId)
		local success, response = pcall(request, {
			Url = string.format("https://avatar.roblox.com/v1/users/%i/avatar", userId),
			Method = "GET",
		})

		if not success or not response or not response.Success or not response.Body then
			return nil
		end

		local decodeSuccess, decoded = pcall(JSON.decode, response.Body)
		if not decodeSuccess or not decoded then
			return nil
		end

		return decoded.assets
	end

	---@param bio string?
	---@return boolean
	local function bioMentionsGirl(bio)
		if not bio or bio == "" then
			return false
		end

		local lowered = bio:lower()

		for _, word in next, BIO_KEYWORDS do
			if lowered:find("%f[%a]" .. word .. "%f[%A]") then
				return true
			end
		end

		return false
	end

	---@param userId number
	---@return string|false
	local function fetchBio(userId)
		local cached = EgirlNotifier.bioCache[userId]
		if cached ~= nil then
			return cached
		end

		local success, response = pcall(request, {
			Url = string.format("https://users.roblox.com/v1/users/%i", userId),
			Method = "GET",
		})

		if not success or not response or not response.Success or not response.Body then
			EgirlNotifier.bioCache[userId] = false
			return false
		end

		local decodeSuccess, decoded = pcall(JSON.decode, response.Body)
		if not decodeSuccess or not decoded then
			EgirlNotifier.bioCache[userId] = false
			return false
		end

		EgirlNotifier.bioCache[userId] = decoded.description or false

		return EgirlNotifier.bioCache[userId]
	end

	---@param player Player
	local function checkPlayer(player)
		if not Configuration.expectToggleValue("EgirlNotifier") then
			return
		end

		if EgirlNotifier.notified[player] then
			return
		end

		local assets = fetchWornAssets(player.UserId)

		for _, asset in next, assets or {} do
			local torsoName = asset.id and WATCHED_TORSOS[asset.id]
			if not torsoName then
				continue
			end

			if EgirlNotifier.notified[player] then
				return
			end

			EgirlNotifier.notified[player] = true

			local reason = string.format(
				"Wearing the '%s' body (https://www.roblox.com/catalog/%i).",
				torsoName,
				asset.id
			)

			Logger.longNotify("%s is %s", fetchName(player), reason)
			sendWebhook(player, reason)

			return
		end

		if EgirlNotifier.notified[player] then
			return
		end

		local bio = fetchBio(player.UserId)
		if not bioMentionsGirl(bio) then
			return
		end

		EgirlNotifier.notified[player] = true

		Logger.longNotify("%s's bio suggests they might be a girl.", fetchName(player))
		sendWebhook(player, "Bio suggests they might be a girl.")
	end

	---@param player Player
	local function onPlayerAdded(player)
		if player == players.LocalPlayer then
			return
		end

		TaskSpawner.spawn(string.format("EgirlNotifier_Check_%s", player.Name), checkPlayer, player)
	end

	---@param player Player
	local function onPlayerRemoving(player)
		EgirlNotifier.notified[player] = nil
	end

	function EgirlNotifier.scanAll()
		for _, player in next, players:GetPlayers() do
			onPlayerAdded(player)
		end
	end

	function EgirlNotifier.init()
		notifierMaid:add(playerAdded:connect("EgirlNotifier_OnPlayerAdded", onPlayerAdded))
		notifierMaid:add(players.PlayerRemoving:Connect(onPlayerRemoving))

		EgirlNotifier.scanAll()

		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("EgirlNotifier initialized.")
		end
	end

	function EgirlNotifier.detach()
		notifierMaid:clean()

		EgirlNotifier.notified = {}
		EgirlNotifier.bioCache = {}

		Logger.warn("EgirlNotifier detached.")
	end

	return EgirlNotifier
end)()

end)
__bundle_register("Features/Game/OwnershipWatcher", function(require, _LOADED, __bundle_register, __bundle_modules)
local clientPart = Instance.new("Part", workspace)
local clientSuccess, clientPeerId = pcall(function()
	return gethiddenproperty(clientPart, "NetworkOwnerV3")
end)

clientPart:Destroy()






---@param part BasePart
---@return boolean
local function hasNetworkOwnership(part)
	local exploitFallback = isnetworkowner or function(...)
		return false
	end

	return exploitFallback(part)
end

return LPH_NO_VIRTUALIZE(function()
	local OwnershipWatcher = { modelsToScan = {}, parts = {} }

	local runService = game:GetService("RunService")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.InstanceWrapper
	local InstanceWrapper = require("Utility/InstanceWrapper")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Features.Automation.EchoFarm
	local EchoFarm = require("Features/Automation/EchoFarm")

	---@module Utility.Throttle
	local throttle = require("Utility/Throttle")

	local renderStepped = Signal.new(runService.RenderStepped)

	local ownershipMaid = Maid.new()

	local function cleanParts()
		for _, maid in next, OwnershipWatcher.modelsToScan do
			maid:clean()
		end
	end

	---@param character Model
	local function onLiveAdded(character)
		if not character:IsA("Model") then
			return
		end

		if OwnershipWatcher.modelsToScan[character] then
			return
		end

		OwnershipWatcher.modelsToScan[character] = Maid.new()
	end

	---@param character Model
	local function onLiveRemoved(character)
		if not OwnershipWatcher.modelsToScan[character] then

			return
		end

		OwnershipWatcher.modelsToScan[character]:clean()
		OwnershipWatcher.modelsToScan[character] = nil
	end

	local function updateOwnership()




		---@optimization: Stop updating when we don't need it.
		if
			not Configuration.expectToggleValue("ShowOwnership")
			and not Configuration.expectToggleValue("VoidMobs")
			and not EchoFarm.voiding
		then
			return cleanParts()
		end

		local updateTable = {}

		for model, maid in next, OwnershipWatcher.modelsToScan do
			local humanoidRootPart = model:FindFirstChild("HumanoidRootPart")
			if not humanoidRootPart then
				continue
			end

			local isNetworkOwner = hasNetworkOwnership(humanoidRootPart)

			local netVisual = InstanceWrapper.create(maid, "NetworkVisual", "Part", model)
			netVisual.Size = Vector3.new(10, 10, 10)
			netVisual.Transparency = Configuration.expectToggleValue("ShowOwnership") and 0.8 or 1.0
			netVisual.Color = isNetworkOwner and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)
			netVisual.CFrame = humanoidRootPart.CFrame
			netVisual.Anchored = true
			netVisual.CanCollide = false

			local data = OwnershipWatcher.parts[humanoidRootPart]
				or {
					owned = isNetworkOwner,
					model = model,
				}

			data.owned = isNetworkOwner
			data.model = model

			OwnershipWatcher.parts[humanoidRootPart] = data

			updateTable[humanoidRootPart] = data
		end

		---@note: This will get rid of any parts that were not updated (e.g no longer existing root part or not in model list) upon cycle.
		---@todo: Fix me - this is a bit of a hack.
		OwnershipWatcher.parts = updateTable
	end

	---@return table<BasePart, table>
	function OwnershipWatcher.get()
		return OwnershipWatcher.parts
	end

	function OwnershipWatcher.init()
		local live = workspace:WaitForChild("Live")
		local liveChildAdded = Signal.new(live.ChildAdded)
		local liveChildRemoved = Signal.new(live.ChildRemoved)

		ownershipMaid:add(liveChildAdded:connect("OwnershipWatcher_OnLiveChildAdded", onLiveAdded))
		ownershipMaid:add(liveChildRemoved:connect("OwnershipWatcher_OnLiveChildRemoved", onLiveRemoved))
		ownershipMaid:add(renderStepped:connect("OwnershipWatcher_RenderStepped", throttle(1 / 20, updateOwnership)))

		for _, entity in next, live:GetChildren() do
			onLiveAdded(entity)
		end

		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("OwnershipWatcher initialized.")
		end
	end

	function OwnershipWatcher.detach()
		ownershipMaid:clean()

		cleanParts()

		Logger.warn("OwnershipWatcher detached.")
	end

	return OwnershipWatcher
end)()
end)
__bundle_register("Utility/Throttle", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Throttle
--- Wrap a per-frame callback so it runs at most once per `interval` seconds, forwarding all
--- arguments (e.g. RenderStepped's dt) straight through. Uses os.clock, so it works regardless
--- of whether the driving signal passes a delta.
---
--- Intended for PASSIVE features that don't need full framerate (attribute farms, ownership
--- scan, ...). Do NOT use it on combat/UI/movement loops -- those want every frame.
---
---@param interval number Minimum seconds between calls.
---@param fn fun(...): ...
---@return fun(...): ...?
local function throttle(interval, fn)
	local last = 0

	return function(...)
		local now = os.clock()
		if now - last < interval then
			return
		end
		last = now
		return fn(...)
	end
end

return throttle

end)
__bundle_register("Utility/InstanceWrapper", function(require, _LOADED, __bundle_register, __bundle_modules)
local InstanceWrapper = {}

local collectionService = game:GetService("CollectionService")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@param instanceMaid Maid
---@param identifier any
---@param inst Instance
---@return Instance
InstanceWrapper.mark = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, inst)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local onAncestorChange = Signal.new(inst.AncestryChanged)

	if inst:IsA("BodyVelocity") then
		collectionService:AddTag(inst, "AllowedBM")
	end

	instanceMaid[identifier] = inst
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if inst:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return inst
end)

---@param instanceMaid Maid
---@param identifier any
---@param type string
---@param parent Instance?
---@return Instance
InstanceWrapper.create = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, type, parent)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local newInstance = Instance.new(type, parent)
	local onAncestorChange = Signal.new(newInstance.AncestryChanged)

	if newInstance:IsA("BodyVelocity") then
		collectionService:AddTag(newInstance, "AllowedBM")
	end

	instanceMaid[identifier] = newInstance
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if newInstance:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return newInstance
end)

return InstanceWrapper

end)
__bundle_register("Features/Game/Spoofing", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.OriginalStoreManager
	local OriginalStoreManager = require("Utility/OriginalStoreManager")

	---@note: Replace (e.g Konga Clutch Ring Spoofer) with Talent Spoofer & Instance Spoofer in the future.
	local Spoofing = { force = false }

	local runService = game:GetService("RunService")
	local starterGui = game:GetService("StarterGui")
	local players = game:GetService("Players")
	local replicatedStorage = game:GetService("ReplicatedStorage")

	local renderStepped = Signal.new(runService.RenderStepped)

	local spoofingMaid = Maid.new()

	local infoSpoofMap = spoofingMaid:mark(OriginalStoreManager.new())

	local fakeKongaClutchRing = Instance.new("Folder")
	fakeKongaClutchRing.Name = "Ring:Konga's Clutch Ring"

	local fakeFreestylerBand = Instance.new("Folder")
	fakeFreestylerBand.Name = "Ring:Freestyler's Band"

	local lastTimestampRun = os.clock()

	local cachedEffectReplicator = nil
	local function getPassives()
		if not cachedEffectReplicator then
			local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
			if effectReplicator then
				local success, result = pcall(require, effectReplicator)
				if success then
					cachedEffectReplicator = result
				end
			end
		end
		return cachedEffectReplicator and cachedEffectReplicator.Passives
	end

	local function updateFreestylerBandSpoof(character)
		local passives = getPassives()
		if passives and not passives["Freestyler's Band"] then
			passives["Freestyler's Band"] = true
		end

		local localPlayer = players.LocalPlayer
		local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
		if backpack then
			fakeFreestylerBand.Parent = backpack
		end
	end

	local function updateKongaClutchRingSpoof(character)
		local passives = getPassives()
		if passives and not passives["Konga's Clutch Ring"] then
			passives["Konga's Clutch Ring"] = true
		end

		local localPlayer = players.LocalPlayer
		local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
		if backpack then
			fakeKongaClutchRing.Parent = backpack
		end
	end

	local function resetFreestylerBandSpoof(character)
		local passives = getPassives()
		if passives and passives["Freestyler's Band"] then
			passives["Freestyler's Band"] = nil
		end
		
		fakeFreestylerBand.Parent = nil
	end

	local function resetKongaClutchRingSpoof(character)
		local passives = getPassives()
		if passives and passives["Konga's Clutch Ring"] then
			passives["Konga's Clutch Ring"] = nil
		end

		fakeKongaClutchRing.Parent = nil
	end

	local function updateLightweightSpoof()
		local passives = getPassives()
		if passives and not passives["Lightweight"] then
			passives["Lightweight"] = true
		end
	end

	local function resetLightweightSpoof()
		local passives = getPassives()
		if passives and passives["Lightweight"] then
			passives["Lightweight"] = nil
		end
	end

	local function updateCaptainEtreaSpoof()
		local passives = getPassives()
		if passives and not passives["Captain Etrea"] then
			passives["Captain Etrea"] = true
		end
	end

	local function resetCaptainEtreaSpoof()
		local passives = getPassives()
		if passives and passives["Captain Etrea"] then
			passives["Captain Etrea"] = nil
		end
	end

	---@param instance Instance
	local function onPgDescendantAdded(instance)
		if
			instance.Name ~= "DeathID"
			and instance.Name ~= "KillerPlayer"
			and instance.Name ~= "KillerCharacter"
			and instance.Name ~= "Timestamp"
		then
			return
		end

		if not instance:IsA("TextLabel") and not instance:IsA("TextBox") then
			return
		end

		instance.Visible = not (
			Configuration.expectToggleValue("InfoSpoofing")
			and Configuration.expectToggleValue("HideDeathInformation")
		)
	end

	local function updateDeathInformationSpoof()
		local localPlayer = players.LocalPlayer
		local playerGui = localPlayer:FindFirstChild("PlayerGui")
		if not playerGui then
			return
		end

		local killGui = playerGui:FindFirstChild("KillGui")
		if not killGui then
			return
		end

		local splash = killGui:FindFirstChild("Splash")
		if not splash then
			return
		end

		for _, descendant in next, splash:GetDescendants() do
			onPgDescendantAdded(descendant)
		end
	end

	local function updateSpoofing()
		if os.clock() - lastTimestampRun <= 2.0 then
			return
		end

		lastTimestampRun = os.clock()

		if not Configuration.expectToggleValue("InfoSpoofing") then
			infoSpoofMap:restore()
		end

		updateDeathInformationSpoof()

		local player = players.LocalPlayer
		if not player then
			return
		end

		local character = player.Character
		if not character then
			return
		end

		if Configuration.expectToggleValue("FreestylersBandSpoof") then
			updateFreestylerBandSpoof(character)
		else
			resetFreestylerBandSpoof(character)
		end

		if Configuration.expectToggleValue("KongaClutchRingSpoof") then
			updateKongaClutchRingSpoof(character)
		else
			resetKongaClutchRingSpoof(character)
		end

		if Configuration.expectToggleValue("LightweightSpoof") then
			updateLightweightSpoof()
		else
			resetLightweightSpoof()
		end

		if Configuration.expectToggleValue("CaptainEtreaSpoof") then
			updateCaptainEtreaSpoof()
		else
			resetCaptainEtreaSpoof()
		end
	end

	---@param value string
	function Spoofing.sgv(value)
		if not Configuration.expectToggleValue("InfoSpoofing") then
			return
		end

		local player = players.LocalPlayer
		if not player then
			return
		end

		local playerGui = player:FindFirstChild("PlayerGui")
		if not playerGui then
			return
		end

		local topBarGui = playerGui:FindFirstChild("TopbarGui")
		local container = topBarGui and topBarGui:FindFirstChild("Container")
		local infoFrame = container and container:FindFirstChild("InfoFrame")
		local gameInfo = infoFrame and infoFrame:FindFirstChild("GameInfo")
		if not gameInfo then
			return
		end

		local gameVersionLabel = gameInfo:FindFirstChild("GameVersion")
		if not gameVersionLabel then
			return
		end

		infoSpoofMap:add(gameVersionLabel, "Text", value)
	end

	---@param value string
	function Spoofing.sds(value)
		if not Configuration.expectToggleValue("InfoSpoofing") then
			return
		end

		local player = players.LocalPlayer
		if not player then
			return
		end

		local playerGui = player:FindFirstChild("PlayerGui")
		if not playerGui then
			return
		end

		local topBarGui = playerGui:FindFirstChild("TopbarGui")
		local container = topBarGui and topBarGui:FindFirstChild("Container")
		local infoFrame = container and container:FindFirstChild("InfoFrame")
		local worldInfoFrame = infoFrame and infoFrame:FindFirstChild("WorldInfo")
		if not worldInfoFrame then
			return
		end

		local dateLabel = worldInfoFrame:FindFirstChild("Date")
		if not dateLabel then
			return
		end

		infoSpoofMap:add(dateLabel, "Text", value)
	end

	---@param value string
	function Spoofing.sss(value)
		if not Configuration.expectToggleValue("InfoSpoofing") then
			return
		end

		local player = players.LocalPlayer
		if not player then
			return
		end

		local playerGui = player:FindFirstChild("PlayerGui")
		if not playerGui then
			return
		end

		local topBarGui = playerGui:FindFirstChild("TopbarGui")
		local container = topBarGui and topBarGui:FindFirstChild("Container")
		local infoFrame = container and container:FindFirstChild("InfoFrame")
		local characterInfo = infoFrame and infoFrame:FindFirstChild("CharacterInfo")
		if not characterInfo then
			return
		end

		local slotLabel = characterInfo:FindFirstChild("Slot")
		if not slotLabel then
			return
		end

		infoSpoofMap:add(slotLabel, "Text", value)
	end

	---@param instance Instance
	---@param attribute string
	function Spoofing.facs(instance, attribute)
		local original = instance:GetAttribute(attribute)
		instance:SetAttribute(attribute, "SPOOFING_RICS")
		instance:SetAttribute(attribute, original)
	end

	---@param instance ValueBase
	function Spoofing.fvcs(instance)
		local original = instance.Value
		instance.Value = "SPOOFING_RICS"
		instance.Value = original
	end

	---@note: Attempts to trigger them w/o using 'firesignal' or 'getconnections' because they crash.
	function Spoofing.rics()
		for _, player in next, players:GetPlayers() do
			Spoofing.facs(player, "Guild")
			Spoofing.facs(player, "FirstName")
			Spoofing.facs(player, "LastName")

			local character = player.Character
			if not character then
				continue
			end

			Spoofing.facs(character, "GuildRich")

			local humanoid = character:FindFirstChild("Humanoid")
			if not humanoid then
				continue
			end

			Spoofing.facs(humanoid, "CharacterName")
		end

		local serverRegion = replicatedStorage:FindFirstChild("SERVER_REGION")
		local serverName = replicatedStorage:FindFirstChild("SERVER_NAME")
		local serverAge = replicatedStorage:FindFirstChild("SERVER_AGE")

		if not serverRegion or not serverName or not serverAge then
			return
		end

		Spoofing.fvcs(serverRegion)
		Spoofing.fvcs(serverName)

		local original = serverAge.Value
		serverAge.Value = "L"
		serverAge.Value = original
	end

	-- PR streamer_mode's server-info spoof: WRITE the values directly and re-apply them whenever the game
	-- changes them (.Changed), instead of intercepting the .Value READ through the now-removed __index hook.
	local function hookServerValue(valueInstance, getSpoofed)
		if not valueInstance then
			return
		end
		local function apply()
			if Spoofing.force or not Configuration.expectToggleValue("InfoSpoofing") then
				return
			end
			local spoofed = getSpoofed()
			if spoofed ~= nil and valueInstance.Value ~= spoofed then
				valueInstance.Value = spoofed
			end
		end
		spoofingMaid:add(valueInstance.Changed:Connect(apply))
		apply()
	end

	function Spoofing.init()
		local localPlayer = players.LocalPlayer
		local playerGui = localPlayer:WaitForChild("PlayerGui")
		local pgDescendantAdded = Signal.new(playerGui.DescendantAdded)

		spoofingMaid:add(renderStepped:connect("Spoofing_OnRenderStepped", updateSpoofing))
		spoofingMaid:add(pgDescendantAdded:connect("Spoofing_OnPGDescendantAdded", onPgDescendantAdded))

		-- Server-info spoof the PR way (direct writes + .Changed re-apply), replacing the dropped __index reads.
		pcall(function()
			hookServerValue(replicatedStorage:WaitForChild("SERVER_NAME", 10), function()
				return Configuration.expectOptionValue("SpoofedServerName")
			end)
			hookServerValue(replicatedStorage:WaitForChild("SERVER_REGION", 10), function()
				return Configuration.expectOptionValue("SpoofedServerRegion")
			end)
			hookServerValue(replicatedStorage:WaitForChild("SERVER_AGE", 10), function()
				return Configuration.expectOptionValue("SpoofedServerAge")
			end)
		end)

		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("Spoofing initialized.")
		end
	end

	function Spoofing.detach()
		Spoofing.force = true

		spoofingMaid:clean()

		Spoofing.rics()

		fakeFreestylerBand.Parent = nil
		fakeKongaClutchRing.Parent = nil
		resetLightweightSpoof()
		resetCaptainEtreaSpoof()

		Logger.warn("Spoofing detached.")
	end

	return Spoofing
end)()

end)
__bundle_register("Utility/OriginalStoreManager", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.OriginalStore
local OriginalStore = require("Utility/OriginalStore")

---@class OriginalStoreManager
---@param inner OriginalStore[]
local OriginalStoreManager = {}
OriginalStoreManager.__index = OriginalStoreManager

---@param data table|Instance
OriginalStoreManager.forget = LPH_NO_VIRTUALIZE(function(self, data)
	self.inner[data] = nil
end)

---@param data table|Instance
---@param index any
OriginalStoreManager.mark = LPH_NO_VIRTUALIZE(function(self, data, index)
	local object = self.inner[data] or OriginalStore.new()

	object:mark(data, index)

	self.inner[data] = object
end)

---@param data table|Instance
---@param index any
---@param value any
OriginalStoreManager.add = LPH_NO_VIRTUALIZE(function(self, data, index, value)
	local object = self.inner[data] or OriginalStore.new()

	object:set(data, index, value)

	self.inner[data] = object
end)

---@return OriginalStore[]
OriginalStoreManager.data = LPH_NO_VIRTUALIZE(function(self)
	return self.inner
end)

---@param data table|Instance
---@return OriginalStore
OriginalStoreManager.get = LPH_NO_VIRTUALIZE(function(self, data)
	return self.inner[data]
end)

OriginalStoreManager.restore = LPH_NO_VIRTUALIZE(function(self)
	for _, store in next, self.inner do
		store:restore()
	end
end)

OriginalStoreManager.detach = LPH_NO_VIRTUALIZE(function(self)
	for _, store in next, self.inner do
		store:detach()
	end

	self.inner = {}
end)

---@return OriginalStoreManager
OriginalStoreManager.new = LPH_NO_VIRTUALIZE(function()
	local self = setmetatable({}, OriginalStoreManager)
	self.inner = {}
	return self
end)

return OriginalStoreManager

end)
__bundle_register("Features/Game/Monitoring", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.OriginalStore
	local OriginalStore = require("Utility/OriginalStore")

	---@module Utility.OriginalStoreManager
	local OriginalStoreManager = require("Utility/OriginalStoreManager")

	---@module Utility.CoreGuiManager
	local CoreGuiManager = require("Utility/CoreGuiManager")

	---@module Utility.TaskSpawner
	local TaskSpawner = require("Utility/TaskSpawner")

	---@module Utility.JSON
	local JSON = require("Utility/JSON")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.Finder
	local Finder = require("Utility/Finder")

	---@module Game.LeaderboardClient
	local LeaderboardClient = require("Game/LeaderboardClient")

	local Monitoring = { subject = nil, seen = {}, proximityLastSeen = {} }

	-- A player must be out of range this long before their proximity notification is dismissed. Stops the
	-- alert re-firing when Finder.gpir briefly drops a still player (HRP streaming / range-boundary jitter).
	local PROXIMITY_GRACE = 2

	local runService = game:GetService("RunService")
	local players = game:GetService("Players")

	local renderStepped = Signal.new(runService.RenderStepped)

	local monitoringMaid = Maid.new()
	local spectateMaid = Maid.new()
	local buildStealMaid = Maid.new()
	local hairStealMaid = Maid.new()
	local plwMaid = Maid.new()

	local beepSound = CoreGuiManager.imark(Instance.new("Sound"))

	local lastUpdateTime = os.clock()

	local cameraSubject = spectateMaid:mark(OriginalStore.new())

	local showHiddenMap = spectateMaid:mark(OriginalStoreManager.new())

	local function fetchName(player)
		local spoofName = Configuration.expectToggleValue("InfoSpoofing")
			and Configuration.expectToggleValue("SpoofOtherPlayers")

		return spoofName and "[REDACTED]"
			or string.format("(%s) %s", player:GetAttribute("CharacterName") or "Unknown Character Name", player.Name)
	end

	---@param player Player
	---@param input InputObject
	local function onWhitelistingInputBegan(player, input)
		if input.KeyCode ~= Enum.KeyCode.L then
			return
		end

		local usernameList = Options["UsernameList"]
		if not usernameList then
			return
		end

		local whitelisted = usernameList.Values
		if not whitelisted then
			return
		end

		local whitelistIndex = table.find(whitelisted, player.Name)

		if whitelistIndex then
			whitelisted[whitelistIndex] = nil

			Logger.notify("Removed player '%s' from the whitelist.", fetchName(player))
		else
			whitelisted[#whitelisted + 1] = player.Name

			Logger.notify("Added player '%s' to the whitelist.", fetchName(player))
		end

		usernameList:SetValues(whitelisted)
		usernameList:SetValue({})
		usernameList:Display()
	end

	---@param player Player
	---@param input InputObject
	local function onSpectateInputBegan(player, input)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		local usedName = fetchName(player)

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return Logger.notify("Failed to spectate '%s' because the local player does not exist.", usedName)
		end

		local character = player.Character
		if not character then
			return Logger.notify("Failed to spectate '%s' because their character does not exist.", usedName)
		end

		local mapPosition = character:GetAttribute("MapPos")
		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")

		if mapPosition and not humanoidRootPart then
			spectateMaid:add(
				TaskSpawner.spawn(
					"Monitoring_RequestStreamMapPos",
					players.LocalPlayer.RequestStreamAroundAsync,
					players.LocalPlayer,
					mapPosition,
					0.1
				)
			)

			return Logger.notify("Requesting stream for unloaded character '%s' - try again later.", usedName)
		end

		if not humanoidRootPart then
			return Logger.notify("Failed to spectate '%s' because they are not loaded in.", usedName)
		end

		local shouldUpdateSubject = Monitoring.subject ~= humanoidRootPart and players.LocalPlayer ~= player

		Monitoring.subject = shouldUpdateSubject and humanoidRootPart or nil

		if shouldUpdateSubject then
			Logger.notify("Started spectating player %s.", usedName)
		else
			Logger.notify("Reset spectating camera subject.")
		end
	end

	---@param player Player
	local function onBuildStealPlayer(player)
		local character = player.Character
		if not character then
			return Logger.notify(
				"Failed to steal build from '%s' because their character does not exist.",
				fetchName(player)
			)
		end

		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return Logger.notify(
				"Failed to steal build from '%s' because their humanoid does not exist.",
				fetchName(player)
			)
		end

		local backpack = player:FindFirstChild("Backpack")
		if not backpack then
			return Logger.notify(
				"Failed to steal build from '%s' because their backpack does not exist.",
				fetchName(player)
			)
		end

		local AttributePoints = 0
		local Power = 0
		for i, v in pairs(character:GetAttributes()) do
			if i:match("Stat") then
				AttributePoints = AttributePoints + v
			end
		end
		for i = 1, 20 do
			if AttributePoints <= 15 then
				break
			end
			AttributePoints = AttributePoints - 15
			Power = Power + 1
		end
		local level = math.min(20, math.max(1, Power))

		local data = {
			version = 3,
			stats = {
				buildName = string.format("%s %s's Stolen Build", os.date("%B %d %Y"), player.Name),
				buildDescription = "Talents are not stealable anymore - this is just the opponent's stats. Preshrine will need to be solved for.",
				buildAuthor = ".gg/lyc",
				power = level,
				pointsUntilNextPower = 67,
				points = 67,
				pointSpent = 67,
				traitPoints = 0,
				traits = {
					Vitality = character:GetAttribute("Trait_Health"),
					Erudition = character:GetAttribute("Trait_Ether"),
					Songchant = character:GetAttribute("Trait_MantraDamage"),
					Proficiency = character:GetAttribute("Trait_WeaponDamage"),
				},
				meta = {
					Race = "None",
					Oath = "None",
					Murmur = "None",
					Bell = "None",
					Origin = "Castaway",
					Outfit = "None",
				},
			},
			attributes = {
				weapon = {
					["Heavy Wep."] = character:GetAttribute("Stat_WeaponHeavy"),
					["Medium Wep."] = character:GetAttribute("Stat_WeaponMedium"),
					["Light Wep."] = character:GetAttribute("Stat_WeaponLight"),
				},
				base = {
					Strength = character:GetAttribute("Stat_Strength"),
					Fortitude = character:GetAttribute("Stat_Fortitude"),
					Agility = character:GetAttribute("Stat_Agility"),
					Intelligence = character:GetAttribute("Stat_Intelligence"),
					Willpower = character:GetAttribute("Stat_Willpower"),
					Charisma = character:GetAttribute("Stat_Charisma"),
				},
				attunement = {
					Flamecharm = character:GetAttribute("Stat_ElementFire"),
					Frostdraw = character:GetAttribute("Stat_ElementIce"),
					Thundercall = character:GetAttribute("Stat_ElementLightning"),
					Galebreathe = character:GetAttribute("Stat_ElementWind"),
					Shadowcast = character:GetAttribute("Stat_ElementShadow"),
					Ironsing = character:GetAttribute("Stat_ElementMetal"),
					Bloodrend = character:GetAttribute("Stat_ElementBlood"),
				},
			},
			content = {
				mantraModifications = {},
				notes = "",
			},
			meta = {
				tags = {},
				isPrivate = true,
			},
			talents = {},
			mantras = {},
			weapons = "",
			enchant = "",
			motif = "",
			preShrine = {
				base = {
					Strength = 100,
					Fortitude = 100,
					Agility = 100,
					Intelligence = 100,
					Willpower = 100,
					Charisma = 100,
				},
				weapon = {
					["Heavy Wep."] = 100,
					["Medium Wep."] = 100,
					["Light Wep."] = 100,
				},
				attunement = {
					Flamecharm = 100,
					Frostdraw = 100,
					Thundercall = 100,
					Galebreathe = 100,
					Shadowcast = 100,
					Ironsing = 100,
					Bloodrend = 100,
				},
			},
			postShrine = nil,
			favoritedTalents = {},
		}

		data.postShrine = data.attributes

		local meta = data.stats.meta
		local notes = {}

		for _, child in next, backpack:GetChildren() do
			if child.Name:match("Resonance:") then
				meta.Bell = child.Name:gsub("Resonance:", "")
			end

			if child.Name:match("Mantra") and child:GetAttribute("DisplayName") then
				local isRecalled = child.Name:match("RecalledMantra")
				notes[#notes + 1] = (isRecalled and "[RECALLED MANTRA]" or "[USED MANTRA]")
					.. " "
					.. (child:GetAttribute("RichStats") and child:GetAttribute("RichStats"):gsub("\n", " | ") or "NO RICH STATS?")

				if not isRecalled then
					data.mantras[#data.mantras + 1] = child:GetAttribute("DisplayName")
					data.content.mantraModifications[child:GetAttribute("DisplayName")] = {}
				end
			end

			if child.Name == "Weapon" then
				notes[#notes + 1] = "[USED WEAPON] " .. (child:GetAttribute("RichStats") and child:GetAttribute("RichStats"):gsub("\n", " | ") or child.Name)
			end
		end

		for _, instance in next, character:GetChildren() do
			if instance.Name == "Ring" then
				local ringName = instance:GetAttribute("DisplayName")
					or instance:GetAttribute("EquipmentRef")
					or instance.Name
				notes[#notes + 1] = string.format("[EQUIPPED RING] %s\n", ringName)
					.. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | ") or instance.Name)
			end

			if instance.Name == "Shirt" then
				notes[#notes + 1] = "[EQUIPPED SHIRT ID] " .. instance.ShirtTemplate
			end

			if instance.Name == "Pants" then
				notes[#notes + 1] = "[EQUIPPED PANTS ID] " .. instance.PantsTemplate
			end

			if
				instance.Name:match("Equipment")
				and instance:GetAttribute("RichStats")
				and instance:GetAttribute("DisplayName")
			then
				notes[#notes + 1] = string.format(
					"[EQUIPPED EQUIPMENT] [%s] %s",
					instance.Name,
					instance:GetAttribute("DisplayName")
				) .. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | ") or "")
			end
		end

		notes[#notes + 1] = string.format("[HEALTH] %.2f/%.2f", humanoid.Health, humanoid.MaxHealth)

		data.content.notes = table.concat(notes, "\n\n")

		local response = request({
			Url = "https://new.deepwoken.co/api/proxy/builds",
			Method = "POST",
			Headers = {
				["Content-Type"] = "application/json",
				["Accept"] = "application/json",
				["Origin"] = "https://deepwoken.co",
				["Referer"] = "https://deepwoken.co/builder",
				["Sec-Fetch-Site"] = "same-origin",
				["Sec-Fetch-Mode"] = "cors",
				["Sec-Fetch-Dest"] = "empty",
			},
			Body = JSON.encode(data),
		})

		if not response then
			return Logger.notify("Failed to steal build from '%s' due to no response.", fetchName(player))
		end

		if not response.Success then
			return Logger.notify(
				"(Status %i) Failed to steal build from '%s' due to build creation failure.",
				response.StatusCode,
				fetchName(player)
			)
		end

		if not response.Body then
			return Logger.notify("Failed to steal build from '%s' due to no response body.", fetchName(player))
		end

		local decoded = JSON.decode(response.Body)

		if not decoded or not decoded.id then
			return Logger.notify(
				"(Status %i) Failed to steal build from '%s' due to invalid response body.",
				response.StatusCode,
				fetchName(player)
			)
		end

		local buildUrl = string.format("https://deepwoken.co/builder?id=%s", decoded.id)
		setclipboard(buildUrl)

		local path = string.format("%s %s Stolen Build", os.date("%B %d %Y"), player.Name)
		Logger.notify("Successfully stole %s's build, %s & saved to file.", fetchName(player), buildUrl)

		if not isfolder("Aero/Stolen Builds") then
			makefolder("Aero/Stolen Builds")
		end
		
		writefile("Aero/Stolen Builds/" .. path .. ".txt", string.format([[.gg/lyc
stolen on %s
build url: %s
%s]], os.date("%B %d %Y"), buildUrl, data.content.notes))
	end

	local function onHairStealPlayer(player)
		local character = player.Character
		if not character then
			return Logger.notify(
				"Failed to steal hair IDs from '%s' because their character does not exist.",
				fetchName(player)
			)
		end

		local hairIds = {}
		local seen = {}

		for _, instance in next, character:GetDescendants() do
			if not instance:IsA("Accessory") then
				continue
			end

			local isHairSlot = instance.AccessoryType == Enum.AccessoryType.Hair
			if not isHairSlot then
				local handle = instance:FindFirstChild("Handle")
				isHairSlot = handle ~= nil and handle:FindFirstChild("HairAttachment") ~= nil
			end

			if not isHairSlot then
				continue
			end

			local id = instance.Name:match("^Asset:(%d+)$") or instance.Name:match("(%d+)")
			if id and not seen[id] then
				seen[id] = true
				table.insert(hairIds, id)
			end
		end

		if #hairIds == 0 then
			return Logger.notify("Failed to find any hair IDs for '%s'.", fetchName(player))
		end

		setclipboard(table.concat(hairIds, ", "))
		Logger.notify("Successfully stole %s's hair ID(s) & copied to clipboard.", fetchName(player))
	end

	local function updateBuildStealing()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan_Steal_%s", player.Name)

			if buildStealMaid[frame] then
				continue
			end

			buildStealMaid[frame] = inputBegan:connect(label, function(input)
				if input.KeyCode ~= Enum.KeyCode.P then
					return
				end

				onBuildStealPlayer(player)
			end)
		end
	end

	local function updateHairStealing()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan_HairSteal_%s", player.Name)

			if hairStealMaid[frame] then
				continue
			end

			hairStealMaid[frame] = inputBegan:connect(label, function(input)
				if input.KeyCode ~= Enum.KeyCode.O then
					return
				end

				onHairStealPlayer(player)
			end)
		end
	end

	local function updatePlayerListWhitelisting()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan_PLW_%s", player.Name)

			if plwMaid[frame] then
				continue
			end

			plwMaid[frame] = inputBegan:connect(label, function(input)
				onWhitelistingInputBegan(player, input)
			end)
		end
	end

	local function updateSpectating()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan%s", player.Name)

			if Configuration.expectToggleValue("ShowHiddenPlayers") then
				showHiddenMap:add(frame, "Visible", true)
			end

			if spectateMaid[frame] then
				continue
			end

			spectateMaid[frame] = inputBegan:connect(label, function(input)
				onSpectateInputBegan(player, input)
			end)
		end
	end

	local function updatePlayerProximity()
		local proximityRange = Configuration.expectOptionValue("PlayerProximityRange") or 350
		local playersInRange = Finder.gpir(proximityRange)
		if not playersInRange then
			return
		end

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		local now = os.clock()

		-- Refresh the last-in-range stamp for everyone currently in range.
		for _, player in next, playersInRange do
			Monitoring.proximityLastSeen[player] = now
		end

		-- Dismiss a player's notification only after they've been out of range for the full grace window.
		-- A one-cycle drop-out keeps the notification up, so returning doesn't re-fire a fresh "entered".
		for player, removeNotification in next, Monitoring.seen do
			local isInPlayerRange = table.find(playersInRange, player)
			if isInPlayerRange then
				continue
			end

			if now - (Monitoring.proximityLastSeen[player] or 0) <= PROXIMITY_GRACE then
				continue
			end

			removeNotification()

			Monitoring.seen[player] = nil
			Monitoring.proximityLastSeen[player] = nil
		end

		for _, player in next, playersInRange do
			if Monitoring.seen[player] ~= nil then
				continue
			end

			if
				Configuration.expectToggleValue("PlayerProximityVW")
				and not backpack:FindFirstChild("Talent:Voidwalker Contract")
			then
				continue
			end

			Monitoring.seen[player] =
				Logger.mnnotify("%s entered your proximity radius of %i studs.", fetchName(player), proximityRange)

			if Configuration.expectToggleValue("PlayerProximityBeep") then
				beepSound.SoundId = "rbxassetid://100849623977896"
				beepSound.PlaybackSpeed = 1
				beepSound.Volume = Configuration.expectOptionValue("PlayerProximityBeepVolume") or 0.1
				beepSound:Play()
			end
		end
	end

	local function updateSubjectMonitoring()
		cameraSubject:set(workspace.CurrentCamera, "CameraSubject", Monitoring.subject)

		if Monitoring.subject ~= nil then
			players.LocalPlayer:AddTag("ForcedSubject")
		else
			players.LocalPlayer:RemoveTag("ForcedSubject")
		end
		-- The spectate stream request is NOT done here any more -- it runs on its own throttled connection in
		-- Monitoring.init, exactly like Project Rain's leaderboard_spectate (inline, never a per-frame spawn).
	end

	local function updateMonitoring()
		if Monitoring.subject then
			updateSubjectMonitoring()
		else
			cameraSubject:restore()
		end

		if os.clock() - lastUpdateTime <= 2.0 then
			return
		end

		lastUpdateTime = os.clock()

		if Configuration.expectToggleValue("PlayerListWhitelisting") then
			updatePlayerListWhitelisting()
		else
			plwMaid:clean()
		end

		if Configuration.expectToggleValue("BuildStealer") then
			updateBuildStealing()
		else
			buildStealMaid:clean()
		end

		if Configuration.expectToggleValue("HairStealer") then
			updateHairStealing()
		else
			hairStealMaid:clean()
		end

		if Configuration.expectToggleValue("PlayerSpectating") then
			updateSpectating()
		else
			spectateMaid:clean()
		end

		if Configuration.expectToggleValue("PlayerProximity") then
			updatePlayerProximity()
		end
	end

	function Monitoring.init()
		monitoringMaid:add(renderStepped:connect("Monitoring_OnRenderStepped", updateMonitoring))

		-- Project Rain's leaderboard_spectate streaming, verbatim in structure: a dedicated RenderStepped loop
		-- that, while a subject is set, calls RequestStreamAroundAsync INLINE in a pcall at most every 0.25s.
		-- PR issues one request per 0.25s on this one connection and lets it return before the next -- so at
		-- most ~one is ever in flight. (aero's old code wrapped it in TaskSpawner.spawn + maid:add EVERY frame,
		-- which piled thousands of parked requests into the fiber pool -> "RSL - panic: failed to spawn a fiber".)
		local lastStreamRequest = tick()
		monitoringMaid:add(renderStepped:connect("Monitoring_StreamSpectate", function()
			if tick() - lastStreamRequest < 0.25 or Monitoring.subject == nil then
				return
			end
			lastStreamRequest = tick()
			pcall(function()
				players.LocalPlayer:RequestStreamAroundAsync(Monitoring.subject.Position, 1000)
			end)
		end))

		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("Monitoring initialized.")
		end
	end

	function Monitoring.detach()
		monitoringMaid:clean()
		buildStealMaid:clean()
		hairStealMaid:clean()
		spectateMaid:clean()
		plwMaid:clean()
		showHiddenMap:restore()

		local refreshLeaderboard = LeaderboardClient.glrf()

		if refreshLeaderboard then
			refreshLeaderboard()
		end

		Logger.warn("Monitoring detached.")
	end

	return Monitoring
end)()

end)
__bundle_register("Game/LeaderboardClient", function(require, _LOADED, __bundle_register, __bundle_modules)
local LeaderboardClient = { calling = false }

local players = game:GetService("Players")

local cachedUpvaluesTable = nil
local cachedUpvaluesFunction = nil
local lastDataCacheTime = os.clock()
local lastFunctionCacheTime = os.clock()

---@param func function?
---@return boolean
local function filterFunction(func)
	if not func or not islclosure(func) then
		return false
	end

	local info = debug.getinfo(func)
	if info.name ~= nil and info.name ~= "" then
		return false
	end

	local constants = debug.getconstants(func)
	if #constants ~= 1 or constants[1] ~= "Destroy" then
		return false
	end

	local upvalues = debug.getupvalues(func)
	if not upvalues then
		return false
	end

	return true
end

---@return function?
function LeaderboardClient.glrf()
	if cachedUpvaluesFunction and os.clock() - lastFunctionCacheTime <= 2.0 then
		return cachedUpvaluesFunction
	end

	for _, con in next, getconnections(players.PlayerRemoving) do
		local func = con.Function
		if not filterFunction(func) then
			continue
		end

		local upvalues = debug.getupvalues(func)
		if not upvalues then
			continue
		end

		local upvaluesFunction = upvalues[2]

		cachedUpvaluesFunction = upvaluesFunction
		lastFunctionCacheTime = os.clock()

		return function()
			if LeaderboardClient.calling then
				return
			end

			LeaderboardClient.calling = true

			upvaluesFunction()

			LeaderboardClient.calling = false
		end
	end

	return nil
end

---@return table?
function LeaderboardClient.gld()
	if cachedUpvaluesTable and os.clock() - lastDataCacheTime <= 2.0 then
		return cachedUpvaluesTable
	end

	for _, con in next, getconnections(players.PlayerRemoving) do
		local func = con.Function
		if not filterFunction(func) then
			continue
		end

		local upvalues = debug.getupvalues(func)
		if not upvalues then
			continue
		end

		local upvaluesTable = upvalues[1]

		cachedUpvaluesTable = upvaluesTable
		lastDataCacheTime = os.clock()

		return upvaluesTable
	end

	return nil
end

return LeaderboardClient

end)
__bundle_register("Features/Game/Removal", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Removal = {}

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Game.KeyHandling
	local KeyHandling = require("Game/KeyHandling")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.OriginalStoreManager
	local OriginalStoreManager = require("Utility/OriginalStoreManager")

	---@module Utility.OriginalStore
	local OriginalStore = require("Utility/OriginalStore")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Game.EffectDispatcher
	local EffectDispatcher = require("Game/EffectDispatcher")

	local runService = game:GetService("RunService")
	local players = game:GetService("Players")
	local replicatedStorage = game:GetService("ReplicatedStorage")
	local lighting = game:GetService("Lighting")
	local debris = game:GetService("Debris")
	local collectionService = game:GetService("CollectionService")

	local removalMaid = Maid.new()

	local originalAcidRemote = nil
	local placeholderRemote = Instance.new("RemoteEvent")
	placeholderRemote.Name = "AcidRemote"

	local noShadows = removalMaid:mark(OriginalStore.new())
	local noBlur = removalMaid:mark(OriginalStore.new())
	local noOverlay = removalMaid:mark(OriginalStore.new())

	local echoModifiersMap = removalMaid:mark(OriginalStoreManager.new())
	local noFogMap = removalMaid:mark(OriginalStoreManager.new())
	local killBricksMap = removalMaid:mark(OriginalStoreManager.new())
	local damageBricksMap = removalMaid:mark(OriginalStoreManager.new())
	local lightBarrierMap = removalMaid:mark(OriginalStoreManager.new())
	local yunShulBarrierMap = removalMaid:mark(OriginalStoreManager.new())
	local yunShulResonanceDoorMap = removalMaid:mark(OriginalStoreManager.new())
	local hiveGateMap = removalMaid:mark(OriginalStoreManager.new())
	local statVFXMap = removalMaid:mark(OriginalStoreManager.new())

	local renderStepped = Signal.new(runService.RenderStepped)
	local workspaceDescendantAdded = Signal.new(workspace.DescendantAdded)
	local workspaceDescendantRemoving = Signal.new(workspace.DescendantRemoving)

	local lastUpdate = os.clock()
	local lastNoKillBricksUpdate = 0
	local noKillBricksWasEnabled = false
	local lastWindEffectTimestamp = os.clock()
	local lastBlindUpdate = os.clock()

	---@param localPlayer Player
	local function updateNoEchoModifiers(localPlayer)
		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		for _, instance in pairs(backpack:GetChildren()) do
			if not instance.Name:match("EchoMod") then
				continue
			end

			echoModifiersMap:add(instance, "Parent", nil)
		end
	end

	local function updateNoHiveGate()
		for _, store in next, hiveGateMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "Parent", nil)
		end
	end

	local function updateNoKillBricks()
		for _, store in next, killBricksMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "CFrame", CFrame.new(math.huge, math.huge, math.huge))
		end
	end

	local function updateNoKillBricksPersistent()
		local now = os.clock()
		if now - lastNoKillBricksUpdate < 0.1 then
			return
		end
		lastNoKillBricksUpdate = now

		if Configuration.expectToggleValue("NoKillBricks") then
			updateNoKillBricks()
			noKillBricksWasEnabled = true
		elseif noKillBricksWasEnabled then
			killBricksMap:restore()
			noKillBricksWasEnabled = false
		end
	end

	local function updateNoLightBarrier()
		for _, store in next, lightBarrierMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "CFrame", CFrame.new(math.huge, math.huge, math.huge))
		end
	end

	-- PR's no fog: push FogEnd far out and zero the Atmosphere density (leave FogStart alone). Routed
	-- through noFogMap so toggling NoFog off restores the game's original values.
	local function updateNoFog()
		if lighting.FogEnd ~= 1000000 then
			noFogMap:add(lighting, "FogEnd", 1000000)
		end

		local atmosphere = lighting:FindFirstChildOfClass("Atmosphere")
		if atmosphere and atmosphere.Density ~= 0 then
			noFogMap:add(atmosphere, "Density", 0)
		end
	end

	local function clearBlindGui(localPlayer)
		local playerGui = localPlayer:FindFirstChild("PlayerGui")
		if not playerGui then
			return
		end

		for _, gui in next, playerGui:GetChildren() do
			if gui.Name == "AshBlind" or gui.Name == "AshVision" or gui.Name == "AshDecaying" then
				gui:Destroy()
			end
		end
	end

	-- Blind passives that we've removed, so we can put them back.
	local BLIND_PASSIVES = { "Blinded", "Blind" }
	local removedBlindPassives = {}

	---Get the EffectReplicator passives table.
	---@return table?
	local function getPassives()
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		if not effectReplicator then
			return nil
		end

		local effectReplicatorModule = require(effectReplicator)
		return effectReplicatorModule and effectReplicatorModule.Passives
	end

	local function updateNoBlind()
		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		clearBlindGui(localPlayer)

		---@note: EffectClient treats us as blinded if Passives.Blinded or Passives.Blind is set.
		local passives = getPassives()
		if not passives then
			return
		end

		for _, name in next, BLIND_PASSIVES do
			local value = passives[name]
			if value == nil then
				continue
			end

			removedBlindPassives[name] = value
			passives[name] = nil
		end
	end

	local function resetNoBlind()
		if not next(removedBlindPassives) then
			return
		end

		local passives = getPassives()
		if passives then
			for name, value in next, removedBlindPassives do
				if passives[name] == nil then
					passives[name] = value
				end
			end
		end

		table.clear(removedBlindPassives)
	end

	local function updateNoBlur()
		local genericBlur = lighting:FindFirstChild("GenericBlur")
		if not genericBlur then
			return
		end

		local underwaterBlur = lighting:FindFirstChild("UnderwaterBlur")
		if not underwaterBlur then
			return
		end

		noBlur:set(genericBlur, "Size", 0.0)
		noBlur:set(underwaterBlur, "Size", 0.0)
	end

	---@param localPlayer Player
	local function updateNoSanityVFX(localPlayer)
		for _, object in next, collectionService:GetTagged("StatVFX") do
			if object.Parent == replicatedStorage then
				continue
			end

			statVFXMap:add(object, "Parent", replicatedStorage)
		end

		local playerGui = localPlayer:FindFirstChild("PlayerGui")
		if not playerGui then
			return
		end

		local overlayGui = playerGui:FindFirstChild("OverlayGui")
		if not overlayGui then
			return
		end

		noOverlay:set(overlayGui, "Enabled", false)
	end

	local function updateNoYunShulBarrier()
		for _, store in next, yunShulBarrierMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "CFrame", CFrame.new(math.huge, math.huge, math.huge))
		end

		for _, store in next, yunShulResonanceDoorMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "Parent", nil)
		end
	end

	local function updateNoAcidWater()
		if originalAcidRemote then
			return
		end

		local requests = replicatedStorage:FindFirstChild("Requests")
		if not requests then
			return
		end

		local acidRemote = requests:FindFirstChild("AcidRemote")
		if not acidRemote then
			return
		end

		originalAcidRemote = acidRemote
		originalAcidRemote.Name = "AcidRemote_Original"
		placeholderRemote.Parent = requests
	end

	local function restoreNoAcidWater()
		if not originalAcidRemote then
			return
		end

		originalAcidRemote.Name = "AcidRemote"
		placeholderRemote.Parent = nil
	end
	
	local function updateNoDamageBricks()
		for _, store in next, damageBricksMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "Parent", nil)
		end
	end

	local function restoreNoDamageBricks()
		damageBricksMap:restore()
		for _,v in next, game:GetService("CollectionService"):GetTagged("DamageBrick") do
			v:Destroy()
		end
	end

	-- PR's no-blind cadence: re-strip the Blind/Blinded passives every 0.5s (instead of riding the 3s
	-- removal loop) so a re-applied blind clears almost instantly rather than lingering up to 3s.
	local function updateNoBlindFast()
		if os.clock() - lastBlindUpdate <= 0.5 then
			return
		end
		lastBlindUpdate = os.clock()

		if Configuration.expectToggleValue("NoBlind") then
			updateNoBlind()
		else
			resetNoBlind()
		end
	end

	local function updateRemoval()
		if os.clock() - lastUpdate <= 3.0 then
			return
		end

		lastUpdate = os.clock()

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		if Configuration.expectToggleValue("NoFog") then
			updateNoFog()
		else
			noFogMap:restore()
		end

		if Configuration.expectToggleValue("NoEchoModifiers") then
			updateNoEchoModifiers(localPlayer)
		else
			echoModifiersMap:restore()
		end

		if Configuration.expectToggleValue("NoKillBricks") then
			updateNoKillBricks()
		else
			killBricksMap:restore()
		end
		
		if Configuration.expectToggleValue("NoDamageBricks") then
			updateNoDamageBricks()
		else
			restoreNoDamageBricks()
		end

		if Configuration.expectToggleValue("NoHiveGate") then
			updateNoHiveGate()
		else
			hiveGateMap:restore()
		end

		if Configuration.expectToggleValue("NoCastleLightBarrier") then
			updateNoLightBarrier()
		else
			lightBarrierMap:restore()
		end

		if Configuration.expectToggleValue("NoYunShulBarrier") then
			updateNoYunShulBarrier()
		else
			yunShulBarrierMap:restore()
			yunShulResonanceDoorMap:restore()
		end

		if Configuration.expectToggleValue("NoBlur") then
			updateNoBlur()
		else
			noBlur:restore()
		end

		if Configuration.expectToggleValue("NoAcidWater") then
			updateNoAcidWater()
		else
			restoreNoAcidWater()
		end

		if Configuration.expectToggleValue("NoShadows") then
			noShadows:set(lighting, "GlobalShadows", false)
		else
			noShadows:restore()
		end

		if Configuration.expectToggleValue("NoSanityVFX") then
			updateNoSanityVFX(localPlayer)
		else
			statVFXMap:restore()
			noOverlay:restore()
		end
	end

	---@param effect table
	local function hideEffect(effect)
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		if not effectReplicator then
			return
		end

		local effectReplicatorModule = require(effectReplicator)
		if not effectReplicatorModule then
			return
		end

		if not effect.ID then
			return
		end

		effectReplicatorModule.Effects[effect.ID] = nil
	end

	---@param effect table
	local function updateRemovalEffects(effect)
		local stunEffects = { "Stun", "Action", "MobileAction" }

		if Configuration.expectToggleValue("NoStun") and table.find(stunEffects, effect.Class) then
			hideEffect(effect)
		end

		if
			(effect.Class == "BeingWinded" or effect.Class == "StrongWind")
			and Configuration.expectToggleValue("NoWind")
		then
			lastWindEffectTimestamp = os.clock()
			return hideEffect(effect)
		end

		if Configuration.expectToggleValue("NoWind") and os.clock() - lastWindEffectTimestamp <= 30.0 then
			if
				effect.Class == "Speed"
				or effect.Class == "NoJump"
				or effect.Class == "NoStun"
				or effect.Class == "NoSprint"
				or effect.Class == "NoRoll"
			then
				return hideEffect(effect)
			end
		end

		if
			(effect.Class == "NoJump" or effect.Class == "NoJumpAlt")
			and Configuration.expectToggleValue("AlwaysAllowJump")
		then
			return hideEffect(effect)
		end

		if
			effect.Class == "SpeedOverride"
			and effect.Value < 14
			and Configuration.expectToggleValue("NoSpeedDebuff")
		then
			return hideEffect(effect)
		end

		if effect.Class == "Speed" and effect.Value < 0 and Configuration.expectToggleValue("NoSpeedDebuff") then
			rawset(effect, "Value", 0)
		end

		if effect.Class == "Burning" and Configuration.expectToggleValue("AutoExtinguishFire") then
			-- getRemote (encoder) + two FireServers -- run on the Heartbeat pump, never on the EffectAdded dispatch
			-- callstack, so this can't nest a guarded STM job (Kernel,2090). The enqueue here is a plain table insert.
			EffectDispatcher.defer(function()
				local serverSlide = KeyHandling.getRemote("ServerSlide")
				local serverSlideStop = KeyHandling.getRemote("ServerSlideStop")

				if not serverSlide or not serverSlideStop then
					return Logger.warn("ServerSlide or ServerSlideStop not found.")
				end

				serverSlide:FireServer(true)
				serverSlideStop:FireServer()
			end)
		end

		if effect.Class == "Blinded" and Configuration.expectToggleValue("NoBlind") then
			return hideEffect(effect)
		end
	end

	---@param descendant Instance
	local function onWorkspaceDescendantAdded(descendant)
		if descendant:IsA("Model") and descendant.Name == "ResonanceDoor" then
			yunShulResonanceDoorMap:mark(descendant, "Parent")
		end

		if descendant:IsA("Model") and descendant.Name == "HiveGate" then
			hiveGateMap:mark(descendant, "Parent")
		end

		if descendant.Name == "WindPusher" and Configuration.expectToggleValue("NoWind") then
			debris:AddItem(descendant, 0.01)
		end

		if not descendant:IsA("BasePart") then
			return
		end

		if descendant.Name == "LifeField" then
			lightBarrierMap:mark(descendant, "CFrame")
		end

		local killInstance = descendant.Name == "KillBrick" or descendant.Name == "KillPlane"
		local killChasm = descendant.Name:match("Chasm")
		local superWall = descendant.Name == "SuperWall"
		local damagePart = descendant.Name == "Lava" and descendant:FindFirstChild("Hazardous") and not descendant:HasTag("DamageBrick")

		if killInstance or killChasm or superWall then
			killBricksMap:mark(descendant, "CFrame")
			if Configuration.expectToggleValue("NoKillBricks") then
				killBricksMap:add(
					descendant,
					"CFrame",
					CFrame.new(math.huge, math.huge, math.huge)
				)
			end
		end

		if descendant.Name == "DeepPassage_Yun" then
			yunShulBarrierMap:mark(descendant, "CFrame")
		end

		if damagePart then
			damageBricksMap:mark(descendant, "Parent")
		end
	end

	---@param descendant Instance
	local function onWorkspaceDescendantRemoving(descendant)
		killBricksMap:forget(descendant)
		lightBarrierMap:forget(descendant)
	end

	-- Effect removal rides the shared Game/EffectDispatcher as an "added" hook (registered in Removal.init) --
	-- one EffectReplicator connection for the whole script, deferred + identity-8 so updateRemovalEffects'
	-- FireServer (AutoExtinguishFire) can't dispatch from the parallel Actor phase.

	function Removal.init()
		removalMaid:add(
			workspaceDescendantAdded:connect("Removal_WorkspaceDescendantAdded", onWorkspaceDescendantAdded)
		)
		removalMaid:add(
			workspaceDescendantRemoving:connect("Removal_WorkspaceDescendantRemoving", onWorkspaceDescendantRemoving)
		)

		removalMaid:add(renderStepped:connect("Removal_RenderStepped", updateRemoval))
		removalMaid:add(
			renderStepped:connect("Removal_NoKillBricksPersistent", updateNoKillBricksPersistent)
		)
		removalMaid:add(renderStepped:connect("Removal_NoBlind", updateNoBlindFast))

		EffectDispatcher.hook("added", updateRemovalEffects)

		for _, descendant in pairs(workspace:GetDescendants()) do
			onWorkspaceDescendantAdded(descendant)
		end
		if Configuration.expectToggleValue("NoKillBricks") then
			updateNoKillBricks()
		end

		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("Removal initialized.")
		end
	end

	function Removal.detach()
		removalMaid:clean()

		resetNoBlind()
		restoreNoAcidWater()

		Logger.warn("Removal detached.")
	end

	return Removal
end)()

end)
__bundle_register("Features/Visuals/ProximityList", function(require, _LOADED, __bundle_register, __bundle_modules)
-- ProximityList: an on-screen list of nearby players (name + distance), ported from project-rain's
-- proximity_list. Draggable frame, updates ~0.15s, notifies on enter/leave, highlights voidwalkers.
-- Gated on the ProximityList toggle, with ProximityListRange + ProximityListNotify options.
local ProximityList = {}

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local screenGui, outer, listFrame
local labelMap = {} -- UserId -> TextLabel
local notified = {} -- UserId -> true while we've announced this player's presence (NOT tied to the label)
local lastInRange = {} -- UserId -> os.clock() last time actually in range (for departure debounce)
local active = false

-- A player must be out of range for this long before we announce they "left" -- stops the enter/leave
-- notifications from spamming when a still player briefly drops out of range (HRP streaming, health read,
-- or jitter right at the range boundary).
local PROXIMITY_GRACE = 2

local function localPlayer()
	return players.LocalPlayer
end

local function root()
	local char = localPlayer() and localPlayer().Character
	return char and char:FindFirstChild("HumanoidRootPart")
end

local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end

local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	instance.Parent = parent
	return instance
end

---Studs -> "123m" / "1.2km".
local function formatDistance(d)
	if d >= 1000 then
		return string.format("%.1fkm", d / 1000)
	end
	return string.format("%im", d)
end

---Voidwalker check (PR's): their Backpack holds the Voideye / Grasp of Eylis talent. NOTE: other players'
---Backpacks usually aren't replicated to us, so this rarely triggers for remote players -- kept for parity.
local function isVoidwalker(plr)
	local bp = plr:FindFirstChildOfClass("Backpack")
	if not bp then
		return false
	end
	return bp:FindFirstChild("Talent:Voideye") ~= nil or bp:FindFirstChild("Talent:Grasp of Eylis") ~= nil
end

local function build()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "AeroProximityList"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9998

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.15, 0),
		Size = UDim2.new(0, 190, 0, 22),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local title = mk("TextLabel", {
		BackgroundColor3 = Library.BackgroundColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		Size = UDim2.new(1, 0, 0, 22),
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.AccentColor,
		Text = "Proximity",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { BackgroundColor3 = "BackgroundColor", TextColor3 = "AccentColor" })

	listFrame = mk("Frame", {
		Name = "List",
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0, 22),
		Size = UDim2.new(1, 0, 0, 0),
		ZIndex = 201,
	}, outer)
	mk("UIListLayout", {
		FillDirection = Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
	}, listFrame)

	pcall(function()
		Library:MakeDraggable(outer, 22)
	end)
end

---Players within `range` of us (alive), sorted nearest-first.
local function getInRange(range)
	local inRange = {}
	local r = root()
	if not r then
		return inRange
	end
	local lp = localPlayer()
	for _, plr in ipairs(players:GetPlayers()) do
		if plr == lp then
			continue
		end
		local char = plr.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if hrp and hum and hum.Health > 0 then
			local dist = (r.Position - hrp.Position).Magnitude
			if dist <= range then
				table.insert(inRange, { player = plr, distance = dist })
			end
		end
	end
	table.sort(inRange, function(a, b)
		return a.distance < b.distance
	end)
	return inRange
end

local function addLabel(voidwalker)
	local label = mk("TextLabel", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		FontFace = Library.Font,
		TextSize = 14,
		TextColor3 = voidwalker and Library.AccentColor or (Library.FontColor or Color3.new(1, 1, 1)),
		Text = "",
		ZIndex = 202,
	}, listFrame)
	Library:AddToRegistry(label, { TextColor3 = voidwalker and "AccentColor" or "FontColor" })
	return label
end

local function clearAll()
	for key, label in pairs(labelMap) do
		pcall(function()
			label:Destroy()
		end)
		labelMap[key] = nil
	end
	for key in pairs(notified) do
		notified[key] = nil
	end
	for key in pairs(lastInRange) do
		lastInRange[key] = nil
	end
end

local function sync(inRange, notify)
	local seen = {}
	local order = 0
	local now = os.clock()
	for _, data in ipairs(inRange) do
		local plr = data.player
		local key = plr.UserId
		seen[key] = true
		lastInRange[key] = now
		local name = plr:GetAttribute("CharacterName") or plr.Name
		local vw = isVoidwalker(plr)

		-- Announce entry ONCE per sustained presence -- keyed off `notified`, not the label, so a one-cycle
		-- drop-out (which destroys/recreates the label below) can't re-fire the notification.
		if notify and not notified[key] then
			Logger.notify(
				"%s [%s] entered your proximity range.%s",
				tostring(plr:GetAttribute("CharacterName") or ""),
				plr.Name,
				vw and " (voidwalker)" or ""
			)
		end
		notified[key] = true

		local label = labelMap[key]
		if not label or not label.Parent then
			label = addLabel(vw)
			labelMap[key] = label
		end
		label.Text = name .. " (" .. formatDistance(data.distance) .. ")"
		label.LayoutOrder = order
		order = order + 1
	end

	-- Labels track the instantaneous range (remove when not seen this cycle).
	for key, label in pairs(labelMap) do
		if not seen[key] then
			pcall(function()
				label:Destroy()
			end)
			labelMap[key] = nil
		end
	end

	-- Departures are debounced: only announce "left" once a player has been out of range for the full
	-- grace window. A brief flicker keeps `notified` set, so returning doesn't re-announce an entry.
	for key in pairs(notified) do
		if not seen[key] and (now - (lastInRange[key] or 0)) > PROXIMITY_GRACE then
			if notify then
				local plr = players:GetPlayerByUserId(key)
				Logger.notify(
					"%s left your proximity range.",
					plr and ((plr:GetAttribute("CharacterName") or "") .. " [" .. plr.Name .. "]") or "A player"
				)
			end
			notified[key] = nil
			lastInRange[key] = nil
		end
	end

	-- Manual sizing (AutomaticSize was unreliable here): grow the box to fit the title + one row per player.
	local count = 0
	for _ in pairs(labelMap) do
		count = count + 1
	end
	if listFrame then
		listFrame.Size = UDim2.new(1, 0, 0, count * 18)
	end
	if outer then
		outer.Size = UDim2.new(0, 190, 0, 22 + count * 18)
	end
end

function ProximityList.init()
	if active then
		return
	end
	active = true

	-- Build the window ONCE, up front (same as the automation overlays' buildOverlay), then drive it from a
	-- task.spawn loop -- not a lazy build inside a render connection.
	build()
	if screenGui then
		screenGui.Enabled = false
	end

	task.spawn(function()
		while active do
			task.wait(0.15)
			pcall(function()
				if not active then
					return
				end
				if not Configuration.expectToggleValue("ProximityList") then
					if screenGui and screenGui.Enabled then
						screenGui.Enabled = false
						clearAll()
					end
					return
				end

				if not screenGui then
					build()
				end

				local range = Configuration.expectOptionValue("ProximityListRange") or 1000
				local notify = Configuration.expectToggleValue("ProximityListNotify")
				sync(getInRange(range), notify)

				-- Show the box whenever the feature is on (just the "Proximity" title when nobody's in range).
				screenGui.Enabled = true
			end)
		end
	end)
end

function ProximityList.detach()
	active = false
	clearAll()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	outer, listFrame = nil, nil
end

return ProximityList

end)
__bundle_register("Features/Visuals/Visuals", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Features.Visuals.Objects.ModelESP
local ModelESP = require("Features/Visuals/Objects/ModelESP")

---@module Features.Visuals.Objects.PartESP
local PartESP = require("Features/Visuals/Objects/PartESP")

---@module Features.Visuals.Objects.MobESP
local MobESP = require("Features/Visuals/Objects/MobESP")

---@module Features.Visuals.Objects.PlayerESP
local PlayerESP = require("Features/Visuals/Objects/PlayerESP")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Features.Visuals.Objects.FilteredESP
local FilteredESP = require("Features/Visuals/Objects/FilteredESP")

---@module Features.Visuals.Group
local Group = require("Features/Visuals/Group")

---@module Utility.Profiler
local Profiler = require("Utility/Profiler")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.OriginalStoreManager
local OriginalStoreManager = require("Utility/OriginalStoreManager")

---@module Features.Visuals.Objects.ChestESP
local ChestESP = require("Features/Visuals/Objects/ChestESP")

---@module Utility.InstanceWrapper
local InstanceWrapper = require("Utility/InstanceWrapper")

---@module Utility.Table
local Table = require("Utility/Table")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Features.Visuals.Objects.ObeliskESP
local ObeliskESP = require("Features/Visuals/Objects/ObeliskESP")

---@module Features.Visuals.Objects.BoneAltarESP
local BoneAltarESP = require("Features/Visuals/Objects/BoneAltarESP")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

local Visuals = { bdata = nil, drinfo = nil }

local lastVisualsUpdate = os.clock()
local lastHoveringUpdate = os.clock()
local lastESPUpdate = os.clock()

local runService = game:GetService("RunService")
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local textChatService = game:GetService("TextChatService")
local userInputService = game:GetService("UserInputService")
local guiService = game:GetService("GuiService")

