-- Bright borders/text and darker panel fills preserve readable game labels.
local buildColors = {
	Needed = Color3.fromRGB(153, 221, 170), -- pastel green: useful / owned
	Excluded = Color3.fromRGB(238, 153, 153), -- pastel red: skip
	PreShrine = Color3.fromRGB(195, 170, 238), -- pastel purple
	Missing = Color3.fromRGB(242, 216, 144), -- pastel yellow
	-- Muted versions of the same colors keep native game text readable.
	NeededFill = Color3.fromRGB(80, 118, 90),
	ReachedFill = Color3.fromRGB(129, 88, 88), -- red: stop investing
	ExceededFill = Color3.fromRGB(100, 103, 110),
	PreShrineFill = Color3.fromRGB(116, 98, 135),
	PostShrineFill = Color3.fromRGB(82, 109, 135), -- soft blue
	MustShrineFill = Color3.fromRGB(140, 121, 78),
}
local mysteryRevealMap = visualsMaid:mark(OriginalStoreManager.new())
