	if not LPH_OBFUSCATED or shared.Aero.verbose then
		Logger.warn("Charisma Farm initialized.")
	end
end

function CharismaFarm.detach()
	autoCharismaMaid:clean()

	Logger.warn("Charisma Farm detached.")
end

return CharismaFarm

end)
__bundle_register("Menu", function(require, _LOADED, __bundle_register, __bundle_modules)
local Menu = {}

---@module GUI.ThemeManager
local ThemeManager = require("GUI/ThemeManager")

---@module GUI.SaveManager
local SaveManager = require("GUI/SaveManager")

local FirstRun = require("GUI/FirstRun")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Menu.CombatTab
local CombatTab = require("Menu/CombatTab")

---@module Menu.GameTab
local GameTab = require("Menu/GameTab")

---@module Menu.AutomationTab
local AutomationTab = require("Menu/AutomationTab")

---@module Menu.TimingBuilderTab
local TimingBuilderTab = require("Menu/TimingBuilderTab")

---@module Menu.VisualsTab
local VisualsTab = require("Menu/VisualsTab")

---@module Menu.ExploitTab
local ExploitTab = require("Menu/ExploitTab")

---@module Menu.AeroTab
local AeroTab = require("Menu/AeroTab")

---@module Menu.AdminTab
local AdminTab = require("Menu/AdminTab")

---@module Menu.CustomTab
local CustomTab = require("Menu/CustomTab")

---@module Features.Custom.Custom
local Custom = require("Features/Custom/Custom")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local runService = game:GetService("RunService")
local stats = game:GetService("Stats")
local players = game:GetService("Players")
local userInputService = game:GetService("UserInputService")

local renderStepped = Signal.new(runService.RenderStepped)

local menuMaid = Maid.new()

local MENU_TITLE = "Aero"

if LRM_UserNote then
	MENU_TITLE = string.format(
		"Aero",
		string.sub("6c10af8d79e3dc253ba6db7f343613361c37e378", 1, 6)
	)
end

function Menu.init()
	local window = Library:CreateWindow({
		Title = MENU_TITLE,
		Center = true,
		AutoShow = not shared.Aero.silent,
		TabPadding = 16,
		MenuFadeTime = 0, -- Avoid per-element tweens when toggling a large menu.
		Size = UDim2.fromOffset(500, 600),
	})

	ThemeManager:SetLibrary(Library)
	ThemeManager:SetFolder("Aero-Rewrite-Themes")

	SaveManager:SetLibrary(Library)
	SaveManager:IgnoreThemeSettings()
	SaveManager:SetFolder("Aero-Rewrite-Configs")
	SaveManager:SetIgnoreIndexes({
		"InterfaceScale",
		"Fly",
		"NoClip",
		"Speedhack",
		"InfiniteJump",
		"TweenToObjective",
		"TweenToBack",
	})

	-- Eager: only the first tab, so the menu has content the instant it auto-shows. The remaining
	-- tabs are built on background frames (see the deferred builder below) so the menu appears
	-- immediately instead of blocking ~1s on control creation.
	CombatTab.init(window)

	local lastUpdate = os.clock()

	menuMaid:add(renderStepped:connect(
		"Menu_WatermarkUpdate",
		LPH_NO_VIRTUALIZE(function()
			if os.clock() - lastUpdate <= 0.5 then
				return
			end

			lastUpdate = os.clock()

			local networkStats = stats:FindFirstChild("Network")
			local workspaceStats = stats:FindFirstChild("Workspace")
			local performanceStats = stats:FindFirstChild("PerformanceStats")
			local serverStats = networkStats and networkStats:FindFirstChild("ServerStatsItem") or nil

			local pingData = serverStats and serverStats:FindFirstChild("Data Ping") or nil
			local heartbeatData = workspaceStats and workspaceStats:FindFirstChild("Heartbeat") or nil
			local cpuData = performanceStats and performanceStats:FindFirstChild("CPU") or nil
			local gpuData = performanceStats and performanceStats:FindFirstChild("GPU") or nil

			local ping = pingData and pingData:GetValue() or 0.0
			local fps = heartbeatData and heartbeatData:GetValue() or 0.0
			local cpu = cpuData and cpuData:GetValue() or 0.0
			local gpu = gpuData and gpuData:GetValue() or 0.0

			local mouse = players.LocalPlayer and players.LocalPlayer:GetMouse()
			local character = players.LocalPlayer and players.LocalPlayer.Character
			local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
			local position = humanoidRootPart and humanoidRootPart.Position
			local positionFormat = position and string.format("(%.2f, %.2f, %.2f)", position.X, position.Y, position.Z)
				or "N/A"

			local str = string.format("%s | %.2fms | %.1f/s | %.1fms | %.1fms", MENU_TITLE, ping, fps, cpu, gpu)

			if Configuration.expectToggleValue("ShowDebugInformation") then
				str = str .. string.format(" | %s", positionFormat)
				str = str .. string.format(" | %s", mouse and mouse.Target and mouse.Target:GetFullName() or "N/A")
			end

			-- YSL's SetWatermark(Text, RText, Sections) measures the frame width from RText, not Text, so
			-- it must be passed too (Obsidian sized off the single arg). Without it the frame collapses and
			-- the watermark renders blank.
			Library:SetWatermark(str, str)
		end)
	))

	local menuUIHidden = false

	menuMaid:add(renderStepped:connect(
		"Menu_HideUIInMenus",
		LPH_NO_VIRTUALIZE(function()
			local playerGui = players.LocalPlayer and players.LocalPlayer:FindFirstChild("PlayerGui")
			local backpackGui = playerGui and playerGui:FindFirstChild("BackpackGui")
			local leftFrame = backpackGui and backpackGui:FindFirstChild("LeftFrame")
			local inMenu = leftFrame and leftFrame:IsA("GuiObject") and leftFrame.Visible

			if Configuration.expectToggleValue("HideUIInMenus") and inMenu then
				Library.KeybindFrame.Visible = false
				Library:SetWatermarkVisibility(false)
				menuUIHidden = true
				return
			end

			if not menuUIHidden then
				return
			end

			menuUIHidden = false
			Library.KeybindFrame.Visible = Options.KeybindList and Options.KeybindList:GetState() or false
			Library:SetWatermarkVisibility(Options.Watermark and Options.Watermark:GetState() or false)
		end)
	))

	local inputBegan = Signal.new(userInputService.InputBegan)

	inputBegan:connect("Menu_InputBegan", function(input, gameProcessed)
		if gameProcessed then
			return
		end

		if not Configuration.expectToggleValue("ShowDebugInformation") then
			return
		end

		if input.KeyCode == Enum.KeyCode.F8 then
			local mouse = players.LocalPlayer and players.LocalPlayer:GetMouse()
			local target = mouse and mouse.Target
			if not target then
				return
			end

			target.Name = tostring(math.random(100000, 1000000))

			return Logger.mnnotify("The target has been renamed to '%s' as a marker.", target.Name)
		end

		if input.KeyCode == Enum.KeyCode.Equals and Library.Recording then
			local Character = players.LocalPlayer and players.LocalPlayer.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Position = HumanoidRootPart and HumanoidRootPart.Position
			local PositionFormat = Position
					and string.format("CFrame.new(%.2f, %.2f, %.2f)", Position.X, Position.Y, Position.Z)
				or "N/A"

			Library.PositionList[#Library.PositionList + 1] = PositionFormat
		end
	end)

	-- Build background tabs within a small per-frame time budget. Controls and autoload
	-- still wait for every tab, while inexpensive tabs can share a frame.
	task.spawn(function()
		local tabs = {
			{ "GameTab", GameTab.init },
			{ "VisualsTab", VisualsTab.init },
			{ "AutomationTab", AutomationTab.init },
			{ "ExploitTab", ExploitTab.init },
			{ "AeroTab", AeroTab.init },
			{ "TimingBuilderTab", TimingBuilderTab.init },
			{ "AntiExploit", CombatTab.initAntiExploit },
			{ "AdminTab", AdminTab.init },
		}
		local frameStarted = os.clock()
		for index, tab in ipairs(tabs) do
			local ok, e = pcall(tab[2], window)
			if not ok then warn("[Aero/diag] " .. tab[1] .. ".init FAILED: " .. tostring(e)) end
			if index < #tabs and os.clock() - frameStarted >= 0.004 then
				task.wait()
				frameStarted = os.clock()
			end
		end

		for order, name in ipairs({ "Combat", "Game", "Visuals", "Auto", "Exploit", "Builder", "Anti-Exploit", "Admin", "Settings" }) do
			if window.Tabs[name] then window.Tabs[name]:SetLayoutOrder(order) end
		end

		Library.ToggleKeybind = Options.MenuKeybind

		SaveManager:BeginTracking()
		SaveManager:LoadAutoloadConfig(function() return window.UserTabIntent == true end)
		FirstRun(Library, SaveManager)

		if not LPH_OBFUSCATED or shared.Aero.verbose then
			Logger.warn("Menu initialized.")
		end
	end)
end

function Menu.detach()
	menuMaid:clean()

	-- Tear down any running custom features (their render/step/input connections outlive the ScreenGui).
	pcall(Custom.stopAll)

	TimingBuilderTab.detach()

	Library:Unload()

	Logger.warn("Menu detached.")
end

return Menu

end)
__bundle_register("Features/Custom/Custom", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Manager for user-built custom features: storage (workspace files), sandboxed execution via CustomAPI,
-- and optional AI code generation (OpenAI / Anthropic / Google) against a described Aero feature API.

---@module Utility.Filesystem
local Filesystem = require("Utility/Filesystem")

---@module Utility.JSON
local JSON = require("Utility/JSON")

---@module Features.Custom.CustomAPI
local CustomAPI = require("Features/Custom/CustomAPI")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local Custom = {}

local storage = Filesystem.new("Aero/Custom")

local host = nil -- the panel widgets render into (set by CustomTab)
local running = {} -- name -> CustomAPI instance
local settingsCache = nil

local DEFAULT_SETTINGS = {
	provider = "OpenAI",
	model = "gpt-4o-mini",
	apiKey = "",
	autorun = {},
}

Custom.PROVIDERS = { "OpenAI", "Anthropic", "Google" }
Custom.DEFAULT_MODELS = {
	OpenAI = "gpt-4o-mini",
	Anthropic = "claude-3-5-sonnet-latest",
	Google = "gemini-1.5-flash",
}

Custom.TEMPLATE = table.concat({
	"-- Custom feature. The Aero API is available as globals (and under `Aero`).",
	"-- Widgets appear in a section on the right; everything is cleaned up on reload.",
	"",
	'local enabled = Toggle("Enabled", function(on)',
	'    Notify(on and "Enabled" or "Disabled")',
	"end)",
	"",
	'Slider("Speed", { min = 16, max = 200, default = 16, callback = function(v)',
	"    local hum = Humanoid()",
	"    if hum then hum.WalkSpeed = v end",
	"end })",
	"",
	"OnRender(function()",
	"    if not enabled.get() then return end",
	"    -- runs every frame while this feature is loaded",
	"end)",
}, "\n")

-- ------------------------------------------------------------ settings
function Custom.settings()
	if settingsCache then
		return settingsCache
	end
	local data = nil
	pcall(function()
		if storage:file("settings.json") then
			local ok, decoded = pcall(JSON.decode, storage:read("settings.json"))
			if ok and type(decoded) == "table" then
				data = decoded
			end
		end
	end)
	data = data or {}
	for k, v in pairs(DEFAULT_SETTINGS) do
		if data[k] == nil then
			data[k] = v
		end
	end
	if type(data.autorun) ~= "table" then
		data.autorun = {}
	end
	settingsCache = data
	return data
end

function Custom.saveSettings()
	local s = Custom.settings()
	pcall(function()
		storage:write("settings.json", JSON.encode(s))
	end)
end

function Custom.setSetting(key, value)
	local s = Custom.settings()
	s[key] = value
	Custom.saveSettings()
end

-- ------------------------------------------------------------ storage
---@return string[]
function Custom.list()
	local out = {}
	pcall(function()
		for _, filename in ipairs(storage:list()) do
			if type(filename) == "string" and filename:sub(-4) == ".lua" then
				out[#out + 1] = filename:sub(1, #filename - 4)
			end
		end
	end)
	table.sort(out)
	return out
end

---@param name string
---@return string?
function Custom.load(name)
	local source
	pcall(function()
		if storage:file(name .. ".lua") then
			source = storage:read(name .. ".lua")
		end
	end)
	return source
end

---@param name string
---@param source string
---@return boolean ok, string? err
function Custom.save(name, source)
	if type(name) ~= "string" or name:gsub("%s", "") == "" then
		return false, "invalid name"
	end
	-- Keep filenames flat/safe.
	name = name:gsub("[\\/:*?\"<>|]", "_")
	local ok, err = pcall(function()
		storage:write(name .. ".lua", source or "")
	end)
	if not ok then
		return false, tostring(err)
	end
	return true
end

---@param name string
function Custom.delete(name)
	Custom.stop(name)
	pcall(function()
		if storage:file(name .. ".lua") then
			storage:delete(name .. ".lua")
		end
	end)
	local s = Custom.settings()
	if s.autorun[name] then
		s.autorun[name] = nil
		Custom.saveSettings()
	end
end

-- ------------------------------------------------------------ execution
function Custom.setHost(panel)
	host = panel
end

function Custom.isRunning(name)
	return running[name] ~= nil
end

function Custom.runningNames()
	local out = {}
	for name in pairs(running) do
		out[#out + 1] = name
	end
	table.sort(out)
	return out
end

function Custom.stop(name)
	local inst = running[name]
	if inst then
		pcall(inst.destroy)
		running[name] = nil
	end
end

function Custom.stopAll()
	for name in pairs(running) do
		Custom.stop(name)
	end
end

---Run (or re-run) a feature's source. Cleans any previous instance of the same name first.
---@param name string
---@param source string
---@return boolean ok, string? err
function Custom.run(name, source)
	if not host then
		return false, "custom panel not ready"
	end

	Custom.stop(name)

	local chunk, compileErr = loadstring(source)
	if not chunk then
		local clean = tostring(compileErr):gsub('^%[string "[^"]*"%]:', "line ")
		return false, "syntax: " .. clean
	end

	local inst = CustomAPI.new(host, name)
	pcall(setfenv, chunk, inst.env)

	local ranOk, runErr = pcall(chunk)
	if not ranOk then
		pcall(inst.destroy)
		local clean = tostring(runErr):gsub('^%[string "[^"]*"%]:', "line ")
		return false, "runtime: " .. clean
	end

	running[name] = inst
	return true
end

function Custom.setAutorun(name, on)
	local s = Custom.settings()
	s.autorun[name] = on and true or nil
	Custom.saveSettings()
end

function Custom.isAutorun(name)
	return Custom.settings().autorun[name] == true
end

-- Run every feature flagged autorun (called by CustomTab once the host panel exists).
function Custom.autorunAll()
	local s = Custom.settings()
	for name in pairs(s.autorun) do
		local source = Custom.load(name)
		if source then
			local ok, err = Custom.run(name, source)
			if not ok then
				Logger.notify("[Custom] autorun '%s' failed: %s", tostring(name), tostring(err))
			end
		end
	end
end

-- ------------------------------------------------------------ AI code generation
local function httpRequest()
	return (syn and syn.request)
		or (http and http.request)
		or http_request
		or request
		or (getgenv and getgenv().request)
end

local API_REFERENCE = table.concat({
	"You write Luau code for the Roblox game Deepwoken, run inside the 'aero' exploit menu's custom-feature sandbox.",
	"The following API is available as GLOBAL functions (also under the `Aero` table). Use ONLY this API for UI + lifecycle:",
	"",
	"UI (each returns a control object):",
	"  Toggle(text, function(value) end)  -- or Toggle(text, { default=bool, callback=fn }); control.get()/control.set(v)",
	"  Button(text, function() end)",
	"  Slider(text, { min=number, max=number, default=number, decimals=number, callback=function(value) end }); control.get()/set(v)",
	"  Dropdown(text, { values={...}, default=any, callback=function(value) end }); control.get()/set(v)/setValues(t)",
	"  Input(text, { default=string, callback=function(text) end }); control.get()/set(v)",
	"  Keybind(text, { default='E', callback=function(key) end })  -- fires callback when the bound key is pressed",
	"  Label(text); control.set(text)",
	"  Section(title) -> a sub-surface with the same UI methods",
	"  Window(title) -> a floating draggable window, a sub-surface with the same UI methods",
	"",
	"Lifecycle (auto-cleaned on reload):",
	"  OnRender(function(dt) end)   -- every RenderStepped frame",
	"  OnStep(function(dt) end)     -- every Heartbeat",
	"  OnInput(function(input, gameProcessed) end)",
	"  Interval(seconds, function() end)",
	"  OnCleanup(function() end)",
	"  Notify(text, seconds)",
	"",
	"Game helpers:",
	"  LocalPlayer, Character(), HRP(), Humanoid(), Mouse(), Camera()",
	"  GetTarget() -> { character, humanoid, root, du } (nearest aim target) ; GetTargets() -> list",
	"  Value(flag) -> read an existing aero toggle/option by flag; Toggles, Options, Services, Library",
	"  Standard Roblox globals (game, workspace, task, math, Vector3, CFrame, etc.) are available.",
	"",
	"Rules: output ONLY runnable Luau code, no markdown fences, no explanation. Do not call loadstring/HttpGet/setfenv.",
	"Guard every frame loop with a toggle. Keep it concise and correct.",
}, "\n")

local function extractCode(text)
	if type(text) ~= "string" then
		return nil
	end
	-- Prefer a fenced code block if the model added one.
	local fenced = text:match("```[%w]*\n(.-)```")
	if fenced and fenced:gsub("%s", "") ~= "" then
		return fenced
	end
	return text
end

---Generate feature code from a natural-language prompt. Runs async; cb(ok, codeOrErr).
---@param prompt string
---@param cb fun(ok: boolean, result: string)
function Custom.generate(prompt, cb)
	task.spawn(function()
		local s = Custom.settings()
		local req = httpRequest()
		if not req then
			return cb(false, "no HTTP request function on this executor")
		end
		if not s.apiKey or s.apiKey:gsub("%s", "") == "" then
			return cb(false, "set your API key first")
		end

		local provider = s.provider or "OpenAI"
		local model = (s.model and s.model:gsub("%s", "") ~= "" and s.model) or Custom.DEFAULT_MODELS[provider] or "gpt-4o-mini"

		local url, headers, body
		if provider == "Anthropic" then
			url = "https://api.anthropic.com/v1/messages"
			headers = {
				["x-api-key"] = s.apiKey,
				["anthropic-version"] = "2023-06-01",
				["Content-Type"] = "application/json",
			}
			body = JSON.encode({
				model = model,
				max_tokens = 2048,
				system = API_REFERENCE,
				messages = { { role = "user", content = prompt } },
			})
		elseif provider == "Google" then
			url = "https://generativelanguage.googleapis.com/v1beta/models/"
				.. model
				.. ":generateContent?key="
				.. s.apiKey
			headers = { ["Content-Type"] = "application/json" }
			body = JSON.encode({
				system_instruction = { parts = { { text = API_REFERENCE } } },
				contents = { { role = "user", parts = { { text = prompt } } } },
			})
		else
			url = "https://api.openai.com/v1/chat/completions"
			headers = {
				["Authorization"] = "Bearer " .. s.apiKey,
				["Content-Type"] = "application/json",
			}
			body = JSON.encode({
				model = model,
				temperature = 0.4,
				messages = {
					{ role = "system", content = API_REFERENCE },
					{ role = "user", content = prompt },
				},
			})
		end

		local ok, res = pcall(req, {
			Url = url,
			Method = "POST",
			Headers = headers,
			Body = body,
		})
		if not ok or type(res) ~= "table" then
			return cb(false, "request failed: " .. tostring(res))
		end
		local status = res.StatusCode or res.Status or 0
		if type(res.Body) ~= "string" or res.Body == "" then
			return cb(false, "empty response (status " .. tostring(status) .. ")")
		end

		local decodeOk, decoded = pcall(JSON.decode, res.Body)
		if not decodeOk or type(decoded) ~= "table" then
			return cb(false, "bad JSON (status " .. tostring(status) .. ")")
		end

		-- API-level error?
		if decoded.error then
			local msg = type(decoded.error) == "table" and decoded.error.message or tostring(decoded.error)
			return cb(false, "api error: " .. tostring(msg))
		end

		local content
		if provider == "Anthropic" then
			content = decoded.content and decoded.content[1] and decoded.content[1].text
		elseif provider == "Google" then
			content = decoded.candidates
				and decoded.candidates[1]
				and decoded.candidates[1].content
				and decoded.candidates[1].content.parts
				and decoded.candidates[1].content.parts[1]
				and decoded.candidates[1].content.parts[1].text
		else
			content = decoded.choices and decoded.choices[1] and decoded.choices[1].message and decoded.choices[1].message.content
		end

		if type(content) ~= "string" or content:gsub("%s", "") == "" then
			return cb(false, "no code in response (status " .. tostring(status) .. ")")
		end

		return cb(true, extractCode(content))
	end)
end

return Custom

end)
__bundle_register("Features/Custom/CustomAPI", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Builds the sandboxed API a user's custom-feature code runs against. new(hostBody, name) returns
-- { env, destroy }: `env` is the environment to setfenv the user chunk with (API helpers are available
-- as globals AND under the `Aero`/`api` table); `destroy()` tears down every widget, window, connection
-- and loop the feature created. Everything the feature makes is tracked so a reload leaves nothing behind.

---@module GUI.Library
local Library = require("GUI/Library")

---@module Features.Custom.CustomWidgets
local Widgets = require("Features/Custom/CustomWidgets")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Features.Combat.Targeting
local Targeting = require("Features/Combat/Targeting")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")

local CustomAPI = {}

local function normalizeOpts(arg)
	if type(arg) == "function" then
		return { callback = arg }
	end
	if type(arg) == "table" then
		return arg
	end
	return {}
end

---@param hostBody Instance where this feature's widgets are parented
---@param name string
---@return table
function CustomAPI.new(hostBody, name)
	local conns = {}
	local roots = {}
	local cleanupFns = {}
	local intervals = {}
	local destroyed = false

	local function track(control)
		if control and control.conns then
			for _, c in ipairs(control.conns) do
				conns[#conns + 1] = c
			end
		end
		return control
	end

	local function trackConn(c)
		conns[#conns + 1] = c
		return c
	end

	-- Section for this feature inside the host panel; all its root widgets live here.
	local rootSection = Widgets.section(hostBody, name or "Custom Feature")
	roots[#roots + 1] = rootSection.instance

	-- Builds a widget surface bound to a particular parent body (root section, a sub-section, or a window).
	local function buildSurface(parent)
		local surface = {}

		function surface.Label(text)
			return track(Widgets.label(parent, text))
		end

		function surface.Button(text, callback)
			return track(Widgets.button(parent, text, callback))
		end

		function surface.Toggle(text, arg)
			local o = normalizeOpts(arg)
			return track(Widgets.toggle(parent, text, o.default, o.callback))
		end

		function surface.Slider(text, arg)
			local o = normalizeOpts(arg)
			return track(Widgets.slider(parent, text, o.min, o.max, o.default, o.callback, o.decimals))
		end

		function surface.Dropdown(text, arg)
			local o = normalizeOpts(arg)
			return track(Widgets.dropdown(parent, text, o.values, o.default, o.callback))
		end

		function surface.Input(text, arg)
			local o = normalizeOpts(arg)
			return track(Widgets.input(parent, text, o.default, o.callback))
		end

		function surface.Keybind(text, arg)
			local o = normalizeOpts(arg)
			return track(Widgets.keybind(parent, text, o.default, o.callback))
		end

		function surface.Section(title)
			local sec = track(Widgets.section(parent, title))
			return buildSurface(sec.body)
		end

		return surface
	end

	local root = buildSurface(rootSection.body)

	-- Floating, draggable window parented to the menu ScreenGui. Returns a widget surface for its body.
	local function makeWindow(title)
		local gui = Library.ScreenGui
		local outer = Library:Create("Frame", {
			Name = "CustomWindow",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(240, 60),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundColor3 = Library.MainColor,
			BorderSizePixel = 0,
			ZIndex = 70,
			Parent = gui,
		})
		Library:Create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = outer })
		local os = Library:Create("UIStroke", { Color = Library.AccentColor, Thickness = 1, Transparency = 0.2, Parent = outer })
		Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor" })
		Library:AddToRegistry(os, { Color = "AccentColor" })
		pcall(function() Library:AddUIScale(outer) end)

		local bar = Library:Create("TextLabel", {
			BackgroundColor3 = Library.BackgroundColor,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, 24),
			Font = Enum.Font.GothamBold,
			Text = "  " .. tostring(title or "Window"),
			TextSize = 13,
			TextColor3 = Library.FontColor,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 71,
			Parent = outer,
		})
		Library:Create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = bar })
		Library:AddToRegistry(bar, { BackgroundColor3 = "BackgroundColor", TextColor3 = "FontColor" })
		pcall(function() Library:MakeDraggable(outer, 24) end)

		local body = Library:Create("Frame", {
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(6, 28),
			Size = UDim2.new(1, -12, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			ZIndex = 71,
			Parent = outer,
		})
		Library:Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4), Parent = body })
		Library:Create("UIPadding", { PaddingBottom = UDim.new(0, 6), Parent = body })

		roots[#roots + 1] = outer
		return buildSurface(body)
	end

	-- ------------------------------------------------------------ lifecycle + helpers
	local api = {}

	-- widget methods (root surface)
	for k, v in pairs(root) do
		api[k] = v
	end

	function api.Window(title)
		return makeWindow(title)
	end

	function api.OnRender(fn)
		trackConn(RunService.RenderStepped:Connect(function(dt)
			if not destroyed then
				local ok, err = pcall(fn, dt)
				if not ok then
					Logger.notify("[Custom] render error: %s", tostring(err))
				end
			end
		end))
	end

	function api.OnStep(fn)
		trackConn(RunService.Heartbeat:Connect(function(dt)
			if not destroyed then
				pcall(fn, dt)
			end
		end))
	end

	function api.OnInput(fn)
		trackConn(UserInputService.InputBegan:Connect(function(input, gameProcessed)
			if not destroyed then
				pcall(fn, input, gameProcessed)
			end
		end))
	end

	function api.Interval(seconds, fn)
		seconds = tonumber(seconds) or 1
		local token = { running = true }
		intervals[#intervals + 1] = token
		task.spawn(function()
			while token.running and not destroyed do
				task.wait(seconds)
				if token.running and not destroyed then
					pcall(fn)
				end
			end
		end)
	end

	function api.OnCleanup(fn)
		cleanupFns[#cleanupFns + 1] = fn
	end

	function api.Notify(text, time)
		pcall(function()
			Library:Notify(tostring(text), time)
		end)
	end

	-- game helpers
	api.LocalPlayer = Players.LocalPlayer
	api.Services = {
		Players = Players,
		RunService = RunService,
		UserInputService = UserInputService,
		Workspace = Workspace,
		ReplicatedStorage = game:GetService("ReplicatedStorage"),
		TweenService = game:GetService("TweenService"),
		VirtualInputManager = nil,
	}

	function api.Character()
		local lp = Players.LocalPlayer
		return lp and lp.Character
	end

	function api.HRP()
		local char = api.Character()
		return char and char:FindFirstChild("HumanoidRootPart")
	end

	function api.Humanoid()
		local char = api.Character()
		return char and char:FindFirstChildOfClass("Humanoid")
	end

	function api.Mouse()
		local lp = Players.LocalPlayer
		return lp and lp:GetMouse()
	end

	function api.Camera()
		return Workspace.CurrentCamera
	end

	-- Current best aim target (Targeting respects the user's targeting config), and the full list.
	function api.GetTarget()
		local ok, list = pcall(Targeting.best)
		if ok and list then
			return list[1]
		end
		return nil
	end

	function api.GetTargets()
		local ok, list = pcall(Targeting.best)
		if ok and list then
			return list
		end
		return {}
	end

	-- Read any existing aero control value by flag.
	function api.Value(flag)
		local v = Configuration.expectToggleValue(flag)
		if v ~= nil then
			return v
		end
		return Configuration.expectOptionValue(flag)
	end

	api.Toggles = getgenv().Toggles
	api.Options = getgenv().Options
	api.Library = Library

	-- ------------------------------------------------------------ sandbox env
	local base = getfenv(1)
	local gg = getgenv and getgenv() or nil
	local backing = {}
	local env = setmetatable(backing, {
		__index = function(_, key)
			local a = api[key]
			if a ~= nil then
				return a
			end
			local b = base[key]
			if b ~= nil then
				return b
			end
			if gg then
				return gg[key]
			end
			return nil
		end,
		__newindex = function(t, key, value)
			rawset(t, key, value)
		end,
	})
	-- Expose the whole surface as a table too, for users who prefer `Aero.Toggle(...)`.
	backing.Aero = api
	backing.api = api

	local function destroy()
		if destroyed then
			return
		end
		destroyed = true
		for _, token in ipairs(intervals) do
			token.running = false
		end
		for _, c in ipairs(conns) do
			pcall(function()
				c:Disconnect()
			end)
		end
		for _, fn in ipairs(cleanupFns) do
			pcall(fn)
		end
		for _, inst in ipairs(roots) do
			pcall(function()
				inst:Destroy()
			end)
		end
	end

	return { env = env, destroy = destroy, api = api }
end

return CustomAPI

end)
__bundle_register("Features/Custom/CustomWidgets", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Self-managed UI widgets for user-built custom features. These are NOT YSL controls -- they're plain
-- styled frames we fully own, so a feature's whole UI can be torn down cleanly on reload (destroy the
-- frames + disconnect the returned connections). Each builder returns { instance, conns, ... }.

---@module GUI.Library
local Library = require("GUI/Library")

local UserInputService = game:GetService("UserInputService")

local CustomWidgets = {}

local ROW_H = 26

local function corner(inst, radius)
	Library:Create("UICorner", { CornerRadius = UDim.new(0, radius or 4), Parent = inst })
end

local function stroke(inst, colorKey, transparency)
	local s = Library:Create("UIStroke", {
		Color = Library[colorKey] or Library.OutlineColor,
		Thickness = 1,
		Transparency = transparency or 0.4,
		Parent = inst,
	})
	Library:AddToRegistry(s, { Color = colorKey or "OutlineColor" })
	return s
end

---@param parent Instance
---@param height number
---@return Frame
local function row(parent, height)
	local f = Library:Create("Frame", {
		BackgroundColor3 = Library.BackgroundColor,
		BackgroundTransparency = 0.3,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, height or ROW_H),
		Parent = parent,
	})
	corner(f, 4)
	Library:AddToRegistry(f, { BackgroundColor3 = "BackgroundColor" })
	return f
end

local function label(parent, text, size, xAlign, width)
	return Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Font = Enum.Font.Gotham,
		Text = text or "",
		TextSize = size or 13,
		TextColor3 = Library.FontColor,
		TextXAlignment = xAlign or Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Size = width or UDim2.new(1, -10, 1, 0),
		Position = UDim2.fromOffset(8, 0),
		Parent = parent,
	})
end

-- ---------------------------------------------------------------- Label ----
function CustomWidgets.label(parent, text)
	local f = Library:Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = parent,
	})
	local l = Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Font = Enum.Font.Gotham,
		Text = tostring(text or ""),
		TextSize = 13,
		TextColor3 = Library.FontColor,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		Size = UDim2.new(1, -8, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Position = UDim2.fromOffset(4, 0),
		Parent = f,
	})
	Library:AddToRegistry(l, { TextColor3 = "FontColor" }, true)
	return {
		instance = f,
		conns = {},
		set = function(t)
			l.Text = tostring(t or "")
		end,
	}
end

-- ---------------------------------------------------------------- Button ----
function CustomWidgets.button(parent, text, callback)
	local f = Library:Create("TextButton", {
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		AutoButtonColor = false,
		Font = Enum.Font.GothamSemibold,
		Text = tostring(text or "Button"),
		TextSize = 13,
		TextColor3 = Library.FontColor,
		Size = UDim2.new(1, 0, 0, ROW_H),
		Parent = parent,
	})
	corner(f, 4)
	stroke(f, "OutlineColor", 0.4)
	Library:AddToRegistry(f, { BackgroundColor3 = "MainColor", TextColor3 = "FontColor" }, true)

	f.MouseEnter:Connect(function()
		f.TextColor3 = Library.AccentColor
	end)
	f.MouseLeave:Connect(function()
		f.TextColor3 = Library.FontColor
	end)
	f.MouseButton1Click:Connect(function()
		if callback then
			pcall(callback)
		end
	end)

	return { instance = f, conns = {} }
end

-- ---------------------------------------------------------------- Toggle ----
function CustomWidgets.toggle(parent, text, default, callback)
	local value = default and true or false
	local f = row(parent, ROW_H)

	label(f, tostring(text or "Toggle"), 13, Enum.TextXAlignment.Left, UDim2.new(1, -36, 1, 0))

	local boxOuter = Library:Create("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -8, 0.5, 0),
		Size = UDim2.fromOffset(16, 16),
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Parent = f,
	})
	corner(boxOuter, 3)
	stroke(boxOuter, "OutlineColor", 0.2)
	Library:AddToRegistry(boxOuter, { BackgroundColor3 = "MainColor" })

	local fill = Library:Create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(10, 10),
		BackgroundColor3 = Library.AccentColor,
		BorderSizePixel = 0,
		Visible = value,
		Parent = boxOuter,
	})
	corner(fill, 2)
	Library:AddToRegistry(fill, { BackgroundColor3 = "AccentColor" })

	local button = Library:Create("TextButton", {
		BackgroundTransparency = 1,
		Text = "",
		Size = UDim2.fromScale(1, 1),
		Parent = f,
	})

	local control
	local function apply(fireCallback)
		fill.Visible = value
		if fireCallback and callback then
			pcall(callback, value)
		end
	end

	button.MouseButton1Click:Connect(function()
		value = not value
		apply(true)
	end)

	control = {
		instance = f,
		conns = {},
		get = function()
			return value
		end,
		set = function(v, fire)
			value = v and true or false
			apply(fire ~= false)
		end,
	}
	return control
end

-- ---------------------------------------------------------------- Slider ----
function CustomWidgets.slider(parent, text, min, max, default, callback, decimals)
	min = tonumber(min) or 0
	max = tonumber(max) or 100
	if max <= min then
		max = min + 1
	end
	decimals = tonumber(decimals) or 0
	local value = math.clamp(tonumber(default) or min, min, max)

	local f = Library:Create("Frame", {
		BackgroundColor3 = Library.BackgroundColor,
		BackgroundTransparency = 0.3,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 34),
		Parent = parent,
	})
	corner(f, 4)
	Library:AddToRegistry(f, { BackgroundColor3 = "BackgroundColor" })

	local nameLabel = label(f, tostring(text or "Slider"), 12, Enum.TextXAlignment.Left, UDim2.new(1, -60, 0, 14))
	nameLabel.Position = UDim2.fromOffset(8, 2)

	local valueLabel = Library:Create("TextLabel", {
		AnchorPoint = Vector2.new(1, 0),
		BackgroundTransparency = 1,
		Position = UDim2.new(1, -8, 0, 2),
		Size = UDim2.fromOffset(54, 14),
		Font = Enum.Font.GothamSemibold,
		TextSize = 12,
		TextColor3 = Library.AccentColor,
		TextXAlignment = Enum.TextXAlignment.Right,
		Text = "",
		Parent = f,
	})
	Library:AddToRegistry(valueLabel, { TextColor3 = "AccentColor" }, true)

	local track = Library:Create("Frame", {
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 8, 0, 22),
		Size = UDim2.new(1, -16, 0, 6),
		Parent = f,
	})
	corner(track, 3)
	Library:AddToRegistry(track, { BackgroundColor3 = "MainColor" })

	local fill = Library:Create("Frame", {
		BackgroundColor3 = Library.AccentColor,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(0, 1),
		Parent = track,
	})
	corner(fill, 3)
	Library:AddToRegistry(fill, { BackgroundColor3 = "AccentColor" })

	local function round(v)
		local m = 10 ^ decimals
		return math.floor(v * m + 0.5) / m
	end

	local control
	local function apply(fireCallback)
		local ratio = (value - min) / (max - min)
		fill.Size = UDim2.fromScale(math.clamp(ratio, 0, 1), 1)
		valueLabel.Text = tostring(round(value))
		if fireCallback and callback then
			pcall(callback, value)
		end
	end

	local dragging = false
	local function setFromX(x)
		local rel = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
		value = round(min + rel * (max - min))
		apply(true)
	end

	track.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = true
			setFromX(input.Position.X)
		end
	end)
	local c1 = UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = false
		end
	end)
	local c2 = UserInputService.InputChanged:Connect(function(input)
		if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
			setFromX(input.Position.X)
		end
	end)

	apply(false)

	control = {
		instance = f,
		conns = { c1, c2 },
		get = function()
			return value
		end,
		set = function(v, fire)
			value = math.clamp(round(tonumber(v) or min), min, max)
			apply(fire ~= false)
		end,
	}
	return control
end

-- ---------------------------------------------------------------- Input ----
function CustomWidgets.input(parent, text, default, callback)
	local f = row(parent, ROW_H)
	local hasLabel = text ~= nil and tostring(text) ~= ""
	if hasLabel then
		label(f, tostring(text), 13, Enum.TextXAlignment.Left, UDim2.new(0.4, -8, 1, 0))
	end

	local boxHolder = Library:Create("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -6, 0.5, 0),
		Size = hasLabel and UDim2.new(0.6, -10, 1, -8) or UDim2.new(1, -12, 1, -8),
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Parent = f,
	})
	corner(boxHolder, 3)
	stroke(boxHolder, "OutlineColor", 0.3)
	Library:AddToRegistry(boxHolder, { BackgroundColor3 = "MainColor" })

	local tb = Library:Create("TextBox", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(6, 0),
		Size = UDim2.new(1, -10, 1, 0),
		Font = Enum.Font.Gotham,
		TextSize = 12,
		TextColor3 = Library.FontColor,
		PlaceholderText = "...",
		PlaceholderColor3 = Library.OutlineColor,
		Text = tostring(default or ""),
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = boxHolder,
	})
	Library:AddToRegistry(tb, { TextColor3 = "FontColor" }, true)

	tb.FocusLost:Connect(function()
		if callback then
			pcall(callback, tb.Text)
		end
	end)

	return {
		instance = f,
		conns = {},
		get = function()
			return tb.Text
		end,
		set = function(t)
			tb.Text = tostring(t or "")
		end,
	}
end

-- ---------------------------------------------------------------- Keybind ----
function CustomWidgets.keybind(parent, text, default, callback)
	local key = default
	local listening = false
	local f = row(parent, ROW_H)

	label(f, tostring(text or "Keybind"), 13, Enum.TextXAlignment.Left, UDim2.new(1, -74, 1, 0))

	local keyBtn = Library:Create("TextButton", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -8, 0.5, 0),
		Size = UDim2.fromOffset(60, 18),
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		AutoButtonColor = false,
		Font = Enum.Font.GothamSemibold,
		TextSize = 11,
		TextColor3 = Library.AccentColor,
		Text = key and tostring(key) or "None",
		Parent = f,
	})
	corner(keyBtn, 3)
	stroke(keyBtn, "OutlineColor", 0.3)
	Library:AddToRegistry(keyBtn, { BackgroundColor3 = "MainColor", TextColor3 = "AccentColor" })

	keyBtn.MouseButton1Click:Connect(function()
		listening = true
		keyBtn.Text = "..."
	end)

	local conn = UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if listening and input.UserInputType == Enum.UserInputType.Keyboard then
			listening = false
			if input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Escape then
				key = nil
				keyBtn.Text = "None"
			else
				key = input.KeyCode.Name
				keyBtn.Text = key
			end
			return
		end
		if gameProcessed then
			return
		end
		if key and input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode.Name == key then
			if callback then
				pcall(callback, key)
			end
		end
	end)

	return {
		instance = f,
		conns = { conn },
		get = function()
			return key
		end,
		set = function(k)
			key = k
			keyBtn.Text = k and tostring(k) or "None"
		end,
	}
end

-- ---------------------------------------------------------------- Dropdown ----
-- Collapsed row shows the selected value; clicking expands an inline option list below it.
function CustomWidgets.dropdown(parent, text, values, default, callback)
	values = values or {}
	local selected = default
	if selected == nil and values[1] ~= nil then
		selected = values[1]
	end

	local f = Library:Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, ROW_H),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = parent,
	})

	local header = row(f, ROW_H)
	label(header, tostring(text or "Dropdown"), 13, Enum.TextXAlignment.Left, UDim2.new(0.5, -8, 1, 0))

	local valueLabel = Library:Create("TextLabel", {
		AnchorPoint = Vector2.new(1, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(1, -22, 0.5, 0),
		Size = UDim2.new(0.5, 0, 1, 0),
		Font = Enum.Font.GothamSemibold,
		TextSize = 12,
		TextColor3 = Library.AccentColor,
		TextXAlignment = Enum.TextXAlignment.Right,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Text = selected ~= nil and tostring(selected) or "...",
		Parent = header,
	})
	Library:AddToRegistry(valueLabel, { TextColor3 = "AccentColor" }, true)

	local arrow = Library:Create("TextLabel", {
		AnchorPoint = Vector2.new(1, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(1, -8, 0.5, 0),
		Size = UDim2.fromOffset(12, 12),
		Font = Enum.Font.GothamBold,
		TextSize = 12,
		TextColor3 = Library.FontColor,
		Text = "+",
		Parent = header,
	})

	local listHolder = Library:Create("Frame", {
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, ROW_H + 2),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
		Parent = f,
	})
	corner(listHolder, 4)
	stroke(listHolder, "OutlineColor", 0.3)
	Library:AddToRegistry(listHolder, { BackgroundColor3 = "MainColor" })
	Library:Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = listHolder })
	Library:Create("UIPadding", {
		PaddingTop = UDim.new(0, 2),
		PaddingBottom = UDim.new(0, 2),
		Parent = listHolder,
	})

	local open = false
	local function setOpen(v)
		open = v
		listHolder.Visible = v
		arrow.Text = v and "-" or "+"
	end

	local headerBtn = Library:Create("TextButton", {
		BackgroundTransparency = 1,
		Text = "",
		Size = UDim2.fromScale(1, 1),
		Parent = header,
	})
	headerBtn.MouseButton1Click:Connect(function()
		setOpen(not open)
	end)

	local control
	local function rebuild()
		for _, c in ipairs(listHolder:GetChildren()) do
			if c:IsA("TextButton") then
				c:Destroy()
			end
		end
		for i, v in ipairs(values) do
			local opt = Library:Create("TextButton", {
				BackgroundTransparency = 1,
				AutoButtonColor = false,
				Font = Enum.Font.Gotham,
				Text = tostring(v),
				TextSize = 12,
				TextColor3 = Library.FontColor,
				TextXAlignment = Enum.TextXAlignment.Left,
				Size = UDim2.new(1, -8, 0, 20),
				Position = UDim2.fromOffset(6, 0),
				LayoutOrder = i,
				Parent = listHolder,
			})
			opt.MouseEnter:Connect(function()
				opt.TextColor3 = Library.AccentColor
			end)
			opt.MouseLeave:Connect(function()
				opt.TextColor3 = Library.FontColor
			end)
			opt.MouseButton1Click:Connect(function()
				selected = v
				valueLabel.Text = tostring(v)
				setOpen(false)
				if callback then
					pcall(callback, v)
				end
			end)
		end
	end
	rebuild()

	control = {
		instance = f,
		conns = {},
		get = function()
			return selected
		end,
		set = function(v, fire)
			selected = v
			valueLabel.Text = v ~= nil and tostring(v) or "..."
			if fire ~= false and callback then
				pcall(callback, v)
			end
		end,
		setValues = function(newValues)
			values = newValues or {}
			rebuild()
		end,
	}
	return control
end

-- ---------------------------------------------------------------- Section ----
-- A labelled container with its own vertical body for nested widgets.
function CustomWidgets.section(parent, title)
	local f = Library:Create("Frame", {
		BackgroundColor3 = Library.MainColor,
		BackgroundTransparency = 0.2,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 24),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = parent,
	})
	corner(f, 4)
	stroke(f, "OutlineColor", 0.5)
	Library:AddToRegistry(f, { BackgroundColor3 = "MainColor" })

	Library:Create("UIPadding", {
		PaddingTop = UDim.new(0, 6),
		PaddingBottom = UDim.new(0, 6),
		PaddingLeft = UDim.new(0, 6),
		PaddingRight = UDim.new(0, 6),
		Parent = f,
	})
	Library:Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 4),
		Parent = f,
	})

	local head = Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Font = Enum.Font.GothamBold,
		Text = tostring(title or "Section"),
		TextSize = 13,
		TextColor3 = Library.AccentColor,
		TextXAlignment = Enum.TextXAlignment.Left,
		Size = UDim2.new(1, 0, 0, 16),
		LayoutOrder = 0,
		Parent = f,
	})
	Library:AddToRegistry(head, { TextColor3 = "AccentColor" }, true)

	local body = Library:Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = f,
	})
	Library:Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 4),
		Parent = body,
	})

	return { instance = f, body = body, conns = {} }
end

return CustomWidgets

end)
__bundle_register("Menu/CustomTab", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module GUI.Icons
local Icons = require("GUI/Icons")

---@module GUI.Library
local Library = require("GUI/Library")

---@module GUI.SaveManager
local SaveManager = require("GUI/SaveManager")

---@module Menu.Objects.CodeEditor
local CodeEditor = require("Menu/Objects/CodeEditor")

---@module Menu.Objects.FloatingWindow
local FloatingWindow = require("Menu/Objects/FloatingWindow")

---@module Features.Custom.Custom
local Custom = require("Features/Custom/Custom")

---@module Features.Custom.AIChat
local AIChat = require("Features/Custom/AIChat")

local CustomTab = {}

local editor -- the code editor control { get, set, setEditable }
local editorWindow
local chatWindow
local statusLabel

local function setStatus(fmt, ...)
	local text = select("#", ...) > 0 and string.format(fmt, ...) or fmt
	pcall(function()
		statusLabel:SetText(text)
	end)
end

local function currentName()
	local name = Options.Custom_FeatureName and Options.Custom_FeatureName.Value or ""
	if type(name) ~= "string" or name:gsub("%s", "") == "" then
		return nil
	end
	return name
end

local function refreshList()
	if Options.Custom_FeatureList then
		Options.Custom_FeatureList:SetValues(Custom.list())
	end
end

-- ============================================================ Editor window (pure code editor)
local function buildEditorWindow()
	editorWindow = FloatingWindow.new({
		title = "Aero - Code Editor",
		size = UDim2.fromOffset(540, 560),
		position = UDim2.fromScale(0.35, 0.5),
	})
	editor = CodeEditor.create(editorWindow.body, 514, "-- write your feature here, or generate one from AI Chat", 205)
	editor.set(Custom.TEMPLATE)
end

-- ============================================================ Chat window (agentic AI)
local function buildChatWindow()
	chatWindow = FloatingWindow.new({
		title = "Aero - AI Chat",
		size = UDim2.fromOffset(430, 520),
		position = UDim2.fromScale(0.65, 0.5),
	})
	local body = chatWindow.body

	local transcript = Library:Create("ScrollingFrame", {
		BackgroundColor3 = Library.BackgroundColor,
		BackgroundTransparency = 0.4,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.new(1, 0, 1, -64),
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 4,
		ZIndex = 202,
		Parent = body,
	})
	Library:Create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = transcript })
	Library:AddToRegistry(transcript, { BackgroundColor3 = "BackgroundColor" })
	Library:Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4), Parent = transcript })
	Library:Create("UIPadding", {
		PaddingTop = UDim.new(0, 4),
		PaddingBottom = UDim.new(0, 4),
		PaddingLeft = UDim.new(0, 6),
		PaddingRight = UDim.new(0, 6),
		Parent = transcript,
	})

	local order = 0
	local function addMsg(role, text)
		order = order + 1
		local color = Library.FontColor
		local prefix = ""
		if role == "user" then
			color = Library.AccentColor
			prefix = "You: "
		elseif role == "assistant" then
			color = Library.FontColor
			prefix = "AI: "
		elseif role == "tool" then
			color = Library.OutlineColor
			prefix = "[tool] "
		elseif role == "toolresult" then
			color = Library.OutlineColor
			prefix = "[result] "
			if #text > 500 then
				text = text:sub(1, 500) .. " ... (" .. #text .. " chars)"
			end
		elseif role == "error" then
			color = Color3.fromRGB(255, 96, 96)
			prefix = "[error] "
		end

		local lbl = Library:Create("TextLabel", {
			BackgroundTransparency = 1,
			Font = (role == "tool" or role == "toolresult") and Enum.Font.Code or Enum.Font.Gotham,
			Text = prefix .. tostring(text),
			TextSize = (role == "tool" or role == "toolresult") and 11 or 12,
			TextColor3 = color,
			TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = order,
			ZIndex = 203,
			Parent = transcript,
		})
		task.defer(function()
			transcript.CanvasPosition = Vector2.new(0, math.max(0, transcript.AbsoluteCanvasSize.Y))
		end)
		return lbl
	end

	addMsg("assistant", "Ask me to build a feature or explain the game. I can inspect the live game and decompile scripts. Set your provider/key in the Custom tab first.")

	local statusText = Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 2, 1, -62),
		Size = UDim2.new(1, -4, 0, 12),
		Font = Enum.Font.Gotham,
		Text = "",
		TextSize = 11,
		TextColor3 = Library.AccentColor,
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 202,
		Parent = body,
	})
	Library:AddToRegistry(statusText, { TextColor3 = "AccentColor" })

	local inputHolder = Library:Create("Frame", {
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 0, 1, -46),
		Size = UDim2.new(1, -66, 0, 28),
		ZIndex = 202,
		Parent = body,
	})
	Library:Create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = inputHolder })
	local is = Library:Create("UIStroke", { Color = Library.OutlineColor, Thickness = 1, Transparency = 0.3, Parent = inputHolder })
	Library:AddToRegistry(inputHolder, { BackgroundColor3 = "MainColor" })
	Library:AddToRegistry(is, { Color = "OutlineColor" })

	local inputBox = Library:Create("TextBox", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 0),
		Size = UDim2.new(1, -14, 1, 0),
		Font = Enum.Font.Gotham,
		TextSize = 12,
		TextColor3 = Library.FontColor,
		PlaceholderText = "Describe a feature, or ask about the game...",
		PlaceholderColor3 = Library.OutlineColor,
		Text = "",
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 203,
		Parent = inputHolder,
	})
	Library:AddToRegistry(inputBox, { TextColor3 = "FontColor" })

	local sendBtn = Library:Create("TextButton", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 1, -46),
		Size = UDim2.fromOffset(60, 28),
		BackgroundColor3 = Library.AccentColor,
		BorderSizePixel = 0,
		AutoButtonColor = false,
		Font = Enum.Font.GothamSemibold,
		Text = "Send",
		TextSize = 12,
		TextColor3 = Library.MainColor,
		ZIndex = 203,
		Parent = body,
	})
	Library:Create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = sendBtn })
	Library:AddToRegistry(sendBtn, { BackgroundColor3 = "AccentColor", TextColor3 = "MainColor" })

	local clearBtn = Library:Create("TextButton", {
		Position = UDim2.new(0, 0, 1, -16),
		Size = UDim2.new(0.5, -2, 0, 16),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Font = Enum.Font.Gotham,
		Text = "Clear chat",
		TextSize = 11,
		TextColor3 = Library.OutlineColor,
		ZIndex = 203,
		Parent = body,
	})
	Library:AddToRegistry(clearBtn, { TextColor3 = "OutlineColor" })

	local toEditorBtn = Library:Create("TextButton", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 1, -16),
		Size = UDim2.new(0.5, -2, 0, 16),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Font = Enum.Font.GothamSemibold,
		Text = "Send code to editor ->",
		TextSize = 11,
		TextColor3 = Library.AccentColor,
		ZIndex = 203,
		Parent = body,
	})
	Library:AddToRegistry(toEditorBtn, { TextColor3 = "AccentColor" })

	local busy = false
	local currentAssistant = nil

	local function scrollBottom()
		task.defer(function()
			transcript.CanvasPosition = Vector2.new(0, math.max(0, transcript.AbsoluteCanvasSize.Y))
		end)
	end

	local function onEvent(kind, payload)
		if kind == "status" then
			statusText.Text = tostring(payload or "")
		elseif kind == "done" then
			busy = false
			currentAssistant = nil
			sendBtn.Text = "Send"
			statusText.Text = ""
		elseif kind == "user" then
			addMsg("user", payload)
		elseif kind == "assistant_begin" then
			currentAssistant = addMsg("assistant", "")
		elseif kind == "assistant_delta" then
			if currentAssistant then
				currentAssistant.Text = currentAssistant.Text .. tostring(payload)
				scrollBottom()
			end
		elseif kind == "assistant_end" then
			currentAssistant = nil
		elseif kind == "assistant" then
			addMsg("assistant", payload)
		elseif kind == "tool" then
			addMsg("tool", payload)
		elseif kind == "toolresult" then
			addMsg("toolresult", payload)
		elseif kind == "error" then
			addMsg("error", payload)
		end
	end

	local function doSend()
		if busy then
			AIChat.cancel()
			statusText.Text = "stopping..."
			return
		end
		local text = inputBox.Text
		if type(text) ~= "string" or text:gsub("%s", "") == "" then
			return
		end
		inputBox.Text = ""
		busy = true
		sendBtn.Text = "Stop"
		AIChat.send(text, onEvent)
	end

	sendBtn.MouseButton1Click:Connect(doSend)
	inputBox.FocusLost:Connect(function(enterPressed)
		if enterPressed and not busy then
			doSend()
		end
	end)

	clearBtn.MouseButton1Click:Connect(function()
		AIChat.reset()
		for _, c in ipairs(transcript:GetChildren()) do
			if c:IsA("TextLabel") then
				c:Destroy()
			end
		end
		order = 0
		addMsg("assistant", "Chat cleared.")
	end)

	toEditorBtn.MouseButton1Click:Connect(function()
		if AIChat.lastCode and editor then
			editor.set(AIChat.lastCode)
			editorWindow:Show()
			setStatus("Pulled AI code into the editor.")
		end
	end)
end

-- ============================================================ tab
function CustomTab.init(window)
	local tab = window:AddTab("Custom", "Custom", Icons.Settings)

	SaveManager:SetIgnoreIndexes({
		"Custom_FeatureName",
		"Custom_FeatureList",
		"Custom_AIKey",
		"Custom_AIModel",
		"Custom_AIProvider",
		"Custom_Autorun",
	})

	buildEditorWindow()
	buildChatWindow()

	-- --------------------------------- LEFT: windows + feature management
	local manageBox = tab:AddLeftGroupbox("Custom Features")

	manageBox
		:AddButton("Open Code Editor", function()
			editorWindow:Show()
		end)
		:AddButton("Open AI Chat", function()
			chatWindow:Show()
		end)

	manageBox:AddInput("Custom_FeatureName", { Text = "Feature name", Default = "" })
	manageBox:AddDropdown("Custom_FeatureList", { Text = "Saved features", Values = Custom.list(), AllowNull = true })

	manageBox
		:AddButton("Run / Reload", function()
			if not editor then
				return setStatus("Editor not ready.")
			end
			if not currentName() then
				Options.Custom_FeatureName:SetValue("Untitled")
			end
			local name = currentName() or "Untitled"
			local source = editor.get()
			Custom.save(name, source)
			refreshList()
			local ok, err = Custom.run(name, source)
			if ok then
				setStatus("Running '%s'.", name)
			else
				setStatus("Error: %s", tostring(err))
			end
		end)
		:AddButton("Stop", function()
			local name = currentName()
			if not name then
				return setStatus("Nothing to stop.")
			end
			Custom.stop(name)
			setStatus("Stopped '%s'.", name)
		end)

	manageBox
		:AddButton("Save", function()
			local name = currentName()
			if not name then
				return setStatus("Enter a feature name first.")
			end
			local ok, err = Custom.save(name, editor and editor.get() or "")
			if ok then
				refreshList()
				setStatus("Saved '%s'.", name)
			else
				setStatus("Save failed: %s", tostring(err))
			end
		end)
		:AddButton("Load", function()
			local sel = Options.Custom_FeatureList.Value
			if type(sel) ~= "string" or sel == "" then
				return setStatus("Select a feature to load.")
			end
			local source = Custom.load(sel)
			if not source then
				return setStatus("Could not read '%s'.", sel)
			end
			if editor then
				editor.set(source)
			end
			Options.Custom_FeatureName:SetValue(sel)
			if Toggles.Custom_Autorun then
				Toggles.Custom_Autorun:SetValue(Custom.isAutorun(sel))
			end
			editorWindow:Show()
			setStatus("Loaded '%s'.", sel)
		end)

	manageBox
		:AddButton("New", function()
			if editor then
				editor.set(Custom.TEMPLATE)
			end
			Options.Custom_FeatureName:SetValue("")
			setStatus("New feature.")
		end)
		:AddButton("Delete", function()
			local sel = Options.Custom_FeatureList.Value
			if type(sel) ~= "string" or sel == "" then
				return setStatus("Select a feature to delete.")
			end
			Custom.delete(sel)
			refreshList()
			Options.Custom_FeatureList:SetValue(nil)
			setStatus("Deleted '%s'.", sel)
		end)

	local autorunToggle = manageBox:AddToggle("Custom_Autorun", {
		Text = "Autorun this feature on load",
		Default = false,
	})
	autorunToggle:OnChanged(function(value)
		local name = currentName()
		if name then
			Custom.setAutorun(name, value)
		end
	end)

	statusLabel = manageBox:AddLabel("Idle.", true)

	-- --------------------------------- LEFT: AI settings
	local aiBox = tab:AddLeftGroupbox("AI Settings")
	local s = Custom.settings()

	aiBox:AddDropdown("Custom_AIProvider", { Text = "Provider", Values = Custom.PROVIDERS, Default = s.provider })
	aiBox:AddInput("Custom_AIModel", { Text = "Model", Default = s.model })
	aiBox:AddInput("Custom_AIKey", { Text = "API key", Default = s.apiKey })

	local aiReady = false
	Options.Custom_AIProvider:OnChanged(function(value)
		Custom.setSetting("provider", value)
		if aiReady then
			local model = Custom.DEFAULT_MODELS[value]
			if model then
				Options.Custom_AIModel:SetValue(model)
			end
		end
	end)
	Options.Custom_AIModel:OnChanged(function(value)
		Custom.setSetting("model", value)
	end)
	Options.Custom_AIKey:OnChanged(function(value)
		Custom.setSetting("apiKey", value)
	end)
	aiReady = true

	aiBox:AddLabel("Key is stored locally (workspace/Aero/Custom), never in configs.", true)

	-- --------------------------------- RIGHT: live controls host
	local controlsBox = tab:AddRightGroupbox("Custom Controls")

	local holder = Library:Create("Frame", {
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -4, 0, 360),
		LayoutOrder = 9999,
		ZIndex = 5,
		Parent = controlsBox.Container,
	})
	Library:Create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = holder })
	Library:AddToRegistry(holder, { BackgroundColor3 = "MainColor" })
	local hstroke = Library:Create("UIStroke", { Color = Library.OutlineColor, Thickness = 1, Transparency = 0.5, Parent = holder })
	Library:AddToRegistry(hstroke, { Color = "OutlineColor" })

	local host = Library:Create("ScrollingFrame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(6, 6),
		Size = UDim2.new(1, -12, 1, -12),
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 4,
		ZIndex = 6,
		Parent = holder,
	})
	Library:Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6), Parent = host })
	Library:Create("UIPadding", { PaddingRight = UDim.new(0, 4), Parent = host })

	local emptyHint = Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 40),
		Font = Enum.Font.Gotham,
		Text = "Run a feature to see its controls here.",
		TextSize = 12,
		TextColor3 = Library.OutlineColor,
		TextWrapped = true,
		Parent = host,
	})
	Library:AddToRegistry(emptyHint, { TextColor3 = "OutlineColor" }, true)

	Custom.setHost(host)

	pcall(function()
		controlsBox:Resize()
	end)

	task.spawn(function()
		Custom.autorunAll()
	end)
end

return CustomTab

end)
__bundle_register("Features/Custom/AIChat", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Conversational AI agent for the Custom tab. Keeps a message transcript, calls the configured provider
-- (OpenAI / Anthropic / Google) as a multi-turn chat, and runs a ReAct-style tool loop: the model asks
-- for a tool by replying with a JSON object, we run it against the live game (GameTools) and feed the
-- result back, repeating until the model gives a final answer. Provider-agnostic (plain chat, no native
-- function-calling), so it works the same across all three.

---@module Utility.JSON
local JSON = require("Utility/JSON")

---@module Features.Custom.GameTools
local GameTools = require("Features/Custom/GameTools")

---@module Features.Custom.Custom
local Custom = require("Features/Custom/Custom")

local AIChat = {}

local MAX_STEPS = 10

AIChat.busy = false
AIChat.lastCode = nil
AIChat.messages = nil
AIChat.current = nil -- active run token (for interrupt)

-- Stop the in-flight run. Takes effect between steps / mid-reveal (a blocking request() can't be aborted).
function AIChat.cancel()
	if AIChat.current then
		AIChat.current.cancelled = true
	end
end

local function httpRequest()
	return (syn and syn.request)
		or (http and http.request)
		or http_request
		or request
		or (getgenv and getgenv().request)
end

local function systemPrompt()
	return table.concat({
		"You are an expert assistant embedded in 'aero', a menu for the Roblox game Deepwoken. You help the",
		"user understand the game and build custom features. You can inspect the LIVE game and decompile",
		"scripts via tools before answering, so prefer checking real data over guessing.",
		"",
		GameTools.API_REFERENCE,
		"",
		GameTools.TOOLS_DOC,
		"",
		"Be concise. When the user asks for a feature, inspect what you need, then give the final code in a",
		"single ```lua block using only the API above.",
	}, "\n")
end

function AIChat.reset()
	AIChat.messages = { { role = "system", content = systemPrompt() } }
	AIChat.lastCode = nil
end

local function ensureInit()
	if not AIChat.messages then
		AIChat.reset()
	end
end

-- ------------------------------------------------------------ provider chat completion (synchronous)
local function chatComplete(messages)
	local s = Custom.settings()
	local req = httpRequest()
	if not req then
		return false, "no HTTP request function on this executor"
	end
	if not s.apiKey or s.apiKey:gsub("%s", "") == "" then
		return false, "set your API key in the Custom tab first"
	end

	local provider = s.provider or "OpenAI"
	local model = (s.model and s.model:gsub("%s", "") ~= "" and s.model) or Custom.DEFAULT_MODELS[provider] or "gpt-4o-mini"

	local url, headers, body
	if provider == "Anthropic" then
		local system = {}
		local msgs = {}
		for _, m in ipairs(messages) do
			if m.role == "system" then
				system[#system + 1] = m.content
			else
				msgs[#msgs + 1] = { role = m.role, content = m.content }
			end
		end
		url = "https://api.anthropic.com/v1/messages"
		headers = {
			["x-api-key"] = s.apiKey,
			["anthropic-version"] = "2023-06-01",
			["Content-Type"] = "application/json",
		}
		body = JSON.encode({
			model = model,
			max_tokens = 4096,
			system = table.concat(system, "\n"),
			messages = msgs,
		})
	elseif provider == "Google" then
		local system = {}
		local contents = {}
		for _, m in ipairs(messages) do
			if m.role == "system" then
				system[#system + 1] = m.content
			else
				local role = (m.role == "assistant") and "model" or "user"
				contents[#contents + 1] = { role = role, parts = { { text = m.content } } }
			end
		end
		url = "https://generativelanguage.googleapis.com/v1beta/models/" .. model .. ":generateContent?key=" .. s.apiKey
		headers = { ["Content-Type"] = "application/json" }
		body = JSON.encode({
			system_instruction = { parts = { { text = table.concat(system, "\n") } } },
			contents = contents,
		})
	else
		url = "https://api.openai.com/v1/chat/completions"
		headers = {
			["Authorization"] = "Bearer " .. s.apiKey,
			["Content-Type"] = "application/json",
		}
		body = JSON.encode({
			model = model,
			temperature = 0.3,
			messages = messages,
		})
	end

	local ok, res = pcall(req, { Url = url, Method = "POST", Headers = headers, Body = body })
	if not ok or type(res) ~= "table" then
		return false, "request failed: " .. tostring(res)
	end
	local status = res.StatusCode or res.Status or 0
	if type(res.Body) ~= "string" or res.Body == "" then
		return false, "empty response (status " .. tostring(status) .. ")"
	end
	local decodeOk, decoded = pcall(JSON.decode, res.Body)
	if not decodeOk or type(decoded) ~= "table" then
		return false, "bad JSON (status " .. tostring(status) .. ")"
	end
	if decoded.error then
		local msg = type(decoded.error) == "table" and decoded.error.message or tostring(decoded.error)
		return false, "api error: " .. tostring(msg)
	end

	local content
	if provider == "Anthropic" then
		if decoded.content then
			local parts = {}
			for _, p in ipairs(decoded.content) do
				if p.type == "text" and p.text then
					parts[#parts + 1] = p.text
				end
			end
			content = table.concat(parts)
		end
	elseif provider == "Google" then
		local cand = decoded.candidates and decoded.candidates[1]
		if cand and cand.content and cand.content.parts then
			local parts = {}
			for _, p in ipairs(cand.content.parts) do
				if p.text then
					parts[#parts + 1] = p.text
				end
			end
			content = table.concat(parts)
		end
	else
		content = decoded.choices and decoded.choices[1] and decoded.choices[1].message and decoded.choices[1].message.content
	end

	if type(content) ~= "string" or content:gsub("%s", "") == "" then
		return false, "no content in response (status " .. tostring(status) .. ")"
	end
	return true, content
end

-- ------------------------------------------------------------ parsing
local function stripFence(text)
	local inner = text:match("^%s*```[%w]*%s*\n(.-)\n?%s*```%s*$")
	return inner or text
end

local function parseToolCall(text)
	local t = stripFence(text)
	t = t:gsub("^%s+", ""):gsub("%s+$", "")
	if t:sub(1, 1) ~= "{" then
		return nil
	end
	local ok, decoded = pcall(JSON.decode, t)
	if ok and type(decoded) == "table" and type(decoded.tool) == "string" then
		return { tool = decoded.tool, args = type(decoded.args) == "table" and decoded.args or {} }
	end
	return nil
end

local function extractCode(text)
	local c = text:match("```lua%s*\n(.-)```") or text:match("```%s*\n(.-)```")
	if c and c:gsub("%s", "") ~= "" then
		return c
	end
	return nil
end
AIChat.extractCode = extractCode

-- Reveal the final answer progressively (typewriter). request() returns the whole body at once, so this
-- is a cosmetic reveal, interruptible via the run token. Chunk size scales with length (~160 ticks total).
local function streamOut(text, onEvent, token)
	AIChat.lastCode = extractCode(text) or AIChat.lastCode
	onEvent("assistant_begin")
	local n = #text
	local chunkSize = math.max(2, math.floor(n / 160))
	local i = 1
	while i <= n do
		if token.cancelled then
			onEvent("assistant_delta", text:sub(i)) -- reveal the remainder instantly on stop
			break
		end
		onEvent("assistant_delta", text:sub(i, i + chunkSize - 1))
		i = i + chunkSize
		task.wait(0.012)
	end
	onEvent("assistant_end")
end

-- ------------------------------------------------------------ agent loop
---@param userText string
---@param onEvent fun(kind: string, text: string?)
-- kinds: user, assistant_begin, assistant_delta, assistant_end, tool, toolresult, error, status, done
function AIChat.send(userText, onEvent)
	ensureInit()
	if AIChat.busy then
		onEvent("error", "still working on the previous message...")
		return
	end
	if type(userText) ~= "string" or userText:gsub("%s", "") == "" then
		return
	end

	local token = { cancelled = false }
	AIChat.current = token
	AIChat.busy = true
	table.insert(AIChat.messages, { role = "user", content = userText })
	onEvent("user", userText)

	task.spawn(function()
		local steps = 0
		local finished = false
		while steps < MAX_STEPS do
			if token.cancelled then
				onEvent("status", "stopped.")
				finished = true
				break
			end
			steps = steps + 1
			onEvent("status", steps > 1 and ("thinking... (step " .. steps .. ")") or "thinking...")

			local ok, text = chatComplete(AIChat.messages)
			if token.cancelled then
				onEvent("status", "stopped.")
				finished = true
				break
			end
			if not ok then
				onEvent("error", text)
				finished = true
				break
			end

			table.insert(AIChat.messages, { role = "assistant", content = text })

			local call = parseToolCall(text)
			if call then
				local argsStr = ""
				pcall(function()
					argsStr = JSON.encode(call.args)
				end)
				onEvent("tool", call.tool .. " " .. argsStr)
				local result = GameTools.run(call.tool, call.args)
				onEvent("toolresult", result)
				table.insert(AIChat.messages, {
					role = "user",
					content = "TOOL RESULT (" .. call.tool .. "):\n" .. result,
				})
			else
				streamOut(text, onEvent, token)
				finished = true
				break
			end
		end

		if not finished then
			onEvent("error", "reached the tool-step limit; ask again or be more specific")
		end

		AIChat.busy = false
		AIChat.current = nil
		onEvent("done")
	end)
end

return AIChat

end)
__bundle_register("Features/Custom/GameTools", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Tools the AI agent can call to inspect the live game and decompile scripts, plus the full aero custom
-- feature API reference it builds code against. Everything is read-only and bounded so a tool call can't
-- hang or dump unbounded output. GameTools.run(name, args) -> string result.

---@module Features.Custom.Custom
local Custom = require("Features/Custom/Custom")

local GameTools = {}

local Players = game:GetService("Players")

-- ------------------------------------------------------------ path resolution
-- Resolve a dot path from the DataModel, e.g. "game.Workspace.Live", "Players.LocalPlayer",
-- "Players.LocalPlayer.Character". Handles services + the LocalPlayer/Character property shortcuts.
local function resolvePath(path)
	if type(path) ~= "string" or path:gsub("%s", "") == "" then
		return game
	end
	path = path:gsub("/", ".")
	local cur = game
	local first = true
	for token in path:gmatch("[^%.]+") do
		if first and (token == "game" or token == "Game" or token == "DataModel") then
			cur = game
		elseif token == "LocalPlayer" then
			cur = Players.LocalPlayer
			if not cur then
				return nil, "LocalPlayer is nil"
			end
		elseif token == "Character" and typeof(cur) == "Instance" and cur:IsA("Player") then
			cur = cur.Character
			if not cur then
				return nil, "Character is nil"
			end
		else
			local nextInst = nil
			if cur == game then
				pcall(function()
					nextInst = game:GetService(token)
				end)
			end
			if not nextInst then
				nextInst = cur:FindFirstChild(token)
			end
			if not nextInst then
				return nil, "not found: '" .. token .. "' under " .. cur:GetFullName()
			end
			cur = nextInst
		end
		first = false
	end
	return cur
end

GameTools.resolvePath = resolvePath

-- ------------------------------------------------------------ tools
local function tExplore(path, depth)
	local inst, err = resolvePath(path)
	if not inst then
		return "Error: " .. tostring(err)
	end
	depth = math.clamp(tonumber(depth) or 1, 1, 3)
	local lines = { inst:GetFullName() .. "  [" .. inst.ClassName .. "]" }
	local count = 0
	local function walk(node, d, indent)
		if count >= 200 then
			return
		end
		local ok, children = pcall(function()
			return node:GetChildren()
		end)
		if not ok then
			return
		end
		for _, child in ipairs(children) do
			count = count + 1
			if count >= 200 then
				lines[#lines + 1] = indent .. "... (truncated)"
				return
			end
			lines[#lines + 1] = indent .. child.Name .. "  [" .. child.ClassName .. "]"
			if d > 1 then
				walk(child, d - 1, indent .. "  ")
			end
		end
	end
	walk(inst, depth, "  ")
	if count == 0 then
		lines[#lines + 1] = "  (no children)"
	end
	return table.concat(lines, "\n")
end

local PROP_CANDIDATES = {
	"Name", "ClassName", "Enabled", "Value", "Visible", "Transparency", "Anchored", "CanCollide",
	"Position", "Size", "Orientation", "CFrame", "Health", "MaxHealth", "WalkSpeed", "JumpPower",
	"HipHeight", "DisplayName", "Text", "PlaceholderText", "Color", "BrickColor", "Material",
	"Massless", "CollisionGroup", "MeshId", "TextureId", "SoundId", "Volume", "Playing", "TimePosition",
	"AssetId", "AnimationId", "PrimaryPart", "Adornee", "Active",
}

local function tProperties(path)
	local inst, err = resolvePath(path)
	if not inst then
		return "Error: " .. tostring(err)
	end
	local out = { inst:GetFullName() .. "  [" .. inst.ClassName .. "]" }
	for _, p in ipairs(PROP_CANDIDATES) do
		local ok, v = pcall(function()
			return inst[p]
		end)
		if ok and v ~= nil then
			out[#out + 1] = p .. " = " .. tostring(v)
		end
	end
	pcall(function()
		if inst.Parent then
			out[#out + 1] = "Parent = " .. inst.Parent:GetFullName()
		end
	end)
	local okA, attrs = pcall(function()
		return inst:GetAttributes()
	end)
	if okA and type(attrs) == "table" then
		for k, v in pairs(attrs) do
			out[#out + 1] = "@" .. tostring(k) .. " = " .. tostring(v)
		end
	end
	return table.concat(out, "\n")
end

local function matchClass(className, filter)
	if filter == nil or filter == "" then
		return true
	end
	return className == filter
end

local function tSearch(query, class, rootPath)
	local root, err = resolvePath(rootPath or "game")
	if not root then
		return "Error: " .. tostring(err)
	end
	query = tostring(query or ""):lower()
	local results = {}
	local scanned = 0
	local ok, descendants = pcall(function()
		return root:GetDescendants()
	end)
	if not ok then
		return "Error: could not enumerate descendants."
	end
	for _, d in ipairs(descendants) do
		scanned = scanned + 1
		if scanned > 60000 then
			break
		end
		if matchClass(d.ClassName, class) and (query == "" or d.Name:lower():find(query, 1, true)) then
			results[#results + 1] = d:GetFullName() .. "  [" .. d.ClassName .. "]"
			if #results >= 60 then
				results[#results + 1] = "... (more results omitted)"
				break
			end
		end
	end
	if #results == 0 then
		return "No matches (scanned " .. scanned .. " descendants)."
	end
	return table.concat(results, "\n")
end

local SCRIPT_CLASSES = { LocalScript = true, ModuleScript = true, Script = true }

local function tScripts(rootPath)
	local root, err = resolvePath(rootPath or "game")
	if not root then
		return "Error: " .. tostring(err)
	end
	local results = {}
	local scanned = 0
	local ok, descendants = pcall(function()
		return root:GetDescendants()
	end)
	if not ok then
		return "Error: could not enumerate descendants."
	end
	for _, d in ipairs(descendants) do
		scanned = scanned + 1
		if scanned > 60000 then
			break
		end
		if SCRIPT_CLASSES[d.ClassName] then
			results[#results + 1] = d:GetFullName() .. "  [" .. d.ClassName .. "]"
			if #results >= 80 then
				results[#results + 1] = "... (more omitted)"
				break
			end
		end
	end
	if #results == 0 then
		return "No scripts found."
	end
	return table.concat(results, "\n")
end

local function tDecompile(path)
	local inst, err = resolvePath(path)
	if not inst then
		return "Error: " .. tostring(err)
	end
	if not (typeof(inst) == "Instance" and inst:IsA("LuaSourceContainer")) then
		return "Not a script: " .. inst.ClassName
	end
	local dec = decompile or (getgenv and getgenv().decompile)
	if not dec then
		return "decompile() is not available on this executor."
	end
	local ok, src = pcall(dec, inst)
	if not ok or type(src) ~= "string" then
		return "Decompile failed: " .. tostring(src)
	end
	if #src > 9000 then
		src = src:sub(1, 9000) .. "\n-- [truncated; ask to decompile a nested module for more]"
	end
	return src
end

-- ------------------------------------------------------------ dispatch
---@param name string
---@param args table?
---@return string
function GameTools.run(name, args)
	args = args or {}
	local ok, result = pcall(function()
		if name == "explore" then
			return tExplore(args.path, args.depth)
		elseif name == "properties" then
			return tProperties(args.path)
		elseif name == "search" then
			return tSearch(args.query, args.class, args.root)
		elseif name == "scripts" then
			return tScripts(args.root)
		elseif name == "decompile" then
			return tDecompile(args.path)
		elseif name == "api_reference" then
			return GameTools.API_REFERENCE
		elseif name == "run_feature" then
			local fname = (type(args.name) == "string" and args.name:gsub("%s", "") ~= "") and args.name or "AI Test"
			if type(args.code) ~= "string" or args.code:gsub("%s", "") == "" then
				return "Error: no 'code' provided."
			end
			Custom.save(fname, args.code)
			local okRun, err = Custom.run(fname, args.code)
			if okRun then
				return "Ran '" .. fname .. "' successfully; its controls are now in the Custom Controls panel. "
					.. "Toggle them to verify behaviour, then give the user the final code in a ```lua block."
			end
			return "Run FAILED: " .. tostring(err) .. "\nFix the code and call run_feature again."
		elseif name == "stop_feature" then
			local fname = type(args.name) == "string" and args.name or ""
			Custom.stop(fname)
			return "Stopped '" .. fname .. "'."
		elseif name == "list_features" then
			local names = Custom.list()
			if #names == 0 then
				return "No saved features."
			end
			return table.concat(names, "\n")
		end
		return "Unknown tool: " .. tostring(name)
	end)
	if not ok then
		return "Tool error: " .. tostring(result)
	end
	return tostring(result)
end

-- ------------------------------------------------------------ docs for the system prompt
GameTools.TOOLS_DOC = table.concat({
	"TOOLS -- to call one, reply with ONLY a JSON object (no prose, no code fences):",
	'  {"tool":"explore","args":{"path":"game.Workspace","depth":1}}   -- list children (depth 1-3)',
	'  {"tool":"properties","args":{"path":"game.Players.LocalPlayer.Character.Humanoid"}}',
	'  {"tool":"search","args":{"query":"ClientManager","class":"ModuleScript","root":"game"}}',
	'  {"tool":"scripts","args":{"root":"game.Players.LocalPlayer.PlayerScripts"}}',
	'  {"tool":"decompile","args":{"path":"game.ReplicatedStorage.SomeModule"}}',
	'  {"tool":"api_reference","args":{}}   -- re-read the aero feature API',
	'  {"tool":"run_feature","args":{"name":"My Feature","code":"<full luau code>"}}  -- TEST your code live; returns success or the error',
	'  {"tool":"stop_feature","args":{"name":"My Feature"}}',
	'  {"tool":"list_features","args":{}}',
	"Paths are dot paths from the DataModel. Shortcuts: 'LocalPlayer' and '.Character' resolve correctly.",
	"After I return a tool result, keep going: call more tools or give your final answer. One tool per message.",
	"Prefer to TEST feature code with run_feature before finishing -- if it returns an error, fix it and retry.",
	"When you have enough info, reply normally. If you wrote a feature, put the final code in a ```lua block.",
}, "\n")

GameTools.API_REFERENCE = table.concat({
	"AERO CUSTOM FEATURE API. User code runs in a sandbox inside the 'aero' Deepwoken exploit menu.",
	"These are available as GLOBAL functions (and under the `Aero` table). Use ONLY this API for UI + lifecycle.",
	"",
	"UI (each returns a control; controls have :get()/:set(v) where sensible, accessed as control.get()/control.set(v)):",
	"  Toggle(text, cb_or_opts)   -- cb_or_opts = function(value) OR { default=bool, callback=fn }",
	"  Button(text, function() end)",
	"  Slider(text, { min=number, max=number, default=number, decimals=number, callback=function(value) end })",
	"  Dropdown(text, { values={...}, default=any, callback=function(value) end })  -- control.setValues(t)",
	"  Input(text, { default=string, callback=function(text) end })  -- or Input(text, function(text) end)",
	"  Keybind(text, { default='E', callback=function(key) end })  -- callback fires when the key is pressed",
	"  Label(text)  -- control.set(text)",
	"  Section(title) -> sub-surface with all the same UI methods",
	"  Window(title) -> a floating draggable window; sub-surface with the same UI methods",
	"",
	"Lifecycle (ALL auto-disconnected when the feature is reloaded/stopped):",
	"  OnRender(function(dt) end)   -- RenderStepped (every frame)",
	"  OnStep(function(dt) end)     -- Heartbeat",
	"  OnInput(function(input, gameProcessed) end)  -- UserInputService.InputBegan",
	"  Interval(seconds, function() end)",
	"  OnCleanup(function() end)",
	"  Notify(text, seconds)",
	"",
	"Game helpers:",
	"  LocalPlayer, Character(), HRP(), Humanoid(), Mouse(), Camera()",
	"  GetTarget() -> nearest target { character, humanoid, root, du=distance } or nil ; GetTargets() -> list",
	"  Value(flag) -> read an existing aero toggle/option by its flag string",
	"  Toggles, Options -> raw aero control tables ; Services -> { Players, RunService, Workspace, ... } ; Library",
	"  Standard Roblox globals work: game, workspace, task, math, string, table, Vector3, CFrame, Instance, etc.",
	"",
	"Rules: guard every frame loop with a toggle so it only runs when enabled. Never call loadstring/HttpGet/",
	"setfenv/require inside a feature. Keep code correct and concise. Example:",
	"  local on = Toggle('Enabled', function(v) end)",
	"  Slider('Speed', { min=16, max=200, default=16, callback=function(v)",
	"    local h = Humanoid(); if h then h.WalkSpeed = v end",
	"  end })",
	"  OnRender(function() if not on.get() then return end end)",
}, "\n")

return GameTools

end)
__bundle_register("Menu/Objects/FloatingWindow", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Reusable floating, draggable window (title bar + close button + body) parented to the menu ScreenGui.
-- new{ title, size, position } -> { frame, body, Show, Hide, Toggle, IsOpen, SetTitle }. Starts hidden.

---@module GUI.Library
local Library = require("GUI/Library")

local FloatingWindow = {}

local BAR_H = 26

---@param opts table
---@return table
function FloatingWindow.new(opts)
	opts = opts or {}
	local size = opts.size or UDim2.fromOffset(360, 300)
	local position = opts.position or UDim2.fromScale(0.5, 0.5)

	local outer = Library:Create("Frame", {
		Name = "AeroFloatingWindow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = position,
		Size = size,
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Visible = false,
		ZIndex = 200,
		Parent = Library.ScreenGui,
	})
	Library:Create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = outer })
	local st = Library:Create("UIStroke", { Color = Library.AccentColor, Thickness = 1, Transparency = 0.2, Parent = outer })
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor" })
	Library:AddToRegistry(st, { Color = "AccentColor" })
	pcall(function()
		Library:AddUIScale(outer)
	end)

	local bar = Library:Create("Frame", {
		BackgroundColor3 = Library.BackgroundColor,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, BAR_H),
		ZIndex = 201,
		Parent = outer,
	})
	Library:Create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = bar })
	Library:AddToRegistry(bar, { BackgroundColor3 = "BackgroundColor" })

	-- cover the bar's bottom rounded corners so it sits flush on the body
	Library:Create("Frame", {
		BackgroundColor3 = Library.BackgroundColor,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 0, 1, -6),
		Size = UDim2.new(1, 0, 0, 6),
		ZIndex = 201,
		Parent = bar,
	})

	local titleLabel = Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(10, 0),
		Size = UDim2.new(1, -40, 1, 0),
		Font = Enum.Font.GothamBold,
		Text = tostring(opts.title or "Window"),
		TextSize = 13,
		TextColor3 = Library.FontColor,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 202,
		Parent = bar,
	})
	Library:AddToRegistry(titleLabel, { TextColor3 = "FontColor" })

	local closeBtn = Library:Create("TextButton", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -6, 0.5, 0),
		Size = UDim2.fromOffset(18, 18),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Font = Enum.Font.GothamBold,
		Text = "X",
		TextSize = 13,
		TextColor3 = Library.FontColor,
		ZIndex = 202,
		Parent = bar,
	})
	Library:AddToRegistry(closeBtn, { TextColor3 = "FontColor" })

	local body = Library:Create("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 6, 0, BAR_H + 4),
		Size = UDim2.new(1, -12, 1, -(BAR_H + 10)),
		ZIndex = 201,
		Parent = outer,
	})

	pcall(function()
		Library:MakeDraggable(outer, BAR_H)
	end)

	local window = {
		frame = outer,
		body = body,
	}

	function window:IsOpen()
		return outer.Visible
	end

	function window:Show()
		outer.Visible = true
		outer.ZIndex = 200
	end

	function window:Hide()
		outer.Visible = false
	end

	function window:Toggle()
		if outer.Visible then
			self:Hide()
		else
			self:Show()
		end
	end

	function window:SetTitle(t)
		titleLabel.Text = tostring(t or "")
	end

	closeBtn.MouseEnter:Connect(function()
		closeBtn.TextColor3 = Library.AccentColor
	end)
	closeBtn.MouseLeave:Connect(function()
		closeBtn.TextColor3 = Library.FontColor
	end)
	closeBtn.MouseButton1Click:Connect(function()
		window:Hide()
	end)

	return window
end

return FloatingWindow

end)
__bundle_register("Menu/Objects/CodeEditor", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Reusable Lua code editor widget (line gutter, custom caret, selection highlight, syntax colouring).
-- Lifted from the timing builder's module editor so the Custom tab can offer the exact same editor.
-- create(host, height, placeholder) -> { get, set, setEditable } ; host is a groupbox/tab (has .Container + :Resize()).

---@module GUI.Library
local Library = require("GUI/Library")

local CodeEditor = {}

local LUA_KEYWORDS = {}
for _, kw in ipairs({
	"and", "break", "do", "else", "elseif", "end", "false", "for", "function", "goto",
	"if", "in", "local", "nil", "not", "or", "repeat", "return", "then", "true", "until",
	"while", "continue", "self",
}) do
	LUA_KEYWORDS[kw] = true
end

local HL_KEYWORD = "#f3a8d6"
local HL_STRING = "#a8e6b0"
local HL_NUMBER = "#f5c07a"
local HL_COMMENT = "#8b7fa0"

local function escapeRich(s)
	return (s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

local function span(color, text)
	return '<font color="' .. color .. '">' .. escapeRich(text) .. "</font>"
end

local function highlightLua(code)
	local out = {}
	local i, n = 1, #code

	while i <= n do
		local c = code:sub(i, i)
		local two = code:sub(i, i + 1)

		if two == "--" then
			local eqs = code:sub(i + 2):match("^%[(=*)%[")
			if eqs then
				local close = "]" .. eqs .. "]"
				local endpos = code:find(close, i + 2, true)
				local chunk = endpos and code:sub(i, endpos + #close - 1) or code:sub(i)
				out[#out + 1] = span(HL_COMMENT, chunk)
				i = i + #chunk
			else
				local nl = code:find("\n", i, true)
				local chunk = nl and code:sub(i, nl - 1) or code:sub(i)
				out[#out + 1] = span(HL_COMMENT, chunk)
				i = i + #chunk
			end
		elseif c == '"' or c == "'" then
			local j = i + 1
			while j <= n do
				local cj = code:sub(j, j)
				if cj == "\\" then
					j = j + 2
				elseif cj == c or cj == "\n" then
					j = j + 1
					break
				else
					j = j + 1
				end
			end
			local chunk = code:sub(i, j - 1)
			out[#out + 1] = span(HL_STRING, chunk)
			i = i + #chunk
		elseif c == "[" and code:sub(i):match("^%[=*%[") then
			local eqs = code:sub(i):match("^%[(=*)%[")
			local close = "]" .. eqs .. "]"
			local endpos = code:find(close, i + #eqs + 2, true)
			local chunk = endpos and code:sub(i, endpos + #close - 1) or code:sub(i)
			out[#out + 1] = span(HL_STRING, chunk)
			i = i + #chunk
		elseif c:match("%d") or (c == "." and code:sub(i + 1, i + 1):match("%d")) then
			local num = code:sub(i):match("^0[xX]%x+")
				or code:sub(i):match("^%d*%.?%d+[eE][%+%-]?%d+")
				or code:sub(i):match("^%d*%.?%d+")
				or c
			out[#out + 1] = span(HL_NUMBER, num)
			i = i + #num
		elseif c:match("[%a_]") then
			local word = code:sub(i):match("^[%w_]+")
			if LUA_KEYWORDS[word] then
				out[#out + 1] = span(HL_KEYWORD, word)
			else
				out[#out + 1] = escapeRich(word)
			end
			i = i + #word
		else
			out[#out + 1] = escapeRich(c)
			i = i + 1
		end
	end

	return table.concat(out)
end

CodeEditor.highlight = highlightLua
CodeEditor.escape = escapeRich

---@param host table|Instance a groupbox/tab (needs .Container and :Resize()) OR a raw parent frame
---@param height number
---@param placeholder string?
---@return table
function CodeEditor.create(host, height, placeholder, zbase)
	local GUTTER_W = 34
	local PAD = 6
	local PLACEHOLDER = placeholder or "-- write your feature here"
	-- The ScreenGui uses Global ZIndexBehavior, so when the editor lives in a high-ZIndex floating window
	-- its elements must be lifted above the window's background (pass zbase ~205), else it renders hidden.
	local Z = zbase or 5

	-- Accept either a aero groupbox/tab (parent into .Container, call :Resize afterwards) or a plain frame.
	local isContainer = typeof(host) ~= "Instance"
	local parentInst = isContainer and host.Container or host

	local holder = Library:Create("Frame", {
		BackgroundColor3 = Library.MainColor,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -4, 0, height),
		LayoutOrder = 9999,
		ZIndex = Z,
		Parent = parentInst,
	})

	Library:Create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = holder })
	Library:AddToRegistry(holder, { BackgroundColor3 = "MainColor" })

	local stroke = Library:Create("UIStroke", {
		Color = Library.OutlineColor,
		Thickness = 1,
		Transparency = 0.5,
		Parent = holder,
	})
	Library:AddToRegistry(stroke, { Color = "OutlineColor" })

	local gutterHolder = Library:Create("Frame", {
		BackgroundColor3 = Library.BackgroundColor,
		BackgroundTransparency = 0.4,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Position = UDim2.new(0, 0, 0, PAD),
		Size = UDim2.new(0, GUTTER_W, 1, -PAD * 2),
		ZIndex = Z + 1,
		Parent = holder,
	})

	local gutter = Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0, 0),
		Size = UDim2.new(1, -4, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Font = Enum.Font.Code,
		TextSize = 13,
		TextColor3 = Library.OutlineColor,
		TextXAlignment = Enum.TextXAlignment.Right,
		TextYAlignment = Enum.TextYAlignment.Top,
		Text = "1",
		ZIndex = Z + 1,
		Parent = gutterHolder,
	})

	local scroll = Library:Create("ScrollingFrame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.new(0, GUTTER_W + 2, 0, PAD),
		Size = UDim2.new(1, -(GUTTER_W + 2 + PAD), 1, -PAD * 2),
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.XY,
		ScrollingDirection = Enum.ScrollingDirection.XY,
		ScrollBarThickness = 4,
		ZIndex = Z + 1,
		Parent = holder,
	})

	local selectionFrames = {}

	local highlight = Library:Create("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 2, 0, 0),
		Size = UDim2.new(0, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		RichText = true,
		Font = Enum.Font.Code,
		TextSize = 13,
		TextColor3 = Color3.fromRGB(150, 150, 162),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		Text = escapeRich(PLACEHOLDER),
		ZIndex = Z + 1,
		Parent = scroll,
	})

	local box = Library:Create("TextBox", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 2, 0, 0),
		Size = UDim2.new(0, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		MultiLine = true,
		ClearTextOnFocus = false,
		TextEditable = true,
		TextWrapped = false,
		Font = Enum.Font.Code,
		TextSize = 13,
		TextColor3 = Library.FontColor,
		TextTransparency = 1,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		Text = "",
		PlaceholderText = "",
		ZIndex = Z + 2,
		Parent = scroll,
	})

	local TextService = game:GetService("TextService")
	local HUGE = Vector2.new(1e6, 1e6)
	local LINE_H = 15
	pcall(function()
		LINE_H = TextService:GetTextSize("Ag", 13, Enum.Font.Code, HUGE).Y
	end)

	local caret = Library:Create("Frame", {
		BackgroundColor3 = Library.FontColor,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 1, 0, LINE_H),
		Position = UDim2.new(0, 2, 0, 0),
		Visible = false,
		ZIndex = Z + 3,
		Parent = scroll,
	})
	Library:AddToRegistry(caret, { BackgroundColor3 = "FontColor" })

	local function updateCaret()
		if not box:IsFocused() then
			caret.Visible = false
			return
		end
		local pos = box.CursorPosition
		if pos < 1 then
			caret.Visible = false
			return
		end
		local before = box.Text:sub(1, pos - 1)
		local line = 0
		for _ in before:gmatch("\n") do
			line = line + 1
		end
		local seg = before:match("[^\n]*$") or ""
		local width = 0
		pcall(function()
			width = TextService:GetTextSize(seg, 13, Enum.Font.Code, HUGE).X
		end)
		caret.Position = UDim2.new(0, 2 + width, 0, line * LINE_H)
		caret.Visible = true
		caret.BackgroundTransparency = 0
	end

	task.spawn(function()
		while caret.Parent do
			task.wait(0.5)
			if box:IsFocused() and caret.Visible then
				caret.BackgroundTransparency = caret.BackgroundTransparency == 0 and 1 or 0
			end
		end
	end)

	local function renderSelection()
		for _, f in ipairs(selectionFrames) do
			f:Destroy()
		end
		selectionFrames = {}

		local sStart, cPos = box.SelectionStart, box.CursorPosition
		if sStart == -1 or cPos == -1 or sStart == cPos then
			return
		end
		local a = math.min(sStart, cPos)
		local b = math.max(sStart, cPos)

		local text = box.Text
		local pos = 1
		for line in (text .. "\n"):gmatch("(.-)\n") do
			local len = #line
			local lineEndPos = pos + len
			local selA = math.max(a, pos)
			local selB = math.min(b, lineEndPos + 1)
			if selB > selA then
				local col1 = math.min(selA - pos, len)
				local col2 = math.min(selB - pos, len)
				local x1, x2 = 0, 0
				pcall(function()
					x1 = TextService:GetTextSize(line:sub(1, col1), 13, Enum.Font.Code, HUGE).X
					x2 = TextService:GetTextSize(line:sub(1, col2), 13, Enum.Font.Code, HUGE).X
				end)
				local lineIdx = 0
				for _ in text:sub(1, pos - 1):gmatch("\n") do
					lineIdx = lineIdx + 1
				end
				local w = x2 - x1
				if b > lineEndPos then
					w = w + 4
				end
				local sel = Library:Create("Frame", {
					BackgroundColor3 = Library.AccentColor,
					BackgroundTransparency = 0.55,
					BorderSizePixel = 0,
					Position = UDim2.new(0, 2 + x1, 0, lineIdx * LINE_H),
					Size = UDim2.new(0, math.max(w, 2), 0, LINE_H),
					ZIndex = Z,
					Parent = scroll,
				})
				Library:AddToRegistry(sel, { BackgroundColor3 = "AccentColor" })
				selectionFrames[#selectionFrames + 1] = sel
			end
			pos = lineEndPos + 1
		end
	end

	box:GetPropertyChangedSignal("CursorPosition"):Connect(function()
		updateCaret()
		renderSelection()
	end)
	box:GetPropertyChangedSignal("SelectionStart"):Connect(renderSelection)
	box.Focused:Connect(updateCaret)
	box.FocusLost:Connect(function()
		caret.Visible = false
		renderSelection()
	end)

	local function refresh()
		local text = box.Text

		if text == "" then
			highlight.TextColor3 = Color3.fromRGB(150, 150, 162)
			highlight.Text = escapeRich(PLACEHOLDER)
		else
			highlight.TextColor3 = Library.FontColor
			local ok, colored = pcall(highlightLua, text)
			highlight.Text = ok and colored or escapeRich(text)
		end

		local lines = 1
		for _ in text:gmatch("\n") do
			lines = lines + 1
		end
		local nums = {}
		for k = 1, lines do
			nums[k] = tostring(k)
		end
		gutter.Text = table.concat(nums, "\n")
	end

	box:GetPropertyChangedSignal("Text"):Connect(function()
		refresh()
		updateCaret()
		renderSelection()
	end)
	scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
		gutter.Position = UDim2.new(0, 0, 0, -scroll.CanvasPosition.Y)
	end)

	refresh()

	if isContainer and host.Resize then
		pcall(function()
			host:Resize()
		end)
	end

	return {
		get = function()
			return box.Text
		end,
		set = function(text)
			box.Text = text or ""
			refresh()
		end,
		setEditable = function(editable)
			box.TextEditable = editable and true or false
			if not editable then
				caret.Visible = false
			end
		end,
	}
end

return CodeEditor

end)
__bundle_register("GUI/SaveManager", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local httpService = game:GetService("HttpService")

	---@param udim2 UDim2
	---@return table
	local function uDIm2Export(udim2)
		return {
			xScale = udim2.X.Scale,
			xOffset = udim2.X.Offset,
			yScale = udim2.Y.Scale,
			yOffset = udim2.Y.Offset,
		}
	end

	---@param serialized table
	---@return UDim2
	local function uDim2Import(serialized)
		return UDim2.new(serialized.xScale, serialized.xOffset, serialized.yScale, serialized.yOffset)
	end

	local SaveManager = {}
	do
		SaveManager.Folder = "Aero-Rewrite-Configs"
		SaveManager.Ignore = {}
		SaveManager.Parser = {
			Toggle = {
				Save = function(idx, object)
					return { type = "Toggle", idx = idx, value = object.Value }
				end,
				Load = function(idx, data)
					if Toggles[idx] then
						Toggles[idx]:SetValue(data.value)
					end
				end,
			},
			Slider = {
				Save = function(idx, object)
					return { type = "Slider", idx = idx, value = tostring(object.Value) }
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx]:SetValue(data.value)
					end
				end,
			},
			Dropdown = {
				Save = function(idx, object)
					return {
						type = "Dropdown",
						idx = idx,
						value = object.Value,
						values = object.SaveValues and object.Values or nil,
						mutli = object.Multi,
					}
				end,
				Load = function(idx, data)
					if Options[idx] then
						-- Restore the option list BEFORE the selection. SetValue filters the incoming
						-- values against Dropdown.Values, so a dynamically-loaded list (mantra dropdowns
						-- start empty and are populated at runtime) must be repopulated first or the
						-- saved selection gets dropped.
						if data.values then
							Options[idx]:SetValues(data.values)
						end

						Options[idx]:SetValue(data.value)
						Options[idx]:Display()
					end
				end,
			},
			ColorPicker = {
				Save = function(idx, object)
					return {
						type = "ColorPicker",
						idx = idx,
						hue = object.Hue,
						sat = object.Sat,
						vib = object.Vib,
						transparency = object.Transparency,
						rainbow = object.Rainbow,
					}
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx].Rainbow = data.rainbow
						Options[idx]:SetValue({ data.hue, data.sat, data.vib }, data.transparency)
						Options[idx]:Display()
					end
				end,
			},
			KeyPicker = {
				Save = function(idx, object)
					return { type = "KeyPicker", idx = idx, mode = object.Mode, key = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx]:SetValue({ data.key, data.mode })
					end
				end,
			},

			Input = {
				Save = function(idx, object)
					return { type = "Input", idx = idx, text = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] and type(data.text) == "string" then
						Options[idx]:SetValue(data.text)
					end
				end,
			},
		}

		local function copy(value)
			if type(value) ~= "table" then return value end
			local result = {}
			for key, child in pairs(value) do result[key] = copy(child) end
			return result
		end
		local function same(a, b)
			if type(a) ~= type(b) then return false end
			if type(a) ~= "table" then return a == b end
			for key, value in pairs(a) do if not same(value, b[key]) then return false end end
			for key in pairs(b) do if a[key] == nil then return false end end
			return true
		end
		function SaveManager:UpdateStatus()
			local dirty = next(self.DirtyOptions or {}) ~= nil or next(self.DirtyFolds or {}) ~= nil
			local text = self.Loading and "Loading config..." or dirty and "Unsaved changes" or self.Baseline and "Config saved" or "No config saved"
			if self.StatusLabel and self.StatusText ~= text then self.StatusLabel:SetText(text); self.StatusText = text end
			local window = self.Library and self.Library.Interface and self.Library.Interface.window
			if window and window.SetConfigDirty and (self.StatusWindow ~= window or self.StatusDirty ~= dirty) then
				window:SetConfigDirty(dirty); self.StatusWindow, self.StatusDirty = window, dirty
			end
		end
		function SaveManager:CaptureBaseline()
			local baseline = {}
			for idx, object in pairs(Toggles) do
				if not self.Ignore[idx] and self.Parser[object.Type] then baseline[idx] = copy(self.Parser[object.Type].Save(idx, object)) end
			end
			for idx, object in pairs(Options) do
				if not self.Ignore[idx] and self.Parser[object.Type] then baseline[idx] = copy(self.Parser[object.Type].Save(idx, object)) end
			end
			self.Baseline = baseline
			local state = self.Library:GetInterfaceState()
			self.BaselineFolds = copy(state and state.folds or {})
			self.DirtyOptions, self.DirtyFolds = {}, {}
			self:UpdateStatus()
		end
		function SaveManager:BeginTracking()
			self.Tracking = true
			self.DirtyOptions, self.DirtyFolds = {}, {}
			self:UpdateStatus()
		end
		function SaveManager:OptionChanged(idx)
			if not self.Tracking or self.Loading or self.Ignore[idx] then return end
			local object = Toggles[idx] or Options[idx]
			local parser = object and self.Parser[object.Type]
			if not parser then return end
			self.DirtyOptions = self.DirtyOptions or {}
			self.DirtyOptions[idx] = not self.Baseline or not same(parser.Save(idx, object), self.Baseline[idx]) or nil
			self:UpdateStatus()
		end
		function SaveManager:FoldChanged(idx, expanded)
			if not self.Tracking or self.Loading then return end
			self.DirtyFolds = self.DirtyFolds or {}
			self.DirtyFolds[idx] = not self.Baseline or (self.BaselineFolds[idx] ~= expanded) or nil
			self:UpdateStatus()
		end

		function SaveManager:SetIgnoreIndexes(list)
			for _, key in next, list do
				self.Ignore[key] = true
			end
		end

		function SaveManager:SetFolder(folder)
			self.Folder = folder
			self:BuildFolderTree()
		end

		-- Executor file APIs do not offer atomic rename. Verify each backup before
		-- replacing the profile, and retain it if a write/rollback fails.
		local function configPath(self, name)
			if type(name) ~= "string" or not name:find("%S") or name == "." or name == ".." or name:find("[/\\%c]") then
				return nil, "invalid config name"
			end
			return self.Folder .. "/" .. name .. ".json"
		end

		local function read(path)
			local ok, value = pcall(readfile, path)
			if ok and type(value) == "string" then return value end
			return nil
		end

		local function writeVerified(path, value)
			local ok = pcall(writefile, path, value)
			return ok and read(path) == value
		end

		local function replaceProfile(path, value, backupSuffix)
			local previous
			if isfile(path) then
				previous = read(path)
				if not previous then return false, "could not read the existing config; nothing was overwritten" end
				if not writeVerified(path .. backupSuffix, previous) then
					return false, "could not verify the backup; nothing was overwritten"
				end
			end
			if writeVerified(path, value) then return true end
			if previous then
				if not writeVerified(path, previous) then
					return false, "write and rollback failed; recover the original from " .. path .. backupSuffix
				end
			end
			return false, "could not write the config"
		end

		function SaveManager:RestoreBackup(name)
			local path, err = configPath(self, name)
			if not path then return false, err end
			if not isfile(path .. ".bak") then return false, "no backup exists for this config" end
			local backup = read(path .. ".bak")
			if not backup then return false, "could not read the backup" end
			local ok, data = pcall(httpService.JSONDecode, httpService, backup)
			if not ok or type(data) ~= "table" or type(data.objects) ~= "table" then
				return false, "invalid backup data; nothing was overwritten"
			end
			-- Keep both the original backup and the profile replaced by this restore.
			local restored, reason = replaceProfile(path, backup, ".restore.bak")
			if restored and name == self.CurrentConfig then
				self.DirtyOptions = self.DirtyOptions or {}; self.DirtyOptions.__restore = true; self:UpdateStatus()
			end
			return restored, reason
		end

		function SaveManager:Save(name)
