		end

		function SaveManager:IgnoreThemeSettings()
			self:SetIgnoreIndexes({
				"BackgroundColor",
				"InnerBoxColor",
				"MenuFont", "MenuFontSize", "ShadowStrength", "ShadowEnabled", "ShadowSize", "GlowStrength", "GlowSize", "GlowUseAccent", "GlowColor", "AnimatedGradients", "GradientEffect", "GradientSpeed", "EdgeGlow",
				"MainColor",
				"AccentColor",
				"OutlineColor",
				"FontColor",
				"ThemeManager_ThemeList",
				"ThemeManager_CustomThemeList",
				"ThemeManager_CustomThemeName",
			})
		end

		function SaveManager:BuildFolderTree()
			local paths = {
				self.Folder,
			}

			for i = 1, #paths do
				local str = paths[i]
				if not isfolder(str) then
					makefolder(str)
				end
			end
		end

		function SaveManager:RefreshConfigList()
			local list = listfiles(self.Folder)

			local out = {}
			for i = 1, #list do
				local file = list[i]
				if file:sub(-5) == ".json" then

					local pos = file:find(".json", 1, true)
					local start = pos

					local char = file:sub(pos, pos)
					while char ~= "/" and char ~= "\\" and char ~= "" do
						pos = pos - 1
						char = file:sub(pos, pos)
					end

					if char == "/" or char == "\\" then
						table.insert(out, file:sub(pos + 1, start - 1))
					end
				end
			end

			return out
		end

		function SaveManager:SetLibrary(library)
			self.Library = library
			library.ConfigTracker = self
		end

		function SaveManager:LoadAutoloadConfig(preserveSelectedTab)
			if isfile(self.Folder .. "/autoload.txt") then
				local name = readfile(self.Folder .. "/autoload.txt")

				local success, err = self:Load(name, preserveSelectedTab)
				if not success then
					return self.Library:Notify("Failed to load autoload config: " .. err)
				end
			end
		end

		function SaveManager:BuildConfigSection(tab, groupbox)
			assert(self.Library, "Must set SaveManager.Library")

			local section = groupbox or tab:AddFullGroupbox("Config Manager")

			self.StatusLabel = section:AddLabel("No config saved", true)
			self.StatusText = nil
			self:UpdateStatus()
			section:AddInput("SaveManager_ConfigName", { Text = "Config name" })
			section:AddDropdown(
				"SaveManager_ConfigList",
				{ Text = "Config list", Values = self:RefreshConfigList(), AllowNull = true }
			)

			section:AddDivider()

			section
				:AddButton("Create config", function()
					local name = Options.SaveManager_ConfigName.Value

					if name:gsub(" ", "") == "" then
						return self.Library:Notify("Invalid config name (empty)", 2)
					end

					local success, err = self:Save(name)
					if not success then
						return self.Library:Notify("Failed to save config: " .. err)
					end

					self.Library:Notify(string.format("Created config %q", name))

					Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
					Options.SaveManager_ConfigList:SetValue(nil)
				end)
				:AddButton("Load config", function()
					local name = Options.SaveManager_ConfigList.Value

					local success, err = self:Load(name)
					if not success then
						return self.Library:Notify("Failed to load config: " .. err)
					end

					self.Library:Notify(string.format("Loaded config %q", name))
				end)

			section:AddButton("Overwrite config", function()
				local name = Options.SaveManager_ConfigList.Value

				local success, err = self:Save(name)
				if not success then
					return self.Library:Notify("Failed to overwrite config: " .. err)
				end

				self.Library:Notify(string.format("Overwrote config %q", name))
			end)

			section:AddButton({ Text = "Restore backup", DoubleClick = true, Func = function()
				local name = Options.SaveManager_ConfigList.Value
				local success, err = self:RestoreBackup(name)
				if not success then return self.Library:Notify("Failed to restore backup: " .. err) end
				self.Library:Notify(string.format("Restored backup for %q. Load config to apply it.", name))
			end })
			section:AddLabel("Overwrites keep one backup. Restore it, then Load config to apply.", true)

			section:AddButton({ Text = "Delete config", DoubleClick = true, Func = function()
				local name = Options.SaveManager_ConfigList.Value
				if type(name) ~= "string" or not table.find(self:RefreshConfigList(), name) then
					return self.Library:Notify("Select an existing config", 2)
				end
				local path = self.Folder .. "/" .. name .. ".json"
				local ok = pcall(delfile, path)
				if not ok then return self.Library:Notify("Failed to delete config", 2) end
				if self.CurrentConfig == name then
					self.CurrentConfig, self.Baseline = nil, nil
					self.DirtyOptions = { __deleted = true }; self:UpdateStatus()
				end
				local autoload = self.Folder .. "/autoload.txt"
				if isfile(autoload) and readfile(autoload) == name then
					delfile(autoload)
					self.AutoloadLabel:SetText("Current autoload config: none")
				end
				Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
				Options.SaveManager_ConfigList:SetValue(nil)
				self.Library:Notify("Deleted config " .. name, 2)
			end })

			section:AddButton("Refresh list", function()
				Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
				Options.SaveManager_ConfigList:SetValue(nil)
			end)

			section:AddButton("Set as autoload", function()
				local name = Options.SaveManager_ConfigList.Value

				if type(name) ~= "string" or name:gsub(" ", "") == "" then
					return self.Library:Notify("No config selected to set as autoload", 2)
				end

				writefile(self.Folder .. "/autoload.txt", name)
				SaveManager.AutoloadLabel:SetText("Current autoload config: " .. name)
				self.Library:Notify(string.format("Set %q to auto load", name))
			end)

			section:AddButton("Clear autoload", function()
				local path = self.Folder .. "/autoload.txt"

				if not isfile(path) then
					return self.Library:Notify("No autoload config is set", 2)
				end

				delfile(path)
				SaveManager.AutoloadLabel:SetText("Current autoload config: none")
				self.Library:Notify("Cleared autoload config")
			end)

			SaveManager.AutoloadLabel = section:AddLabel("Current autoload config: none", true)

			if isfile(self.Folder .. "/autoload.txt") then
				local name = readfile(self.Folder .. "/autoload.txt")
				SaveManager.AutoloadLabel:SetText("Current autoload config: " .. name)
			end

			SaveManager:SetIgnoreIndexes({ "SaveManager_ConfigList", "SaveManager_ConfigName" })
		end

		SaveManager:BuildFolderTree()
	end

	return SaveManager
end)()

end)
