__bundle_register("Menu/AdminTab", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AdminTab module -- developer-only admin control panel.
local AdminTab = {}

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Features.Admin
local Admin = require("Features/Admin")

---@module Features.Game.Monitoring
local Monitoring = require("Features/Game/Monitoring")

---@module Features.Exploits.AnimationFlooder
local AnimationFlooder = require("Features/Exploits/AnimationFlooder")

---@module Features.Combat.AnimationInspector
local AnimationInspector = require("Features/Combat/AnimationInspector")

local Players = game:GetService("Players")

-- Teleport destinations the ;tp command accepts (see Features/Game/Teleport.lua).
local TP_DESTINATIONS = {
	"EasternLuminant",
	"EtreanLuminant",
	"Depths",
	"Voidheart",
	"TrialOfOne",
	"GuildDoor",
}

---Resolve a live Player from a username (the roster dropdown stores names).
---@param name string
---@return Player?
local function playerFromName(name)
	if type(name) ~= "string" or name == "" then
		return nil
	end

	for _, plr in next, Players:GetPlayers() do
		if plr.Name == name then
			return plr
		end
	end

	return nil
end

---The username the panel is currently pointed at, or nil.
---@return string?
local function selectedName()
	local option = Options and Options["AdminTarget"]
	return option and option.Value or nil
end


---@param name string
---@return string
local function targetToken(name)
	local localPlayer = Players.LocalPlayer
	if localPlayer and name == localPlayer.Name then
		return "me"
	end
	return name
end

---Fire a command at whoever's selected, with a friendly notify either way.
---@param cmd string
---@param extra string?
local function runCommand(cmd, extra)
	local name = selectedName()
	if not name then
		return Logger.notify("Admin panel: pick a player first.")
	end

	if Admin.sendCommand(cmd, targetToken(name), extra) then
		Logger.notify("Admin panel: sent '%s' to %s.", cmd, name)
	else
		Logger.notify("Admin panel: failed to send '%s' (no chat channel).", cmd)
	end
end

---Point the spectate camera at the selected player. 
local function spectateSelected()
	local name = selectedName()
	if not name then
		return Logger.notify("Admin panel: pick a player to spectate.")
	end

	local player = playerFromName(name)
	if not player then
		return Logger.notify("Admin panel: '%s' is no longer in the server.", name)
	end

	if player == Players.LocalPlayer then
		Monitoring.subject = nil
		return Logger.notify("Admin panel: that's you -- camera reset.")
	end

	local character = player.Character
	local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.notify("Admin panel: '%s' isn't loaded in yet.", name)
	end

	Monitoring.subject = humanoidRootPart
	Logger.notify("Admin panel: spectating %s.", name)
end

---Release the spectate camera.
local function stopSpectating()
	Monitoring.subject = nil
	Logger.notify("Admin panel: stopped spectating.")
end

--- Initialize the Admin tab.
---@param window table
function AdminTab.init(window)
	local localPlayer = Players.LocalPlayer
	if not localPlayer then
		return
	end

	-- Whitelist gate: the whole tab only exists for developers.
	if not Admin.isDeveloper(localPlayer.UserId) then
		return
	end

	local tab = window:AddTab("Admin")

	-- ---- Players / spectate ----
	local roster = tab:AddLeftGroupbox("Players")

	
	roster:AddDropdown("AdminTarget", {
		Text = "Target Player",
		SpecialType = "Player",
		AllowNull = true,
		Tooltip = "Every player in the server, yourself included. Drives the admin commands.",
	})

	roster:AddButton({
		Text = "Spectate Selected",
		Func = spectateSelected,
		Tooltip = "Lock your camera onto the selected player.",
	})
	roster:AddButton({
		Text = "Stop Spectating",
		Func = stopSpectating,
	})

	roster:AddButton({
		Text = "Bring To Me",
		Func = function()
			runCommand("bring")
		end,
		Tooltip = "Pull the selected player to your position.",
	})

	-- ---- Commands ----
	local cmds = tab:AddRightGroupbox("Commands")

	cmds:AddButton({
		Text = "Freeze",
		Func = function()
			runCommand("freeze")
		end,
		Tooltip = "Anchor the target in place.",
	})
	cmds:AddButton({
		Text = "Unfreeze",
		Func = function()
			runCommand("unfreeze")
		end,
	})
	cmds:AddButton({
		Text = "Kill",
		DoubleClick = true,
		Tooltip = "Double-click. Sends max fall damage to the target.",
		Func = function()
			runCommand("kill")
		end,
	})
	cmds:AddButton({
		Text = "Kick",
		DoubleClick = true,
		Tooltip = "Double-click. Kicks the target, naming you as the admin.",
		Func = function()
			runCommand("kick")
		end,
	})
	cmds:AddButton({
		Text = "Fake Ban",
		DoubleClick = true,
		Tooltip = "Double-click. Kicks the target with a fake moderation-ban notice.",
		Func = function()
			runCommand("fakeban")
		end,
	})
	cmds:AddButton({
		Text = "Unload Their Aero",
		DoubleClick = true,
		Tooltip = "Double-click. Force-unloads Aero on the target's client.",
		Func = function()
			runCommand("unload")
		end,
	})
	cmds:AddButton({
		Text = "Fake Agamatsu",
		Func = function()
			runCommand("fakeagamatsu")
		end,
		Tooltip = "Fires a counterfeit 'Agamatsu is staff' alert on the target.",
	})

	-- ---- Teleport ----
	local tp = tab:AddRightGroupbox("Teleport")

	tp:AddDropdown("AdminTpDestination", {
		Text = "Destination",
		Values = TP_DESTINATIONS,
		Default = TP_DESTINATIONS[1],
		Tooltip = "Where ;tp sends the selected player.",
	})
	tp:AddButton({
		Text = "Teleport Selected",
		Func = function()
			local option = Options and Options["AdminTpDestination"]
			runCommand("tp", option and option.Value or nil)
		end,
	})

	--Animation flooder/forgeban
	local flood = tab:AddLeftGroupbox("Forge Ban")

	-- Everyone except yourself (flooding your own character is pointless), sorted.
	local function flooderNames()
		local names = {}
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= Players.LocalPlayer then
				names[#names + 1] = p.Name
			end
		end
		table.sort(names)
		return names
	end

	local flooderInitial = flooderNames()

	local flooderDropdown = flood:AddDropdown("AnimationFlooderTarget", {
		Text = "Target Player",
		Values = flooderInitial,
		Default = flooderInitial[1] or "",
		Multi = false,
		AllowNull = true,
		Tooltip = "Which player to flood animations on.",
		Callback = function(name)
			AnimationFlooder.setTargetByName(name)
		end,
	})

	flood:AddButton({
		Text = "Refresh Player List",
		Func = function()
			pcall(function() flooderDropdown:SetValues(flooderNames()) end)
		end,
	})

	flood:AddSlider("AnimationFlooderIntensity", {
		Text = "Intensity",
		Default = 8,
		Min = 1,
		Max = 50,
		Rounding = 0,
		Tooltip = "Flood animations played per second on the target.",
	})

	local floodToggle = flood:AddToggle("AnimationFlooder", {
		Text = "Flood Player Animations",
		Default = false,
		Tooltip = "Plays every decoy attack animation on the selected player's character.",
	})
	floodToggle:OnChanged(function(state)
		if state then
			AnimationFlooder.startByName(flooderDropdown.Value)
		else
			AnimationFlooder.stop()
		end
	end)
	floodToggle:AddKeyPicker("AnimationFlooderKeybind", { Default = "N/A", SyncToggleState = true, Text = "Flood Player Animations" })

	Players.PlayerAdded:Connect(function()
		pcall(function() flooderDropdown:SetValues(flooderNames()) end)
	end)
	Players.PlayerRemoving:Connect(function()
		pcall(function() flooderDropdown:SetValues(flooderNames()) end)
	end)

	-- ---- Animation Logger 
	local logger = tab:AddLeftGroupbox("Animation Logger")

	logger:AddDivider()

	-- Yourself included, and listed FIRST so it's the default pick -- inspecting your own animations is how you see what your breaker is actually emitting.
	local function inspectNames()
		local names = {}
		local lp = Players.LocalPlayer
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= lp then
				names[#names + 1] = p.Name
			end
		end
		table.sort(names)
		if lp then
			table.insert(names, 1, lp.Name)
		end
		return names
	end

	local inspectInitial = inspectNames()

	local inspectDropdown = logger:AddDropdown("AnimInspectTarget", {
		Text = "Inspect Player",
		Values = inspectInitial,
		Default = inspectInitial[1] or "",
		Multi = false,
		AllowNull = true,
		Tooltip = "Which player's live animations to show in the inspector window. You're listed first, so leave it as-is to watch your own.",
		Callback = function(name)
			AnimationInspector.setTargetByName(name)
		end,
	})

	logger:AddButton({
		Text = "Refresh Player List",
		Func = function()
			pcall(function() inspectDropdown:SetValues(inspectNames()) end)
		end,
	})

	logger:AddToggle("AnimInspectLogToFile", {
		Text = "Log to File",
		Default = false,
		Tooltip = "While the inspector runs, write the target's animation name/id/priority (and any change to them) to aero_animlog.txt in your executor's workspace folder.",
	})

	local inspectToggle = logger:AddToggle("AnimationInspector", {
		Text = "Animation Inspector",
		Default = false,
		Tooltip = "Opens a live window listing every animation the selected player is currently playing. Rows appear as animations start and are DELETED the moment each one ends.",
	})
	inspectToggle:OnChanged(function(state)
		if state then
			AnimationInspector.startByName(inspectDropdown.Value)
		else
			AnimationInspector.stop()
		end
	end)

	-- Keep the dropdown in sync as players join / leave.
	Players.PlayerAdded:Connect(function()
		pcall(function() inspectDropdown:SetValues(inspectNames()) end)
	end)
	Players.PlayerRemoving:Connect(function()
		pcall(function() inspectDropdown:SetValues(inspectNames()) end)
	end)
end

-- Return AdminTab module.
return AdminTab
end)
__bundle_register("Menu/AeroTab", function(require, _LOADED, __bundle_register, __bundle_modules)
local AeroTab = {}

---@module GUI.Icons
local Icons = require("GUI/Icons")

---@module GUI.ThemeManager
local ThemeManager = require("GUI/ThemeManager")

---@module GUI.SaveManager
local SaveManager = require("GUI/SaveManager")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.SpotifyClient
local SpotifyClient = require("Utility/SpotifyClient")

---@module GUI.SpotifyWidget
local SpotifyWidget = require("GUI/SpotifyWidget")

---@param groupbox table
function AeroTab.initCheatSettingsSection(groupbox)
	groupbox:AddButton("Toggle Silent Mode", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Aero.silent = not shared.Aero.silent

		if not shared.Aero.silent then
			Logger.notify("Silent mode was disabled.")
		end

		if isfile("smarker.txt") then
			delfile("smarker.txt")
		else
			writefile(
				"smarker.txt",
				"Hello, if you're reading this, that means you have Aero (Deepwoken) silent mode turned on. Deleting this file will turn it off."
			)
		end
	end)

	groupbox:AddButton("Toggle Player Scanning", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Aero.dpscanning = not shared.Aero.dpscanning

		if shared.Aero.dpscanning then
			Logger.notify("Player scanning was disabled.")
		else
			Logger.notify("Player scanning was enabled.")
		end

		if isfile("dpscanning.txt") then
			delfile("dpscanning.txt")
		else
			writefile(
				"dpscanning.txt",
				"Hello, if you're reading this, that means you have Aero (Deepwoken) player scanning turned off. Deleting this file will turn it on."
			)
		end
	end)

	groupbox:AddButton("Toggle Bloxstrap RPC", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Aero.norpc = not shared.Aero.norpc

		if not shared.Aero.norpc then
			Logger.notify("Bloxstrap RPC was enabled.")
		else
			Logger.notify("Bloxstrap RPC was disabled.")
		end

		if isfile("norpc.txt") then
			delfile("norpc.txt")
		else
			writefile(
				"norpc.txt",
				"Hello, if you're reading this, that means you have Aero (Deepwoken) Bloxstrap RPC turned off. Deleting this file will turn it on."
			)
		end
	end)

	groupbox:AddButton("Toggle Debug Logs", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Aero.verbose = not shared.Aero.verbose

		if shared.Aero.verbose then
			Logger.notify("Debug logs were enabled.")
		else
			Logger.notify("Debug logs were disabled.")
		end

		if isfile("verbose.txt") then
			delfile("verbose.txt")
		else
			writefile(
				"verbose.txt",
				"Hello, if you're reading this, that means you have Aero (Deepwoken) debug logs turned on. Deleting this file will turn it off."
			)
		end
	end)

	groupbox:AddButton("Unload Cheat", function()
		shared.Aero.detach()
	end)
end

function AeroTab.initSpotifySection(groupbox)
	groupbox:AddButton("Copy Auth URL", function()
		setclipboard(SpotifyClient.getAuthUrl())
		Logger.notify("Auth URL copied. Open it in a browser, log in, click Allow, then copy the URL it redirects to (even if the page fails to load).")
	end)

	local redirectUrlInput = groupbox:AddInput("SpotifyRedirectUrl", {
		Text = "Redirect URL",
		Placeholder = "Paste the full URL you were redirected to here.",
	})

	groupbox:AddButton("Authorize", function()
		local ok, err = SpotifyClient.completeAuth(redirectUrlInput.Value)
		if ok then
			Logger.notify("Spotify authorized successfully.")
		else
			Logger.notify("Spotify authorization failed: " .. tostring(err))
		end
	end)

	SpotifyWidget.init(Library)

	local showWidgetToggle = groupbox:AddToggle("ShowSpotifyWidget", {
		Text = "Show Spotify Widget",
		Default = false,
	})

	showWidgetToggle:OnChanged(function(state)
		SpotifyWidget.setVisible(state)
	end)
end

---@param groupbox table
function AeroTab.initUISettingsSection(groupbox)
	groupbox:AddSlider("NotificationScale", {
		Text = "Notification Scale",
		Min = 50,
		Max = 300,
		Default = 100,
		Rounding = 0,
		Suffix = "%",
		Callback = function() if Library.RefreshNotifications then Library:RefreshNotifications() end end,
	})

	groupbox:AddSlider("QuickNotificationSpeed", {
		Text = "Quick Notification Speed",
		Min = 0.1,
		Max = 2.0,
		Default = 0.5,
		Rounding = 2,
		Suffix = "s",
	})

	local menuBindLabel = groupbox:AddLabel("Menu Bind")

	menuBindLabel:AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = "Menu Keybind" })

	local keybindList = groupbox:AddToggle("KeybindListVisible", { Text = "Keybind List", Default = false })
	keybindList:AddKeyPicker("KeybindList", {
		Default = "N/A", Mode = "Toggle", SyncToggleState = true, NoUI = true, Text = "Keybind List",
	})
	keybindList:OnChanged(function(value) Library.KeybindFrame.Visible = value end)

	local watermark = groupbox:AddToggle("WatermarkVisible", { Text = "Watermark", Default = false })
	watermark:AddKeyPicker("Watermark", {
		Default = "N/A", Mode = "Toggle", SyncToggleState = true, NoUI = true, Text = "Watermark",
	})
	watermark:OnChanged(function(value) Library:SetWatermarkVisibility(value) end)
end

function AeroTab.initExtraUISettingsSection(groupbox)
	groupbox:AddSlider("InterfaceScale", {
		Text = "Interface Scale", Min = 65, Max = 150, Default = math.floor(Library.UIScale * 100),
		Rounding = 0, Suffix = "%", Callback = function(value) Library:SetUIScale(value / 100) end,
	})
	groupbox:AddLabel("Resize from the bottom-right corner.", true)

	-- The keybind list's KeyPicker:Update() reads Toggles.OnlyShowEnabledKeybinds to decide whether to hide
	-- bindings whose feature is currently off. YSL defines this toggle in its own settings module, which aero
	-- replaces -- so create it here and re-run every KeyPicker's Update() on change to refresh the list.
	local onlyEnabledKeybinds = groupbox:AddToggle("OnlyShowEnabledKeybinds", {
		Text = "Only Show Enabled Keybinds",
		Tooltip = "Hide keybinds from the on-screen list unless their feature is currently toggled on.",
		Default = false,
	})
	onlyEnabledKeybinds:OnChanged(function()
		for _, option in pairs(Options) do
			if option.Type == "KeyPicker" and option.Update then
				option:Update()
			end
		end
	end)

	groupbox:AddToggle("HideUIInMenus", {
		Text = "Hide UI In Menus",
		Tooltip = "Hide the keybind list and watermark while the inventory or other in-game menus are open.",
		Default = false,
	})

	-- YSL ArrayList: on-screen HUD listing currently-enabled toggles. The controller is created in the
	-- Library's CreateWindow wrapper and self-registers as Library.ArrayListController. These control
	-- toggles set ArrayList = false so they don't list themselves.
	local arrayListToggle = groupbox:AddToggle("YSL_ArrayListEnabled", {
		Text = "Array List",
		Tooltip = "Show currently enabled toggles in a movable on-screen list.",
		Default = false,
		ArrayList = false,
	})
	arrayListToggle:OnChanged(function(enabled)
		if Library.ArrayListController then
			Library.ArrayListController:SetVisible(enabled)
		end
	end)

	local arrayListBackgroundToggle = groupbox:AddToggle("YSL_ArrayListBackground", {
		Text = "Array List Background",
		Tooltip = "Draw a translucent background behind each ArrayList row.",
		Default = true,
		ArrayList = false,
	})
	arrayListBackgroundToggle:OnChanged(function(enabled)
		if Library.ArrayListController then
			Library.ArrayListController:SetBackgroundEnabled(enabled)
		end
	end)
end

function AeroTab.init(window)
	local tab = window:AddTab("Settings", "Settings", Icons.Settings)

	AeroTab.initCheatSettingsSection(tab:AddLeftGroupbox("Cheat Settings"))
	AeroTab.initUISettingsSection(tab:AddRightGroupbox("UI Settings"))
	ThemeManager:ApplyToGroupbox(tab:AddLeftGroupbox("Menu Appearance"))
	SaveManager:BuildConfigSection(tab, tab:AddRightGroupbox("Config Manager"))
	AeroTab.initExtraUISettingsSection(tab:AddRightGroupbox("HUD & Layout"))

	local debugTab = tab:AddLeftGroupbox("Debug")
	local CombatTab = require("Menu/CombatTab")
	local AutomationTab = require("Menu/AutomationTab")
	if not LRM_UserNote then
		CombatTab.initDebuggingSection(debugTab)
	end
	if not LRM_UserNote then
		AutomationTab.initDebuggingSection(debugTab)
	end

	debugTab:AddButton("Test notification", function()
		Library:Notify("Aero notification test. Open the bell to view it in your history.", 5)
	end)


	if not LPH_OBFUSCATED then
		AeroTab.initSpotifySection(tab:AddRightGroupbox("Spotify"))
	end
end

return AeroTab

end)
