function AutomationTab.init(window)
	local tab = window:AddTab("Auto", "Utility", Icons.Auto)
	AutomationTab.initGeneralSection(tab:AddHeaderGroupbox("General", true))
	local farms = tab:AddCategory("Farms")
	local bosses = tab:AddCategory("Bosses")
	local progression = tab:AddCategory("Progression")
	local loot = tab:AddCategory("Loot")
	local statuses = {}

	local function add(category, title, init, read, enabled, pendingKey)
		local box = category:AddDynamicGroupbox(title)
		init(box)
		if read then statuses[#statuses + 1] = { box = box, read = read, enabled = enabled, pendingKey = pendingKey } end
	end
	local function toggle(name)
		return function() return Toggles[name] and Toggles[name].Value == true end
	end

	add(farms, "Fish Farm", AutomationTab.initFishFarmSection, toggle("AutoFish"), true)
	add(farms, "Attribute Farm", AutomationTab.initAttributeSection, function()
		return (Toggles.AutoCharisma and Toggles.AutoCharisma.Value) or (Toggles.AutoIntelligence and Toggles.AutoIntelligence.Value)
	end, true)
	add(farms, "Echo Farm", AutomationTab.initEchoFarmSection, EchoFarm.isRunning, false, "efdata")
	add(farms, "Auto Notes", AutomationTab.initAutoNotesSection, AutoNotes.isRunning, false, "notesdata")

	add(bosses, "Auto Ferryman", AutomationTab.initAutoFerrymanSection, function() return AutoFerryman.running end)
	add(bosses, "Auto Duke", AutomationTab.initAutoDukeSection, AutoDuke.isRunning)
	add(bosses, "Auto Titus", AutomationTab.initAutoTitusSection, AutoTitus.isRunning)
	add(bosses, "Auto Saramaed", AutomationTab.initAutoSaramedSection, AutoSaramed.isRunning)
	add(bosses, "Auto Mooneyrie", AutomationTab.initAutoMooneyrieSection, AutoMooneyrie.isRunning)

	add(progression, "Auto To1", AutomationTab.initAutoTo1Section, function() return AutoTo1.running end)
	add(progression, "Auto VoI", AutomationTab.initAutoVoISection, function() return AutoVoI.running end)
	add(progression, "Auto L2", AutomationTab.initAutoLayer2Section, AutoLayer2.isRunning)
	add(progression, "Auto Authority", AutomationTab.initAutoAuthoritySection, AutoAuthority.isRunning)
	add(progression, "Auto Builder", AutomationTab.initAutoBuilderSection, function() return AutoBuilder.picking end)
	add(progression, "Auto Prog", AutomationTab.initAutoProgSection, AutoProg.isRunning)
	add(loot, "Auto Loot", AutomationTab.initAutoLootSection, toggle("AutoLoot"), true)

	function tab:RefreshStatuses()
		for _, status in ipairs(statuses) do
			if status.box.Outer.Visible then
				local active = status.read() == true
				local text = active and (status.enabled and "Enabled" or "Running") or (status.enabled and "Disabled" or "Stopped")
				if not active and status.pendingKey and PersistentData.get(status.pendingKey) then text = "Pending" end
				status.box:SetStatus(text, active)
			end
		end
	end
	local elapsed = 0
	Library:GiveSignal(runService.Heartbeat:Connect(function(delta)
		if not Library.Interface.outer.Visible or Library.Interface.window.SelectedTab ~= tab.Name then return end
		elapsed = elapsed + delta
		if elapsed < 0.25 then return end
		elapsed = 0
		tab:RefreshStatuses()
	end))
	tab:RefreshStatuses()
end

return AutomationTab

end)
