local colorKeys = { "BackgroundColor", "InnerBoxColor", "MainColor", "AccentColor", "OutlineColor", "FontColor" }
local transparencyKeys = { BackgroundColor = true, InnerBoxColor = true, MainColor = true }
local fonts = { "Gotham", "GothamMedium", "RobotoMono", "Code", "SourceSans", "Arial" }
local function validName(name)
	return type(name) == "string" and name:find("%S") and #name <= 80
		and not name:find("[%c/\\:]") and name ~= "." and name ~= ".."
end
local function notify(self, message) self.Library:Notify(message, 3) end
-- Accept saved defaults/public calls from before the display-name change.
local function builtinName(name) return name == "Deepwoken Rewrite" and "Default" or name end
local function applyTheme(self, name)
	name = builtinName(name)
	local colors = themes[name]
	if not colors then return false end
	for _, key in ipairs(colorKeys) do self.Library[key] = colors[key] or colors.BackgroundColor end
	self:ThemeUpdate()
	return true
end

ThemeManager.Folder = "Aero-Rewrite-Themes"
function ThemeManager:SetLibrary(library) self.Library = library end
function ThemeManager:SetFolder(folder) self.Folder = folder end
function ThemeManager:BuildFolderTree()
	if not isfolder or not makefolder then return false end
	return pcall(function() if not isfolder(self.Folder) then makefolder(self.Folder) end end)
end
function ThemeManager:ThemeUpdate()
	local library = self.Library
	self.syncing = true
	for _, key in ipairs(colorKeys) do
		local transparency = library.Appearance and library.Appearance.transparency[key]
		if Options[key] and (Options[key].Value:ToHex() ~= library[key]:ToHex()
			or transparency ~= nil and Options[key].Transparency ~= transparency) then
			Options[key]:SetValueRGB(library[key], transparency)
		end
	end
	self.syncing = false
	library.AccentColorDark = library:GetDarkerColor(library.AccentColor)
	library:UpdateColorsUsingRegistry()
	if library.Appearance then library.Appearance:Update() end
end
function ThemeManager:ApplyTheme(name) return applyTheme(self, name) end
function ThemeManager:GetCustomTheme()
	local data = { version = 1, colors = {} }
	for _, key in ipairs(colorKeys) do data.colors[key] = self.Library[key]:ToHex() end
	local appearance = self.Library.Appearance
	if appearance then
		data.transparency = {}
		for key in pairs(transparencyKeys) do data.transparency[key] = appearance.transparency[key] end
		data.font, data.fontSize = appearance.fontName, math.floor(appearance.fontScale * 100 + 0.5)
		data.shadow, data.animated, data.glow = appearance.shadow, appearance.animated, appearance.glow
		data.gradientEffect, data.gradientSpeed = appearance.effect, appearance.speed
		data.shadowEnabled, data.shadowSize = appearance.shadowEnabled, appearance.shadowSize
		data.glowStrength, data.glowSize = appearance.glowStrength, appearance.glowSize
		data.glowUseAccent, data.glowColor = appearance.glowUseAccent, appearance.glowColor:ToHex()
	end
	return data
end
function ThemeManager:SaveCustomTheme(name, overwrite)
	if not validName(name) then return false, "Enter a valid theme name" end
	if not self:BuildFolderTree() or not writefile then return false, "Theme files are unavailable" end
	local path = self.Folder .. "/" .. name .. ".json"
	if isfile(path) and not overwrite then return false, "Theme exists; use Overwrite theme" end
	local ok = pcall(function()
		writefile(path, game:GetService("HttpService"):JSONEncode(self:GetCustomTheme()))
	end)
	return ok, ok and "Theme saved" or "Could not save theme"
end
function ThemeManager:LoadCustomTheme(name)
	if not validName(name) or not readfile then return false, "Select a theme" end
	local ok, data = pcall(function()
		return game:GetService("HttpService"):JSONDecode(readfile(self.Folder .. "/" .. name .. ".json"))
	end)
	if not ok or type(data) ~= "table" or data.version ~= 1 or type(data.colors) ~= "table" then
		return false, "Invalid theme file"
	end
	-- Validate the complete palette before modifying the current theme.
	local colors = {}
	for _, key in ipairs(colorKeys) do
		local hex = data.colors[key] or (key == "InnerBoxColor" and data.colors.BackgroundColor)
		if type(hex) ~= "string" or not hex:match("^%x%x%x%x%x%x$") then return false, "Invalid theme colors" end
		colors[key] = Color3.fromHex(hex)
	end
	for key, color in pairs(colors) do self.Library[key] = color end
	if self.Library.Appearance then
		for key in pairs(transparencyKeys) do
			local value = type(data.transparency) == "table" and data.transparency[key]
			if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then value = 0 end
			self.Library.Appearance:SetTransparency(key, value)
		end
	end
	self:ThemeUpdate()
	local function number(value, fallback, low, high)
		return type(value) == "number" and value == value and math.clamp(value, low, high) or fallback
	end
	if Options.MenuFont then
		Options.MenuFont:SetValue(table.find(fonts, data.font) and data.font or "Gotham")
		Options.MenuFontSize:SetValue(number(data.fontSize, 100, 75, 125))
		Options.ShadowStrength:SetValue(number(data.shadow, 100, 0, 100))
		Options.ShadowSize:SetValue(number(data.shadowSize, 28, 8, 48))
		Toggles.ShadowEnabled:SetValue(data.shadowEnabled ~= false)
		Options.GlowStrength:SetValue(number(data.glowStrength, 40, 0, 100))
		Options.GlowSize:SetValue(number(data.glowSize, 16, 4, 40))
		Toggles.GlowUseAccent:SetValue(data.glowUseAccent ~= false)
		Options.GlowColor:SetValueRGB(type(data.glowColor) == "string" and data.glowColor:match("^%x%x%x%x%x%x$") and Color3.fromHex(data.glowColor) or self.Library.AccentColor)
		Options.GradientEffect:SetValue(table.find({ "Sweep", "Rotate", "Wave" }, data.gradientEffect) and data.gradientEffect or "Sweep")
		Options.GradientSpeed:SetValue(number(data.gradientSpeed, 1, 0.2, 3))
		for _, pair in ipairs({ { "AnimatedGradients", data.animated }, { "EdgeGlow", data.glow } }) do
			Toggles[pair[1]]:SetValue(pair[2] == true)
		end
	end
	return true, "Theme loaded"
end
function ThemeManager:ReloadCustomThemes()
	local names = {}
	if listfiles then
		local ok, paths = pcall(listfiles, self.Folder)
		if ok then
			for _, path in ipairs(paths) do
				local name = path:match("([^/\\]+)%.json$")
				if validName(name) then names[#names + 1] = name end
			end
		end
	end
	table.sort(names)
	if Options.ThemeManager_CustomThemeList then Options.ThemeManager_CustomThemeList:SetValues(names) end
	return names
end
function ThemeManager:SaveDefault(name, custom)
	if not custom then name = builtinName(name) end
	if not (custom and validName(name) or not custom and themes[name]) then return false, "Select a theme" end
	if not self:BuildFolderTree() or not writefile then return false, "Theme files are unavailable" end
	local ok = pcall(writefile, self.Folder .. "/default.txt", (custom and "custom:" or "builtin:") .. name)
	return ok, ok and "Default theme saved" or "Could not save default theme"
end
function ThemeManager:LoadDefault()
	if not readfile then return end
	local ok, value = pcall(readfile, self.Folder .. "/default.txt")
	if not ok or type(value) ~= "string" then return end
	local custom = value:sub(1, 7) == "custom:"
	local name = value:gsub("^custom:", ""):gsub("^builtin:", "")
	if custom then
		local loaded = self:LoadCustomTheme(name)
		if loaded and Options.ThemeManager_CustomThemeList then Options.ThemeManager_CustomThemeList:SetValue(name) end
	elseif themes[builtinName(name)] then
		Options.ThemeManager_ThemeList:SetValue(builtinName(name))
	end
end
function ThemeManager:ApplyToGroupbox(groupbox)
	if not groupbox or not self.Library then return end
	local library = self.Library
	for _, key in ipairs(colorKeys) do
		local label = key:gsub("(%u)", " %1"):gsub("^ ", "")
		local alpha
		if transparencyKeys[key] and library.Appearance then alpha = library.Appearance.transparency[key] end
		groupbox:AddLabel(label):AddColorPicker(key, { Title = label, Default = library[key] or library.BackgroundColor,
			Transparency = alpha,
			TransparencyCallback = alpha ~= nil and function(value)
				if not self.syncing then library.Appearance:SetTransparency(key, value) end
			end or nil,
			Callback = function(value)
			if self.syncing then return end
			library[key] = value
			self:ThemeUpdate()
		end })
	end
	local function updateFont()
		if library.Appearance then library.Appearance:SetFont(Options.MenuFont.Value, Options.MenuFontSize and Options.MenuFontSize.Value or 100) end
	end
	groupbox:AddDropdown("MenuFont", { Text = "Menu Font", Values = fonts, Default = "Gotham", Callback = updateFont })
	groupbox:AddSlider("MenuFontSize", { Text = "Font Size", Default = 100, Min = 75, Max = 125, Rounding = 0, Suffix = "%", Callback = updateFont })
	local function update(field, value)
		if library.Appearance then library.Appearance[field] = value; library.Appearance:Update() end
	end
	groupbox:AddToggle("ShadowEnabled", { Text = "Window Shadow", Default = true, Callback = function(value) update("shadowEnabled", value) end })
	local shadow = groupbox:AddDependencyBox()
	shadow:AddSlider("ShadowStrength", { Text = "Shadow Strength", Default = 100, Min = 0, Max = 100, Rounding = 0, Suffix = "%", Callback = function(value) update("shadow", value) end })
	shadow:AddSlider("ShadowSize", { Text = "Shadow Softness", Default = 28, Min = 8, Max = 48, Rounding = 0, Suffix = "px", Callback = function(value) update("shadowSize", value) end })
	shadow:SetupDependencies({ { Toggles.ShadowEnabled, true } })
	groupbox:AddToggle("EdgeGlow", { Text = "Edge Glow", Default = false, Callback = function(value) update("glow", value) end })
	local glow = groupbox:AddDependencyBox()
	glow:AddSlider("GlowStrength", { Text = "Glow Intensity", Default = 40, Min = 0, Max = 100, Rounding = 0, Suffix = "%", Callback = function(value) update("glowStrength", value) end })
	glow:AddSlider("GlowSize", { Text = "Glow Softness", Default = 16, Min = 4, Max = 40, Rounding = 0, Suffix = "px", Callback = function(value) update("glowSize", value) end })
	glow:AddToggle("GlowUseAccent", { Text = "Use Accent Color", Default = true, Callback = function(value) update("glowUseAccent", value) end })
	local customGlow = glow:AddDependencyBox()
	customGlow:AddLabel("Glow Color"):AddColorPicker("GlowColor", { Title = "Glow Color", Default = library.AccentColor, Callback = function(value) update("glowColor", value) end })
	customGlow:SetupDependencies({ { Toggles.GlowUseAccent, false } })
	glow:SetupDependencies({ { Toggles.EdgeGlow, true } })
	groupbox:AddToggle("AnimatedGradients", { Text = "Animated Gradients", Default = false, Callback = function(value) update("animated", value) end })
	local motion = groupbox:AddDependencyBox()
	motion:AddDropdown("GradientEffect", { Text = "Gradient Effect", Values = { "Sweep", "Rotate", "Wave" }, Default = "Sweep", Callback = function(value)
		if library.Appearance then library.Appearance.effect = value; library.Appearance:UpdateAnimation() end
	end })
	motion:AddSlider("GradientSpeed", { Text = "Gradient Speed", Min = 0.2, Max = 3, Default = 1, Rounding = 1, Suffix = "x", Callback = function(value)
		if library.Appearance then library.Appearance.speed = value end
	end })
	motion:SetupDependencies({ { Toggles.AnimatedGradients, true } })
	groupbox:AddDivider()
	local names = {}; for name in pairs(themes) do names[#names + 1] = name end; table.sort(names)
	groupbox:AddDropdown("ThemeManager_ThemeList", { Text = "Theme list", Values = names, Default = "Default", Callback = function(value) applyTheme(self, value) end })
	groupbox:AddButton("Set as default", function() local _, message = self:SaveDefault(Options.ThemeManager_ThemeList.Value); notify(self, message) end)
	groupbox:AddDivider()
	groupbox:AddInput("ThemeManager_CustomThemeName", { Text = "Custom theme name" })
	self:BuildFolderTree()
	groupbox:AddDropdown("ThemeManager_CustomThemeList", { Text = "Custom themes", Values = self:ReloadCustomThemes(), AllowNull = true })
	groupbox:AddButton("Save theme", function()
		local name = Options.ThemeManager_CustomThemeName.Value
		local ok, message = self:SaveCustomTheme(name)
		if ok then self:ReloadCustomThemes(); Options.ThemeManager_CustomThemeList:SetValue(name) end
		notify(self, message)
	end)
	groupbox:AddButton("Load theme", function() local _, message = self:LoadCustomTheme(Options.ThemeManager_CustomThemeList.Value); notify(self, message) end)
	groupbox:AddButton({ Text = "Overwrite theme", DoubleClick = true, Func = function()
		local _, message = self:SaveCustomTheme(Options.ThemeManager_CustomThemeList.Value, true); notify(self, message)
	end })
	groupbox:AddButton({ Text = "Delete theme", DoubleClick = true, Func = function()
		local name = Options.ThemeManager_CustomThemeList.Value
		if not validName(name) then return notify(self, "Select a theme") end
		local ok = delfile and pcall(delfile, self.Folder .. "/" .. name .. ".json")
		if ok then
			local defaultPath = self.Folder .. "/default.txt"
			if readfile and isfile(defaultPath) and readfile(defaultPath) == "custom:" .. name then delfile(defaultPath) end
			self:ReloadCustomThemes(); Options.ThemeManager_CustomThemeList:SetValue(nil)
		end
		notify(self, ok and "Theme deleted" or "Could not delete theme")
	end })
	groupbox:AddButton("Refresh list", function() self:ReloadCustomThemes() end)
	groupbox:AddButton("Set as default", function() local _, message = self:SaveDefault(Options.ThemeManager_CustomThemeList.Value, true); notify(self, message) end)
	self:LoadDefault()
end
function ThemeManager:ApplyToTab(tab)
	if tab and tab.AddLeftGroupbox then self:ApplyToGroupbox(tab:AddLeftGroupbox("Menu Appearance")) end
end
return ThemeManager
end)()

end)
__bundle_register("Menu/ExploitTab", function(require, _LOADED, __bundle_register, __bundle_modules)
local ExploitTab = {}

---@module GUI.Icons
local Icons = require("GUI/Icons")

---@module Features.Game.Teleport
local Teleport = require("Features/Game/Teleport")

---@module Menu.ServerActions
